fn parked_looks(host: &HostHandle) -> usize {
    host.shared.restored.lock().unwrap().parked_looks
}

fn no_step_while_parked(host: &HostHandle, looks: usize, stepped: &dyn Fn() -> usize) {
    until("no step in flight", || {
        let queue = host.shared.restored.lock().unwrap();
        !queue.attempts.iter().any(|attempt| attempt.acting)
    });
    let due = {
        let queue = host.shared.restored.lock().unwrap();
        queue.attempts.iter().map(|attempt| attempt.due).max()
    };
    if let Some(due) = due {
        until("every queued attempt due", || Instant::now() >= due);
    }
    let (from, steps) = (parked_looks(host), stepped());
    until("the queue's worker looked at the park", || {
        host.shared.restored_wake.notify_all();
        parked_looks(host) >= from + looks || stepped() != steps
    });
    assert_eq!(
        stepped(),
        steps,
        "no step starts while the terminal is parked"
    );
}

#[test]
fn the_restored_hold_lasts_while_agents_are_queued_and_never_past_its_bound() {
    let _lane = crate::message_inbox::own_lane_for_test();
    let world = Arc::new(World::default());
    let (gate_tx, gate_rx) = std::sync::mpsc::channel::<&'static str>();
    let gate_rx = Mutex::new(gate_rx);
    let mut h = hooks(&world, parking_body(&world));
    h.acts.relaunch_restored = Arc::new(move |_, _, _, _| {
        gate_rx
            .lock()
            .unwrap()
            .recv()
            .unwrap_or("adopted")
            .to_string()
    });
    let host = HostHandle::start(on(), false, false, h);
    let before = Instant::now();
    assert!(!host.restored_pending(before), "nothing queued");
    host.relaunch_restored(vec![restored("s-a", "in tab 1")]);
    let first = Instant::now();
    assert!(host.restored_pending(first), "an agent is queued");
    until("its first step in flight", || {
        let queue = host.shared.restored.lock().unwrap();
        queue.attempts.front().is_some_and(|a| a.acting)
    });
    host.shared.restored.lock().unwrap().attempts[0].agent_seen = true;
    assert!(
        host.restored_pending(Instant::now()),
        "a step in flight holds it, an agent seen in its tab"
    );
    let typed = |on: bool| {
        let mut queue = host.shared.restored.lock().unwrap();
        let attempt = &mut queue.attempts[0];
        attempt.acting = !on;
        attempt.resume_wait_since = on.then(Instant::now);
    };
    typed(true);
    assert!(
        host.restored_pending(Instant::now()),
        "a line typed holds it, an agent seen in its tab"
    );
    typed(false);
    assert!(
        !host.restored_pending(first + RESTORED_HOLD),
        "never past its bound"
    );
    gate_tx.send("adopted").unwrap();
    until("the queue is done", || {
        !host.restored_pending(Instant::now())
    });
    std::thread::sleep(Duration::from_millis(20));
    host.relaunch_restored(vec![restored("s-b", "in tab 2")]);
    assert!(host.restored_pending(Instant::now()));
    assert!(
        !host.restored_pending(before + RESTORED_HOLD + Duration::from_millis(10)),
        "once per process: the bound runs from the first relaunch"
    );
    gate_tx.send("adopted").unwrap();
    until("the second queue is done", || {
        !host.restored_pending(Instant::now())
    });
}

fn restored_rows(within: Duration) -> Vec<crate::message_inbox::InboxMessage> {
    let deadline = Instant::now() + within;
    let mut rows = Vec::new();
    while rows.is_empty() && Instant::now() < deadline {
        rows.extend(crate::message_inbox::take_queued().into_iter().filter(|m| {
            m.message.key.as_deref() == Some(crate::message_reporters::KEY_RESTORED_AGENTS)
        }));
        std::thread::sleep(Duration::from_millis(10));
    }
    rows
}

#[test]
fn a_restart_in_flight_behind_the_claim_grace_is_carried_once_the_agent_is_gone() {
    let _lane = crate::message_inbox::own_lane_for_test();
    let supervisable = Arc::new(AtomicBool::new(true));
    let stepped: Arc<Mutex<Vec<String>>> = Arc::default();
    let carry: Arc<CarryInFlightFn> = {
        let (supervisable, stepped) = (Arc::clone(&supervisable), Arc::clone(&stepped));
        Arc::new(move |sid, _| {
            carry_in_flight_now(
                || {
                    stepped
                        .lock()
                        .unwrap()
                        .is_empty()
                        .then_some(upgrade::Agent::Claude)
                },
                || supervisable.load(Ordering::SeqCst),
                || {
                    stepped.lock().unwrap().push(sid.to_string());
                    "adopted".to_string()
                },
            )
        })
    };
    let world = Arc::new(World::default());
    let mut h = hooks(&world, parking_body(&world));
    h.acts.carry_in_flight = carry;
    h.pause = Arc::new(carry_pause);
    let host = HostHandle::start(on(), false, true, h);
    host.defer_adopted_claims(vec!["s-exiting".into()], Duration::from_millis(200));
    host.resume_after_handoff(vec![("s-exiting".into(), "in tab 1".into())]);
    std::thread::sleep(Duration::from_millis(50));
    supervisable.store(false, Ordering::SeqCst);
    until("the restart carried on once its agent was gone", || {
        !stepped.lock().unwrap().is_empty()
    });
    assert_eq!(*stepped.lock().unwrap(), ["s-exiting"]);
    assert_eq!(
        carry_in_flight_now(|| None, || true, || unreachable!()),
        None
    );
    assert_eq!(
        carry_in_flight_now(|| Some(upgrade::Agent::Codex), || true, || unreachable!()),
        Some((CARRY_SUPERVISED.to_string(), upgrade::Agent::Codex))
    );
    host.shutdown_and_join();
}

#[test]
fn a_restart_the_successor_cannot_carry_in_time_is_said() {
    let _lane = crate::message_inbox::own_lane_for_test();
    let _ = crate::message_inbox::take_queued();
    let steps = Arc::new(AtomicU64::new(0));
    let (land, landing) = std::sync::mpsc::channel::<()>();
    let carry: Arc<CarryInFlightFn> = {
        let (steps, landing) = (Arc::clone(&steps), Mutex::new(landing));
        Arc::new(move |_, _| {
            if steps.fetch_add(1, Ordering::SeqCst) == 0 {
                let _ = landing.lock().unwrap().recv();
            }
            Some(("wait:shell-prompt".to_string(), upgrade::Agent::Claude))
        })
    };
    let world = Arc::new(World::default());
    let mut h = hooks(&world, parking_body(&world));
    h.acts.carry_in_flight = carry;
    h.pause = Arc::new(carry_pause);
    let clock = StepClock::new();
    h.carry_clock = Arc::clone(&clock) as Arc<dyn CarryClock>;
    let host = HostHandle::start(on(), false, true, h);
    host.resume_after_handoff(vec![("s-shell".into(), "in tab 1".into())]);
    until("the first step", || steps.load(Ordering::SeqCst) > 0);
    host.suspend();
    land.send(()).unwrap();
    let released = clock.now();
    let span = 2 * carry_pause(RESTORED_MAX_PAUSE);
    let parked = aterm_spec::wait::within(
        aterm_spec::wait::MUST_HAPPEN,
        Duration::from_millis(1),
        || {
            let at = clock.now();
            let now = steps.load(Ordering::SeqCst);
            (now > 1 || at >= released + span).then_some(now)
        },
    )
    .expect("the carry waited on the park");
    assert_eq!(parked, 1, "nothing is stepped while the park holds");
    host.resume();
    until("stepped again after the resume", || {
        steps.load(Ordering::SeqCst) > parked
    });
    let rows = restored_rows(Duration::from_secs(60));
    assert_eq!(rows.len(), 1, "{rows:?}");
    assert!(rows[0].message.title.ends_with("tab 1"));
    host.shutdown_and_join();
}

#[test]
fn a_hand_on_a_tab_the_successor_carries_starts_its_bound_over() {
    let _lane = crate::message_inbox::own_lane_for_test();
    let _ = crate::message_inbox::take_queued();
    const HELD: u64 = 20;
    let steps = Arc::new(AtomicU64::new(0));
    let carry: Arc<CarryInFlightFn> = {
        let steps = Arc::clone(&steps);
        Arc::new(move |_, _| {
            let n = steps.fetch_add(1, Ordering::SeqCst) + 1;
            let word = if n <= HELD {
                relaunch::WAIT_HAND_LIFTS
            } else {
                "wait:shell-prompt"
            };
            Some((word.to_string(), upgrade::Agent::Claude))
        })
    };
    let world = Arc::new(World::default());
    let mut h = hooks(&world, parking_body(&world));
    h.acts.carry_in_flight = carry;
    h.pause = Arc::new(carry_pause);
    h.carry_clock = StepClock::new();
    let host = HostHandle::start(on(), false, true, h);
    host.resume_after_handoff(vec![("s-held".into(), "in tab 47".into())]);
    let ours = |m: &crate::message_inbox::InboxMessage| {
        m.message.key.as_deref() == Some(crate::message_reporters::KEY_RESTORED_AGENTS)
            && m.message.title.contains("tab 47")
    };
    let mut rows = Vec::new();
    let said = aterm_spec::wait::within(
        aterm_spec::wait::MUST_HAPPEN,
        Duration::from_millis(10),
        || {
            rows.extend(crate::message_inbox::take_queued().into_iter().filter(ours));
            (!rows.is_empty()).then_some(())
        },
    );
    assert!(said.is_some(), "said once the hand lifted");
    assert!(
        steps.load(Ordering::SeqCst) > HELD,
        "carried through the hand: {} steps",
        steps.load(Ordering::SeqCst)
    );
    assert_eq!(rows.len(), 1, "{rows:?}");
    host.shutdown_and_join();
}

struct ByHand {
    host: HostHandle,
    world: Arc<World>,
    entered: std::sync::mpsc::Receiver<String>,
    word: std::sync::mpsc::Sender<&'static str>,
    steps: Arc<AtomicUsize>,
    /// Set before a word is sent: the retry that word owes waits an hour,
    /// until the test makes it due ([`HOLD_RETRY`]); else a thousandth of
    /// its back-off ([`quick_pause`]).
    hold: Arc<AtomicBool>,
}

thread_local! {
    static HOLD_RETRY: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

fn hold_this_steps_retry() {
    HOLD_RETRY.with(|hold| hold.set(true));
}

fn holding_retries(inner: Arc<PauseFn>) -> Arc<PauseFn> {
    Arc::new(move |pause| {
        let waited = inner(pause);
        if HOLD_RETRY.with(|hold| hold.replace(false)) {
            Duration::from_secs(3600)
        } else {
            waited
        }
    })
}

fn restored_by_hand() -> ByHand {
    let (entered_tx, entered) = std::sync::mpsc::channel::<String>();
    let (word, word_rx) = std::sync::mpsc::channel::<&'static str>();
    let (entered_tx, word_rx) = (Mutex::new(entered_tx), Mutex::new(word_rx));
    let steps = Arc::new(AtomicUsize::new(0));
    let hold = Arc::new(AtomicBool::new(false));
    let world = Arc::new(World::default());
    let mut h = hooks(&world, parking_body(&world));
    let (begun, held) = (Arc::clone(&steps), Arc::clone(&hold));
    h.acts.relaunch_restored = Arc::new(move |sid, _, _, _| {
        begun.fetch_add(1, Ordering::SeqCst);
        let _ = entered_tx.lock().unwrap().send(sid.to_string());
        let word = word_rx
            .lock()
            .unwrap()
            .recv()
            .unwrap_or("wait:shell-prompt");
        if held.swap(false, Ordering::SeqCst) {
            hold_this_steps_retry();
        }
        word.to_string()
    });
    h.pause = holding_retries(Arc::new(quick_pause));
    let host = HostHandle::start(on(), false, false, h);
    host.relaunch_restored(vec![restored("s-a", "in tab 1")]);
    ByHand {
        host,
        world,
        entered,
        word,
        steps,
        hold,
    }
}

fn project_carry(
    state: &aterm_spec::interp::State,
    host: &HostHandle,
) -> aterm_spec::interp::State {
    let mut seen = state.clone();
    let queue = host.shared.restored.lock().unwrap();
    let attempt = queue.attempts.iter().find(|a| a.agent.sid == "s-a");
    seen.insert("queued", i64::from(attempt.is_some()));
    seen.insert("acting", i64::from(attempt.is_some_and(|a| a.acting)));
    if let Some(attempt) = attempt {
        seen.insert("typed", i64::from(attempt.typed()));
        seen.insert(
            "overtaken",
            i64::from(attempt.agent_seen && !attempt.typed()),
        );
    }
    seen
}

fn restored_row_naming(place: &str) -> crate::message_inbox::InboxMessage {
    let found: Mutex<Option<crate::message_inbox::InboxMessage>> = Mutex::default();
    until(&format!("the restored agents' row naming {place}"), || {
        let mut found = found.lock().unwrap();
        if found.is_none() {
            *found = crate::message_inbox::take_queued().into_iter().find(|m| {
                m.message.key.as_deref() == Some(crate::message_reporters::KEY_RESTORED_AGENTS)
                    && (m.message.title.ends_with(place)
                        || m.message.detail.iter().any(|line| line.starts_with(place)))
            });
        }
        found.is_some()
    });
    found.into_inner().unwrap().expect("found")
}

#[test]
fn the_real_restored_carry_conforms_to_its_model() {
    let _lane = crate::message_inbox::own_lane_for_test();
    let _ = crate::message_inbox::take_queued();
    let model = aterm_models_harness::harness_restored_carry_model();
    let must = aterm_spec::wait::MUST_HAPPEN;

    let one = restored_by_hand();
    let parent = &one.host;
    let mut state = model.init_state();
    assert_eq!(one.entered.recv_timeout(must).unwrap(), "s-a");
    assert!(model.fire("StepStart", &mut state), "{state:?}");
    assert_eq!(
        project_carry(&state, parent),
        state,
        "queued while its step runs"
    );
    parent.pause_restored();
    assert!(model.fire("Park", &mut state), "{state:?}");
    let pending = parent.pending_restored_snapshot_for("s-a");
    assert_eq!(
        i64::from(pending.is_some()),
        state["captured"],
        "the park's capture"
    );
    one.word.send("wait:shell-prompt").unwrap();
    assert!(model.fire("StepRetries", &mut state), "{state:?}");
    no_step_while_parked(parent, 2, &|| one.steps.load(Ordering::SeqCst));
    assert!(!model.action_enabled("StepStart", &state));
    assert_eq!(project_carry(&state, parent), state, "its step over");
    let recaptured = parent.pending_restored_snapshot_for("s-a");
    assert_eq!(
        recaptured == pending,
        model.action_enabled("Commit", &state),
        "the captures agree exactly where the model's Commit is enabled"
    );
    assert!(model.fire("Commit", &mut state), "{state:?}");
    let relaunched: Arc<Mutex<Vec<Snapshot>>> = Arc::default();
    let (swept, refused) = (Arc::new(AtomicUsize::new(0)), Arc::new(AtomicUsize::new(0)));
    let world = Arc::new(World::default());
    let mut h = hooks(&world, parking_body(&world));
    let r = Arc::clone(&relaunched);
    h.acts.relaunch_restored = Arc::new(move |_, snap, _, _| {
        r.lock().unwrap().push(snap.clone());
        "adopted".to_string()
    });
    let (w, g) = (Arc::clone(&swept), Arc::clone(&refused));
    h.acts.carry_in_flight = Arc::new(move |sid, _| {
        if sid == "s-shell" {
            w.fetch_add(1, Ordering::SeqCst);
            Some(("adopted".to_string(), upgrade::Agent::Claude))
        } else {
            g.fetch_add(1, Ordering::SeqCst);
            Some(("refused:shell-gone".to_string(), upgrade::Agent::Claude))
        }
    });
    h.carry_clock = StepClock::new();
    let successor = HostHandle::start(on(), false, true, h);
    successor.resume_after_handoff(vec![
        ("s-shell".to_string(), "in tab 2".to_string()),
        ("s-gone".to_string(), "in tab 9".to_string()),
    ]);
    let carried = pending.expect("the park carried the agent");
    successor.relaunch_restored(vec![RestoredAgent {
        sid: "s-a".to_string(),
        snap: carried.clone(),
        place: "in tab 1".to_string(),
        cold: true,
        asked: None,
        was: None,
    }]);
    until("the successor relaunched it", || {
        !relaunched.lock().unwrap().is_empty()
    });
    assert_eq!(relaunched.lock().unwrap()[0], carried);
    assert!(model.fire("SuccRelaunches", &mut state), "{state:?}");
    let row = restored_row_naming("in tab 9");
    assert!(row.message.title.ends_with("tab 9"), "the sweep's row");
    assert_eq!(
        (swept.load(Ordering::SeqCst), refused.load(Ordering::SeqCst)),
        (1, 1),
        "a carry-on that relaunched, and one that can never land, are not stepped again"
    );
    assert!(model.fire("SweepCarriesOn", &mut state), "{state:?}");
    for invariant in [
        "NoSilentLoss",
        "NoStepWhileParked",
        "NoRelaunchOverAgent",
        "NoStrandedRestart",
    ] {
        assert!(model.check_invariant(invariant, &state), "{invariant}");
    }
    assert_eq!((state["resolved"], state["restart"]), (1, 0));
    successor.shutdown_and_join();
    one.host.shutdown_and_join();

    let two = restored_by_hand();
    let parent = &two.host;
    let mut state = model.init_state();
    assert_eq!(two.entered.recv_timeout(must).unwrap(), "s-a");
    assert!(model.fire("StepStart", &mut state), "{state:?}");
    parent.pause_restored();
    assert!(model.fire("Park", &mut state), "{state:?}");
    let pending = parent.pending_restored_snapshot_for("s-a");
    assert_eq!(i64::from(pending.is_some()), state["captured"]);
    two.word.send("adopted").unwrap();
    until("the relaunch that landed off the queue", || {
        parent.pending_restored().is_empty()
    });
    assert!(model.fire("StepResolves", &mut state), "{state:?}");
    assert_eq!(project_carry(&state, parent), state, "landed while parked");
    let recaptured = parent.pending_restored_snapshot_for("s-a");
    assert_eq!(
        (
            recaptured == pending,
            model.action_enabled("Commit", &state)
        ),
        (false, false),
        "(the captures agree, the model's Commit enabled)"
    );
    parent.resume_restored();
    assert!(model.fire("Rollback", &mut state), "{state:?}");
    assert_eq!(project_carry(&state, parent), state, "rolled back");
    assert_eq!((state["queued"], state["resolved"]), (0, 1));
    parent.shutdown_and_join();

    let three = restored_by_hand();
    let parent = &three.host;
    let mut state = model.init_state();
    assert_eq!(three.entered.recv_timeout(must).unwrap(), "s-a");
    assert!(model.fire("StepStart", &mut state), "{state:?}");
    three.hold.store(true, Ordering::SeqCst);
    three.word.send("wait:shell-prompt").unwrap();
    until("its step over", || {
        let queue = parent.shared.restored.lock().unwrap();
        !queue.attempts.iter().any(|attempt| attempt.acting)
    });
    assert!(model.fire("StepRetries", &mut state), "{state:?}");
    assert_eq!(
        project_carry(&state, parent),
        state,
        "queued, its step over"
    );
    parent.pause_restored();
    assert!(model.fire("Park", &mut state), "{state:?}");
    let pending = parent.pending_restored_snapshot_for("s-a");
    assert_eq!(i64::from(pending.is_some()), state["captured"]);
    three.world.set(&[("s-a", Program::Claude)]);
    until("its agent supervised", || parent.live() == ["s-a"]);
    assert!(model.fire("AgentRuns", &mut state), "{state:?}");
    assert_eq!(
        project_carry(&state, parent),
        state,
        "an agent ran in the tab"
    );
    three.world.set(&[]);
    until("its agent gone", || parent.live().is_empty());
    let recaptured = parent.pending_restored_snapshot_for("s-a");
    assert_eq!(
        (
            recaptured == pending,
            model.action_enabled("Commit", &state)
        ),
        (false, false),
        "(the captures agree, the model's Commit enabled)"
    );
    parent.shared.restored.lock().unwrap().attempts[0].due = Instant::now();
    parent.resume_restored();
    assert!(model.fire("Rollback", &mut state), "{state:?}");
    assert!(!model.action_enabled("StepStart", &state));
    let begun = three.steps.load(Ordering::SeqCst);
    until("taken off the queue, or stepped", || {
        parent.pending_restored().is_empty() || three.steps.load(Ordering::SeqCst) != begun
    });
    assert_eq!(
        three.steps.load(Ordering::SeqCst),
        begun,
        "no step once an agent ran in the tab"
    );
    assert!(model.fire("Overtaken", &mut state), "{state:?}");
    assert_eq!(project_carry(&state, parent), state, "taken off");
    assert!(
        three.world.badges.lock().unwrap().is_empty(),
        "the attention of the tab an agent ran in is its worker's"
    );
    for invariant in [
        "NoSilentLoss",
        "NoStepWhileParked",
        "NoRelaunchOverAgent",
        "NoStrandedRestart",
    ] {
        assert!(model.check_invariant(invariant, &state), "{invariant}");
    }
    parent.shutdown_and_join();

    let four = restored_by_hand();
    let parent = &four.host;
    let mut state = model.init_state();
    assert_eq!(four.entered.recv_timeout(must).unwrap(), "s-a");
    assert!(model.fire("StepStart", &mut state), "{state:?}");
    four.hold.store(true, Ordering::SeqCst);
    four.word.send("wait:resume").unwrap();
    until("its step typed, and over", || {
        let queue = parent.shared.restored.lock().unwrap();
        queue
            .attempts
            .front()
            .is_some_and(|attempt| attempt.typed() && !attempt.acting)
    });
    assert!(model.fire("StepTypes", &mut state), "{state:?}");
    assert_eq!(project_carry(&state, parent), state, "queued, typed");
    four.world.set(&[("s-a", Program::Claude)]);
    until("its agent supervised, and seen", || {
        parent.live() == ["s-a"]
            && parent
                .shared
                .restored
                .lock()
                .unwrap()
                .attempts
                .iter()
                .any(|a| a.agent_seen)
    });
    assert!(model.fire("AgentRuns", &mut state), "{state:?}");
    assert_eq!(
        project_carry(&state, parent),
        state,
        "its own agent: not overtaken"
    );
    parent.pause_restored();
    assert!(model.fire("Park", &mut state), "{state:?}");
    let pending = parent.pending_restored_snapshot_for("s-a");
    assert_eq!(i64::from(pending.is_some()), state["captured"]);
    assert_eq!(
        parent.pending_restored_snapshot_for("s-a") == pending,
        model.action_enabled("Commit", &state),
        "the captures agree exactly where the model's Commit is enabled"
    );
    parent.shared.restored.lock().unwrap().attempts[0].due = Instant::now();
    parent.resume_restored();
    assert!(model.fire("Rollback", &mut state), "{state:?}");
    assert_eq!(four.entered.recv_timeout(must).unwrap(), "s-a");
    assert!(model.fire("StepStart", &mut state), "{state:?}");
    four.word.send("adopted").unwrap();
    until("landed, off the queue", || {
        parent.pending_restored().is_empty()
    });
    assert!(model.fire("StepResolves", &mut state), "{state:?}");
    assert_eq!(project_carry(&state, parent), state, "landed");
    for invariant in [
        "NoSilentLoss",
        "NoStepWhileParked",
        "NoRelaunchOverAgent",
        "NoStrandedRestart",
    ] {
        assert!(model.check_invariant(invariant, &state), "{invariant}");
    }
    parent.shutdown_and_join();

    let buggy = aterm_spec::interp::with_buggy(&model, 1);
    let replay = |actions: &[&str]| {
        let mut old = buggy.init_state();
        for action in actions {
            assert!(buggy.fire(action, &mut old), "{action}: {old:?}");
        }
        old
    };
    let dropped = replay(&["StepStart", "ParkDropsQueue", "StepRetries", "Commit"]);
    assert_eq!(dropped["captured"], 0, "the handoff leaf said agent: None");
    assert!(!buggy.check_invariant("NoSilentLoss", &dropped));
    let unswept = replay(&["StepStart", "Park", "StepRetries", "CommitWithoutSweep"]);
    assert!(!buggy.check_invariant("NoStrandedRestart", &unswept));
    let frozen = replay(&[
        "StepStart",
        "StepRetries",
        "ParkFreezes",
        "AgentRuns",
        "Commit",
        "SuccRelaunches",
    ]);
    assert!(!buggy.check_invariant("NoRelaunchOverAgent", &frozen));
    let forgotten = replay(&[
        "StepStart",
        "StepRetries",
        "Park",
        "AgentRuns",
        "AgentStopsForgotten",
        "Commit",
        "SuccRelaunches",
    ]);
    assert!(!buggy.check_invariant("NoRelaunchOverAgent", &forgotten));
}

#[test]
fn the_disk_watch_looks_once_per_tick_over_the_supervised_sessions() {
    let world = Arc::new(World::default());
    let looks: Arc<Mutex<Vec<Vec<String>>>> = Arc::default();
    let beats = Arc::new(AtomicUsize::new(0));
    let (l, b) = (Arc::clone(&looks), Arc::clone(&beats));
    let hooks = Hooks {
        disk: Arc::new(move |sids| l.lock().unwrap().push(sids.to_vec())),
        note: Arc::new(move |note| {
            if note == HostNote::DiskLooked {
                b.fetch_add(1, Ordering::SeqCst);
            }
        }),
        ..hooks(&world, parking_body(&world))
    };
    let beats = || beats.load(Ordering::SeqCst);
    let none = OffSessions::default();
    let t0 = Instant::now();
    let mut at = t0 + DISK_FIRST_LOOK;
    let two: HashMap<String, Program> = [
        ("s-b".to_string(), Program::Codex),
        ("s-a".to_string(), Program::Claude),
    ]
    .into();

    assert_eq!(
        look_at_disk(&mut at, t0, true, &two, &none, &hooks),
        Some(at)
    );
    assert!(looks.lock().unwrap().is_empty(), "not before its instant");
    assert_eq!(beats(), 0, "no look, no beat");
    let due = t0 + DISK_FIRST_LOOK;
    assert_eq!(
        look_at_disk(&mut at, due, true, &two, &none, &hooks),
        Some(due + DISK_TICK)
    );
    assert_eq!(
        *looks.lock().unwrap(),
        [vec!["s-a".to_string(), "s-b".to_string()]]
    );
    assert_eq!(beats(), 1, "the look's beat");
    assert_eq!(
        look_at_disk(&mut at, due + DISK_TICK / 2, true, &two, &none, &hooks),
        Some(due + DISK_TICK),
        "one look per tick"
    );
    assert_eq!((looks.lock().unwrap().len(), beats()), (1, 1));

    let late = due + DISK_TICK * 2;
    assert_eq!(
        look_at_disk(&mut at, late, false, &two, &none, &hooks),
        Some(late + DISK_TICK)
    );
    let later = late + DISK_TICK;
    assert_eq!(
        look_at_disk(&mut at, later, true, &HashMap::new(), &none, &hooks),
        Some(later + DISK_TICK)
    );
    assert_eq!(
        looks.lock().unwrap()[1..],
        [Vec::<String>::new(), Vec::new()],
        "off, or nothing hosted: looked at, no session handed"
    );
    assert_eq!(beats(), 3, "a beat at every look, handed a session or not");
}

#[test]
fn the_disk_watch_hands_over_no_off_session() {
    let world = Arc::new(World::default());
    let looks: Arc<Mutex<Vec<Vec<String>>>> = Arc::default();
    let l = Arc::clone(&looks);
    let hooks = Hooks {
        disk: Arc::new(move |sids| l.lock().unwrap().push(sids.to_vec())),
        ..hooks(&world, parking_body(&world))
    };
    let two: HashMap<String, Program> = [
        ("s-a".to_string(), Program::Claude),
        ("s-b".to_string(), Program::Codex),
    ]
    .into();
    let words = |words: &[(&str, Autopilot)], default: Autopilot| OffSessions {
        words: words
            .iter()
            .map(|(sid, word)| ((*sid).to_string(), *word))
            .collect(),
        default,
    };
    let look = |off: &OffSessions| {
        let now = Instant::now();
        let mut at = now;
        let next = look_at_disk(&mut at, now, true, &two, off, &hooks);
        (next.is_some(), at > now)
    };
    let cruise = Autopilot::Cruise;
    assert_eq!(look(&words(&[], cruise)), (true, true), "none Off");
    assert_eq!(
        look(&words(&[("s-b", Autopilot::Off)], cruise)),
        (true, true),
        "s-b Off by its word"
    );
    assert_eq!(
        look(&words(&[("s-a", cruise)], Autopilot::Off)),
        (true, true),
        "s-b Off by the default, s-a opted in"
    );
    assert_eq!(
        look(&words(&[("s-a", Autopilot::Off)], Autopilot::Off)),
        (true, true),
        "every session Off: the volume is looked at, no session handed"
    );
    let s = |sids: &[&str]| sids.iter().map(|s| (*s).to_string()).collect::<Vec<_>>();
    assert_eq!(
        *looks.lock().unwrap(),
        [s(&["s-a", "s-b"]), s(&["s-a"]), s(&["s-a"]), s(&[])]
    );
}

#[test]
fn a_codex_no_worker_supervises_keeps_the_disk_tick() {
    let world = Arc::new(World::default());
    let looks: Arc<Mutex<Vec<Vec<String>>>> = Arc::default();
    let codexes: Arc<Mutex<Vec<String>>> = Arc::new(Mutex::new(vec!["s-v".to_string()]));
    let (l, c) = (Arc::clone(&looks), Arc::clone(&codexes));
    let hooks = Hooks {
        disk: Arc::new(move |sids| l.lock().unwrap().push(sids.to_vec())),
        codex_roster: Arc::new(move || c.lock().unwrap().clone()),
        ..hooks(&world, parking_body(&world))
    };
    let handle = HostHandle::start(on(), false, true, hooks.clone());
    handle.shared.lock().suspended = false;
    let mut host = HostState::from_shared(&handle.shared);
    let pass = |host: &mut HostState| {
        host.disk_at = Instant::now();
        match host_pass(&handle.shared, host, true, &hooks) {
            ControlFlow::Continue(_) => {}
            ControlFlow::Break(()) => panic!("shut down"),
        }
    };
    pass(&mut host);
    assert!(handle.live().is_empty(), "no worker supervises the codex");
    assert_eq!(*looks.lock().unwrap(), [vec!["s-v".to_string()]]);
    assert!(
        host.disk_at > Instant::now(),
        "the next look is named a tick on"
    );
    let supervised: HashMap<String, Program> = [
        ("s-v".to_string(), Program::Codex),
        ("s-a".to_string(), Program::Claude),
    ]
    .into();
    let mut both: Vec<_> = disk_roster(&supervised, true, &hooks).into_iter().collect();
    both.sort_by(|a, b| a.0.cmp(&b.0));
    assert_eq!(
        both,
        [
            ("s-a".to_string(), Program::Claude),
            ("s-v".to_string(), Program::Codex)
        ]
    );
    codexes.lock().unwrap().clear();
    looks.lock().unwrap().clear();
    pass(&mut host);
    assert_eq!(
        *looks.lock().unwrap(),
        [Vec::<String>::new()],
        "a look with no session for the watch"
    );
    *codexes.lock().unwrap() = vec!["s-v".to_string()];
    assert!(disk_roster(&HashMap::new(), false, &hooks).is_empty());
    assert_eq!(
        disk_roster(&HashMap::new(), true, &hooks)
            .keys()
            .collect::<Vec<_>>(),
        ["s-v"]
    );
    handle.shared.lock().shutting_down = true;
    assert_eq!(
        host_pass(&handle.shared, &mut host, true, &hooks),
        ControlFlow::Break(())
    );
    handle.shutdown_and_join();
}

#[test]
fn the_codex_roster_names_every_codex_and_every_proven_self_claim() {
    use crate::session_timeline::{AgentStamp, claim_supervisor_as};
    let store = crate::session_store::new_store();
    let register = |n: u64, reader: Option<Program>| {
        let handle = crate::session_store::test_handle(n);
        let sid = handle.sid.as_str().to_string();
        let ctx = Arc::clone(&handle.ctx);
        if reader.is_some() {
            ctx.timeline.lock().unwrap().publish_agent(
                "idle",
                None,
                None,
                reader,
                AgentStamp {
                    generation: crate::control::ScreenGen { epoch: 1, seq: n },
                    fp: n,
                },
            );
        }
        store.write().unwrap().register(handle);
        (sid, ctx)
    };
    let (codex, _) = register(1, Some(Program::Codex));
    let (claude, _) = register(2, Some(Program::Claude));
    let (shell, _) = register(3, None);
    let (proven, proven_ctx) = register(4, None);
    let (unproven, unproven_ctx) = register(5, None);
    let (node, node_ctx) = register(6, None);
    node_ctx
        .timeline
        .lock()
        .unwrap()
        .set_program(4242, Some("node".to_string()));
    note_codex_report(&node, true);
    let now = crate::metrics::now_us();
    let me = std::process::id();
    claim_supervisor_as(
        &proven_ctx,
        &format!("codex-alab@{me}"),
        Some(1),
        None,
        Some(crate::self_claim::Proven {
            pid: me,
            start: "a test identity".to_string(),
        }),
        now,
        aterm_slog::Actor::Ctl,
    )
    .expect("the proven claim");
    claim_supervisor_as(
        &unproven_ctx,
        &format!("codex-alab@{me}"),
        Some(2),
        None,
        None,
        now,
        aterm_slog::Actor::Ctl,
    )
    .expect("an ordinary claim");
    let mut roster = codex_roster_of(&store);
    roster.sort();
    let mut want = vec![codex.clone(), proven.clone(), node.clone()];
    want.sort();
    assert_eq!(roster, want);
    for other in [&claude, &shell, &unproven] {
        assert!(!roster.contains(other), "{other} is not a codex");
    }
    note_codex_report(&node, false);
    let roster = codex_roster_of(&store);
    assert!(!roster.contains(&node), "{roster:?}");
    assert!(roster.contains(&codex) && roster.contains(&proven));
}

#[test]
fn a_pass_that_freed_something_but_left_the_volume_short_still_counts() {
    let config = aterm_agent::harness::disk::Config::default();
    let gib = 1u64 << 30;
    let below = Some(3 * gib);
    let at_floor = Some(config.auto_free_gib * gib);
    let short = std::sync::atomic::AtomicU32::new(0);
    assert_eq!(
        disk_pass_outcome(true, below, config, &short),
        DiskOutcome::Short
    );
    assert_eq!(
        disk_pass_outcome(true, below, config, &short),
        DiskOutcome::Low {
            looks: 2,
            free_gib: 3
        },
        "freed something both times, still short: the owner is told"
    );
    assert_eq!(
        disk_pass_outcome(true, at_floor, config, &short),
        DiskOutcome::Plenty
    );
    assert_eq!(
        disk_pass_outcome(false, below, config, &short),
        DiskOutcome::Short,
        "the count began again"
    );
    assert!(matches!(
        disk_pass_outcome(false, below, config, &short),
        DiskOutcome::Low { looks: 2, .. }
    ));
    assert_eq!(
        disk_pass_outcome(true, None, config, &short),
        DiskOutcome::Plenty
    );
    assert_eq!(
        disk_pass_outcome(false, None, config, &short),
        DiskOutcome::Short
    );
    let left = free_after_pass(false, below, || at_floor);
    assert_eq!(
        disk_pass_outcome(false, left, config, &short),
        DiskOutcome::Plenty,
        "a second short pass on the figure read before it"
    );
    assert_eq!(free_after_pass(false, below, || None), below);
    assert_eq!(free_after_pass(true, below, || None), None);
}

#[test]
fn a_disk_setting_aterm_cannot_read_is_said_and_a_short_volume_still_opens_its_line() {
    let tmp = aterm_tempfile::Builder::new()
        .prefix("aterm-hh-disk-")
        .tempdir()
        .expect("temp dir");
    let read = |text: &str| {
        let path = tmp.path().join("aterm.toml");
        std::fs::write(&path, text).expect("write aterm.toml");
        let reading = aterm_agent::harness::cli::disk_config_read(Some(&path));
        let faults = aterm_agent::harness::cli::disk_faults(text);
        (reading, faults)
    };
    let gib = 1u64 << 30;
    let floor = aterm_agent::harness::disk::Config::default().auto_free_gib;
    let low = Some(2 * gib);
    let runs = DiskRuns::new();

    let (faulty, faults) = read("[disk]\napply = \"yes\"\n");
    assert!(
        matches!(&disk_settings_note(&faulty, &faults),
            HostNote::DiskSettingsOff { notes } if !notes.is_empty() && *notes == faulty.notes),
        "{faulty:?}"
    );
    assert_eq!(disk_look_without_pass(&faulty, low, &runs), None);
    assert_eq!(
        disk_look_without_pass(&faulty, low, &runs),
        Some(HostNote::DiskLowCleanupOff {
            free_gib: 2,
            floor_gib: floor,
            asked: None,
        }),
        "short two looks running while removal is off: the owner is told no pass ran"
    );
    assert_eq!(
        disk_look_without_pass(&faulty, Some(floor * gib), &runs),
        Some(HostNote::DiskPlenty)
    );
    assert_eq!(
        disk_look_without_pass(&faulty, low, &runs),
        None,
        "the count began again"
    );
    for _ in 0..DISK_SHORT_LOOKS + 1 {
        assert!(
            !matches!(
                disk_look_without_pass(&faulty, None, &runs),
                Some(HostNote::DiskLowCleanupOff { .. } | HostNote::DiskLow { .. })
            ),
            "a figure nobody read opens no line"
        );
    }

    let (off, off_faults) = read("[disk]\nauto_free_gib = 0\n");
    assert_eq!(
        disk_settings_note(&off, &off_faults),
        HostNote::DiskSettingsRead
    );
    for _ in 0..DISK_SHORT_LOOKS + 1 {
        assert!(
            !matches!(
                disk_look_without_pass(&off, low, &runs),
                Some(HostNote::DiskLowCleanupOff { .. } | HostNote::DiskLow { .. })
            ),
            "{off:?}"
        );
    }

    let (unread_floor, unread_faults) = read("[disk]\nauto_free_gib = \"off\"\n");
    assert!(matches!(
        disk_settings_note(&unread_floor, &unread_faults),
        HostNote::DiskSettingsOff { .. }
    ));
    for free in [low, Some(100 * gib)] {
        for _ in 0..DISK_SHORT_LOOKS + 1 {
            assert_eq!(disk_look_without_pass(&unread_floor, free, &runs), None);
        }
    }

    let (fixed, fixed_faults) = read("[disk]\napply = true\n");
    assert_eq!(
        disk_settings_note(&fixed, &fixed_faults),
        HostNote::DiskSettingsRead
    );
}

#[test]
fn the_disk_watch_says_each_end_once_a_change() {
    let t0 = Instant::now();
    let minute = Duration::from_secs(60);
    let mut said = DiskEndsSaid::default();
    assert!(
        said.owed(&HostNote::DiskSettingsRead, t0),
        "the first look's"
    );
    assert!(said.owed(&HostNote::DiskPlenty, t0), "the first look's");
    for look in 1..=10 {
        let at = t0 + minute * look;
        assert!(!said.owed(&HostNote::DiskSettingsRead, at), "look {look}");
        assert!(!said.owed(&HostNote::DiskPlenty, at), "look {look}");
    }
    let low = HostNote::DiskLow {
        free_gib: 2,
        floor_gib: 20,
        hogs: Vec::new(),
        asked: None,
    };
    let at = t0 + minute * 11;
    assert!(said.owed(&low, at));
    assert!(said.owed(&low, at), "an opening note always passes");
    assert!(said.owed(&HostNote::DiskPlenty, at + minute));
    assert!(!said.owed(&HostNote::DiskPlenty, at + minute * 2));
    assert!(said.owed(&HostNote::DiskSettingsRead, at + minute));
    let off = HostNote::DiskSettingsOff {
        notes: vec!["apply".to_string()],
    };
    assert!(said.owed(&off, at + minute * 3));
    assert!(said.owed(&HostNote::DiskSettingsRead, at + minute * 4));
    let late = at + minute * 4 + DISK_END_RESTATE;
    assert!(said.owed(&HostNote::DiskSettingsRead, late));
    assert!(said.owed(&HostNote::DiskPlenty, late));
    assert!(said.owed(&HostNote::DiskFullOver, late));
    assert!(said.owed(&HostNote::DiskFullOver, late));
}

#[test]
fn the_disk_watchs_looks_tell_the_window_each_end_once() {
    static LOOKING: AtomicBool = AtomicBool::new(false);
    let told: Arc<Mutex<Vec<HostNote>>> = Arc::default();
    let note: Arc<NoteFn> = {
        let told = Arc::clone(&told);
        Arc::new(move |n| told.lock().unwrap().push(n))
    };
    let (done_tx, done) = std::sync::mpsc::channel::<()>();
    let done_tx = Mutex::new(done_tx);
    let first = AtomicBool::new(true);
    let run: Arc<DiskLookFn> = Arc::new(move |_sids, _cwds, _agents, _seen, note| {
        note(HostNote::DiskSettingsRead);
        note(HostNote::DiskPlenty);
        note(HostNote::DiskFullOver);
        let _ = done_tx.lock().unwrap().send(());
        assert!(
            !first.swap(false, Ordering::SeqCst),
            "the first look fails (a test's)"
        );
    });
    let look = disk_watch(crate::session_store::new_store(), note, &LOOKING, run);
    for _ in 0..2 {
        look(&[]);
        done.recv_timeout(Duration::from_secs(60))
            .expect("the look ran");
        let ran = Instant::now();
        while LOOKING.load(Ordering::SeqCst) {
            assert!(ran.elapsed() < Duration::from_secs(60), "the look ends");
            std::thread::yield_now();
        }
    }
    let told = told.lock().unwrap().clone();
    let count = |want: &HostNote| told.iter().filter(|n| *n == want).count();
    assert_eq!(
        count(&HostNote::DiskFullOver),
        2,
        "both looks ran: {told:?}"
    );
    assert_eq!(count(&HostNote::DiskSettingsRead), 1, "{told:?}");
    assert_eq!(count(&HostNote::DiskPlenty), 1, "{told:?}");
}

#[cfg(windows)]
#[test]
fn a_tab_in_a_short_spelled_folder_reads_its_volumes_row() {
    let tmp = aterm_tempfile::TempDir::new().expect("scratch");
    let folder = std::fs::canonicalize(tmp.path())
        .expect("canonical")
        .join("a folder with a long name");
    std::fs::create_dir(&folder).expect("the long-named folder");
    let short = aterm_sysprobe::short_spelling(&folder).unwrap_or_else(|| {
        panic!(
            "PREMISE: the volume generates 8.3 short names; none for {}",
            folder.display()
        )
    });
    let short = aterm_sysprobe::paths::plain(&short).into_owned();
    let table = aterm_sysprobe::volumes::table();
    assert!(
        aterm_sysprobe::volumes::mount_of(&short, &table).is_none(),
        "{short:?} places on no mount as spelled"
    );
    let state = aterm_tempfile::TempDir::new().expect("harness state");
    let reading = aterm_agent::harness::cli::disk_config_read(None);
    let gone = short.join("removed-since");
    let sessions = [(7, short.clone()), (8, gone.clone())];
    let (rows, map) = disk_look_rows(&table, None, &sessions, &reading, state.path(), 0);
    let want = aterm_sysprobe::volumes::read_path(&folder, &table).expect("its volume");
    for (id, cwd) in &sessions {
        let row = map
            .get(id)
            .and_then(|&i| rows.get(i))
            .unwrap_or_else(|| panic!("{cwd:?} mapped onto no row: {map:?}"));
        assert_eq!(
            (&row.reading.mount, &row.reading.key),
            (&want.mount, &want.key),
            "{cwd:?}"
        );
    }
}

#[cfg(windows)]
#[test]
fn an_8_3_tab_reads_its_volumes_row_before_any_look_and_with_no_watch() {
    static BOARD: crate::disk_board::Shelf = crate::disk_board::Shelf::new();
    let tmp = aterm_tempfile::TempDir::new().expect("scratch");
    let folder = std::fs::canonicalize(tmp.path())
        .expect("canonical")
        .join("a folder with a long name");
    std::fs::create_dir(&folder).expect("the long-named folder");
    let short = aterm_sysprobe::short_spelling(&folder).unwrap_or_else(|| {
        panic!(
            "PREMISE: the volume generates 8.3 short names; none for {}",
            folder.display()
        )
    });
    let short = aterm_sysprobe::paths::plain(&short).into_owned();
    let spelled = short.to_str().expect("text").to_owned();
    let table = aterm_sysprobe::volumes::table();
    let r = aterm_sysprobe::volumes::read_path(&folder, &table).expect("its volume");
    let key = r.key.clone();
    let t = aterm_agent::harness::cli::disk_config_read(None).thresholds_with(Some(r.total), None);
    BOARD.publish(|b| {
        b.table = table.clone();
        b.volumes = vec![crate::disk_board::VolumeRow {
            level: t.level(Some(r.free), r.files_free),
            thresholds: t,
            room: None,
            reading: r,
            as_of: Instant::now(),
            as_of_unix: 0,
            reclaimed_here: false,
        }];
    });
    let placed = |id: u64, cwd: &str| {
        BOARD
            .board_lock()
            .row_of(id, Some(cwd))
            .map(|row| row.reading.key.clone())
    };
    {
        let b = BOARD.board_lock();
        assert!(!b.watched, "no watch");
        assert_eq!(b.watch, crate::disk_board::Watch::NotStarted, "no look");
        assert!(b.sessions.is_empty(), "no look mapped a session");
    }
    assert_eq!(placed(7, &spelled), None, "{spelled} alone places nowhere");

    disk_cwd_reported_onto(&BOARD, 7, Some(&spelled));
    let deadline = Instant::now() + aterm_spec::wait::MUST_HAPPEN;
    while !BOARD.board_lock().spelled.contains_key(&7) {
        assert!(Instant::now() < deadline, "the speller never spelled it");
        std::thread::sleep(Duration::from_millis(1));
    }
    assert_eq!(placed(7, &spelled), Some(key.clone()), "{spelled}");

    let gone = short.join("not-yet-made");
    let gone_spelled = gone.to_str().expect("text").to_owned();
    assert_eq!(placed(8, &gone_spelled), None, "{gone_spelled} unspelled");
    assert!(disk_spell_now(&BOARD, &table, 8, &gone), "{gone_spelled}");
    assert_eq!(placed(8, &gone_spelled), Some(key), "{gone_spelled}");

    assert!(!disk_short_spelled(&folder), "{folder:?}");
    assert!(!disk_spell_now(&BOARD, &table, 9, &folder));
}

#[test]
fn a_spelling_the_file_system_stalls_on_costs_one_deadline_then_nothing() {
    static GATE: Mutex<()> = Mutex::new(());
    fn stalls(_: &Path) -> Option<PathBuf> {
        drop(GATE.lock().unwrap_or_else(PoisonError::into_inner));
        None
    }
    fn answers(through: &Path) -> Option<PathBuf> {
        Some(through.join("long"))
    }
    let stuck = |through: &Path| {
        DISK_SPELL_STUCK
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .iter()
            .any(|p| p == through)
    };
    let must_happen = aterm_spec::wait::MUST_HAPPEN;
    let tmp = aterm_tempfile::Builder::new()
        .prefix("aterm-hh-disk-stall-")
        .tempdir()
        .expect("temp dir");
    let through = tmp.path().join("STALLS~1");
    assert_eq!(
        disk_long_name_by(&through, answers, must_happen),
        Some(through.join("long"))
    );

    let held = GATE.lock().unwrap_or_else(PoisonError::into_inner);
    let (tx, rx) = std::sync::mpsc::channel();
    let asked = through.clone();
    std::thread::spawn(move || {
        let _ = tx.send(disk_long_name_by(&asked, stalls, Duration::from_millis(10)));
    });
    let answer = rx
        .recv_timeout(must_happen)
        .expect("the stalled call was waited on past its deadline");
    assert_eq!(answer, None, "a stalled call answers nothing");
    assert!(stuck(&through), "and is marked stuck");
    assert_eq!(
        disk_long_name_by(&through, answers, must_happen),
        None,
        "stuck: answered at once, never asked again"
    );

    #[cfg(windows)]
    let speller = {
        static BOARD: crate::disk_board::Shelf = crate::disk_board::Shelf::new();
        let cwd = tmp.path().join(r"SPELLS~1\x");
        let (tx, rx) = std::sync::mpsc::channel();
        let report = cwd.clone();
        std::thread::spawn(move || {
            let table = aterm_sysprobe::volumes::table();
            let _ = tx.send(disk_spell_with(&BOARD, &table, 7, &report, stalls));
        });
        let spelled = rx
            .recv_timeout(must_happen)
            .expect("the speller was held past its deadline");
        assert!(!spelled, "nothing recorded for {cwd:?}");
        assert!(BOARD.board_lock().spelled.is_empty());
        let through = aterm_sysprobe::paths::short_spelled(&cwd)
            .expect("8.3")
            .through;
        assert!(stuck(&through), "PREMISE: its call was made: {through:?}");
        through
    };

    drop(held);
    let deadline = Instant::now() + must_happen;
    while stuck(&through) {
        assert!(Instant::now() < deadline, "the stalled call never returned");
        std::thread::sleep(Duration::from_millis(1));
    }
    #[cfg(windows)]
    while stuck(&speller) {
        assert!(
            Instant::now() < deadline,
            "the speller's call never returned"
        );
        std::thread::sleep(Duration::from_millis(1));
    }
    assert_eq!(
        disk_long_name_by(&through, answers, must_happen),
        Some(through.join("long")),
        "asked again once it returned"
    );
}

#[test]
fn the_disk_watchs_threads_hold_the_error_boxes_off() {
    static LOOKING: AtomicBool = AtomicBool::new(false);
    static FIRST: Mutex<Option<bool>> = Mutex::new(None);
    fn read(_: Option<&Path>) {
        *FIRST.lock().unwrap_or_else(PoisonError::into_inner) =
            Some(aterm_sysprobe::errors_quiet());
    }
    let (tx, rx) = std::sync::mpsc::channel::<bool>();
    let tx = Mutex::new(tx);
    let run: Arc<DiskLookFn> = Arc::new(move |_sids, _cwds, _agents, _seen, _note| {
        let _ = tx.lock().unwrap().send(aterm_sysprobe::errors_quiet());
    });
    let note: Arc<NoteFn> = Arc::new(|_| {});
    let look = disk_watch(crate::session_store::new_store(), note, &LOOKING, run);
    look(&[]);
    let looked = rx
        .recv_timeout(aterm_spec::wait::MUST_HAPPEN)
        .expect("the look ran");
    assert!(looked, "the look's thread holds the error boxes off");

    assert!(first_reading_off_thread(None, read), "a thread of its own");
    let deadline = Instant::now() + aterm_spec::wait::MUST_HAPPEN;
    let first = loop {
        if let Some(quiet) = *FIRST.lock().unwrap_or_else(PoisonError::into_inner) {
            break quiet;
        }
        assert!(Instant::now() < deadline, "the first reading never ran");
        std::thread::sleep(Duration::from_millis(1));
    };
    assert!(
        first,
        "the first reading's thread holds the error boxes off"
    );
    assert_eq!(
        aterm_sysprobe::errors_quiet(),
        !cfg!(windows),
        "a thread with no guard has them on"
    );
}

#[test]
fn the_runs_of_short_looks_never_lend_each_other_a_count() {
    let tmp = aterm_tempfile::Builder::new()
        .prefix("aterm-hh-runs-")
        .tempdir()
        .expect("temp dir");
    let path = tmp.path().join("aterm.toml");
    std::fs::write(&path, "[disk]\napply = \"yes\"\n").expect("write aterm.toml");
    let faulty = aterm_agent::harness::cli::disk_config_read(Some(&path));
    assert!(faulty.off_by_fault, "{faulty:?}");
    let config = aterm_agent::harness::disk::Config::default();
    let low = Some(2 * (1u64 << 30));
    let runs = DiskRuns::new();

    for _ in 0..DISK_SHORT_LOOKS {
        let _ = disk_look_without_pass(&faulty, low, &runs);
    }
    assert_eq!(runs.pass(false, low, config), DiskOutcome::Short);
    assert!(matches!(
        runs.pass(false, low, config),
        DiskOutcome::Low { looks: 2, .. }
    ));

    let runs = DiskRuns::new();
    assert_eq!(runs.pass(false, low, config), DiskOutcome::Short);
    assert_eq!(disk_look_without_pass(&faulty, low, &runs), None);
    assert_eq!(runs.pass(false, low, config), DiskOutcome::Short);

    let runs = DiskRuns::new();
    assert_eq!(disk_look_without_pass(&faulty, low, &runs), None);
    assert_eq!(runs.pass(false, low, config), DiskOutcome::Short);
    assert_eq!(disk_look_without_pass(&faulty, low, &runs), None);
}

#[test]
fn the_settings_line_names_what_turned_cleanup_off() {
    let tmp = aterm_tempfile::Builder::new()
        .prefix("aterm-hh-faults-")
        .tempdir()
        .expect("temp dir");
    let path = tmp.path().join("aterm.toml");
    let notes_of = |note: HostNote| match note {
        HostNote::DiskSettingsOff { notes } => notes,
        other => panic!("not off: {other:?}"),
    };
    let text =
        "[disk]\nwarn_free_gib = \"many\"\ntarget_stale_days = -3\nzzz = 1\napply = \"yes\"\n";
    std::fs::write(&path, text).expect("write aterm.toml");
    let reading = aterm_agent::harness::cli::disk_config_read(Some(&path));
    let faults = aterm_agent::harness::cli::disk_faults(text);
    let off: Vec<String> = faults
        .iter()
        .filter(|f| f.removal_off)
        .map(|f| f.note.clone())
        .collect();
    assert!(
        !off.is_empty() && reading.notes.len() > off.len(),
        "{reading:?} / {faults:?}"
    );
    assert_eq!(notes_of(disk_settings_note(&reading, &faults)), off);
    assert_eq!(
        notes_of(disk_settings_note(&reading, &[])),
        reading.notes,
        "no faults to say which: every note"
    );

    let broken = "[disk\napply = true\n";
    std::fs::write(&path, broken).expect("write aterm.toml");
    let unread = aterm_agent::harness::cli::disk_config_read(Some(&path));
    let none = aterm_agent::harness::cli::disk_faults(broken);
    assert!(unread.off_by_fault && none.is_empty(), "{unread:?}");
    assert_eq!(notes_of(disk_settings_note(&unread, &none)), unread.notes);
    assert_eq!(unread.notes.len(), 1);
}

#[test]
fn the_disk_watch_searches_where_the_agents_work_and_the_shared_roots() {
    let root = std::path::Path::new(if cfg!(windows) { "C:\\" } else { "/" });
    let home = &root.join("nonexistent-home-for-disk-roots");
    let cwds = vec![home.join("work"), home.join("aterm-wt/x")];
    let alt = root.join("nonexistent-alt/.claude");
    let claude = aterm_agent::harness::disk::discover::RunningClaude {
        pid: u32::MAX - 2,
        started: None,
        cwd: Some(home.join("work")),
        profile: None,
        stored_login: true,
    };
    let running = aterm_agent::harness::disk::discover::Running {
        claudes: vec![claude.clone()],
        dirs: vec![alt.clone()],
    };
    let roots = disk_roots(&cwds, &[u32::MAX - 1], home, Ok(running));
    assert!(roots.claude_dirs.contains(&alt), "{roots:?}");
    assert_eq!(roots.claudes, [claude]);
    assert_eq!(roots.claude_unread, None);
    let unread = disk_roots(&cwds, &[], home, Err("unread".to_owned()));
    assert_eq!(unread.claude_unread.as_deref(), Some("unread"));
    assert_eq!(roots.cwds, cwds);
    assert_eq!(roots.home.as_deref(), Some(home.as_path()));
    assert!(roots.agent_target_dirs.is_empty(), "{roots:?}");
    let uid = aterm_agent::harness::disk::discover::own_uid();
    let tmp = if cfg!(windows) {
        "claude".to_owned()
    } else {
        format!("claude-{uid}")
    };
    assert!(
        roots.claude_tmp.as_ref().is_some_and(|t| t.ends_with(&tmp)),
        "{roots:?}"
    );
}

#[test]
fn the_owners_view_is_looked_at_only_when_something_it_shows_may_have_moved() {
    let world = Arc::new(World::default());
    let looks: Arc<Mutex<Vec<bool>>> = Arc::default();
    let next: Arc<Mutex<Option<u64>>> = Arc::default();
    let (l, n) = (Arc::clone(&looks), Arc::clone(&next));
    let hooks = Hooks {
        upgrade_view: Arc::new(move |look, _, _, _| {
            l.lock().unwrap().push(look);
            ViewNext {
                at: *n.lock().unwrap(),
                ..ViewNext::default()
            }
        }),
        ..hooks(&world, parking_body(&world))
    };
    let taken = || std::mem::take(&mut *looks.lock().unwrap());
    let mut view = ViewLook::default();
    let none: HashMap<String, FollowStamp> = HashMap::new();
    let one: HashMap<String, Program> = [("s-a".to_string(), Program::Claude)].into();
    let two: HashMap<String, Program> = [
        ("s-a".to_string(), Program::Claude),
        ("s-b".to_string(), Program::Claude),
    ]
    .into();
    assert_eq!(
        look_at_upgrades(&mut view, &one, &none, true, (0, 0), &hooks),
        None
    );
    assert_eq!(taken(), [true], "the first look");
    assert_eq!(
        look_at_upgrades(&mut view, &one, &none, true, (0, 0), &hooks),
        None
    );
    assert!(taken().is_empty(), "nothing moved: no look");
    let _ = look_at_upgrades(&mut view, &one, &none, true, (1, 0), &hooks);
    assert_eq!(taken(), [true], "a worker acted");
    let _ = look_at_upgrades(&mut view, &one, &none, true, (1, 1), &hooks);
    assert_eq!(taken(), [true], "an activation, or the owner's word");
    let _ = look_at_upgrades(&mut view, &two, &none, true, (1, 1), &hooks);
    assert_eq!(taken(), [true], "the roster changed");
    *next.lock().unwrap() = Some(crate::upgrade_host::now_s());
    let _ = look_at_upgrades(&mut view, &one, &none, true, (1, 1), &hooks);
    assert_eq!(taken(), [true]);
    *next.lock().unwrap() = None;
    assert!(
        look_at_upgrades(&mut view, &one, &none, true, (1, 1), &hooks).is_none(),
        "looked at again at its instant, and named none after"
    );
    assert_eq!(taken(), [true]);
    let _ = look_at_upgrades(&mut view, &one, &none, false, (1, 1), &hooks);
    let _ = look_at_upgrades(&mut view, &one, &none, false, (2, 2), &hooks);
    assert_eq!(taken(), [false], "stood down once");
    let _ = look_at_upgrades(&mut view, &one, &none, true, (2, 2), &hooks);
    assert_eq!(taken(), [true], "back on");
}

#[test]
fn the_records_folder_the_view_cannot_list_is_said_to_the_owner() {
    let world = Arc::new(World::default());
    let dir = PathBuf::from("/state/harness/upgrade");
    let unlisted: Arc<Mutex<Option<PathBuf>>> = Arc::default();
    let panics = Arc::new(AtomicBool::new(false));
    let (u, p) = (Arc::clone(&unlisted), Arc::clone(&panics));
    let hooks = Hooks {
        upgrade_view: Arc::new(move |look, _, _, _| {
            assert!(!(look && p.load(Ordering::SeqCst)), "a view that panics");
            ViewNext {
                unlisted: if look {
                    u.lock().unwrap().clone()
                } else {
                    None
                },
                ..ViewNext::default()
            }
        }),
        ..hooks(&world, parking_body(&world))
    };
    let said = || {
        world
            .notes
            .lock()
            .unwrap()
            .drain(..)
            .filter_map(|n| match n {
                HostNote::UpgradeRecords { unlisted } => Some(unlisted),
                _ => None,
            })
            .collect::<Vec<_>>()
    };
    let mut view = ViewLook::default();
    let none: HashMap<String, FollowStamp> = HashMap::new();
    let one: HashMap<String, Program> = [("s-a".to_string(), Program::Claude)].into();
    let _ = look_at_upgrades(&mut view, &one, &none, true, (0, 0), &hooks);
    assert_eq!(said(), [None], "the first look says the folder is listed");
    let _ = look_at_upgrades(&mut view, &one, &none, true, (1, 0), &hooks);
    assert!(said().is_empty(), "the same again: nothing said");
    *unlisted.lock().unwrap() = Some(dir.clone());
    let _ = look_at_upgrades(&mut view, &one, &none, true, (2, 0), &hooks);
    assert_eq!(said(), [Some(dir.clone())], "the folder it cannot list");
    let _ = look_at_upgrades(&mut view, &one, &none, true, (3, 0), &hooks);
    assert!(said().is_empty(), "said once while it stands");
    panics.store(true, Ordering::SeqCst);
    let _ = look_at_upgrades(&mut view, &one, &none, true, (4, 0), &hooks);
    assert!(said().is_empty(), "a panicked look says nothing");
    panics.store(false, Ordering::SeqCst);
    *unlisted.lock().unwrap() = None;
    let _ = look_at_upgrades(&mut view, &one, &none, true, (5, 0), &hooks);
    assert_eq!(said(), [None], "listed again: it ends");
    *unlisted.lock().unwrap() = Some(dir.clone());
    let _ = look_at_upgrades(&mut view, &one, &none, true, (6, 0), &hooks);
    assert_eq!(said(), [Some(dir)]);
    let _ = look_at_upgrades(&mut view, &one, &none, false, (6, 0), &hooks);
    assert_eq!(said(), [None], "stood down: it ends");
}

#[test]
fn the_records_the_view_cannot_read_are_said_to_the_owner() {
    let world = Arc::new(World::default());
    let file = PathBuf::from("/state/harness/upgrade/0badf00d.json");
    let unreadable: Arc<Mutex<Vec<PathBuf>>> = Arc::default();
    let panics = Arc::new(AtomicBool::new(false));
    let (u, p) = (Arc::clone(&unreadable), Arc::clone(&panics));
    let hooks = Hooks {
        upgrade_view: Arc::new(move |look, _, _, _| {
            assert!(!(look && p.load(Ordering::SeqCst)), "a view that panics");
            ViewNext {
                unreadable: if look {
                    u.lock().unwrap().clone()
                } else {
                    Vec::new()
                },
                ..ViewNext::default()
            }
        }),
        ..hooks(&world, parking_body(&world))
    };
    let said = || {
        world
            .notes
            .lock()
            .unwrap()
            .drain(..)
            .filter_map(|n| match n {
                HostNote::UpgradeRecordsUnreadable { files } => Some(files),
                _ => None,
            })
            .collect::<Vec<_>>()
    };
    let mut view = ViewLook::default();
    let none: HashMap<String, FollowStamp> = HashMap::new();
    let one: HashMap<String, Program> = [("s-a".to_string(), Program::Claude)].into();
    let _ = look_at_upgrades(&mut view, &one, &none, true, (0, 0), &hooks);
    assert_eq!(said(), [Vec::<PathBuf>::new()], "the first look says none");
    let _ = look_at_upgrades(&mut view, &one, &none, true, (1, 0), &hooks);
    assert!(said().is_empty(), "the same again: nothing said");
    *unreadable.lock().unwrap() = vec![file.clone()];
    let _ = look_at_upgrades(&mut view, &one, &none, true, (2, 0), &hooks);
    assert_eq!(said(), [vec![file.clone()]], "the record it cannot read");
    let _ = look_at_upgrades(&mut view, &one, &none, true, (3, 0), &hooks);
    assert!(said().is_empty(), "said once while it stands");
    panics.store(true, Ordering::SeqCst);
    let _ = look_at_upgrades(&mut view, &one, &none, true, (4, 0), &hooks);
    assert!(said().is_empty(), "a panicked look says nothing");
    panics.store(false, Ordering::SeqCst);
    unreadable.lock().unwrap().clear();
    let _ = look_at_upgrades(&mut view, &one, &none, true, (5, 0), &hooks);
    assert_eq!(said(), [Vec::<PathBuf>::new()], "read again: it ends");
    *unreadable.lock().unwrap() = vec![file.clone()];
    let _ = look_at_upgrades(&mut view, &one, &none, true, (6, 0), &hooks);
    assert_eq!(said(), [vec![file]]);
    let _ = look_at_upgrades(&mut view, &one, &none, false, (6, 0), &hooks);
    assert_eq!(said(), [Vec::<PathBuf>::new()], "stood down: it ends");
}

#[test]
fn the_owners_view_is_looked_at_by_the_wall_clock_after_a_sleep() {
    let world = Arc::new(World::default());
    let looks: Arc<Mutex<Vec<bool>>> = Arc::default();
    let l = Arc::clone(&looks);
    let hooks = Hooks {
        upgrade_view: Arc::new(move |look, _, _, _| {
            l.lock().unwrap().push(look);
            ViewNext {
                at: Some(crate::upgrade_host::now_s() + 3_600),
                ..ViewNext::default()
            }
        }),
        ..hooks(&world, parking_body(&world))
    };
    let taken = || std::mem::take(&mut *looks.lock().unwrap());
    let none: HashMap<String, FollowStamp> = HashMap::new();
    let one: HashMap<String, Program> = [("s-a".to_string(), Program::Claude)].into();
    let mut view = ViewLook::default();
    let _ = look_at_upgrades(&mut view, &one, &none, true, (0, 0), &hooks);
    assert_eq!(taken(), [true], "the first look");
    let wall = view.next_s.expect("the view's instant, on the wall clock");
    assert!(wall > crate::upgrade_host::now_s());
    view.next = Some(Instant::now() + Duration::from_secs(3_600));
    view.next_s = Some(crate::upgrade_host::now_s() - 1);
    let next = look_at_upgrades(&mut view, &one, &none, true, (0, 0), &hooks);
    assert_eq!(taken(), [true], "looked at by the wall clock");
    assert!(next.is_some() && view.next_s.is_some_and(|at| at > wall - 1));
    view.next = Some(Instant::now() + Duration::from_secs(3_600));
    view.next_s = None;
    let _ = look_at_upgrades(&mut view, &one, &none, true, (0, 0), &hooks);
    assert!(taken().is_empty(), "the look before: nothing");
    let until_timed = |wait: &dyn Fn() -> bool| {
        let bound = Instant::now() + Duration::from_secs(60);
        loop {
            if wait() {
                return true;
            }
            if Instant::now() >= bound {
                return false;
            }
        }
    };
    let far = Some(Instant::now() + Duration::from_secs(3_600));
    let started = Instant::now();
    let timed =
        until_timed(&|| bell_wait(bell_now(), far, Some(crate::upgrade_host::now_s() - 1)).1);
    assert!(timed, "the wall deadline passed: timed out");
    assert!(
        started.elapsed() < aterm_spec::wait::MUST_HAPPEN,
        "at once: {:?}",
        started.elapsed()
    );
    let started = Instant::now();
    let wall_ahead = Some(crate::upgrade_host::now_s() + 3_600);
    let timed = until_timed(&|| {
        let (_, timed) = bell_wait(
            bell_now(),
            Some(started + Duration::from_millis(50)),
            wall_ahead,
        );
        assert!(
            !timed || started.elapsed() >= Duration::from_millis(50),
            "timed out before the monotonic deadline"
        );
        timed
    });
    assert!(timed && started.elapsed() >= Duration::from_millis(50));
}

#[test]
fn the_owners_view_follows_the_screen_of_a_tab_whose_row_reads_a_live_status() {
    let world = Arc::new(World::default());
    let looks: Arc<Mutex<Vec<bool>>> = Arc::default();
    let follows: Arc<Mutex<Vec<String>>> = Arc::default();
    let (l, f) = (Arc::clone(&looks), Arc::clone(&follows));
    let hooks = Hooks {
        upgrade_view: Arc::new(move |look, _, _, _| {
            l.lock().unwrap().push(look);
            ViewNext {
                at: None,
                follows: f.lock().unwrap().clone(),
                ..ViewNext::default()
            }
        }),
        ..hooks(&world, parking_body(&world))
    };
    let taken = || std::mem::take(&mut *looks.lock().unwrap());
    let wanted: HashMap<String, Program> = [
        ("s-a".to_string(), Program::Claude),
        ("s-b".to_string(), Program::Claude),
    ]
    .into();
    let revs = |a: u64, b: u64| -> HashMap<String, FollowStamp> {
        [("s-a", a), ("s-b", b)]
            .into_iter()
            .map(|(sid, rev)| {
                (
                    sid.to_string(),
                    FollowStamp {
                        rev,
                        ..FollowStamp::default()
                    },
                )
            })
            .collect()
    };
    let mut view = ViewLook::default();
    let mut look =
        |a: u64, b: u64| look_at_upgrades(&mut view, &wanted, &revs(a, b), true, (0, 0), &hooks);

    *follows.lock().unwrap() = vec!["s-a".to_string()];
    assert_eq!(look(1, 1), None, "no instant named");
    assert_eq!(
        taken(),
        [true],
        "the first look: s-a's row reads its status"
    );
    let _ = look(1, 1);
    assert!(taken().is_empty(), "nothing moved: no look");
    let _ = look(1, 2);
    assert!(taken().is_empty(), "another tab's screen moved: no look");
    let settle = look(2, 2);
    assert_eq!(taken(), [true], "the followed tab's screen moved: a look");
    assert!(settle.is_some(), "and one more once the status is written");
    std::thread::sleep((hooks.pause)(STATUS_AFTER_SCREEN) + Duration::from_millis(20));
    assert_eq!(
        look(2, 2),
        None,
        "the look after the move names nothing more"
    );
    assert_eq!(taken(), [true], "the look after the move");
    let _ = look(2, 2);
    assert!(taken().is_empty(), "taken once");
    *follows.lock().unwrap() = Vec::new();
    assert_eq!(look(3, 2), None, "nothing more to follow");
    assert_eq!(taken(), [true], "the move while it was followed");
    let _ = look(4, 2);
    assert!(taken().is_empty(), "no longer followed: no look");
}

#[test]
fn a_headless_instance_runs_a_host_unless_the_policy_limits_it() {
    let world = Arc::new(World::default());
    world.set(&[("s-h", Program::Claude)]);
    let mut limited = on();
    limited.set("headless", "false").unwrap();
    let host = HostHandle::start(
        limited.clone(),
        true,
        false,
        hooks(&world, parking_body(&world)),
    );
    assert!(
        !host.is_running(),
        "headless under [harness] headless = false"
    );
    let host2 = HostHandle::start(on(), true, false, hooks(&world, parking_body(&world)));
    assert!(host2.is_running(), "headless by default");
    until("a worker for s-h", || host2.live() == ["s-h"]);
    host2.shutdown_and_join();
    host.shutdown_and_join();
    let windowed = HostHandle::start(limited, false, false, hooks(&world, parking_body(&world)));
    assert!(windowed.is_running());
    windowed.shutdown_and_join();
}

#[test]
fn a_crashs_surviving_record_is_what_the_layout_names_through_the_back_off() {
    const MOVED: &str = "feedface-1111-2222-3333-444455556666";
    let a = Arc::new(Acting::default());
    let sid = "s-exit-read";
    let held = snap(sid).session;
    let run = |session: &str, start: &str| {
        let mut hooks = a.hooks();
        let record = SessionFile {
            pid: snap(sid).pid,
            session_id: session.to_string(),
            cwd: "/".to_string(),
            version: "2.1.281".to_string(),
            status: "busy".to_string(),
            status_updated_at_ms: 1,
            proc_start: start.to_string(),
            kind: "interactive".to_string(),
            entrypoint: "cli".to_string(),
            claude_dir: None,
            profile: None,
        };
        hooks.acts.exit_look = Arc::new(move |_, _| {
            Some(ExitLook {
                running: false,
                record: Some(record.clone()),
                agent: aterm_agent::harness::upgrade::Agent::Claude,
                crashed: None,
                refused: false,
                restarted_itself: false,
            })
        });
        type Seen = (Option<String>, Option<String>, bool);
        let seen: Arc<Mutex<Vec<Seen>>> = Arc::default();
        let notes: Arc<Mutex<Vec<HostNote>>> = Arc::default();
        let (s1, n1, n2) = (Arc::clone(&seen), Arc::clone(&notes), Arc::clone(&notes));
        hooks.acts.relaunch = Arc::new(move |sid, _, snap, _, _, _| {
            let layout = published_snapshot(sid).and_then(|s| s.session);
            let told = n2
                .lock()
                .unwrap()
                .iter()
                .any(|n| matches!(n, HostNote::AgentPublished { .. }));
            s1.lock()
                .unwrap()
                .push((layout, snap.session.clone(), told));
            "ended:graceful-exit".to_string()
        });
        hooks.note = Arc::new(move |note| n1.lock().unwrap().push(note));
        hooks.pause = Arc::new(|_| Duration::ZERO);
        let job = WorkerJob {
            revoked: Arc::default(),
            sid: sid.to_string(),
            agent: Program::Claude,
            opts: SuperviseOpts::hosted(),
            stop: Arc::new(AtomicBool::new(true)),
            interrupt: Arc::default(),
            handover: Arc::default(),
            clear_badge: false,
            unset_mark: false,
            faults: Arc::default(),
            park: Arc::default(),
            look_at: Arc::default(),
            left: Arc::new(ExitWord::handed()),
            acting: Arc::default(),
            switches: {
                let s = Arc::new(Switches::default());
                s.set(&on(), false);
                s
            },
            kept: Arc::default(),
            note: Arc::default(),
            group: Arc::default(),
            host: std::sync::Weak::new(),
            watch_until: None,
            beside: Arc::default(),
            left_at_commit: Arc::default(),
        };
        with_kept(&job, |k| k.snapshot = Some(snap(sid)));
        publish_snapshot_for_test(sid, Some(&snap(sid)));
        on_agent_left(&job, &hooks);
        seen.lock().unwrap().clone()
    };
    let start = snap(sid).start;
    assert_eq!(
        run(MOVED, &start),
        [(Some(MOVED.to_string()), Some(MOVED.to_string()), true)],
        "the layout and what is owed name the conversation the crash left, the window told \
         (its journal captures again)"
    );
    assert_eq!(
        run(held.as_deref().unwrap(), &start),
        [(held.clone(), held.clone(), false)],
        "nothing moved, nothing told"
    );
    assert_eq!(
        run(MOVED, "Fri Sep 25 01:02:03 2026"),
        [(held.clone(), held.clone(), false)],
        "another start's record names nothing of this process"
    );
    publish_snapshot_for_test(sid, None);
}
#[test]
fn a_relaunch_only_lane_is_read_and_stepped_without_an_upgrade() {
    let a = Arc::new(Acting::default());
    a.due.store(true, Ordering::SeqCst);
    let hooks = a.hooks();
    a.set(&[
        ("s-m", Program::Muse),
        ("s-y", Program::Agy),
        ("s-g", Program::Gemini),
        ("s-c", Program::Codex),
    ]);
    let (sid, agent) = ("s-g", Program::Gemini);
    let job = left_job(sid, agent, &on());
    attach(&job, &hooks);
    assert!(
        with_kept(&job, |k| k.snapshot.is_some()),
        "{agent:?}: its run read"
    );
    assert!(
        !job.park.load(Ordering::SeqCst),
        "{agent:?}: no upgrade is ever due for it"
    );
    for (sid, agent) in [("s-m", Program::Muse), ("s-y", Program::Agy)] {
        let job = left_job(sid, agent, &on());
        attach(&job, &hooks);
        assert!(
            with_kept(&job, |k| k.snapshot.is_some()),
            "{agent:?}: its run read"
        );
        assert!(
            job.park.load(Ordering::SeqCst),
            "{agent:?}: parked for its upgrade"
        );
    }
    a.owed.store(true, Ordering::SeqCst);
    let reads = |sid: &str| {
        a.read
            .lock()
            .unwrap()
            .iter()
            .filter(|(s, _)| s == sid)
            .count()
    };
    for (n, (sid, agent)) in [
        ("s-m", Program::Muse),
        ("s-y", Program::Agy),
        ("s-g", Program::Gemini),
    ]
    .into_iter()
    .enumerate()
    {
        a.owed.store(true, Ordering::SeqCst);
        let before = reads(sid);
        let idle = idle_host(sid, agent, switched(&on()), a.hooks());
        let step = idle.at_idle().expect("its relaunch's owed carry-on");
        assert!(step.line.starts_with("carry-on step="), "{}", step.line);
        assert!(
            reads(sid) > before,
            "{agent:?}: read again at its idle point"
        );
        assert_eq!(a.carried.load(Ordering::SeqCst), n + 1, "{agent:?}");
    }
    a.owed.store(true, Ordering::SeqCst);
    let idle_codex = idle_host("s-c", Program::Codex, switched(&on()), a.hooks());
    assert!(idle_codex.at_idle().is_none(), "the sweep's: no step here");
    assert!(
        idle_codex.idle_step(IdlePoint::default()).is_none(),
        "the step's own guard"
    );
    assert_eq!(reads("s-c"), 0, "not read at its idle point");
    assert_eq!(
        a.carried.load(Ordering::SeqCst),
        3,
        "nothing carried for a codex-alab"
    );
}

