#[test]
fn a_relaunch_only_lanes_worker_carries_its_own_agents_record_alone() {
    let a = Arc::new(Acting::default());
    a.set(&[
        ("s-m", Program::Muse),
        ("s-y", Program::Agy),
        ("s-g", Program::Gemini),
        ("s-c", Program::Claude),
    ]);
    let lanes = [
        (
            "s-m",
            Program::Muse,
            upgrade::Agent::Muse,
            upgrade::Agent::Agy,
        ),
        (
            "s-y",
            Program::Agy,
            upgrade::Agent::Agy,
            upgrade::Agent::Gemini,
        ),
        (
            "s-g",
            Program::Gemini,
            upgrade::Agent::Gemini,
            upgrade::Agent::Muse,
        ),
    ];
    for (sid, program, _, other) in lanes {
        for by in [upgrade::Agent::Codex, other] {
            a.owed.store(true, Ordering::SeqCst);
            *a.owed_by.lock().unwrap() = Some(by);
            let job = left_job(sid, program, &on());
            attach(&job, &a.hooks());
            assert!(
                !job.park.load(Ordering::SeqCst),
                "{program:?} over {by:?}'s record: parked for nothing"
            );
            let idle = idle_host(sid, program, switched(&on()), a.hooks());
            assert!(
                idle.at_idle().is_none(),
                "{program:?} over {by:?}'s record: nothing carried"
            );
        }
    }
    assert_eq!(a.carried.load(Ordering::SeqCst), 0);
    a.owed.store(true, Ordering::SeqCst);
    *a.owed_by.lock().unwrap() = Some(upgrade::Agent::Codex);
    let claude = idle_host("s-c", Program::Claude, switched(&on()), a.hooks());
    let step = claude.at_idle().expect("whatever its tab owes");
    assert!(step.line.starts_with("carry-on step="), "{}", step.line);
    assert_eq!(a.carried.load(Ordering::SeqCst), 1);
    for (n, (sid, program, own, _)) in lanes.into_iter().enumerate() {
        a.owed.store(true, Ordering::SeqCst);
        *a.owed_by.lock().unwrap() = Some(own);
        let job = left_job(sid, program, &on());
        attach(&job, &a.hooks());
        assert!(job.park.load(Ordering::SeqCst), "{program:?}: parked for");
        let idle = idle_host(sid, program, switched(&on()), a.hooks());
        let step = idle.at_idle().expect("its own: carried");
        assert!(step.line.starts_with("carry-on step="), "{}", step.line);
        assert_eq!(a.carried.load(Ordering::SeqCst), n + 2, "{program:?}");
    }
    assert_eq!(
        *a.onlys.lock().unwrap(),
        [
            None,
            Some(upgrade::Agent::Muse),
            Some(upgrade::Agent::Agy),
            Some(upgrade::Agent::Gemini)
        ],
        "each carry-on told the one agent it carries; Claude Code's, any"
    );
}

#[test]
fn a_restored_landing_after_the_attach_asks_for_the_next_idle_point() {
    use aterm_agent::harness::relaunch::{AgentRun, AgyRun, GeminiRun, MuseRun};
    let _lane = crate::message_inbox::lane_test_guard();
    let world = Arc::new(World::default());
    let mut h = hooks(&world, parking_body(&world));
    h.acts.snapshot = Arc::new(|_| None);
    h.acts.open = Arc::new(|sid| matches!(sid, "s-m" | "s-y" | "s-g" | "s-c" | "s-x"));
    let host = HostHandle::start(on(), false, false, h.clone());
    let a = Arc::new(Acting::default());
    a.set(&[
        ("s-m", Program::Muse),
        ("s-y", Program::Agy),
        ("s-g", Program::Gemini),
        ("s-c", Program::Claude),
        ("s-x", Program::Codex),
    ]);
    let kept_of = |sid: &str| {
        Arc::clone(
            host.shared
                .kept
                .lock()
                .unwrap()
                .entry(sid.to_string())
                .or_default(),
        )
    };
    let worker = |sid: &str, agent: Program| {
        let mut idle = idle_host(sid, agent, switched(&on()), a.hooks());
        idle.kept = kept_of(sid);
        idle
    };
    let land = |agent: &RestoredAgent| {
        let _ = restored_landing_look(
            &host.shared,
            &h,
            &agent.sid,
            false,
            &agent.snap,
            &AtomicBool::new(false),
        );
    };
    let muse = {
        let mut agent = restored("s-m", "in tab 1");
        agent.snap.program = std::path::PathBuf::from("/opt/muse");
        agent.snap.argv = vec!["/opt/muse".to_string()];
        agent.snap.run = AgentRun::Muse(MuseRun {
            data: "/u/.local/share".into(),
            env: Vec::new(),
            workspace: None,
            lock: None,
            started_ms: 0,
            block: None,
        });
        agent
    };
    let idle = worker("s-m", Program::Muse);
    a.owed.store(true, Ordering::SeqCst);
    assert!(!idle.wants(), "owed after its attach: no point asked yet");
    land(&muse);
    assert!(idle.wants(), "the landing asks for its next idle point");
    let step = idle.at_idle().expect("its relaunch's owed carry-on");
    assert!(step.line.starts_with("carry-on step="), "{}", step.line);
    assert_eq!(a.carried.load(Ordering::SeqCst), 1);
    assert!(
        !with_kept_of(&idle.kept, |k| k.carry_asked),
        "the point answered the ask"
    );
    a.owed.store(true, Ordering::SeqCst);
    land(&muse);
    assert!(with_kept_of(&idle.kept, |k| k.carry_asked), "asked again");
    let mut job = left_job("s-m", Program::Muse, &on());
    job.kept = kept_of("s-m");
    attach(&job, &a.hooks());
    assert!(
        !with_kept(&job, |k| k.carry_asked),
        "the attach answered it"
    );
    assert!(job.park.load(Ordering::SeqCst), "parked for what is owed");
    let agy = {
        let mut agent = restored("s-y", "in tab 4");
        agent.snap.program = std::path::PathBuf::from("/opt/agy");
        agent.snap.argv = vec!["/opt/agy".to_string()];
        agent.snap.run = AgentRun::Agy(AgyRun {
            config: "/u/.gemini/antigravity-cli".into(),
            env: Vec::new(),
            lock: None,
            crash: None,
            started_ms: 0,
            block: None,
        });
        agent
    };
    let idle = worker("s-y", Program::Agy);
    a.owed.store(true, Ordering::SeqCst);
    assert!(
        !idle.wants(),
        "agy: owed after its attach, no point asked yet"
    );
    land(&agy);
    assert!(
        idle.wants(),
        "agy: the landing asks for its next idle point"
    );
    let step = idle.at_idle().expect("agy: its relaunch's owed carry-on");
    assert!(step.line.starts_with("carry-on step="), "{}", step.line);
    assert_eq!(a.carried.load(Ordering::SeqCst), 2);
    assert!(
        !with_kept_of(&idle.kept, |k| k.carry_asked),
        "agy: the point answered the ask"
    );
    a.owed.store(true, Ordering::SeqCst);
    land(&agy);
    assert!(
        with_kept_of(&idle.kept, |k| k.carry_asked),
        "agy: asked again"
    );
    let mut job = left_job("s-y", Program::Agy, &on());
    job.kept = kept_of("s-y");
    attach(&job, &a.hooks());
    assert!(
        !with_kept(&job, |k| k.carry_asked),
        "agy: the attach answered it"
    );
    assert!(
        job.park.load(Ordering::SeqCst),
        "agy: parked for what is owed"
    );
    let gemini = {
        let mut agent = restored("s-g", "in tab 5");
        agent.snap.program = std::path::PathBuf::from("/opt/homebrew/opt/node/bin/node");
        agent.snap.argv = vec![
            "/opt/homebrew/opt/node/bin/node".to_string(),
            "/opt/homebrew/bin/gemini".to_string(),
        ];
        agent.snap.run = AgentRun::Gemini(GeminiRun {
            home: "/u/.gemini".into(),
            chats: Some("/u/.gemini/tmp/w/chats".into()),
            env: Vec::new(),
            started_ms: 0,
            child: 0,
            unwitnessed: None,
            block: None,
        });
        agent
    };
    let idle = worker("s-g", Program::Gemini);
    a.owed.store(true, Ordering::SeqCst);
    assert!(
        !idle.wants(),
        "Gemini CLI: owed after its attach, no point asked yet"
    );
    land(&gemini);
    assert!(
        idle.wants(),
        "Gemini CLI: the landing asks for its next idle point"
    );
    let step = idle
        .at_idle()
        .expect("Gemini CLI: its relaunch's owed carry-on");
    assert!(step.line.starts_with("carry-on step="), "{}", step.line);
    assert_eq!(a.carried.load(Ordering::SeqCst), 3);
    assert!(
        !with_kept_of(&idle.kept, |k| k.carry_asked),
        "Gemini CLI: the point answered the ask"
    );
    a.owed.store(true, Ordering::SeqCst);
    land(&gemini);
    let mut job = left_job("s-g", Program::Gemini, &on());
    job.kept = kept_of("s-g");
    attach(&job, &a.hooks());
    assert!(
        !with_kept(&job, |k| k.carry_asked),
        "Gemini CLI: the attach answered it"
    );
    assert!(
        job.park.load(Ordering::SeqCst),
        "Gemini CLI: parked for what is owed"
    );
    let claude = worker("s-c", Program::Claude);
    land(&restored("s-c", "in tab 2"));
    assert!(
        !with_kept_of(&claude.kept, |k| k.carry_asked),
        "Claude Code"
    );
    assert!(!claude.wants(), "no point asked for Claude Code");
    let codex = worker("s-x", Program::Codex);
    land(&RestoredAgent {
        snap: codex_snap("s-x", &["/opt/codex"]),
        ..restored("s-x", "in tab 3")
    });
    assert!(!with_kept_of(&codex.kept, |k| k.carry_asked), "codex-alab");
    with_kept_of(&claude.kept, |k| k.carry_asked = true);
    assert!(!claude.wants(), "Claude Code's own path, as on main");
    host.shutdown_and_join();
}

#[test]
fn an_agent_the_harness_own_restart_ended_is_carried_whoever_is_at_the_tab() {
    let a = Arc::new(Acting::default());
    let hooks = a.hooks();
    let job = |agent: Program, relaunch: bool| {
        let mut cfg = on();
        if !relaunch {
            cfg.set("relaunch", "false").unwrap();
        }
        left_job("s-k", agent, &cfg)
    };
    let with_snapshot = |job: WorkerJob| {
        let now = a.pids.lock().unwrap().get("s-k").map(|(pid, _)| *pid);
        let pid = now.unwrap_or(snap("s-k").pid);
        with_kept(&job, |k| k.snapshot = Some(Snapshot { pid, ..snap("s-k") }));
        job
    };
    *a.human_ms.lock().unwrap() = Some(800);
    a.restart_in_flight.store(true, Ordering::SeqCst);
    on_agent_left(&with_snapshot(job(Program::Claude, false)), &hooks);
    assert_eq!(*a.carries.lock().unwrap(), [(false, Some(4242))]);
    assert!(
        a.relaunched.lock().unwrap().is_empty(),
        "never the relaunch on exit's attempt"
    );
    assert!(a.badges.lock().unwrap().is_empty(), "landed: nothing said");
    let asked = a.restarted_asked.lock().unwrap().len();
    on_agent_left(&with_snapshot(job(Program::Codex, true)), &hooks);
    assert_eq!(
        a.carries.lock().unwrap().len(),
        1,
        "a Codex's: never carried"
    );
    assert_eq!(
        a.restarted_asked.lock().unwrap().len(),
        asked,
        "no restart record of the lane's read for it"
    );
    assert!(
        a.badges.lock().unwrap().is_empty(),
        "nothing marked: {:?}",
        a.badges.lock().unwrap()
    );
    a.pauses.lock().unwrap().clear();
    *a.carry_steps.lock().unwrap() =
        VecDeque::from(["wait:held", "wait:held", "wait:held", "refused:stale-exit"]);
    on_agent_left(&with_snapshot(job(Program::Claude, true)), &hooks);
    assert_eq!(a.carries.lock().unwrap().len(), 5, "every attempt carried");
    let pauses = a.pauses.lock().unwrap().clone();
    assert!(
        pauses.len() == 4 && pauses.iter().all(|p| *p <= relaunch::CARRY_EVERY),
        "never a pause its record outlives: {pauses:?}"
    );
    let badges = a.badges.lock().unwrap().clone();
    assert!(
        matches!(&badges[..], [Some(cannot)]
            if cannot.contains("claude --resume ") && !cannot.contains("refused:")),
        "{badges:?}"
    );
    let told: Vec<RelaunchSay> = a
        .notes
        .lock()
        .unwrap()
        .iter()
        .filter_map(|n| match n {
            HostNote::Relaunch { said, .. } => Some(said.clone()),
            _ => None,
        })
        .collect();
    assert!(
        matches!(
            &told[..],
            [
                RelaunchSay::Failing {
                    blocked_by: Some("held"),
                    restarted: true,
                    command: None,
                },
                RelaunchSay::Cannot {
                    restarted: true,
                    command: Some(_),
                    ..
                }
            ]
        ),
        "{told:?}"
    );
    a.restart_in_flight.store(false, Ordering::SeqCst);
    a.badges.lock().unwrap().clear();
    on_agent_left(&with_snapshot(job(Program::Claude, true)), &hooks);
    assert_eq!(a.carries.lock().unwrap().len(), 5, "nothing carried");
    assert!(
        a.relaunched.lock().unwrap().is_empty(),
        "left to the person"
    );
    assert!(a.badges.lock().unwrap().is_empty());
    *a.human_ms.lock().unwrap() = None;
    a.held.store(false, Ordering::SeqCst);
    let informed = || {
        a.notes
            .lock()
            .unwrap()
            .iter()
            .filter(|n| matches!(n, HostNote::Inform { .. }))
            .count()
    };
    let before = informed();
    on_agent_left(&with_snapshot(job(Program::Codex, true)), &hooks);
    assert_eq!(a.carries.lock().unwrap().len(), 5, "nothing carried");
    assert!(
        a.relaunched.lock().unwrap().is_empty(),
        "never the lane's relaunch"
    );
    assert_eq!(informed(), before + 1, "said once");
    assert!(
        a.badges.lock().unwrap().iter().all(Option::is_none),
        "{:?}",
        a.badges.lock().unwrap()
    );
    let mut carried = 5;
    let mut relaunched = 0;
    for agent in [Program::Muse, Program::Agy] {
        a.restart_in_flight.store(true, Ordering::SeqCst);
        let asked = a.restarted_asked.lock().unwrap().len();
        on_agent_left(&with_snapshot(job(agent, true)), &hooks);
        carried += 1;
        assert_eq!(
            a.restarted_asked.lock().unwrap().len(),
            asked + 1,
            "{agent:?}: its restart record read"
        );
        assert_eq!(
            a.carries.lock().unwrap().len(),
            carried,
            "{agent:?}: carried as the restart's"
        );
        assert_eq!(
            a.relaunched.lock().unwrap().len(),
            relaunched,
            "{agent:?}: never the relaunch on exit's attempt"
        );
        a.restart_in_flight.store(false, Ordering::SeqCst);
        on_agent_left(&with_snapshot(job(agent, true)), &hooks);
        relaunched += 1;
        assert_eq!(
            a.carries.lock().unwrap().len(),
            carried,
            "{agent:?}: nothing carried"
        );
        assert_eq!(
            a.relaunched.lock().unwrap().len(),
            relaunched,
            "{agent:?}: its crash relaunched on exit"
        );
    }
    a.restart_in_flight.store(true, Ordering::SeqCst);
    let agent = Program::Gemini;
    let asked = a.restarted_asked.lock().unwrap().len();
    on_agent_left(&with_snapshot(job(agent, true)), &hooks);
    relaunched += 1;
    assert_eq!(
        a.restarted_asked.lock().unwrap().len(),
        asked,
        "{agent:?}: no restart record read"
    );
    assert_eq!(
        a.carries.lock().unwrap().len(),
        carried,
        "{agent:?}: nothing carried"
    );
    assert_eq!(
        a.relaunched.lock().unwrap().len(),
        relaunched,
        "{agent:?}: relaunched on exit"
    );
}
#[test]
fn a_restarts_carry_its_upgrade_row_answers_is_said_there_alone() {
    let a = Arc::new(Acting::default());
    let hooks = a.hooks();
    let claude = || {
        let job = left_job("s-k", Program::Claude, &on());
        with_kept(&job, |k| k.snapshot = Some(snap("s-k")));
        job
    };
    let run = |step: &'static str| {
        a.badges.lock().unwrap().clear();
        a.notes.lock().unwrap().clear();
        a.accounts_gone.lock().unwrap().clear();
        a.carries.lock().unwrap().clear();
        a.restart_in_flight.store(true, Ordering::SeqCst);
        *a.carry_steps.lock().unwrap() = [step].into();
        on_agent_left(&claude(), &hooks);
        let told: Vec<RelaunchSay> = a
            .notes
            .lock()
            .unwrap()
            .iter()
            .filter_map(|n| match n {
                HostNote::Relaunch { said, .. } => Some(said.clone()),
                _ => None,
            })
            .collect();
        (
            a.carries.lock().unwrap().len(),
            a.badges.lock().unwrap().clone(),
            told,
            a.accounts_gone.lock().unwrap().clone(),
        )
    };
    let (carries, badges, told, gone) = run("told:no-resume");
    assert_eq!(carries, 1, "never tried again");
    assert!(badges.iter().all(Option::is_none), "{badges:?}");
    assert_eq!(told, [RelaunchSay::Ended], "its own lines end");
    assert_eq!(gone, ["s-k"]);
    let (carries, badges, told, gone) = run("refused:no-resume");
    assert_eq!(carries, 1);
    assert!(
        matches!(&badges[..], [Some(mark)] if mark.contains("claude --resume ")),
        "{badges:?}"
    );
    assert!(
        matches!(
            &told[..],
            [RelaunchSay::Cannot {
                restarted: true,
                command: Some(_),
                marked: true,
                lost: true,
                new_tab: false,
                ..
            }]
        ),
        "{told:?}"
    );
    assert_eq!(gone, ["s-k"]);
}

#[test]
fn a_restarts_carry_that_landed_on_an_agent_gone_again_is_carried_once() {
    let a = Arc::new(Acting::default());
    a.open.lock().unwrap().insert("s-a".to_string());
    a.set(&[("s-a", Program::Claude)]);
    let ended = snap("s-a").pid;
    a.restarted_pids.lock().unwrap().push(ended);
    *a.carry_steps.lock().unwrap() = ["adopted", "refused:no-resume"].into();
    let mut h = a.hooks();
    let slot: Arc<Mutex<Option<HostHandle>>> = Arc::default();
    h.acts.carry = {
        let (a, slot) = (Arc::clone(&a), Arc::clone(&slot));
        let live = Arc::clone(&h.acts.carry);
        Arc::new(move |sid, grace, agent, pid, through_hand| {
            if a.carries.lock().unwrap().is_empty() {
                let host = slot.lock().unwrap().clone().expect("started");
                a.set(&[(sid, Program::Claude)]);
                until("the host read the line's agent", || {
                    host.shared
                        .lock()
                        .stops
                        .iter()
                        .all(|w| w.left.is(Word::Watching))
                });
                a.set(&[]);
            }
            live(sid, grace, agent, pid, through_hand)
        })
    };
    let host = HostHandle::start(on(), false, false, h);
    *slot.lock().unwrap() = Some(host.clone());
    a.attached(&host, "s-a");
    a.set(&[]);
    until("its worker ended", || {
        host.live().is_empty() && !a.carries.lock().unwrap().is_empty()
    });
    assert_eq!(*a.carries.lock().unwrap(), [(false, Some(ended))]);
    let cannot = a.notes.lock().unwrap().iter().any(|n| {
        matches!(
            n,
            HostNote::Relaunch {
                said: RelaunchSay::Cannot { .. },
                ..
            }
        )
    });
    assert!(!cannot, "{:?}", a.notes.lock().unwrap());
    assert!(
        a.badges.lock().unwrap().iter().all(Option::is_none),
        "{:?}",
        a.badges.lock().unwrap()
    );
    host.shutdown_and_join();
}

fn cfg_gen(host: &HostHandle) -> u64 {
    host.shared.lock().cfg_gen
}

#[test]
fn a_reload_restarts_workers_and_switching_off_stops_them() {
    let world = Arc::new(World::default());
    world.set(&[("s-r", Program::Claude)]);
    let host = HostHandle::start(off(), false, false, hooks(&world, parking_body(&world)));
    assert!(!host.is_running(), "enabled=false starts no host thread");
    host.set_config(on());
    assert!(host.is_running());
    until("first worker", || {
        host.live() == ["s-r"] && world.runs.load(Ordering::SeqCst) == 1
    });
    let generation = cfg_gen(&host);
    host.set_config(on());
    assert_eq!(cfg_gen(&host), generation);
    let mut changed = on();
    changed.set("dismiss_surveys", "false").unwrap();
    host.set_config(changed);
    until("restarted", || world.runs.load(Ordering::SeqCst) == 2);
    host.set_config(off());
    until("stopped", || host.live().is_empty());
    host.shutdown_and_join();
}

#[test]
fn a_relaunch_edit_is_news_to_a_waiting_limit_and_hands_no_worker_over() {
    let world = Arc::new(World::default());
    let host = HostHandle::start(on(), false, false, hooks(&world, parking_body(&world)));
    let news = || host.shared.switches.accounts_news.load(Ordering::SeqCst);
    let generation = cfg_gen(&host);
    let before = news();
    let mut no_relaunch = on();
    no_relaunch.set("relaunch", "false").unwrap();
    host.set_config(no_relaunch.clone());
    assert_eq!(cfg_gen(&host), generation, "masked: no worker handed over");
    assert_eq!(news(), before + 1);
    host.set_config(no_relaunch.clone());
    let mut upgrade_off = no_relaunch;
    upgrade_off.set("upgrade", "false").unwrap();
    host.set_config(upgrade_off);
    assert_eq!(news(), before + 1);
    host.set_config(on());
    assert_eq!(news(), before + 2);
    assert_eq!(cfg_gen(&host), generation);
    host.shutdown_and_join();
}

#[test]
fn every_supervisor_key_reaches_the_engine_and_only_those_restart_it() {
    let world = Arc::new(World::default());
    world.set(&[("s-i", Program::Claude)]);
    let host = HostHandle::start(on(), false, false, hooks(&world, parking_body(&world)));
    until("first worker", || world.runs.load(Ordering::SeqCst) == 1);
    let mut upgrade_off = on();
    upgrade_off.set("upgrade", "false").unwrap();
    upgrade_off.set("land_at", "18:00").unwrap();
    assert_eq!(effective(&upgrade_off), on());
    let generation = cfg_gen(&host);
    host.set_config(upgrade_off);
    assert_eq!(cfg_gen(&host), generation);
    let mut applied = on();
    for (key, value) in [
        ("trust_roots", "~/x*, /y"),
        ("continue", "false"),
        ("continue_per_hour", "1"),
        ("continue_text", "go"),
        ("rules_file", "/r"),
        ("retry_api_errors", "false"),
        ("model_fallback", ""),
        ("compact_on_context_wall", "false"),
        ("question_priority", "long-term"),
        ("approve", "safe"),
        ("usage_credits", "true"),
    ] {
        applied.set(key, value).unwrap();
    }
    assert_eq!(effective(&applied), applied);
    let opts = SuperviseOpts::hosted_with(&effective(&applied));
    assert_eq!(opts.policy.trust_roots, ["~/x*", "/y"]);
    assert!(!opts.policy.continue_policy && !opts.policy.retry_api_errors);
    assert_eq!(opts.policy.continue_per_hour, 1);
    assert_eq!(opts.policy.continue_text, "go");
    assert_eq!(
        opts.policy.rules_file.as_deref(),
        Some(std::path::Path::new("/r"))
    );
    assert_eq!(opts.policy.model_fallback, None);
    assert!(!opts.policy.compact_on_context_wall);
    assert_eq!(
        opts.policy.question_priority,
        aterm_agent::supervise::QuestionPriority::LongTerm,
        "how a question is answered reaches the engine"
    );
    assert_eq!(
        opts.policy.approve,
        aterm_agent::supervise::config::Approve::Safe,
        "the approval level reaches the engine (the Settings row `harness.approve`)"
    );
    assert!(
        opts.policy.usage_credits,
        "the credits opt-in reaches the engine: the approval and turn-end policies read it"
    );
    assert!(
        opts.yield_when_held,
        "a hosted loop parks behind another's claim"
    );
    host.set_config(applied);
    until("restarted", || world.runs.load(Ordering::SeqCst) == 2);
    host.shutdown_and_join();
}

#[test]
fn a_panicking_worker_is_restarted_past_its_budget_and_never_turned_off() {
    let world = Arc::new(World::default());
    world.set(&[("s-p", Program::Claude)]);
    let w = Arc::clone(&world);
    let body: Arc<BodyFn> = Arc::new(move |_job: &WorkerJob| {
        w.runs.fetch_add(1, Ordering::SeqCst);
        panic!("boom in the loop");
    });
    let host = HostHandle::start(on(), false, false, hooks(&world, body));
    until("restarted past the budget", || {
        world.runs.load(Ordering::SeqCst) >= RESTART_BUDGET + 3
    });
    assert_eq!(host.live(), ["s-p"], "never turned off");
    assert!(
        world.badges.lock().unwrap().is_empty(),
        "no tab is marked: {:?}",
        world.badges.lock().unwrap()
    );
    let told: Vec<HostNote> = world.notes.lock().unwrap().clone();
    let failing: Vec<&HostNote> = told
        .iter()
        .filter(|n| matches!(n, HostNote::SupervisorFailing { .. }))
        .collect();
    assert!(!failing.is_empty(), "{told:?}");
    assert!(
        failing
            .iter()
            .all(|n| matches!(n, HostNote::SupervisorFailing { sid, why, .. }
            if sid == "s-p" && why.contains("boom in the loop"))),
        "{failing:?}"
    );
    host.shutdown_and_join();
    assert!(
        world.notes.lock().unwrap().iter().any(|n| *n
            == HostNote::SupervisorSteady {
                sid: "s-p".to_string()
            }),
        "the worker's end ends what it told: {:?}",
        world.notes.lock().unwrap()
    );

    let world = Arc::new(World::default());
    world.set(&[("s-q", Program::Claude)]);
    let w = Arc::clone(&world);
    let body: Arc<BodyFn> = Arc::new(move |_job: &WorkerJob| {
        let n = w.runs.fetch_add(1, Ordering::SeqCst);
        if n < RESTART_BUDGET {
            panic!("boom");
        }
        while !_job.stop.load(Ordering::SeqCst) {
            std::thread::sleep(Duration::from_millis(2));
        }
        BodyEnd::Stopped
    });
    let host = HostHandle::start(on(), false, false, hooks(&world, body));
    until("running after its restarts", || {
        world.runs.load(Ordering::SeqCst) == RESTART_BUDGET + 1
    });
    assert!(world.badges.lock().unwrap().is_empty());
    assert!(
        !world
            .notes
            .lock()
            .unwrap()
            .iter()
            .any(|n| matches!(n, HostNote::SupervisorFailing { .. })),
        "{:?}",
        world.notes.lock().unwrap()
    );
    host.shutdown_and_join();
}

#[test]
fn a_failing_worker_waits_its_backoff_and_a_stop_cuts_it_short() {
    let world = Arc::new(World::default());
    world.set(&[("s-b", Program::Claude)]);
    let w = Arc::clone(&world);
    let started = Instant::now();
    let body: Arc<BodyFn> = Arc::new(move |_job: &WorkerJob| {
        w.runs.fetch_add(1, Ordering::SeqCst);
        BodyEnd::Failed("transient".to_string())
    });
    let host = HostHandle::start(on(), false, false, hooks(&world, body));
    until("past the budget: told", || {
        world
            .notes
            .lock()
            .unwrap()
            .iter()
            .any(|n| matches!(n, HostNote::SupervisorFailing { .. }))
    });
    let spent = started.elapsed();
    let floor: Duration = (1..=RESTART_BUDGET).map(quick_backoff).sum();
    assert!(spent >= floor, "{spent:?} < {floor:?}");
    host.shutdown_and_join();

    let world = Arc::new(World::default());
    world.set(&[("s-c", Program::Claude)]);
    let w = Arc::clone(&world);
    let body: Arc<BodyFn> = Arc::new(move |_job: &WorkerJob| {
        w.runs.fetch_add(1, Ordering::SeqCst);
        BodyEnd::Failed("transient".to_string())
    });
    let mut h = hooks(&world, body);
    h.backoff = Arc::new(|_| Duration::from_secs(3600));
    let host = HostHandle::start(on(), false, false, h);
    until("in the first backoff", || host.faults_of("s-c") >= 1);
    world.set(&[]);
    until("worker gone", || host.live().is_empty());
    assert_eq!(
        world.runs.load(Ordering::SeqCst),
        1,
        "the stop ended the first backoff; no restart ran"
    );
    host.shutdown_and_join();
}

#[test]
fn a_worker_relays_the_loops_next_try_and_a_worker_that_ends_clears_it() {
    use aterm_agent::supervise::{IdleHost, WaitPlan};
    const AT: i64 = 1_789_660_680;
    let wakes = |tell: &dyn Fn(&WorkerIdle)| {
        let (tx, rx) = std::sync::mpsc::channel();
        let tx = Mutex::new(tx);
        let (idle, _) = attended_worker_with(&Arc::new(World::default()), &[], |h| {
            h.waiting = waiting_hook(move |wake| {
                let _ = tx.lock().unwrap().send(wake);
            });
        });
        tell(&idle);
        drop(idle);
        rx.try_iter()
            .map(|wake| match wake {
                crate::Wake::HarnessWait { sid, plan } => (sid, plan.map(|p| p.at_unix)),
                _ => panic!("not the harness's wait"),
            })
            .collect::<Vec<_>>()
    };
    let plan = |at_unix: i64, why: &str| {
        Some(WaitPlan {
            at_unix,
            why: why.to_string(),
            kind: aterm_agent::supervise::WaitKind::Retry,
        })
    };
    let told = wakes(&|idle| {
        idle.waiting(plan(AT, "api-error retry 1"));
        idle.waiting(None);
        idle.waiting(plan(AT + 300, "api-error retry 2"));
    });
    let sid = || "s-att".to_string();
    assert_eq!(
        told,
        [
            (sid(), Some(AT)),
            (sid(), None),
            (sid(), Some(AT + 300)),
            (sid(), None)
        ],
        "the plans as told, a wait's end, and the worker's end"
    );
    assert_eq!(
        wakes(&|_| {}),
        [(sid(), None)],
        "nothing told: one clearing"
    );
}

/// What a worker handed the window of the loop's told waits, in order ([`WorkerIdle::waiting`]).
#[derive(Clone, Debug, PartialEq, Eq)]
enum Handed {
    Wait(Option<i64>),
    Pause(Option<crate::PausePlan>),
}

#[test]
fn a_worker_routes_a_retry_to_the_tab_and_a_back_off_to_the_glass() {
    use aterm_agent::supervise::{IdleHost, WaitKind, WaitPlan};
    const AT: i64 = 1_789_660_680;
    let (tx, rx) = std::sync::mpsc::channel::<Handed>();
    let (wait_tx, fact_tx) = (Mutex::new(tx.clone()), Mutex::new(tx));
    let (idle, _) = attended_worker_with(&Arc::new(World::default()), &[], |h| {
        h.waiting = Arc::new(move |_, plan| {
            let _ = wait_tx
                .lock()
                .unwrap()
                .send(Handed::Wait(plan.map(|p| p.at_unix)));
        });
        h.fact = Arc::new(move |_, fact| {
            if let crate::HarnessFact::Pause(pause) = fact {
                let _ = fact_tx.lock().unwrap().send(Handed::Pause(pause));
            }
        });
    });
    let plan = |at_unix: i64, kind: WaitKind| {
        Some(WaitPlan {
            at_unix,
            why: format!("{kind:?}"),
            kind,
        })
    };
    let pause = |at_unix: i64, short: u8| Some(crate::PausePlan { at_unix, short });
    let told = |tell: Option<WaitPlan>| {
        idle.waiting(tell);
        rx.try_iter().collect::<Vec<_>>()
    };
    assert_eq!(
        told(plan(AT, WaitKind::Retry)),
        [Handed::Wait(Some(AT))],
        "a next try: the tab's wait, as before"
    );
    assert_eq!(
        told(plan(AT + 120, WaitKind::BackOff { short: 3 })),
        [Handed::Wait(None), Handed::Pause(pause(AT + 120, 3))],
        "a back-off clears the try it replaces, and is the glass's pause"
    );
    assert_eq!(
        told(plan(AT + 600, WaitKind::Retry)),
        [Handed::Pause(None), Handed::Wait(Some(AT + 600))],
        "a try clears the pause it replaces"
    );
    assert_eq!(told(None), [Handed::Wait(None)], "none: the try cleared");
    assert_eq!(
        told(plan(AT + 900, WaitKind::BackOff { short: 1 })),
        [Handed::Pause(pause(AT + 900, 1))],
        "nothing to clear: the pause alone"
    );
    assert_eq!(told(None), [Handed::Pause(None)], "none: the pause cleared");
    assert_eq!(
        told(None),
        [Handed::Wait(None)],
        "CONTROL: nothing told, the tab's wait cleared as before"
    );
    assert_eq!(
        told(plan(AT + 960, WaitKind::Other)),
        [Handed::Wait(None)],
        "a kind the loop never tells is no wait"
    );
    told(plan(AT + 1200, WaitKind::BackOff { short: 2 }));
    drop(idle);
    let ended: Vec<Handed> = rx.try_iter().collect();
    assert_eq!(
        ended,
        [Handed::Wait(None), Handed::Pause(None)],
        "a worker that ends takes its try and its pause with it"
    );
}

#[test]
fn a_failed_loops_pause_is_cleared_before_the_restart() {
    use aterm_agent::supervise::{WaitKind, WaitPlan};
    let world = Arc::new(World::default());
    world.set(&[("s-p", Program::Claude)]);
    let pauses: Arc<Mutex<Vec<Option<crate::PausePlan>>>> = Arc::default();
    let (w, seen) = (Arc::clone(&world), Arc::new(Mutex::new(Vec::new())));
    let (s, p) = (Arc::clone(&seen), Arc::clone(&pauses));
    let body: Arc<BodyFn> = Arc::new(move |job: &WorkerJob| {
        s.lock().unwrap().push(p.lock().unwrap().clone());
        let run = w.runs.fetch_add(1, Ordering::SeqCst) + 1;
        if run == 1 {
            job.opts
                .idle_host
                .as_ref()
                .expect("the worker's idle host")
                .waiting(Some(WaitPlan {
                    at_unix: 1_789_660_680,
                    why: "2 short turn(s) in a row: 4 min back-off".to_string(),
                    kind: WaitKind::BackOff { short: 2 },
                }));
            return BodyEnd::Failed("transient".to_string());
        }
        while !job.stop.load(Ordering::SeqCst) {
            std::thread::sleep(Duration::from_millis(2));
        }
        BodyEnd::Stopped
    });
    let mut h = hooks(&world, body);
    let p = Arc::clone(&pauses);
    h.fact = Arc::new(move |_, fact| {
        if let crate::HarnessFact::Pause(pause) = fact {
            p.lock().unwrap().push(pause);
        }
    });
    let host = HostHandle::start(on(), false, false, h);
    until("restarted", || world.runs.load(Ordering::SeqCst) >= 2);
    let before_restart = seen.lock().unwrap()[1].clone();
    assert_eq!(
        before_restart.first(),
        Some(&Some(crate::PausePlan {
            at_unix: 1_789_660_680,
            short: 2
        })),
        "control: the pause was told: {before_restart:?}"
    );
    assert_eq!(
        before_restart.last(),
        Some(&None),
        "the pause gone before the second run: {before_restart:?}"
    );
    host.shutdown_and_join();
}

#[test]
fn a_failed_loops_next_try_is_cleared_before_the_restart() {
    use aterm_agent::supervise::WaitPlan;
    let world = Arc::new(World::default());
    world.set(&[("s-f", Program::Claude)]);
    let (w, seen) = (Arc::clone(&world), Arc::new(Mutex::new(Vec::new())));
    let s = Arc::clone(&seen);
    let body: Arc<BodyFn> = Arc::new(move |job: &WorkerJob| {
        s.lock().unwrap().push(w.told.lock().unwrap().len());
        let run = w.runs.fetch_add(1, Ordering::SeqCst) + 1;
        if run == 1 {
            job.opts
                .idle_host
                .as_ref()
                .expect("the worker's idle host")
                .waiting(Some(WaitPlan {
                    at_unix: 1_789_660_680,
                    why: "api-error retry 1".to_string(),
                    kind: aterm_agent::supervise::WaitKind::Retry,
                }));
            return BodyEnd::Failed("transient".to_string());
        }
        while !job.stop.load(Ordering::SeqCst) {
            std::thread::sleep(Duration::from_millis(2));
        }
        BodyEnd::Stopped
    });
    let host = HostHandle::start(on(), false, false, hooks(&world, body));
    until("restarted", || world.runs.load(Ordering::SeqCst) >= 2);
    let told = world.told.lock().unwrap().clone();
    assert!(
        matches!(told.as_slice(), [(_, Some(_)), (_, None), ..]),
        "the plan, then none — before the second run: {told:#?}"
    );
    assert!(
        seen.lock().unwrap()[1] >= 2,
        "the restart began after the window was told: {:?}",
        seen.lock().unwrap()
    );
    host.shutdown_and_join();
}
#[test]
fn a_host_thread_that_panicked_is_started_again_in_place() {
    let world = Arc::new(World::default());
    world.set(&[("s-h", Program::Claude)]);
    let calls = Arc::new(AtomicUsize::new(0));
    let mut h = hooks(&world, parking_body(&world));
    let (w, c) = (Arc::clone(&world), Arc::clone(&calls));
    h.roster = Arc::new(move || {
        assert!(
            c.fetch_add(1, Ordering::SeqCst) > 0,
            "the first roster read panics"
        );
        w.roster
            .lock()
            .unwrap()
            .iter()
            .map(|(sid, program)| (sid.clone(), *program, FollowStamp::default()))
            .collect()
    });
    let host = HostHandle::start(on(), false, false, h);
    until("supervised again, with no policy change", || {
        world.runs.load(Ordering::SeqCst) == 1
    });
    host.shutdown_and_join();

    let world = Arc::new(World::default());
    world.set(&[("s-a", Program::Claude)]);
    let mut h = hooks(&world, parking_body(&world));
    let reads = Arc::new(AtomicUsize::new(0));
    let r = Arc::clone(&reads);
    h.roster = Arc::new(move || {
        r.fetch_add(1, Ordering::SeqCst);
        panic!("the host run panics");
    });
    let host = HostHandle::start(on(), false, false, h);
    until("started again more than three times", || {
        reads.load(Ordering::SeqCst) > 6
    });
    assert!(
        !host
            .thread
            .lock()
            .unwrap()
            .as_ref()
            .is_some_and(JoinHandle::is_finished),
        "never given up on"
    );
    host.shutdown_and_join();

    let world = Arc::new(World::default());
    world.set(&[("s-b", Program::Claude)]);
    let mut h = hooks(&world, parking_body(&world));
    h.roster = Arc::new(|| panic!("the host run panics"));
    h.backoff = Arc::new(|_| Duration::from_secs(3600));
    let host = HostHandle::start(on(), false, false, h);
    std::thread::sleep(Duration::from_millis(200));
    let asked = Instant::now();
    host.shutdown_and_join();
    assert!(
        asked.elapsed() < Duration::from_secs(60),
        "the back-off held the shutdown for {:?}",
        asked.elapsed()
    );
    assert!(
        host.thread
            .lock()
            .unwrap()
            .as_ref()
            .is_none_or(JoinHandle::is_finished),
        "the host thread ended"
    );
}

#[test]
fn one_tabs_part_of_a_host_pass_that_panics_is_that_tabs_alone() {
    for panics in [true, false] {
        let world = Arc::new(World::default());
        world.set(&[("s-pa", Program::Claude)]);
        let mut h = hooks(&world, parking_body(&world));
        h.backoff = Arc::new(|_| Duration::from_secs(3600));
        let asked = Arc::new(AtomicUsize::new(0));
        let a = Arc::clone(&asked);
        h.acts.open = Arc::new(move |sid| {
            if sid == "s-pa" {
                a.fetch_add(1, Ordering::SeqCst);
                assert!(!panics, "the look at the tab panics (a test's)");
            }
            true
        });
        let host = HostHandle::start(on(), false, false, h);
        until("s-pa's worker runs", || {
            world.runs.load(Ordering::SeqCst) == 1
        });
        world.set(&[("s-pb", Program::Claude)]);
        until("the new tab's worker runs", || {
            world.runs.load(Ordering::SeqCst) == 2
        });
        assert!(asked.load(Ordering::SeqCst) >= 1, "panics={panics}: asked");
        if panics {
            let reads = world.word_reads.load(Ordering::SeqCst);
            ring();
            until("a pass after the new tab's start", || {
                world.word_reads.load(Ordering::SeqCst) > reads
            });
            assert_eq!(
                asked.load(Ordering::SeqCst),
                1,
                "not asked again within its rung"
            );
        }
        host.shutdown_and_join();
    }
}

#[test]
fn a_tabs_stage_that_panicked_once_is_asked_again_after_its_rung() {
    let world = Arc::new(World::default());
    world.set(&[("s-pa", Program::Claude)]);
    let ends: Arc<Mutex<Vec<(String, bool)>>> = Arc::default();
    let (w, e) = (Arc::clone(&world), Arc::clone(&ends));
    let body: Arc<BodyFn> = Arc::new(move |job: &WorkerJob| {
        w.runs.fetch_add(1, Ordering::SeqCst);
        let me = std::thread::current();
        *job.interrupt.lock().unwrap() = Some(Box::new(move || me.unpark()));
        while !job.stop.load(Ordering::SeqCst) {
            std::thread::park();
        }
        e.lock()
            .unwrap()
            .push((job.sid.clone(), job.left.is(Word::Left)));
        BodyEnd::Stopped
    });
    let mut h = hooks(&world, body);
    let asked = Arc::new(AtomicUsize::new(0));
    let a = Arc::clone(&asked);
    h.acts.open = Arc::new(move |sid| {
        if sid == "s-pa" {
            assert!(
                a.fetch_add(1, Ordering::SeqCst) > 0,
                "the look at the tab panics once (a test's)"
            );
        }
        true
    });
    let host = HostHandle::start(on(), false, false, h);
    until("s-pa's worker runs", || {
        world.runs.load(Ordering::SeqCst) == 1
    });
    world.set(&[("s-pb", Program::Claude)]);
    until("the new tab's worker runs", || {
        world.runs.load(Ordering::SeqCst) == 2
    });
    until("the look panicked once", || {
        asked.load(Ordering::SeqCst) >= 1
    });
    until(
        "s-pa's worker is handed its exit after the one panic",
        || {
            ring();
            ends.lock()
                .unwrap()
                .iter()
                .any(|(sid, left)| sid == "s-pa" && *left)
        },
    );
    host.shutdown_and_join();
}

#[test]
fn a_stages_rung_still_to_come_is_a_look_and_one_passed_is_not() {
    let world = Arc::new(World::default());
    let host = HostHandle::start(off(), false, false, hooks(&world, parking_body(&world)));
    let now = Instant::now();
    let fault = |again_at| HostFault {
        panics: 1,
        again_at,
    };
    {
        let mut faults = host.shared.host_faults.lock().unwrap();
        faults
            .entry("s-1".to_string())
            .or_default()
            .insert("its worker's start", fault(now - Duration::from_secs(5)));
    }
    assert_eq!(host_faults_due(&host.shared, now), None, "a rung passed");
    let soon = now + Duration::from_secs(5);
    let later = now + Duration::from_secs(60);
    {
        let mut faults = host.shared.host_faults.lock().unwrap();
        faults
            .entry("s-2".to_string())
            .or_default()
            .insert("its worker's visit", fault(later));
        faults
            .entry("s-2".to_string())
            .or_default()
            .insert("the end of its lost word", fault(soon));
    }
    assert_eq!(
        host_faults_due(&host.shared, now),
        Some(soon),
        "the earliest still to come"
    );
    host.shutdown_and_join();
}

#[test]
fn a_look_at_a_closed_tab_that_panicked_waits_out_its_rung() {
    let world = Arc::new(World::default());
    world.set(&[("s-px", Program::Claude)]);
    let ended = Arc::new(AtomicBool::new(false));
    let (w, e) = (Arc::clone(&world), Arc::clone(&ended));
    let body: Arc<BodyFn> = Arc::new(move |job: &WorkerJob| {
        w.runs.fetch_add(1, Ordering::SeqCst);
        let me = std::thread::current();
        *job.interrupt.lock().unwrap() = Some(Box::new(move || me.unpark()));
        while !job.stop.load(Ordering::SeqCst) {
            std::thread::park();
        }
        e.store(true, Ordering::SeqCst);
        BodyEnd::Stopped
    });
    let mut h = hooks(&world, body);
    h.backoff = Arc::new(|_| Duration::from_secs(3600));
    let panicked = Arc::new(AtomicUsize::new(0));
    let (p, e) = (Arc::clone(&panicked), Arc::clone(&ended));
    h.acts.open = Arc::new(move |sid| {
        if sid == "s-px" && e.load(Ordering::SeqCst) {
            p.fetch_add(1, Ordering::SeqCst);
            panic!("the look at the closed tab panics (a test's)");
        }
        false
    });
    let host = HostHandle::start(on(), false, false, h);
    until("s-px's worker runs", || {
        world.runs.load(Ordering::SeqCst) == 1
    });
    world.set(&[]);
    let faulted = || {
        host.shared
            .host_faults
            .lock()
            .unwrap()
            .get("s-px")
            .is_some_and(|f| f.contains_key("the look at whether its tab is open"))
    };
    until("the closed tab's look panicked", || {
        ring();
        faulted()
    });
    let asked = panicked.load(Ordering::SeqCst);
    world.passes();
    world.passes();
    assert_eq!(
        panicked.load(Ordering::SeqCst),
        asked,
        "not asked again within its rung"
    );
    assert!(faulted(), "its fault is kept while its session is kept");
    host.shutdown_and_join();
}

#[test]
fn a_session_parked_behind_another_claim_is_named_to_the_owners_view() {
    let world = Arc::new(World::default());
    world.set(&[("s-held", Program::Claude), ("s-run", Program::Claude)]);
    let parks = parking_body(&world);
    let refused = Arc::new(AtomicBool::new(true));
    let r = Arc::clone(&refused);
    let body: Arc<BodyFn> = Arc::new(move |job: &WorkerJob| {
        if job.sid == "s-held" && r.load(Ordering::SeqCst) {
            return BodyEnd::Held("someone-else".to_string());
        }
        parks(job)
    });
    let named: Arc<Mutex<Vec<Vec<String>>>> = Arc::default();
    let n = Arc::clone(&named);
    let hooks = Hooks {
        upgrade_view: Arc::new(move |look, claimed, _, _| {
            if look {
                n.lock().unwrap().push(claimed.to_vec());
            }
            ViewNext::default()
        }),
        ..hooks(&world, body)
    };
    let last = || named.lock().unwrap().last().cloned();
    let host = HostHandle::start(on(), false, false, hooks);
    until("the parked session named", || {
        last().is_some_and(|c| c == ["s-held"])
    });
    until("the other one's worker runs", || {
        host.live().contains(&"s-run".to_string())
    });
    refused.store(false, Ordering::SeqCst);
    world.released.fetch_add(1, Ordering::SeqCst);
    ring();
    until("claimed again, and named no more", || {
        host.live().contains(&"s-held".to_string()) && last().is_some_and(|c| c.is_empty())
    });
    assert!(
        named
            .lock()
            .unwrap()
            .iter()
            .all(|c| !c.contains(&"s-run".to_string())),
        "NEGATIVE CONTROL: {:?}",
        named.lock().unwrap()
    );
    host.shutdown_and_join();
}

#[test]
fn an_off_session_is_named_to_the_owners_view() {
    type Looks = Mutex<Vec<(Vec<String>, Vec<String>)>>;
    let world = Arc::new(World::default());
    world.set(&[("s-off", Program::Claude), ("s-on", Program::Claude)]);
    let named: Arc<Looks> = Arc::default();
    let n = Arc::clone(&named);
    let hooks = Hooks {
        upgrade_view: Arc::new(move |look, claimed, off, _| {
            if look {
                n.lock().unwrap().push((claimed.to_vec(), off.to_vec()));
            }
            ViewNext::default()
        }),
        ..hooks(&world, parking_body(&world))
    };
    let last_off = || named.lock().unwrap().last().map(|(_, off)| off.clone());
    let host = HostHandle::start(on(), false, false, hooks);
    until("both supervised, and looked at", || {
        host.live() == ["s-off", "s-on"] && last_off().is_some()
    });
    assert_eq!(last_off(), Some(Vec::new()), "none Off yet");
    world.word("s-off", Some(Autopilot::Off));
    until("the Off session named", || {
        last_off().is_some_and(|off| off == ["s-off"])
    });
    until("its worker stopped", || host.live() == ["s-on"]);
    world.word("s-off", None);
    until("supervised again, and named no more", || {
        host.live() == ["s-off", "s-on"] && last_off().is_some_and(|off| off.is_empty())
    });
    assert!(
        named
            .lock()
            .unwrap()
            .iter()
            .all(|(claimed, off)| claimed.is_empty() && !off.contains(&"s-on".to_string())),
        "NEGATIVE CONTROL: {:?}",
        named.lock().unwrap()
    );
    host.shutdown_and_join();
}

#[test]
fn an_agent_switched_off_is_named_to_the_owners_view() {
    type Looks = Mutex<Vec<(Vec<String>, Vec<String>, Vec<String>)>>;
    let world = Arc::new(World::default());
    world.set(&[("s-codex", Program::Codex), ("s-claude", Program::Claude)]);
    let named: Arc<Looks> = Arc::default();
    let n = Arc::clone(&named);
    let hooks = Hooks {
        upgrade_view: Arc::new(move |look, claimed, off, agent_off| {
            if look {
                n.lock()
                    .unwrap()
                    .push((claimed.to_vec(), off.to_vec(), agent_off.to_vec()));
            }
            ViewNext::default()
        }),
        ..hooks(&world, parking_body(&world))
    };
    let last = || {
        named
            .lock()
            .unwrap()
            .last()
            .map(|(_, _, agent_off)| agent_off.clone())
    };
    let host = HostHandle::start(on(), false, false, hooks);
    until("both supervised, and looked at", || {
        host.live() == ["s-claude", "s-codex"] && last().is_some()
    });
    assert_eq!(last(), Some(Vec::new()), "none switched off yet");
    let mut codex_off = on();
    codex_off.off.push(Program::Codex);
    host.set_config(codex_off);
    until("the switched-off tab named", || {
        last().is_some_and(|tabs| tabs == ["s-codex"])
    });
    until("its worker revoked", || host.live() == ["s-claude"]);
    host.set_config(on());
    until("supervised again, and named no more", || {
        host.live() == ["s-claude", "s-codex"] && last().is_some_and(|tabs| tabs.is_empty())
    });
    assert!(
        named
            .lock()
            .unwrap()
            .iter()
            .all(|(claimed, off, agent_off)| {
                claimed.is_empty() && off.is_empty() && !agent_off.contains(&"s-claude".to_string())
            }),
        "NEGATIVE CONTROL: {:?}",
        named.lock().unwrap()
    );
    host.shutdown_and_join();
}

fn claiming_body(world: &Arc<World>, claimed: &Arc<Mutex<Vec<String>>>) -> Arc<BodyFn> {
    let (park, claimed) = (parking_body(world), Arc::clone(claimed));
    Arc::new(move |job: &WorkerJob| {
        claimed.lock().unwrap().push(job.sid.clone());
        park(job)
    })
}

#[test]
fn the_successor_harness_waits_a_renewal_before_claiming_an_adopted_session() {
    assert!(
        ADOPTED_CLAIM_GRACE > 2 * aterm_agent::supervise::CLAIM_RENEW,
        "{ADOPTED_CLAIM_GRACE:?}"
    );
    let resumed_with = |grace: Duration| {
        let world = Arc::new(World::default());
        world.set(&[
            ("s-adopted", Program::Claude),
            ("s-vouched", Program::Claude),
        ]);
        let claimed: Arc<Mutex<Vec<String>>> = Arc::default();
        let host = HostHandle::start(
            on(),
            false,
            true,
            hooks(&world, claiming_body(&world, &claimed)),
        );
        host.defer_adopted_claims(vec!["s-adopted".to_string()], grace);
        assert!(!host.is_running());
        let resumed = Instant::now();
        host.resume();
        until("the vouched session is claimed at resume", || {
            claimed.lock().unwrap().iter().any(|sid| sid == "s-vouched")
        });
        until("the adopted session watched", || {
            host.live() == ["s-adopted", "s-vouched"]
        });
        (host, claimed, resumed)
    };
    let (host, claimed, _) = resumed_with(Duration::from_secs(3600));
    assert_eq!(
        *claimed.lock().unwrap(),
        ["s-vouched"],
        "held off through its grace"
    );
    assert_eq!(host.held_off(), ["s-adopted"]);
    host.shutdown_and_join();

    let grace = Duration::from_millis(100);
    let (host, claimed, resumed) = resumed_with(grace);
    until("claimed once its grace has run out", || {
        claimed.lock().unwrap().len() == 2
    });
    assert!(
        resumed.elapsed() >= grace,
        "not before the grace: {:?}",
        resumed.elapsed()
    );
    assert!(host.held_off().is_empty(), "the grace is over");
    assert_eq!(host.live(), ["s-adopted", "s-vouched"], "the same workers");
    let mut claims = claimed.lock().unwrap().clone();
    claims.sort();
    assert_eq!(claims, ["s-adopted", "s-vouched"], "one claim each");
    host.shutdown_and_join();

    let world = Arc::new(World::default());
    world.set(&[("s-late", Program::Claude)]);
    let claimed: Arc<Mutex<Vec<String>>> = Arc::default();
    let host = HostHandle::start(
        on(),
        false,
        false,
        hooks(&world, claiming_body(&world, &claimed)),
    );
    until("supervised", || *claimed.lock().unwrap() == ["s-late"]);
    let named = Instant::now();
    host.defer_adopted_claims(vec!["s-next".to_string()], grace);
    world.set(&[("s-late", Program::Claude), ("s-next", Program::Claude)]);
    until("claimed after its grace", || {
        *claimed.lock().unwrap() == ["s-late", "s-next"]
    });
    assert!(named.elapsed() >= grace, "{:?}", named.elapsed());
    host.shutdown_and_join();
}

fn successor(a: &Arc<Acting>, held: &[(&str, Duration)]) -> HostHandle {
    let host = HostHandle::start(on(), false, true, a.hooks());
    for (sid, grace) in held {
        host.defer_adopted_claims(vec![(*sid).to_string()], *grace);
    }
    host.resume();
    host
}

#[test]
fn an_agent_that_crashes_inside_its_adopted_claim_grace_is_relaunched() {
    let a = Arc::new(Acting::default());
    a.open.lock().unwrap().insert("s-a".to_string());
    a.set(&[("s-a", Program::Claude)]);
    let host = successor(&a, &[("s-a", Duration::from_secs(3600))]);
    until("the adopted agent read inside its grace", || {
        a.read_in("s-a")
    });
    assert_eq!(host.held_off(), ["s-a"], "inside its grace");
    a.set(&[]);
    until("relaunched", || a.relaunched.lock().unwrap().len() == 1);
    assert_eq!(*a.exit_records.lock().unwrap(), ["survived"]);
    assert_eq!(
        *a.resumed.lock().unwrap(),
        [snap("s-a").session],
        "on its conversation"
    );
    assert!(
        a.ran.lock().unwrap().is_empty(),
        "no loop ran: nothing claimed, nothing typed but the relaunch"
    );
    assert!(
        host.pending_restored().is_empty(),
        "the worker's own relaunch"
    );
    host.shutdown_and_join();
}

fn self_copy(
    a: &Acting,
    sid: &str,
    seen: self_claimed::Seen,
    resume: Result<Vec<String>, &'static str>,
) -> self_claimed::Copy {
    let pid = snap(sid).pid;
    self_claimed::Copy {
        pid,
        start: a.start_of(sid, pid),
        home: "/u/.codex".into(),
        seen,
        resume: resume.map(|argv| self_claimed::Resume {
            argv,
            session: "0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string(),
            codex_home: None,
            cwd: None,
        }),
    }
}

fn standing_record() -> self_claimed::Seen {
    self_claimed::Seen::Present(self_claimed::Record {
        pid: 4242,
        session_id: Some("0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string()),
        resume_argv: None,
        env: Vec::new(),
        status: Some("busy".to_string()),
        exit: None,
        cwd: None,
        draft_empty: None,
        frame: None,
        initializing: false,
    })
}

#[test]
fn a_proven_self_claim_makes_the_worker_watch_only_in_both_orders() {
    let holder = "codex-alab@4242".to_string();
    let a = Arc::new(Acting::default());
    let sid = "s-selfclaim-met";
    a.open.lock().unwrap().insert(sid.to_string());
    a.claims
        .lock()
        .unwrap()
        .insert(sid.to_string(), holder.clone());
    a.proven.lock().unwrap().insert(sid.to_string());
    a.set(&[(sid, Program::Codex)]);
    let host = HostHandle::start(on(), false, false, a.hooks());
    until("its loop runs beside the self-claim", || {
        a.beside_ran
            .lock()
            .unwrap()
            .contains(&(sid.to_string(), Some(holder.clone())))
    });
    assert_eq!(host.live(), [sid], "a watch-only worker, never parked");
    host.shutdown_and_join();

    let a = Arc::new(Acting::default());
    let sid = "s-selfclaim-replaced";
    a.open.lock().unwrap().insert(sid.to_string());
    a.set(&[(sid, Program::Codex)]);
    let host = HostHandle::start(on(), false, false, a.hooks());
    until("its loop runs beside the agent itself", || {
        a.beside_ran
            .lock()
            .unwrap()
            .contains(&(sid.to_string(), Some(UNCLAIMED_CODEX_ALAB.to_string())))
    });
    a.claims
        .lock()
        .unwrap()
        .insert(sid.to_string(), holder.clone());
    a.proven.lock().unwrap().insert(sid.to_string());
    self_claimed(sid, Some(&crate::harness_host::holder()));
    until("the cut loop's worker runs beside it", || {
        a.beside_ran.lock().unwrap().last() == Some(&(sid.to_string(), Some(holder.clone())))
    });
    assert_eq!(host.live(), [sid]);
    a.claims.lock().unwrap().remove(sid);
    a.proven.lock().unwrap().remove(sid);
    self_claim_released(sid, true);
    until("its loop runs beside the agent itself again", || {
        a.beside_ran.lock().unwrap().last()
            == Some(&(sid.to_string(), Some(UNCLAIMED_CODEX_ALAB.to_string())))
    });
    assert!(
        !a.beside_ran
            .lock()
            .unwrap()
            .iter()
            .any(|(s, beside)| s == sid && beside.is_none()),
        "never its own supervising loop"
    );
    assert_eq!(
        a.ran.lock().unwrap().iter().filter(|s| *s == sid).count(),
        3
    );
    host.shutdown_and_join();

    let a = Arc::new(Acting::default());
    let sid = "s-selfclaim-unproven";
    a.open.lock().unwrap().insert(sid.to_string());
    a.claims
        .lock()
        .unwrap()
        .insert(sid.to_string(), holder.clone());
    a.set(&[(sid, Program::Codex)]);
    let host = HostHandle::start(on(), false, false, a.hooks());
    until("its loop runs beside the agent itself", || {
        a.beside_ran
            .lock()
            .unwrap()
            .contains(&(sid.to_string(), Some(UNCLAIMED_CODEX_ALAB.to_string())))
    });
    assert!(
        !a.beside_ran
            .lock()
            .unwrap()
            .iter()
            .any(|(s, beside)| s == sid && beside.as_deref() == Some(holder.as_str())),
        "never beside an unproven claim's holder"
    );
    host.shutdown_and_join();
}

fn gone_pid() -> u32 {
    let mut gone = if cfg!(windows) {
        let mut cmd = aterm_uds::spawnfd::command("cmd");
        cmd.args(["/c", "exit 0"]);
        cmd
    } else {
        aterm_uds::spawnfd::command("/usr/bin/true")
    }
    .spawn()
    .expect("spawn a child that exits");
    let dead = gone.id();
    let _ = gone.wait();
    dead
}

#[test]
fn a_self_supervised_agents_exit_is_decided_by_its_copy_alone() {
    let line = vec![
        "/u/.aterm/agents/codex".to_string(),
        "resume".to_string(),
        "0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string(),
    ];
    let dead = gone_pid();
    let run = |sid: &str, seen: self_claimed::Seen, resume: Result<Vec<String>, &'static str>| {
        let a = Arc::new(Acting::default());
        a.open.lock().unwrap().insert(sid.to_string());
        a.set(&[(sid, Program::Codex)]);
        let copy = self_copy(&a, sid, seen, resume);
        a.self_copies.lock().unwrap().insert(sid.to_string(), copy);
        let host = HostHandle::start(on(), false, false, a.hooks());
        a.attached(&host, sid);
        until("its snapshot published", || {
            crate::harness_host::published_snapshot(sid).is_some()
        });
        a.claims
            .lock()
            .unwrap()
            .insert(sid.to_string(), format!("codex-alab@{dead}"));
        a.proven.lock().unwrap().insert(sid.to_string());
        a.set(&[]);
        until("the exit decided", || {
            !a.self_relaunched.lock().unwrap().is_empty()
                || !a.accounts_gone.lock().unwrap().is_empty()
                || a.notes
                    .lock()
                    .unwrap()
                    .iter()
                    .any(|n| matches!(n, HostNote::Inform { .. }))
                || crate::harness_host::published_snapshot(sid).is_none()
        });
        host.shutdown_and_join();
        a
    };
    #[cfg(target_os = "macos")]
    let decided = |a: &Acting| {
        let model = aterm_models_harness::harness_restart_stamp_model();
        let mut before = model.init_state();
        for step in ["SelfClaimOn", "Copied", "EndsOtherwise"] {
            assert!(model.fire(step, &mut before), "{step} at {before:?}");
        }
        assert!(
            !model.action_enabled("Read", &before),
            "the copy decides alone"
        );
        let seen = RestartSeen {
            ended: 2,
            read: 2,
            self_claim: true,
            ..RestartSeen::default()
        };
        assert!(
            reaches(&model, &before, &project_restart_stamp(&seen), 2),
            "{seen:?} from {before:?}"
        );
        assert!(a.relaunched.lock().unwrap().is_empty());
    };
    #[cfg(not(target_os = "macos"))]
    let decided = |_: &Acting| {};
    let a = run("s-selfclaim-crash", standing_record(), Ok(line.clone()));
    decided(a.as_ref());
    assert_eq!(
        a.self_relaunched.lock().unwrap().as_slice(),
        [("s-selfclaim-crash".to_string(), line.clone(), None)],
        "relaunched once, on its own record's line, under the dead self-claim"
    );
    assert!(
        a.relaunched.lock().unwrap().is_empty(),
        "never the Codex lane's relaunch"
    );
    assert_eq!(
        a.exit_looks.load(Ordering::SeqCst),
        0,
        "nor its look at the exit"
    );
    let a = run(
        "s-selfclaim-never",
        self_claimed::Seen::Never,
        Ok(line.clone()),
    );
    decided(a.as_ref());
    assert_eq!(
        a.self_relaunched.lock().unwrap().as_slice(),
        [("s-selfclaim-never".to_string(), line.clone(), None)],
        "a never-read copy's end is a crash, relaunched on its inherited line"
    );
    let a = run(
        "s-selfclaim-never-unlined",
        self_claimed::Seen::Never,
        Err("no-record-yet"),
    );
    decided(a.as_ref());
    assert!(a.self_relaunched.lock().unwrap().is_empty());
    let said: Vec<String> = a
        .notes
        .lock()
        .unwrap()
        .iter()
        .filter_map(|n| match n {
            HostNote::Inform { text, .. } => Some(text.clone()),
            _ => None,
        })
        .collect();
    assert!(
        said.len() == 1 && said[0].contains("before its session record named a line"),
        "said once: {said:?}"
    );
    let a = run(
        "s-selfclaim-orderly",
        self_claimed::Seen::Removed,
        Ok(line.clone()),
    );
    decided(a.as_ref());
    assert!(
        a.self_relaunched.lock().unwrap().is_empty(),
        "an orderly end is left"
    );
    assert!(a.relaunched.lock().unwrap().is_empty());
    let a = run("s-selfclaim-refused", standing_record(), Err("launch-path"));
    decided(a.as_ref());
    assert!(
        a.self_relaunched.lock().unwrap().is_empty(),
        "nothing relaunched"
    );
    let said: Vec<String> = a
        .notes
        .lock()
        .unwrap()
        .iter()
        .filter_map(|n| match n {
            HostNote::Inform { text, .. } => Some(text.clone()),
            _ => None,
        })
        .collect();
    assert_eq!(said.len(), 1, "said once: {said:?}");
    assert!(said[0].contains("launch-path"), "{said:?}");
}
#[test]
fn a_self_claimed_relaunch_owed_at_a_commit_carries_its_validated_line() {
    use aterm_agent::harness::relaunch::self_claimed_line;
    let line = vec![
        "/u/.aterm/agents/codex".to_string(),
        "resume".to_string(),
        "0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string(),
    ];
    let dead = gone_pid();
    let world = |sid: &str, resume: Result<Vec<String>, &'static str>| {
        let a = Arc::new(Acting::default());
        *a.self_relaunch_steps.lock().unwrap() =
            std::iter::repeat_n("wait:shell-prompt".to_string(), 64).collect();
        a.open.lock().unwrap().insert(sid.to_string());
        a.set(&[(sid, Program::Codex)]);
        let copy = self_copy(&a, sid, standing_record(), resume);
        a.self_copies.lock().unwrap().insert(sid.to_string(), copy);
        let taken_up: Arc<Mutex<Vec<Snapshot>>> = Arc::default();
        let mut h = a.hooks();
        h.acts.relaunch_restored = {
            let taken_up = Arc::clone(&taken_up);
            Arc::new(move |_, snap, _, _| {
                taken_up.lock().unwrap().push(snap.clone());
                "adopted".to_string()
            })
        };
        let (gate, pause) = gated_pauses(sid);
        h.pause = pause;
        let host = HostHandle::start(on(), false, false, h);
        a.attached(&host, sid);
        a.claims
            .lock()
            .unwrap()
            .insert(sid.to_string(), format!("codex-alab@{dead}"));
        a.proven.lock().unwrap().insert(sid.to_string());
        (a, host, gate, taken_up)
    };
    let sid = "s-selfclaim-owed";
    let (a, host, gate, taken_up) = world(sid, Ok(line.clone()));
    a.set(&[]);
    until("a first try on the copy's line", || {
        !a.self_relaunched.lock().unwrap().is_empty()
    });
    let owed = host
        .pending_restored_for(sid)
        .expect("owed on its back-off");
    assert_eq!(
        self_claimed_line(&owed.snap).map(|r| r.argv.clone()),
        Some(line.clone()),
        "owed on the validated line"
    );
    let leaf = crate::restore::AgentRestore::owed(owed.snap.clone(), owed.asked);
    let wire = aterm_toml::to_string(&leaf).expect("the leaf");
    assert!(wire.contains("[codex.alab]"), "{wire}");
    let back = aterm_toml::from_str::<crate::restore::AgentRestore>(&wire)
        .expect("the leaf reads")
        .snapshot(sid.to_string(), 7777)
        .expect("an agent this build knows");
    assert_eq!(
        self_claimed_line(&back).map(|r| r.argv.clone()),
        Some(line.clone()),
        "the successor's snapshot carries it"
    );
    host.pause_restored();
    gate.shut();
    until("the worker held in its pause", || gate.held());
    host.suspend();
    host.resume();
    host.resume_restored();
    host.relaunch_stranded(&|_| "in tab 1".to_string());
    gate.open();
    until("taken up on the restored queue", || {
        !taken_up.lock().unwrap().is_empty()
    });
    assert_eq!(
        self_claimed_line(&taken_up.lock().unwrap()[0]).map(|r| r.argv.clone()),
        Some(line.clone()),
        "relaunched on the validated line"
    );
    #[cfg(target_os = "macos")]
    {
        let model = aterm_models_harness::harness_restart_stamp_model();
        let mut before = model.init_state();
        for step in ["SelfClaimOn", "Copied", "EndsOtherwise", "Commit"] {
            assert!(model.fire(step, &mut before), "{step} at {before:?}");
        }
        assert!(!model.action_enabled("Read", &before), "the copy decides");
        let relaunched = taken_up.lock().unwrap()[0].clone();
        let seen = |relaunched: &Snapshot| RestartSeen {
            ended: 2,
            read: 2,
            committed: true,
            self_claim: true,
            lost: self_claimed_line(relaunched).is_none(),
            ..RestartSeen::default()
        };
        let real = project_restart_stamp(&seen(&relaunched));
        assert!(
            model.check_invariant("TheCopysDecisionRidesTheCommit", &real),
            "{real:?}"
        );
        assert!(
            reaches(&model, &before, &real, 1),
            "{real:?} from {before:?}"
        );
        let mut lineless = relaunched.clone();
        if let Some(run) = lineless.codex_mut() {
            run.self_claimed = None;
        }
        let dropped_seen = project_restart_stamp(&seen(&lineless));
        assert!(!model.check_invariant("TheCopysDecisionRidesTheCommit", &dropped_seen));
        let buggy = aterm_spec::interp::with_buggy(&model, 1);
        let mut dropped = buggy.init_state();
        for step in [
            "SelfClaimOn",
            "Copied",
            "EndsOtherwise",
            "CommitDropsTheCopy",
        ] {
            assert!(buggy.fire(step, &mut dropped), "{step} at {dropped:?}");
        }
        assert!(!buggy.check_invariant("TheCopysDecisionRidesTheCommit", &dropped));
        assert!(buggy.action_enabled("Read", &dropped), "left to the lane");
        assert!(
            reaches(&buggy, &dropped, &dropped_seen, 1),
            "the line-less relaunch is the mutant's: {dropped_seen:?} from {dropped:?}"
        );
    }
    host.shutdown_and_join();
    let sid = "s-selfclaim-unowed";
    let (a, host, _gate, taken_up) = world(sid, Err("launch-path"));
    a.set(&[]);
    until("said once, relaunched never", || {
        a.notes
            .lock()
            .unwrap()
            .iter()
            .any(|n| matches!(n, HostNote::Inform { .. }))
    });
    assert!(a.self_relaunched.lock().unwrap().is_empty());
    assert!(host.pending_restored_for(sid).is_none(), "owed nothing");
    assert!(taken_up.lock().unwrap().is_empty());
    host.shutdown_and_join();
}

#[test]
fn under_a_hold_the_self_claims_watch_only_worker_stands_and_types_nothing() {
    let line = vec![
        "/u/.aterm/agents/codex".to_string(),
        "resume".to_string(),
        "0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string(),
    ];
    let dead = gone_pid();
    let holder = format!("codex-alab@{dead}");
    let sid = "s-selfclaim-held";
    let a = Arc::new(Acting::default());
    a.open.lock().unwrap().insert(sid.to_string());
    a.claims
        .lock()
        .unwrap()
        .insert(sid.to_string(), holder.clone());
    a.proven.lock().unwrap().insert(sid.to_string());
    a.set(&[(sid, Program::Codex)]);
    let copy = self_copy(&a, sid, standing_record(), Ok(line.clone()));
    a.self_copies.lock().unwrap().insert(sid.to_string(), copy);
    let host = HostHandle::start(on(), false, false, a.hooks());
    let beside = (sid.to_string(), Some(holder.clone()));
    until("its loop runs beside the self-claim", || {
        a.beside_ran.lock().unwrap().contains(&beside)
    });
    a.attached(&host, sid);
    a.held.store(true, Ordering::SeqCst);
    a.passes();
    assert_eq!(host.live(), [sid], "the watch-only worker stands");
    assert_eq!(
        a.beside_ran.lock().unwrap().last(),
        Some(&beside),
        "still beside the self-claim, never its own loop"
    );
    a.set(&[]);
    until("the exit under the hold decided, its worker done", || {
        host.live().is_empty() && crate::harness_host::published_snapshot(sid).is_none()
    });
    assert!(
        a.self_relaunched.lock().unwrap().is_empty(),
        "nothing typed into a halted tab"
    );
    assert!(
        a.relaunched.lock().unwrap().is_empty(),
        "never the Codex lane's relaunch"
    );
    assert_eq!(
        a.exit_looks.load(Ordering::SeqCst),
        0,
        "nor its look at the exit"
    );
    a.held.store(false, Ordering::SeqCst);
    let runs = a.runs.load(Ordering::SeqCst);
    a.set(&[(sid, Program::Codex)]);
    until("a worker beside the self-claim again", || {
        a.runs.load(Ordering::SeqCst) > runs && a.beside_ran.lock().unwrap().last() == Some(&beside)
    });
    a.attached(&host, sid);
    let next = a.agent_in(sid).expect("the next agent").0;
    let copy = self_claimed::Copy {
        pid: next,
        start: a.start_of(sid, next),
        ..self_copy(&a, sid, standing_record(), Ok(line.clone()))
    };
    a.self_copies.lock().unwrap().insert(sid.to_string(), copy);
    a.set(&[]);
    until("relaunched on the copy's line", || {
        !a.self_relaunched.lock().unwrap().is_empty()
    });
    assert_eq!(
        a.self_relaunched.lock().unwrap().as_slice(),
        [(sid.to_string(), line, None)]
    );
    assert!(a.relaunched.lock().unwrap().is_empty());
    host.shutdown_and_join();
}

#[test]
fn a_self_claimed_snapshot_publishes_the_line_its_copy_validated() {
    use aterm_agent::harness::relaunch::{CodexRun, self_claimed_line};
    let a = Acting::default();
    let sid = "s-selfclaim-publish";
    let line = vec![
        "/u/.aterm/agents/codex".to_string(),
        "resume".to_string(),
        "0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string(),
    ];
    let codex = Snapshot {
        start: a.start_of(sid, snap(sid).pid),
        run: aterm_agent::harness::relaunch::AgentRun::Codex(CodexRun {
            home: "/u/.codex".into(),
            home_env: None,
            self_claimed: None,
        }),
        ..snap(sid)
    };
    let published = |copy: Option<self_claimed::Copy>, snap: &Snapshot| {
        crate::self_claim::set_copy_for_test(sid, copy);
        publish_snapshot_for_test(sid, Some(snap));
        let published = published_snapshot(sid).expect("published");
        self_claimed_line(&published).map(|r| r.argv.clone())
    };
    let ok = self_copy(&a, sid, standing_record(), Ok(line.clone()));
    assert_eq!(published(Some(ok.clone()), &codex), Some(line.clone()));
    let leaf = crate::restore::AgentRestore::of(published_snapshot(sid).expect("published"));
    assert!(
        matches!(&leaf.run, Some(crate::restore::RunRestore::Codex(run)) if run.alab.is_some()),
        "the leaf carries it: {leaf:?}"
    );
    let other = self_claimed::Copy {
        start: "Thu Jan  1 00:00:00 1970".to_string(),
        ..ok.clone()
    };
    assert_eq!(published(Some(other), &codex), None, "another process");
    let refused = self_copy(&a, sid, standing_record(), Err("launch-path"));
    assert_eq!(published(Some(refused), &codex), None, "a refused line");
    assert_eq!(published(None, &codex), None, "no copy");
    assert_eq!(published(Some(ok), &snap(sid)), None, "a Claude Code");
    crate::self_claim::set_copy_for_test(sid, None);
    publish_snapshot_for_test(sid, None);
}
#[test]
fn a_handed_self_claimed_agent_keeps_no_line_its_successor_never_validated() {
    use aterm_agent::harness::relaunch::{CodexRun, self_claimed_line};
    let a = Arc::new(Acting::default());
    let sid = "s-selfclaim-handed";
    a.open.lock().unwrap().insert(sid.to_string());
    let line = aterm_agent::harness::self_claimed::Resume {
        argv: vec![
            "/u/.aterm/agents/codex".to_string(),
            "resume".to_string(),
            "0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string(),
        ],
        session: "0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string(),
        codex_home: None,
        cwd: None,
    };
    let handed = Snapshot {
        start: a.start_of(sid, snap(sid).pid),
        run: aterm_agent::harness::relaunch::AgentRun::Codex(CodexRun {
            home: "/u/.codex".into(),
            home_env: None,
            self_claimed: Some(line.clone()),
        }),
        ..snap(sid)
    };
    assert_eq!(
        self_claimed_line(&handed),
        Some(&line),
        "the leaf carried it"
    );
    crate::self_claim::set_copy_for_test(sid, None);
    let host = HostHandle::start(on(), false, true, a.hooks());
    host.watch_handed(vec![(sid.to_string(), handed.clone())]);
    let kept = host
        .shared
        .kept
        .lock()
        .unwrap()
        .get(sid)
        .map(Arc::clone)
        .expect("kept");
    let kept = with_kept_of(&kept, |k| k.snapshot.clone()).expect("the handed snapshot");
    assert_eq!((kept.pid, &kept.start), (handed.pid, &handed.start));
    assert_eq!(self_claimed_line(&kept), None, "kept with no line");
    assert_eq!(
        published_snapshot(sid).as_ref().and_then(self_claimed_line),
        Some(&line),
        "published with it, for the crash image's own relaunch"
    );
    #[cfg(target_os = "macos")]
    {
        let model = aterm_models_harness::harness_restart_stamp_model();
        let mut before = model.init_state();
        for step in ["SelfClaimOn", "Copied", "Commit"] {
            assert!(model.fire(step, &mut before), "{step} at {before:?}");
        }
        let seen = |kept: &Snapshot| RestartSeen {
            alive: true,
            committed: true,
            copy: self_claimed_line(kept).is_some(),
            ..RestartSeen::default()
        };
        assert!(
            reaches(&model, &before, &project_restart_stamp(&seen(&kept)), 0),
            "{before:?}"
        );
        assert!(!model.action_enabled("CopyRelaunches", &before));
        assert!(
            !reaches(&model, &before, &project_restart_stamp(&seen(&handed)), 4),
            "the line kept past the Commit is no state of the model"
        );
    }
    end_exit_watches(&host.shared, EVERY_WATCH, |_| true);
    host.shutdown_and_join();
    publish_snapshot_for_test(sid, None);
}
