#[test]
fn the_upgrades_notice_is_due_where_the_hosts_step_would_type_it() {
    let asked = Arc::default();
    let due = door_worker(Program::Claude, Due::Yes, &asked);
    assert!(due.upgrade_due());
    *due.background_at.lock().unwrap() = Some(Instant::now() + Duration::from_secs(600));
    assert!(due.upgrade_due(), "a paused look");
    assert!(
        !door_worker(Program::Claude, Due::No, &asked).upgrade_due(),
        "not due"
    );
    assert!(
        !door_worker(Program::Codex, Due::Yes, &asked).upgrade_due(),
        "no upgrade lane"
    );
    let stopped = door_worker(Program::Claude, Due::Yes, &asked);
    stopped.stop.store(true, Ordering::SeqCst);
    assert!(!stopped.upgrade_due(), "stopped");
    let beside = door_worker(Program::Claude, Due::Yes, &asked);
    *beside.beside.lock().unwrap() = Some("a self-claim".to_string());
    assert!(!beside.upgrade_due(), "beside");
    let mut off = SupervisorConfig::default();
    off.set("upgrade", "false").unwrap();
    let mut no_upgrade = door_worker(Program::Claude, Due::Yes, &asked);
    no_upgrade.switches = switched(&off);
    assert!(!no_upgrade.upgrade_due(), "upgrade off");
}

#[test]
fn a_fact_lines_pace_is_refused_where_the_worker_takes_no_step() {
    use aterm_agent::supervise::occupancy::{PaceGrant, PaceRefusal, RuleId};
    let asked: Arc<Mutex<Vec<String>>> = Arc::default();
    let pace = |idle: &WorkerIdle| idle.occupancy_pace(RuleId::HoldRoom, 42);
    assert_eq!(
        pace(&door_worker(Program::Claude, Due::No, &asked)),
        PaceGrant::Granted
    );
    assert_eq!(*asked.lock().unwrap(), ["s-door hold-room@v1 42"]);
    asked.lock().unwrap().clear();
    let stopped = door_worker(Program::Claude, Due::No, &asked);
    stopped.stop.store(true, Ordering::SeqCst);
    let beside = door_worker(Program::Claude, Due::No, &asked);
    *beside.beside.lock().unwrap() = Some("a self-claim".to_string());
    let owns = door_worker(Program::Claude, Due::No, &asked);
    owns.owns.store(true, Ordering::SeqCst);
    assert!(owns.owns_turn_end());
    assert!(host_carries_relaunch(Program::Agy));
    let carry = door_worker(Program::Agy, Due::No, &asked);
    with_kept_of(&carry.kept, |k| k.carry_asked = true);
    for (idle, why) in [
        (stopped, PaceRefusal::Off),
        (beside, PaceRefusal::Beside),
        (owns, PaceRefusal::Owns),
        (carry, PaceRefusal::CarryOwed),
    ] {
        assert_eq!(pace(&idle), PaceGrant::Refused(why));
    }
    assert!(
        asked.lock().unwrap().is_empty(),
        "{:?}",
        asked.lock().unwrap()
    );
    let swept = door_worker(Program::Claude, Due::No, &asked);
    with_kept_of(&swept.kept, |k| k.carry_asked = true);
    assert_eq!(pace(&swept), PaceGrant::Granted);
}

/// Under `observe` and `off` a worker's fact word is `Fenced` and never reaches the act; under
/// `prompt` it reaches it with the session's own sid and the word as asked.
#[test]
fn a_workers_task_fact_is_refused_unless_the_owners_mode_here_is_prompt() {
    use aterm_agent::supervise::Occupancy;
    use aterm_agent::supervise::occupancy::{FactWord, NoteOutcome, RuleId};
    let asked: Arc<Mutex<Vec<String>>> = Arc::default();
    let mut hooks = hooks(
        &Arc::new(World::default()),
        Arc::new(|_: &WorkerJob| BodyEnd::Stopped),
    );
    let seen = Arc::clone(&asked);
    hooks.acts = Acts {
        task_fact: Arc::new(move |sid, word| {
            let said = word.map_or_else(|| "-".to_string(), FactWord::word);
            seen.lock().unwrap().push(format!("{sid} {said}"));
            NoteOutcome::Noted
        }),
        ..Acts::inert()
    };
    let idle = idle_host("s-door", Program::Claude, switched(&on()), hooks);
    let word = FactWord::new(RuleId::HoldRoom, 1);
    assert!(word.is_some());
    for mode in [Occupancy::Observe, Occupancy::Off] {
        crate::occupancy_host::set_mode(mode);
        assert_eq!(idle.task_fact(word), NoteOutcome::Fenced, "{mode:?}");
        assert_eq!(idle.task_fact(None), NoteOutcome::Fenced, "{mode:?}");
    }
    assert!(
        asked.lock().unwrap().is_empty(),
        "{:?}",
        asked.lock().unwrap()
    );
    crate::occupancy_host::set_mode(Occupancy::Prompt);
    assert_eq!(idle.task_fact(word), NoteOutcome::Noted);
    assert_eq!(idle.task_fact(None), NoteOutcome::Noted);
    assert_eq!(
        *asked.lock().unwrap(),
        ["s-door hold-room@v1#1", "s-door -"]
    );
    crate::occupancy_host::set_mode(Occupancy::Observe);
}

/// The live task door ([`task_fact_live`]) writes the word on the record of the session with that
/// sid and answers its outcome; a sid no session of this instance has is `NoTask`, and moves no
/// record.
#[test]
fn the_live_task_fact_marks_the_session_with_that_sid_alone() {
    crate::occupancy_host::set_mode(aterm_agent::supervise::Occupancy::Prompt);
    use crate::task_record::{TaskMark, TaskState, mark_session_task};
    use aterm_agent::supervise::occupancy::{FactWord, NoteOutcome, RuleId};
    let store = crate::session_store::new_store();
    let handle = crate::session_store::test_handle(31);
    let sid = handle.sid.as_str().to_string();
    let ctx = Arc::clone(&handle.ctx);
    store.write().unwrap().register(handle);
    let word = FactWord::new(RuleId::WaitNudge, 2);
    assert_eq!(task_fact_live(&store, &sid, word), NoteOutcome::NoTask);
    mark_session_task(&ctx, 31, &TaskMark::new(TaskState::Working)).expect("unfenced");
    assert_eq!(
        task_fact_live(&store, "s-nobody", word),
        NoteOutcome::NoTask
    );
    let fact = || {
        let timeline = ctx.timeline.lock().unwrap();
        let task = timeline.task().expect("a task");
        (task.fact, task.fact_rev)
    };
    assert_eq!(fact(), (None, 0));
    assert_eq!(task_fact_live(&store, &sid, word), NoteOutcome::Noted);
    assert_eq!(fact(), (word, 1));
    assert_eq!(task_fact_live(&store, &sid, None), NoteOutcome::Cleared);
    assert_eq!(fact(), (None, 2));
    crate::occupancy_host::set_mode(aterm_agent::supervise::Occupancy::Observe);
    assert_eq!(task_fact_live(&store, &sid, word), NoteOutcome::Fenced);
    assert_eq!(fact(), (None, 2));
}

#[test]
fn the_occupancy_board_keys_each_session_by_its_tabs_id() {
    use crate::occupancy_host::{Judged, board_of};
    let store = crate::session_store::new_store();
    let mut sids = Vec::new();
    for n in [3, 8] {
        let handle = crate::session_store::test_handle(n);
        sids.push(handle.sid.as_str().to_string());
        store.write().unwrap().register(handle);
    }
    let mut asked = sids.clone();
    asked.push("s-gone".to_string());
    let sessions = board_sessions(&store, &asked);
    assert_eq!(sessions, [(3, sids[0].clone()), (8, sids[1].clone())]);
    let now_ms = 1_792_656_000_000;
    let snap = aterm_vitals::model::Snapshot {
        slot_tabs: Some(vec![8]),
        ..aterm_vitals::model::Snapshot::default()
    };
    let mut j = Judged::default();
    j.step(
        board_of(&snap, Some(now_ms), None, now_ms),
        Some(&snap),
        &sessions,
    );
    assert_eq!(j.reading(&sids[1], now_ms).held_slot_last_ms, Some(now_ms));
    assert_eq!(j.reading(&sids[0], now_ms).held_slot_last_ms, None);
}

#[test]
fn a_workers_canary_reads_its_own_sessions_stuck_call_from_the_jobs_board() {
    use aterm_agent::supervise::BackgroundEvidence;
    use aterm_vitals::jobs::{Consumer, JobsView};
    static BOARD: crate::vitals_jobs::JobsBoard = crate::vitals_jobs::JobsBoard::new();
    let worker = |sid: &str, board: &'static crate::vitals_jobs::JobsBoard| {
        let mut hooks = hooks(
            &Arc::new(World::default()),
            Arc::new(|_: &WorkerJob| BodyEnd::Stopped),
        );
        hooks.acts = Acts {
            jobs_board: board,
            ..Acts::inert()
        };
        idle_host(sid, Program::Claude, switched(&on()), hooks)
    };
    let row = crate::vitals_jobs::tests::call_row;
    BOARD.post(
        Arc::new(JobsView {
            rows: vec![
                row(4, Consumer::Agent, true, 31, 27098, "aterm_gui-e0964a"),
                row(9, Consumer::AgentBg, false, 40, 600, "cargo"),
            ],
            ..JobsView::default()
        }),
        std::collections::BTreeMap::from([(4, "s-hung".to_string()), (9, "s-calm".to_string())]),
        Instant::now(),
    );
    match worker("s-hung", &BOARD).background_jobs() {
        BackgroundEvidence::NoProgress { worst } => {
            assert_eq!(
                (worst.pid, worst.exe.as_str(), worst.quiet_min()),
                (
                    27098,
                    &"aterm_gui-e0964a"[..crate::vitals_jobs::COMM_BYTES],
                    31
                )
            );
        }
        other => panic!("the hung call is named: {other:?}"),
    }
    assert_eq!(
        worker("s-calm", &BOARD).background_jobs(),
        BackgroundEvidence::Unknown
    );
    assert_eq!(
        worker("s-hung", Acts::inert().jobs_board).background_jobs(),
        BackgroundEvidence::Unknown
    );
}

/// The worker's facts ([`IdleHost::facts`]) are its own session's `no_progress` agent calls, worst
/// first, whose leader is proved alive at the ask ([`Acts::leader_lives`]); a view past
/// [`crate::vitals_jobs::JOBS_FRESH`], or a board no view was posted to, reads nothing.
#[test]
fn a_workers_facts_are_its_sessions_calls_that_made_no_progress_proved_alive() {
    use aterm_agent::supervise::BackgroundEvidence;
    use aterm_vitals::jobs::{Consumer, JobRow, JobsView};
    static BOARD: crate::vitals_jobs::JobsBoard = crate::vitals_jobs::JobsBoard::new();
    static STALE: crate::vitals_jobs::JobsBoard = crate::vitals_jobs::JobsBoard::new();
    // Every leader lives at the birth the view read but 503, which ended, and 505, whose pid a
    // later process took (it lives at another birth).
    fn lives(pid: u32, birth: u64) -> bool {
        match pid {
            503 => false,
            505 => birth == 99,
            _ => true,
        }
    }
    let worker = |board: &'static crate::vitals_jobs::JobsBoard| {
        let mut hooks = hooks(
            &Arc::new(World::default()),
            Arc::new(|_: &WorkerJob| BodyEnd::Stopped),
        );
        hooks.acts = Acts {
            jobs_board: board,
            leader_lives: lives,
            ..Acts::inert()
        };
        idle_host("s-hung", Program::Claude, switched(&on()), hooks)
    };
    let row = |consumer, stuck, min, pid, birth: Option<u64>| JobRow {
        leader: (pid, birth),
        ..crate::vitals_jobs::tests::call_row(4, consumer, stuck, min, pid, "aterm_gui-e0964a")
    };
    let view = Arc::new(JobsView {
        rows: vec![
            row(Consumer::Agent, true, 20, 501, Some(11)),
            row(Consumer::AgentBg, true, 31, 27098, Some(12)),
            row(Consumer::AgentBg, true, 50, 503, Some(13)),
            row(Consumer::AgentBg, true, 40, 505, Some(15)),
            row(Consumer::AgentBg, true, 90, 504, None),
            row(Consumer::AgentBg, false, 5, 502, Some(14)),
        ],
        ..JobsView::default()
    });
    let sids = std::collections::BTreeMap::from([(4, "s-hung".to_string())]);
    BOARD.post(Arc::clone(&view), sids.clone(), Instant::now());
    let reading = worker(&BOARD).facts().expect("a fresh view");
    let named: Vec<(u32, Option<u64>, u64)> = reading
        .no_progress
        .iter()
        .map(|c| (c.pid, c.birth, c.quiet_min()))
        .collect();
    assert_eq!(named, [(27098, Some(12), 31), (501, Some(11), 20)]);
    let now_ms = i64::try_from(aterm_time::unix_millis().expect("the clock")).unwrap();
    assert!(reading.fresh_at(now_ms), "{} at {now_ms}", reading.as_of_ms);
    assert_eq!(
        worker(&BOARD).background_jobs(),
        BackgroundEvidence::Unknown,
        "the canary's evidence asks every call"
    );
    let old = Instant::now()
        .checked_sub(crate::vitals_jobs::JOBS_FRESH + Duration::from_secs(1))
        .expect("a clock past the bound");
    STALE.post(view, sids, old);
    assert_eq!(worker(&STALE).facts(), None);
    assert_eq!(worker(Acts::inert().jobs_board).facts(), None);
}

/// The live measure ([`agent_memory`]) of a real stand-in.
#[cfg(target_os = "macos")]
#[test]
fn the_live_measure_reads_a_growing_stand_ins_group_footprint() {
    use aterm_agent::supervise::memory::{self, MemoryCeiling};
    use std::io::BufRead as _;
    let stand_in = |mib: u64| {
        let script =
            format!("my $x = \"a\" x ({mib} * 1024 * 1024); $| = 1; print \"ready\\n\"; sleep 60;");
        let mut child = aterm_uds::spawnfd::command("/usr/bin/perl")
            .args(["-e", &script])
            .stdout(aterm_uds::spawnfd::Stdio::piped())
            .process_group(0)
            .spawn()
            .expect("perl");
        let mut line = String::new();
        let out = child.stdout.take().expect("its stdout");
        std::io::BufReader::new(out)
            .read_line(&mut line)
            .expect("its ready line");
        assert_eq!(line, "ready\n");
        let pid = child.id();
        let m = agent_memory(pid);
        let _ = child.kill(); // SIGKILL
        let _ = child.wait();
        (m, pid)
    };
    let small_mac = |m: AgentMemory| AgentMemory {
        physical_mib: Some(1024),
        available_mib: Some(1024),
        used_mib: Some(1024),
        pressure: Some(memory::Pressure::Normal),
        ..m
    };
    let (big, pid) = stand_in(640);
    let big = big.expect("the stand-in's group");
    assert!(big.footprint_mib >= 600, "{big:?}");
    assert!(big.physical_mib.is_some_and(|p| p >= 4096), "{big:?}");
    assert!(
        big.available_mib.is_some() && big.used_mib.is_some_and(|u| u > 0),
        "{big:?}"
    );
    let over = memory::judge(MemoryCeiling::Auto, &small_mac(big)).expect("over 512 MiB");
    assert_eq!(over.ceiling_mib, 512);
    assert!(!over.acts(), "a warning: the Mac is not in trouble");
    let (small, _) = stand_in(16);
    let small = small.expect("the stand-in's group");
    assert!(small.footprint_mib < 256, "{small:?}");
    assert_eq!(memory::judge(MemoryCeiling::Auto, &small_mac(small)), None);
    assert_eq!(agent_memory(pid), None, "a process that is gone");
}

#[test]
fn the_memory_board_answers_the_largest_other_agent_and_forgets_stale_ones() {
    let board = MemoryBoard::default();
    let t0 = Instant::now();
    assert_eq!(board.record("s-a", 100, t0), None, "alone");
    assert_eq!(board.record("s-b", 50, t0), Some(100));
    assert_eq!(board.record("s-a", 30, t0), Some(50), "its own replaced");
    assert_eq!(board.record("s-c", 10, t0), Some(50));
    let later = t0 + BOARD_FRESH + Duration::from_secs(1);
    assert_eq!(
        board.record("s-c", 10, later),
        None,
        "the others went stale"
    );
    assert_eq!(board.record("s-a", 30, later), Some(10));
}

fn gated_behind(
    hooks: &mut Hooks,
) -> (
    Arc<AtomicUsize>,
    std::sync::mpsc::Sender<Option<Behind>>,
    std::sync::mpsc::Receiver<u64>,
) {
    let (inside_tx, inside_rx) = std::sync::mpsc::channel();
    let (word_tx, word_rx) = std::sync::mpsc::channel::<Option<Behind>>();
    let (acts, word_rx) = (Arc::new(AtomicUsize::new(0)), Mutex::new(word_rx));
    let counted = Arc::clone(&acts);
    let inside_tx = Mutex::new(inside_tx);
    hooks.acts.behind = Arc::new(move |_, since| {
        counted.fetch_add(1, Ordering::SeqCst);
        inside_tx.lock().unwrap().send(since).unwrap();
        let word = word_rx
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .recv_timeout(Duration::from_secs(60))
            .expect("a word for the act within 60 s");
        word.unwrap_or_else(|| panic!("the act fails (a test's)"))
    });
    (acts, word_tx, inside_rx)
}

#[test]
fn an_owed_note_is_asked_by_one_asker_at_a_time() {
    let world = Arc::new(World::default());
    let mut h = hooks(&world, parking_body(&world));
    let (acts, word, inside) = gated_behind(&mut h);
    let hooks = Arc::new(h);
    let note: Note = Arc::default();
    let wait_inside = || {
        inside
            .recv_timeout(Duration::from_secs(60))
            .expect("the act within 60 s")
    };
    let fly = || {
        let (hooks, note) = (Arc::clone(&hooks), Arc::clone(&note));
        std::thread::spawn(move || {
            let rung = RINGS_HERE.with(std::cell::Cell::get);
            let said = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                ask_note("s-1", &note, &hooks)
            }));
            (said.ok(), RINGS_HERE.with(std::cell::Cell::get) - rung)
        })
    };
    let owed = || *note.lock().unwrap();

    owe_note(&note, 100);
    let asker = fly();
    assert_eq!(wait_inside(), 100);
    assert_eq!(ask_note("s-1", &note, &hooks), None, "a second ask skips");
    let now = Instant::now();
    assert_eq!(host_note("s-1", &note, now, &hooks), None, "the wake skips");
    word.send(Some(Behind::Busy)).unwrap();
    let (said, rings) = asker.join().unwrap();
    assert_eq!(said, Some(Some(Behind::Busy)));
    assert_eq!(acts.load(Ordering::SeqCst), 1, "asked once");
    assert!(rings >= 1, "the put-back after a skip rings the host");
    let o = owed().expect("busy: still owed");
    assert!(!o.flying && !o.skipped && o.by.is_some_and(|by| by > now));

    let asker = fly();
    wait_inside();
    word.send(Some(Behind::Busy)).unwrap();
    assert_eq!(asker.join().unwrap(), (Some(Some(Behind::Busy)), 0));

    let asker = fly();
    wait_inside();
    assert_eq!(host_wake(&note), None, "no wake named in flight");
    word.send(Some(Behind::Unread(upgrade_drive::UNREAD_RECORD)))
        .unwrap();
    let (said, rings) = asker.join().unwrap();
    assert!(matches!(said, Some(Some(Behind::Unread(_)))));
    assert!(
        rings >= 1,
        "the put-back after the last read rings the host"
    );
    assert!(host_wake(&note).is_some(), "the host wakes for it again");

    let asker = fly();
    wait_inside();
    owe_note(&note, 50);
    let at = Instant::now();
    assert_eq!(host_note("s-1", &note, at, &hooks), None);
    word.send(Some(Behind::Nothing)).unwrap();
    let (said, rings) = asker.join().unwrap();
    assert_eq!(said, Some(Some(Behind::Nothing)));
    assert!(rings >= 1, "the host is rung for the notice's note");
    let o = owed().expect("re-owed: still owed");
    assert!(o.since == 50 && !o.flying && o.by.is_some_and(|by| by <= at));
    word.send(Some(Behind::Noted)).unwrap();
    assert_eq!(host_note("s-1", &note, Instant::now(), &hooks), None);
    assert_eq!(wait_inside(), 50, "asked with the notice's second");
    assert!(owed().is_none(), "noted: nothing more owed");

    owe_note(&note, 7);
    let before = acts.load(Ordering::SeqCst);
    let asker = fly();
    wait_inside();
    assert_eq!(host_note("s-1", &note, Instant::now(), &hooks), None);
    word.send(None).unwrap();
    let (said, rings) = asker.join().unwrap();
    assert_eq!(said, None, "the act panicked");
    assert!(rings >= 1, "the unwound flight rings for the skip");
    assert!(owed().is_some_and(|o| !o.flying && o.since == 7));
    word.send(Some(Behind::Noted)).unwrap();
    assert_eq!(ask_note("s-1", &note, &hooks), Some(Behind::Noted));
    assert_eq!(acts.load(Ordering::SeqCst), before + 2, "asked again");
    assert_eq!(wait_inside(), 7, "with the owed second");
}

#[test]
fn a_fresh_launch_is_behind_from_its_attach_once_its_record_reads() {
    {
        let agent = Program::Claude;
        let a = Arc::new(Acting::default());
        a.busy.store(true, Ordering::SeqCst);
        *a.due_says.lock().unwrap() = [Due::Unread(upgrade_drive::UNREAD_RECORD)].into();
        a.due.store(true, Ordering::SeqCst);
        *a.behind_says.lock().unwrap() = [
            Behind::Unread(upgrade_drive::UNREAD_RECORD),
            Behind::Unread(upgrade_drive::UNREAD_RECORD),
        ]
        .into();
        *a.steps.lock().unwrap() = ["announced:1"].into();
        let before = crate::upgrade_host::now_s();
        a.set(&[("s-f", agent)]);
        let host = HostHandle::start(on(), false, false, a.hooks());
        until("noted, the record read", || {
            a.behinds.load(Ordering::SeqCst) == 3
        });
        assert_eq!(
            a.parks.load(Ordering::SeqCst),
            0,
            "{agent:?}: before the first idle point"
        );
        let asked = a.behind_since.lock().unwrap().clone();
        let since = asked[0].0;
        assert!(
            (before..=crate::upgrade_host::now_s()).contains(&since),
            "{agent:?}: the attach's second"
        );
        assert!(
            asked.iter().all(|&(s, stepped)| s == since && stepped == 0),
            "{agent:?}: {asked:?}"
        );
        a.busy.store(false, Ordering::SeqCst);
        until("the step", || a.stepped.load(Ordering::SeqCst) >= 1);
        host.shutdown_and_join();
    }
}
#[test]
fn a_note_the_ladder_could_not_read_is_asked_at_the_idle_point_before_the_step() {
    let a = Arc::new(Acting::default());
    a.busy.store(true, Ordering::SeqCst);
    *a.due_says.lock().unwrap() = [Due::Unread(upgrade_drive::UNREAD_SOCKET)].into();
    a.due.store(true, Ordering::SeqCst);
    *a.behind_says.lock().unwrap() =
        [Behind::Unread(upgrade_drive::UNREAD_SOCKET); 1 + NOTE_AGAIN.len()].into();
    a.set(&[("s-l", Program::Claude)]);
    let host = HostHandle::start(on(), false, false, a.hooks());
    until("the ladder spent", || {
        a.behinds.load(Ordering::SeqCst) == 1 + NOTE_AGAIN.len()
    });
    a.busy.store(false, Ordering::SeqCst);
    until("the step", || a.stepped.load(Ordering::SeqCst) >= 1);
    let asked = a.behind_since.lock().unwrap().clone();
    let (since, _) = asked[0];
    assert_eq!(
        asked[1 + NOTE_AGAIN.len()..],
        [(since, 0)],
        "asked once more at the idle point, before the step, with the attach's second"
    );
    host.shutdown_and_join();
}

