#[test]
fn a_clear_on_a_registered_tab_wakes_the_host_and_moves_its_roster_screen() {
    use crate::session_timeline::AgentStamp;
    let store = crate::session_store::new_store();
    let handle = crate::session_store::test_handle(1);
    let sid = handle.sid.as_str().to_string();
    let ctx = Arc::clone(&handle.ctx);
    store.write().unwrap().register(handle);
    let read = |word: &'static str, seq: u64| {
        ctx.timeline.lock().unwrap().publish_agent(
            word,
            None,
            None,
            Some(Program::Claude),
            AgentStamp {
                generation: crate::control::ScreenGen { epoch: 1, seq },
                fp: seq,
            },
        );
    };
    let screen = || {
        roster_of(&store)
            .into_iter()
            .find(|(tab, ..)| *tab == sid)
            .map(|(_, program, stamp)| (program, stamp.screen))
    };
    let phase_rings = || PHASE_RINGS_HERE.with(std::cell::Cell::get);
    read("idle", 1);
    assert_eq!(screen(), Some((Program::Claude, 0)), "on the roster");
    let rung = phase_rings();
    read("idle", 2);
    assert_eq!(phase_rings() - rung, 1, "the screen's move woke the host");
    assert_eq!(
        screen(),
        Some((Program::Claude, 1)),
        "the roster's screen moved"
    );
    read("busy", 3);
    let (rung, before) = (phase_rings(), screen());
    read("busy", 4);
    read("busy", 5);
    assert_eq!(phase_rings() - rung, 0, "a spinner wakes nothing");
    assert_eq!(screen(), before, "and moves no screen");
}

#[test]
fn a_screen_alone_is_read_once_per_settle() {
    let world = Arc::new(World::default());
    let mut hooks = hooks(&world, parking_body(&world));
    let reads = Arc::new(AtomicUsize::new(0));
    let counted = Arc::clone(&reads);
    hooks.acts.follow = Arc::new(move |_, _| {
        counted.fetch_add(1, Ordering::SeqCst);
        Foreground::Agent
    });
    hooks.pause = Arc::new(|pause| pause);
    let following = vec![(
        "s-settle-cost".to_string(),
        Arc::new(Mutex::new(Kept {
            snapshot: Some(snap("s-settle-cost")),
            ..Kept::default()
        })),
    )];
    let (mut followed, mut settle) = (HashMap::new(), HashMap::new());
    let t0 = Instant::now();
    let at = |secs: u64| t0 + Duration::from_secs(secs);
    let mut stamp = FollowStamp {
        group: 7,
        reader: Some(Program::Claude),
        ..FollowStamp::default()
    };
    let look = |stamp: FollowStamp, now: Instant, followed: &mut _, settle: &mut _| {
        let stamps = HashMap::from([("s-settle-cost".to_string(), stamp)]);
        follow_entries(&following, &stamps, (followed, settle), false, now, &hooks)
    };
    assert_eq!(look(stamp, at(0), &mut followed, &mut settle), None);
    assert_eq!(reads.load(Ordering::SeqCst), 1);
    assert_eq!(look(stamp, at(1), &mut followed, &mut settle), None);
    assert_eq!(
        reads.load(Ordering::SeqCst),
        1,
        "an unmoved stamp reads nothing"
    );
    stamp.screen += 1;
    let settle_at = look(stamp, at(10), &mut followed, &mut settle);
    assert_eq!(settle_at, Some(at(10) + STATUS_AFTER_SCREEN));
    assert_eq!(reads.load(Ordering::SeqCst), 2);
    for _ in 0..5 {
        stamp.screen += 1;
        assert_eq!(look(stamp, at(11), &mut followed, &mut settle), settle_at);
    }
    assert_eq!(reads.load(Ordering::SeqCst), 2, "one read per settle");
    let again = look(stamp, at(12), &mut followed, &mut settle);
    assert_eq!(reads.load(Ordering::SeqCst), 3);
    assert_eq!(again, Some(at(12) + STATUS_AFTER_SCREEN));
    assert_eq!(look(stamp, at(14), &mut followed, &mut settle), None);
    assert_eq!(reads.load(Ordering::SeqCst), 4);
    stamp.screen += 1;
    look(stamp, at(20), &mut followed, &mut settle);
    assert_eq!(reads.load(Ordering::SeqCst), 5);
    stamp.rev += 1;
    let owed = look(stamp, at(21), &mut followed, &mut settle);
    assert_eq!(
        reads.load(Ordering::SeqCst),
        6,
        "the verdict moved: read now"
    );
    assert_eq!(owed, Some(at(21) + STATUS_AFTER_SCREEN), "re-armed");
    let none = follow_entries(
        &following,
        &HashMap::new(),
        (&mut HashMap::new(), &mut HashMap::new()),
        false,
        at(30),
        &hooks,
    );
    assert_eq!((none, reads.load(Ordering::SeqCst)), (None, 7));
}

#[test]
fn a_wait_a_settle_alone_ended_is_no_full_follow() {
    let world = Arc::new(World::default());
    let handle = HostHandle::start(on(), false, true, hooks(&world, parking_body(&world)));
    let mut host = HostState::from_shared(&handle.shared);
    let now = Instant::now();
    assert!(!settle_alone(&host, now), "none owed");
    host.settle
        .insert("s-a".to_string(), now + Duration::from_secs(1));
    assert!(!settle_alone(&host, now), "not come yet");
    host.settle.insert("s-b".to_string(), now);
    host.timer_at = Some(now + Duration::from_secs(60));
    assert!(settle_alone(&host, now), "a settle came, nothing else");
    host.timer_at = Some(now);
    assert!(!settle_alone(&host, now), "another instant came too");
    host.timer_at = None;
    assert!(settle_alone(&host, now));
    handle.shutdown_and_join();
}

#[test]
fn a_publication_that_moves_what_a_restore_carries_tells_the_window() {
    let a = Arc::new(Acting::default());
    let hooks = a.hooks();
    let kept = Mutex::new(Kept {
        snapshot: Some(snap("s-tell")),
        ..Kept::default()
    });
    a.set(&[("s-tell", Program::Claude)]);
    let told = || {
        a.notes
            .lock()
            .unwrap()
            .iter()
            .filter(|n| matches!(n, HostNote::AgentPublished { sid } if sid == "s-tell"))
            .count()
    };
    assert!(follow_snapshot("s-tell", &kept, &hooks));
    assert_eq!(told(), 1, "first published");
    assert!(follow_snapshot("s-tell", &kept, &hooks));
    assert_eq!(told(), 1, "the same conversation tells nothing");
    *a.conversation.lock().unwrap() = Some("0badf00d-c1ea-4ed0-8000-0000000c1ea5".to_string());
    assert!(follow_snapshot("s-tell", &kept, &hooks));
    assert_eq!(told(), 2, "another conversation is told");
    let quiet = Snapshot {
        dialect: Some(aterm_agent::harness::upgrade::Dialect::Bash),
        ..kept.lock().unwrap().snapshot.clone().expect("kept")
    };
    assert!(
        !publish_snapshot("s-tell", Some(&quiet)),
        "no layout carries a dialect"
    );
    assert!(publish_snapshot("s-tell", None), "gone");
    assert!(!publish_snapshot("s-tell", None), "gone already");
}

/// How [`pty_job`]'s agent is parented, which decides how its end reads.
#[cfg(unix)]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum JobEnd {
    /// Its parent exits at once, so the agent is reaped (by init) the
    /// moment it ends.
    Reaped,
    /// As `Reaped`, with a second process in the agent's group that
    /// outlives it (a runtime's child, a pipeline's other end).
    Member,
}

/// A pty whose session leader (a `sleep` standing in for the tab's shell) never takes the
/// terminal back, and whose foreground group is a job of that session (a `sleep` leading its
/// own group, standing in for the agent).
#[cfg(unix)]
fn pty_job(end: JobEnd) -> (i32, std::process::Child, i32) {
    use aterm_uds::spawnfd::InheritNothing as _;
    use std::ffi::CString;
    use std::os::fd::{FromRawFd as _, OwnedFd};
    use std::os::unix::process::CommandExt as _;
    let (master, slave) = aterm_pty::open_pty_pair().expect("open_pty_pair");
    // SAFETY: `slave` is a fresh fd this function alone owns.
    let slave = unsafe { OwnedFd::from_raw_fd(slave) };
    let stdio = || std::process::Stdio::from(slave.try_clone().expect("dup slave"));
    let (image, secs) = (
        CString::new("/bin/sleep").expect("path"),
        CString::new("30").expect("arg"),
    );
    let mut cmd = std::process::Command::new("/bin/sleep");
    cmd.inherit_nothing()
        .arg("30")
        .stdin(stdio())
        .stdout(stdio())
        .stderr(stdio());
    // SAFETY: runs in the forked child before exec and calls only async-signal-safe functions.
    unsafe {
        cmd.pre_exec(move || {
            if libc::setsid() < 0 || libc::ioctl(0, libc::TIOCSCTTY as _, 0) < 0 {
                return Err(std::io::Error::last_os_error());
            }
            let argv = [image.as_ptr(), secs.as_ptr(), std::ptr::null()];
            let between = libc::fork();
            if between == 0 {
                if libc::fork() == 0 {
                    libc::setpgid(0, 0);
                    libc::signal(libc::SIGTTOU, libc::SIG_IGN);
                    libc::tcsetpgrp(0, libc::getpid());
                    if end == JobEnd::Member {
                        libc::fork();
                    }
                    libc::execv(argv[0], argv.as_ptr());
                    libc::_exit(127);
                }
                libc::_exit(0);
            } else if between > 0 {
                libc::waitpid(between, std::ptr::null_mut(), 0);
            }
            Ok(())
        });
    }
    let leader = cmd.spawn().expect("spawn the session leader");
    drop(slave);
    let shell = libc::pid_t::try_from(leader.id()).expect("pid");
    let agent = std::cell::Cell::new(0);
    until("the agent's group leads the pty's foreground", || {
        agent.set(crate::quit_safety::foreground_pgrp(master));
        agent.get() > 0 && agent.get() != shell
    });
    (master, leader, agent.get())
}

/// End what [`pty_job`] made: the agent's group, the session leader,
/// the master.
#[cfg(unix)]
fn end_pty_job(master: i32, mut leader: std::process::Child, agent: i32) {
    // SAFETY: signals the test's own processes and closes the master fd owned by this test.
    unsafe {
        libc::killpg(agent, libc::SIGKILL);
    }
    let _ = leader.kill();
    let _ = leader.wait();
    // SAFETY: as above.
    unsafe { libc::close(master) };
}

/// Kill `pid` alone, and wait until it is gone — reaped, not a zombie.
#[cfg(unix)]
fn kill_until_reaped(pid: i32) {
    // SAFETY: signals the test's own process.
    unsafe { libc::kill(pid, libc::SIGKILL) };
    until("reaped", || {
        !aterm_uds::process::pid_alive(u32::try_from(pid).expect("pid"))
    });
}

/// A tab on `master` registered in a fresh store, its agent named `claude` in `group`:
/// `(store, sid, name)`, where `name` names its program again.
#[cfg(unix)]
fn tab_on(master: i32, local: u64, group: i32) -> (Store, String, impl Fn(Option<&str>)) {
    let store = crate::session_store::new_store();
    let handle = crate::session_store::test_handle_on(local, master);
    let sid = handle.sid.as_str().to_string();
    let ctx = Arc::clone(&handle.ctx);
    let name = move |program: Option<&str>| {
        let mut tl = ctx.timeline.lock().unwrap();
        tl.note_foreground_group(group);
        tl.set_program(group, program.map(str::to_string));
    };
    name(Some("claude"));
    store.write().unwrap().register(handle);
    (store, sid, name)
}

/// The hold, read for real ([`holds`], [`Acts::holds`]) on a real pty.
#[cfg(unix)]
#[test]
fn the_real_hold_reads_the_tabs_foreground_and_its_leader() {
    let (master, leader, group) = pty_job(JobEnd::Reaped);
    let (store, sid, name) = tab_on(master, 7101, group);
    assert_eq!(holds(&store, &sid, group), Some(true), "it holds its tab");
    assert_eq!(holds(&store, &sid, group + 1), Some(false), "another group");
    assert!(still_wanted(&store, &sid, group), "named");
    name(None);
    assert_eq!(holds(&store, &sid, group), Some(true), "a misread");
    assert!(
        still_wanted(&store, &sid, group),
        "a failed run during a misread"
    );
    assert!(
        !still_wanted(&store, &sid, group + 1),
        "not in the group it was named in"
    );
    name(Some("node"));
    assert_eq!(holds(&store, &sid, group), Some(true), "a runtime");
    name(Some("zsh"));
    assert_eq!(
        holds(&store, &sid, group),
        Some(false),
        "an exec into a shell"
    );
    assert!(!still_wanted(&store, &sid, group), "a shell's");
    name(Some("claude"));
    assert_eq!(holds(&store, &sid, 0), None, "no group named");
    assert_eq!(
        holds(&store, "s-00000000000000000000", group),
        None,
        "no such tab"
    );
    kill_until_reaped(group);
    assert_eq!(
        crate::quit_safety::foreground_pgrp(master),
        group,
        "the dead group still reads as the foreground: only the leader's conjunct reads its end"
    );
    assert_eq!(holds(&store, &sid, group), Some(false), "its end");
    store.write().unwrap().set_state(7101, SessionState::Exited);
    assert_eq!(holds(&store, &sid, group), Some(false), "the tab ended");
    end_pty_job(master, leader, group);
}

/// The hold is the group leader's ([`holds`]): on a real pty whose shell stays, it ends with the
/// agent, its group's leader, though a member of the group lives on in the foreground.
#[cfg(unix)]
#[test]
fn the_hold_reads_the_groups_leader() {
    let (master, leader, group) = pty_job(JobEnd::Member);
    let (store, sid, _name) = tab_on(master, 7102, group);
    assert_eq!(holds(&store, &sid, group), Some(true), "it holds its tab");
    kill_until_reaped(group);
    // SAFETY: `killpg(.., 0)` only asks whether the group has a member.
    assert_eq!(unsafe { libc::killpg(group, 0) }, 0, "a member lives on");
    assert_eq!(
        crate::quit_safety::foreground_pgrp(master),
        group,
        "its group is still the foreground"
    );
    assert_eq!(holds(&store, &sid, group), Some(false), "its leader ended");
    end_pty_job(master, leader, group);
}

#[test]
fn the_upgrades_own_restart_is_carried_on_whatever_relaunch_says() {
    let mut limited = on();
    limited.set("relaunch", "false").unwrap();
    let run = |restarted: Option<u32>, removed: bool| {
        let a = Arc::new(Acting::default());
        *a.steps.lock().unwrap() = ["wait:shell-prompt"].into();
        a.due.store(true, Ordering::SeqCst);
        a.open.lock().unwrap().insert("s-u".to_string());
        let end = Arc::clone(&a);
        *a.during_step.lock().unwrap() = Some(Box::new(move || {
            end.restarted_pids.lock().unwrap().extend(restarted);
            end.record_gone.store(removed, Ordering::SeqCst);
            *end.holds.lock().unwrap() = Some(false);
            end.busy.store(true, Ordering::SeqCst);
            end.set(&[]);
        }));
        a.set(&[("s-u", Program::Claude)]);
        let host = HostHandle::start(limited.clone(), false, false, a.hooks());
        (a, host)
    };
    let said = |a: &Acting| a.said_limited();
    let (a, host) = run(Some(snap("s-u").pid), true);
    until("carried", || a.carries.lock().unwrap().len() == 1);
    assert_eq!(*a.carries.lock().unwrap(), [(false, Some(snap("s-u").pid))]);
    assert_eq!(a.stepped.load(Ordering::SeqCst), 1);
    assert!(a.restarted_pids.lock().unwrap().is_empty(), "landed");
    assert!(
        a.relaunched.lock().unwrap().is_empty(),
        "never the relaunch on exit's"
    );
    assert!(!said(&a), "{:?}", a.badges.lock().unwrap());
    until("the relaunching worker reaped", || host.live().is_empty());
    a.busy.store(false, Ordering::SeqCst);
    a.set(&[("s-u", Program::Claude)]);
    until("attached again, and carried on", || {
        host.live() == ["s-u"] && a.carried.load(Ordering::SeqCst) == 1
    });
    assert!(!said(&a), "{:?}", a.badges.lock().unwrap());
    host.shutdown_and_join();
    for restarted in [None, Some(snap("s-u").pid + 1)] {
        let (a, host) = run(restarted, false);
        until("said once", || said(&a));
        assert!(
            a.relaunched.lock().unwrap().is_empty() && a.carries.lock().unwrap().is_empty(),
            "left: {restarted:?}"
        );
        host.shutdown_and_join();
    }
}

#[test]
fn a_restarts_loss_is_told_to_the_owner_once() {
    let lost = |notes: &[HostNote]| {
        notes
            .iter()
            .filter(|n| {
                matches!(
                    n,
                    HostNote::Relaunch {
                        said: RelaunchSay::NotRestored,
                        ..
                    }
                )
            })
            .count()
    };
    for (steps, told) in [
        (vec!["done:finished", "done:lost"], 1),
        (vec!["done:finished", "done:finished", "done"], 0),
        (vec!["done:resumed", "done"], 0),
        (vec!["done:resumed", "continued:restore", "done"], 0),
    ] {
        let a = Arc::new(Acting::default());
        let carried = steps.len();
        *a.carry.lock().unwrap() = steps.clone().into();
        a.owed.store(true, Ordering::SeqCst);
        a.open.lock().unwrap().insert("s-l".to_string());
        a.set(&[("s-l", Program::Claude)]);
        let host = HostHandle::start(on(), false, false, a.hooks());
        until("every look taken", || {
            a.carried.load(Ordering::SeqCst) >= carried && !a.owed.load(Ordering::SeqCst)
        });
        host.shutdown_and_join();
        assert_eq!(lost(&a.notes.lock().unwrap()), told, "{steps:?}");
    }
}

#[test]
fn a_relaunched_agent_is_carried_on_where_its_loop_parks() {
    let a = Arc::new(Acting::default());
    *a.carry.lock().unwrap() = ["continued", "done"].into();
    a.open.lock().unwrap().insert("s-h".to_string());
    a.set(&[("s-h", Program::Claude)]);
    let mut no_upgrade = on();
    no_upgrade.set("upgrade", "false").unwrap();
    let host = HostHandle::start(no_upgrade, false, false, a.hooks());
    a.attached(&host, "s-h");
    a.set(&[]);
    until("adopted", || a.owed.load(Ordering::SeqCst));
    a.set(&[("s-h", Program::Claude)]); // the relaunched agent
    until(
        "carried on, its model read at the next idle point: done",
        || a.carried.load(Ordering::SeqCst) == 2 && !a.owed.load(Ordering::SeqCst),
    );
    assert_eq!(a.stepped.load(Ordering::SeqCst), 0, "no upgrade step");
    host.shutdown_and_join();
}

#[test]
fn a_quiet_restarts_look_is_taken_at_the_tabs_next_look() {
    for (steps, carried) in [(vec!["done:resumed", "done"], 2), (vec!["done"], 1)] {
        let a = Arc::new(Acting::default());
        *a.carry.lock().unwrap() = steps.clone().into();
        a.owed.store(true, Ordering::SeqCst);
        a.open.lock().unwrap().insert("s-q".to_string());
        a.set(&[("s-q", Program::Claude)]);
        let host = HostHandle::start(on(), false, false, a.hooks());
        let decided = || {
            let decided = a.decided.lock().unwrap();
            (1..=carried)
                .map(|n| {
                    decided
                        .iter()
                        .find(|(at, _)| *at == n)
                        .map(|&(_, look)| look)
                })
                .collect::<Option<Vec<bool>>>()
        };
        until("every carry-on's point answered", || decided().is_some());
        assert!(!a.owed.load(Ordering::SeqCst), "{steps:?}");
        let looks = decided().expect("answered");
        let expected: Vec<bool> = (1..=carried).map(|n| n < carried).collect();
        assert_eq!(looks, expected, "{steps:?}");
        assert_eq!(a.carried.load(Ordering::SeqCst), carried, "{steps:?}");
        host.shutdown_and_join();
    }
}

#[test]
fn a_worker_that_attached_to_a_dead_agent_relaunches_on_what_was_read() {
    let a = Arc::new(Acting::default());
    a.open.lock().unwrap().insert("s-d".to_string());
    a.set(&[("s-d", Program::Claude)]);
    let host = HostHandle::start(on(), false, false, a.hooks());
    until("attached", || a.runs.load(Ordering::SeqCst) == 1);
    a.gone.store(true, Ordering::SeqCst);
    let mut changed = on();
    changed.set("dismiss_surveys", "false").unwrap();
    host.set_config(changed);
    until("a second worker, attached to what is gone", || {
        a.runs.load(Ordering::SeqCst) == 2
    });
    assert_eq!(a.parks.load(Ordering::SeqCst), 0);
    a.set(&[]);
    until("relaunched", || a.relaunched.lock().unwrap().len() == 1);
    assert!(a.badges.lock().unwrap().is_empty(), "nothing to say");
    host.shutdown_and_join();
    let b = Arc::new(Acting::default());
    b.gone.store(true, Ordering::SeqCst);
    b.open.lock().unwrap().insert("s-n".to_string());
    b.set(&[("s-n", Program::Claude)]);
    let host = HostHandle::start(on(), false, false, b.hooks());
    until(
        "attached, its idle point asked for once to read again",
        || b.runs.load(Ordering::SeqCst) == 1 && b.parks.load(Ordering::SeqCst) == 1,
    );
    b.set(&[]);
    until(
        "decided: nothing to relaunch it on, the session over",
        || host.live().is_empty() && !b.accounts_gone.lock().unwrap().is_empty(),
    );
    assert!(b.relaunched.lock().unwrap().is_empty());
    assert!(b.badges.lock().unwrap().is_empty(), "nothing to say");
    host.shutdown_and_join();
}

#[test]
fn the_snapshot_follows_its_agent_and_goes_with_its_exit() {
    let published = || published_snapshot("s-s");
    let a = Arc::new(Acting::default());
    a.open.lock().unwrap().insert("s-s".to_string());
    a.set(&[("s-s", Program::Claude)]);
    let host = HostHandle::start(on(), false, false, a.hooks());
    a.attached(&host, "s-s");
    until("the agent's snapshot read", || published().is_some());
    let cleared = "0badf00d-7777-2222-3333-444455556666".to_string();
    *a.conversation.lock().unwrap() = Some(cleared.clone());
    ring();
    until("the snapshot follows the /clear", || {
        published().and_then(|snap| snap.session).as_ref() == Some(&cleared)
    });
    a.set(&[]);
    until("relaunched", || a.relaunched.lock().unwrap().len() == 1);
    assert_eq!(*a.resumed.lock().unwrap(), [Some(cleared)], "the new one");
    until("the relaunching worker reaped", || host.live().is_empty());
    a.set(&[("s-s", Program::Claude)]);
    a.attached(&host, "s-s");
    *a.human_ms.lock().unwrap() = Some(1_000);
    a.set(&[]);
    until("detached", || host.live().is_empty());
    *a.human_ms.lock().unwrap() = None;
    a.gone.store(true, Ordering::SeqCst);
    a.set(&[("s-s", Program::Claude)]);
    until("attached to the wrapper", || host.live() == ["s-s"]);
    a.set(&[]);
    until("detached", || host.live().is_empty());
    assert_eq!(a.relaunched.lock().unwrap().len(), 1, "B is not A");
    a.gone.store(false, Ordering::SeqCst);
    a.set(&[("s-s", Program::Claude)]);
    a.attached(&host, "s-s");
    until("the agent's snapshot read", || published().is_some());
    a.gone.store(true, Ordering::SeqCst);
    a.another_job("s-s");
    until("the snapshot forgotten", || published().is_none());
    a.set(&[]);
    until("detached", || host.live().is_empty());
    assert_eq!(a.relaunched.lock().unwrap().len(), 1, "forgotten");
    assert!(a.badges.lock().unwrap().is_empty(), "nothing said");
    host.shutdown_and_join();
}

/// A layout that finds the host's copy behind its agent's record rings the host.
#[cfg(unix)]
#[test]
fn a_layout_that_finds_the_hosts_copy_behind_its_agents_record_rings_the_host() {
    let tmp = aterm_tempfile::Builder::new()
        .prefix("aterm-hh-followed-")
        .tempdir()
        .expect("temp dir");
    let dir = tmp.path().join(".claude");
    std::fs::create_dir_all(dir.join("sessions")).expect("the records' dir");
    let sid = "s-lc1-followed";
    let left = "0badf00d-1111-2222-3333-444455556666";
    let moved = "0badf00d-7777-2222-3333-444455556666";
    let copy = Snapshot {
        home: Some(dir.to_string_lossy().into_owned()),
        claude_dir: Some(dir.clone()),
        ..snap(sid)
    };
    assert_eq!(copy.session.as_deref(), Some(left));
    let record = |session: &str| {
        std::fs::write(
            dir.join("sessions/4242.json"),
            format!(
                r#"{{"pid":4242,"sessionId":"{session}","cwd":"{}","version":"{}","status":"idle","statusUpdatedAt":1,"procStart":"{}","kind":"interactive","entrypoint":"cli"}}"#,
                copy.cwd,
                copy.version.as_deref().expect("a build"),
                copy.start
            ),
        )
        .expect("the record");
    };
    let rings = || RINGS_HERE.with(std::cell::Cell::get);
    let session_of = |snap: Option<Snapshot>| snap.and_then(|snap| snap.session);
    publish_snapshot(sid, Some(&copy));

    record(moved);
    let before = rings();
    let followed = followed_snapshot(sid);
    assert_eq!(
        (session_of(followed), rings() - before),
        (Some(moved.to_string()), 1),
        "the record's conversation, and one ring"
    );
    assert_eq!(
        session_of(published_snapshot(sid)),
        Some(left.to_string()),
        "the host's copy is the host's to move"
    );

    record(left);
    let before = rings();
    let followed = followed_snapshot(sid);
    assert_eq!(
        (followed, rings() - before),
        (Some(copy.clone()), 0),
        "a copy the record agrees with rings nothing"
    );

    publish_snapshot(sid, None);
    let before = rings();
    assert_eq!(
        (followed_snapshot(sid), rings() - before),
        (None, 0),
        "no copy, nothing read"
    );
}

#[test]
fn a_record_read_that_hangs_holds_a_layout_one_bound_at_most() {
    const MOVED: &str = "feedface-1111-2222-3333-444455556666";
    let sid = "s-records-hung";
    let gate = Arc::new((Mutex::new(true), Condvar::new()));
    let reads = Arc::new(AtomicUsize::new(0));
    let (g, r) = (Arc::clone(&gate), Arc::clone(&reads));
    let records = Arc::new(RecordReader::new(move |_, snap| {
        r.fetch_add(1, Ordering::SeqCst);
        let (open, opened) = &*g;
        let mut open = open.lock().unwrap();
        while !*open {
            open = opened.wait(open).unwrap();
        }
        snap.session = Some(MOVED.to_string());
        true
    }));
    let copy = Snapshot {
        claude_dir: Some(PathBuf::from("/nonexistent/.claude")),
        ..snap(sid)
    };
    let left = copy.session.clone();
    publish_snapshot_for_test(sid, Some(&copy));
    let ask = |bound: Duration| {
        let (records, (tx, rx)) = (Arc::clone(&records), std::sync::mpsc::channel());
        std::thread::spawn(move || {
            let _ = tx.send(followed_snapshot_by(sid, &records, bound).and_then(|s| s.session));
        });
        rx.recv_timeout(aterm_spec::wait::MUST_HAPPEN)
            .expect("the ask answered within its hang detector")
    };
    let moved = Some(MOVED.to_string());
    assert_eq!(
        ask(aterm_spec::wait::MUST_HAPPEN),
        moved,
        "a read that answers"
    );
    *gate.0.lock().unwrap() = false;
    assert_eq!(
        ask(Duration::from_millis(1)),
        left,
        "past its bound: the copy"
    );
    until("the hung read started", || {
        reads.load(Ordering::SeqCst) == 2
    });
    assert_eq!(
        ask(aterm_spec::wait::MUST_HAPPEN),
        left,
        "while it hangs: the copy at once"
    );
    *gate.0.lock().unwrap() = true;
    gate.1.notify_all();
    until("the hung read ended", || {
        records.done.load(Ordering::SeqCst) >= records.given_up.load(Ordering::SeqCst)
    });
    assert_eq!(ask(aterm_spec::wait::MUST_HAPPEN), moved, "read again");
    assert_eq!(
        reads.load(Ordering::SeqCst),
        3,
        "no read was asked behind the hung one"
    );
    publish_snapshot_for_test(sid, None);
}

#[test]
fn a_failing_relaunch_names_the_cause_only_a_person_clears() {
    for (step, cause) in [
        ("wait:held", "held"),
        ("wait:shell-prompt", "shell-prompt"),
        ("wait:conversation-in-other-tab", "other-tab"),
    ] {
        assert_eq!(blocked_cause(step), Some(cause), "{step}");
    }
    assert_eq!(blocked_cause("wait:resume"), None);
    assert_eq!(blocked_cause("failed:no-resume"), None);
}

