#[test]
fn the_failing_mark_keeps_its_reason() {
    let command = "claude --resume 0badf00d-1111-2222-3333-444455556666";
    for (step, reason) in [
        ("wait:held", "its tab is held"),
        ("wait:shell-prompt", "a job keeps its shell from its prompt"),
        (
            "wait:resume",
            "the new agent never picked the conversation back up",
        ),
        (
            "failed:no-resume",
            "the new agent never picked the conversation back up",
        ),
    ] {
        let mark = failing_text(step, command).expect("a mark");
        assert!(
            mark.contains(&format!("({reason})")) && mark.contains(command),
            "{step}: {mark}"
        );
        assert!(mark.len() <= 190, "{step}: {} bytes", mark.len());
    }
    let long = "claude --model claude-opus-4-1-20250805 --permission-mode plan --resume \
                0badf00d-1111-2222-3333-444455556666";
    let mark = failing_text("wait:resume", long).expect("a mark");
    assert!(
        mark.contains("--permission-mode plan")
            && mark.ends_with("--resume 0badf00d-1111-2222-3333-444455556666 in this tab")
            && !mark.contains("--model"),
        "{mark}"
    );
}

#[test]
fn the_rosters_word_names_the_row_the_login_is_and_the_next_to_sign_in() {
    use aterm_agent::supervise::policy::turn_end::{HeldBy, Ready, RosterWord, SignInNext};
    let a = Accts::new();
    let never = a.login_dir("m8-2");
    std::fs::write(
        a.roster_path(),
        format!(
            "[[account]]\nlabel = \"main\"\nclass = \"dedicated\"\n\n[[account]]\nlabel = \
             \"m8-2\"\nclass = \"dedicated\"\ndir = '{never}'\nemail = \"two@example.com\"\n"
        ),
    )
    .unwrap();
    a.spawn("s-1", ACCT_TALK_A, "main");
    let idle = a.worker("s-1", &on());
    assert_eq!(
        idle.roster_word(),
        Some(RosterWord::Row {
            next: Some(SignInNext {
                label: "m8-2".to_string(),
                renew: true,
            }),
            ready: None,
            held: Some(HeldBy::Earlier),
        })
    );
    a.write_roster();
    let ready = |held: Option<HeldBy>| {
        Some(RosterWord::Row {
            next: None,
            ready: Some(Ready {
                label: "work-2".to_string(),
            }),
            held,
        })
    };
    assert_eq!(idle.roster_word(), ready(Some(HeldBy::Earlier)));
    edited(&a, |state| {
        accounts::note_wall(
            state,
            "main",
            "seven_day",
            Some(ACCT_NOW + 5 * 86_400),
            ACCT_NOW - 10,
            ACCT_NOW,
        );
        state.active = Some("main".to_string());
        state.proven = true;
        state.pinned = true;
    });
    assert_eq!(idle.roster_word(), ready(Some(HeldBy::Pin)));
    edited(&a, |state| {
        state.pinned = false;
        if let Some(main) = state.accounts.get_mut("main") {
            main.offer = Some(accounts::Offer {
                kind: None,
                left: 1,
                use_by: Some(ACCT_NOW + 3_600),
                at: ACCT_NOW - 10,
                by: "lab".to_string(),
            });
        }
    });
    assert_eq!(idle.roster_word(), ready(Some(HeldBy::Reset)));
    edited(&a, |state| {
        if let Some(main) = state.accounts.get_mut("main") {
            main.offer = None;
        }
    });
    assert_eq!(idle.roster_word(), ready(None));
    edited(&a, |state| {
        for label in ["work-2", "pool-a"] {
            accounts::note_wall(
                state,
                label,
                "seven_day",
                Some(ACCT_NOW + 5 * 86_400),
                ACCT_NOW - 10,
                ACCT_NOW,
            );
        }
    });
    assert_eq!(
        idle.roster_word(),
        Some(RosterWord::Row {
            next: None,
            ready: None,
            held: None,
        })
    );
    let unread = a.worker("s-gone", &on());
    assert_eq!(unread.roster_word(), Some(RosterWord::Unread));
    std::fs::write(a.roster_path(), "[[account]\nlabel = \n").unwrap();
    assert_eq!(idle.roster_word(), Some(RosterWord::Unread));
    std::fs::remove_file(a.roster_path()).unwrap();
    assert_eq!(idle.roster_word(), Some(RosterWord::Unlisted));
    a.write_roster();
    a.exec(
        "s-2",
        ACCT_TALK_A,
        Some("/elsewhere/claude"),
        ACCT_NOW - 100,
    );
    let other = a.worker("s-2", &on());
    assert_eq!(other.roster_word(), Some(RosterWord::Unlisted));
}

fn weekly_limit_reading(t: Instant) -> aterm_agent::supervise::policy::turn_end::TurnEndReading {
    use aterm_agent::supervise::policy::turn_end::TurnEndReading;
    let rows = aterm_phase::prompt::fixtures::rows(&["⏺ Carrying on.", ""]);
    let wall = "You've hit your weekly limit · resets Oct 23 at 8am (America/Los_Angeles)";
    TurnEndReading {
        phase: aterm_agent::supervise::phase::Phase::Idle,
        authoritative: true,
        wall: Some(aterm_phase::WallKind::UsageWeekly),
        wall_message: wall.to_string(),
        said_tail: Some(wall.to_string()),
        reset_at: Some(t + Duration::from_secs(6 * 24 * 3600)),
        taskless: false,
        program: Program::Claude,
        ..TurnEndReading::of(
            &aterm_phase::read(Some("claude"), &rows, Some(2)),
            &rows,
            false,
            Some(Duration::from_secs(180)),
            None,
            None,
        )
    }
}

fn weekly_worker_reading(
    a: &Arc<Accts>,
    sid: &str,
    cfg: &SupervisorConfig,
    weekly: &aterm_agent::supervise::policy::turn_end::TurnEndReading,
    st: &aterm_agent::supervise::policy::turn_end::TurnEndState,
    t: Instant,
) -> (
    bool,
    Option<aterm_agent::supervise::policy::turn_end::RosterWord>,
) {
    use aterm_agent::supervise::policy::exception::exception_for;
    use aterm_agent::supervise::policy::turn_end::TurnEndReading;
    let idle = a.worker(sid, cfg);
    let r = TurnEndReading {
        restartable: idle.can_restart(),
        relaunch_off: idle.relaunch_off(),
        roster: idle.roster_word(),
        ..weekly.clone()
    };
    assert_eq!(exception_for(st, &r, &effective(cfg), t), None);
    (r.relaunch_off, r.roster)
}

#[test]
fn relaunch_off_in_aterm_toml_is_named_by_a_weekly_limits_notice() {
    use aterm_agent::supervise::policy::turn_end::{HeldBy, Ready, RosterWord, TurnEndState};
    let a = Accts::new();
    a.spawn("s-1", ACCT_TALK_A, "main");
    let t = Instant::now();
    let weekly = weekly_limit_reading(t);
    let mut st = TurnEndState::default();
    st.observe(&weekly, t);
    let mut no_relaunch = on();
    no_relaunch.set("relaunch", "false").unwrap();
    assert_eq!(
        effective(&no_relaunch),
        on(),
        "the loop's config says it on"
    );
    let (relaunch_off, roster) = weekly_worker_reading(&a, "s-1", &no_relaunch, &weekly, &st, t);
    assert!(relaunch_off);
    assert_eq!(
        roster,
        Some(RosterWord::Row {
            next: None,
            ready: Some(Ready {
                label: "work-2".to_string()
            }),
            held: Some(HeldBy::Earlier),
        })
    );
    let (relaunch_off, _) = weekly_worker_reading(&a, "s-1", &on(), &weekly, &st, t);
    assert!(!relaunch_off);
}

#[test]
fn a_sign_in_by_name_promises_a_switch_only_where_the_roster_makes_one() {
    use aterm_agent::supervise::policy::turn_end::{
        HeldBy, Ready, RosterWord, SignInNext, TurnEndState,
    };
    let a = Accts::new();
    let m8 = a.login_dir("m8-2");
    std::fs::write(
        a.roster_path(),
        format!(
            "[[account]]\nlabel = \"main\"\nclass = \"dedicated\"\n\n[[account]]\nlabel = \
             \"m8-2\"\nclass = \"dedicated\"\ndir = '{m8}'\nemail = \"two@example.com\"\n"
        ),
    )
    .unwrap();
    let t = Instant::now();
    let weekly = weekly_limit_reading(t);
    let mut st = TurnEndState::default();
    st.observe(&weekly, t);
    let mut off = on();
    off.set("accounts", "off").unwrap();
    a.spawn("s-old", ACCT_TALK_A, "main");
    a.wall(ACCT_TALK_A, ACCT_NOW - 200);
    a.spawn("s-own", ACCT_TALK_B, "main");
    a.wall(ACCT_TALK_B, ACCT_NOW - 10);
    let sign_in = Some(SignInNext {
        label: "m8-2".to_string(),
        renew: true,
    });
    for (cfg, held_old, held_own) in [
        (at_wall_only(), Some(HeldBy::Earlier), None),
        (off.clone(), Some(HeldBy::Earlier), None),
    ] {
        let (_, roster_old) = weekly_worker_reading(&a, "s-old", &cfg, &weekly, &st, t);
        assert_eq!(
            roster_old,
            Some(RosterWord::Row {
                next: sign_in.clone(),
                ready: None,
                held: held_old,
            })
        );
        let (_, roster_own) = weekly_worker_reading(&a, "s-own", &cfg, &weekly, &st, t);
        assert_eq!(
            roster_own,
            Some(RosterWord::Row {
                next: sign_in.clone(),
                ready: None,
                held: held_own,
            })
        );
    }
    std::fs::create_dir_all(&m8).unwrap();
    std::fs::write(std::path::Path::new(&m8).join("a-login-file"), "{}").unwrap();
    let ready = Some(Ready {
        label: "m8-2".to_string(),
    });
    let (_, roster_ready) = weekly_worker_reading(&a, "s-old", &at_wall_only(), &weekly, &st, t);
    assert_eq!(
        roster_ready,
        Some(RosterWord::Row {
            next: None,
            ready: ready.clone(),
            held: Some(HeldBy::Earlier),
        })
    );
    let (_, roster_off_old) = weekly_worker_reading(&a, "s-old", &off, &weekly, &st, t);
    assert_eq!(
        roster_off_old,
        Some(RosterWord::Row {
            next: None,
            ready: ready.clone(),
            held: Some(HeldBy::Earlier),
        })
    );
    let (_, roster_off_own) = weekly_worker_reading(&a, "s-own", &off, &weekly, &st, t);
    assert_eq!(
        roster_off_own,
        Some(RosterWord::Row {
            next: None,
            ready,
            held: None,
        })
    );
}

#[test]
fn a_login_signed_back_in_at_the_tab_is_ok_again_for_its_own_account_alone() {
    let a = Accts::new();
    std::fs::write(
        a.roster_path(),
        "[[account]]\nlabel = \"main\"\nclass = \"dedicated\"\nemail = \"owner@example.com\"\n",
    )
    .unwrap();
    a.spawn("s-back", ACCT_TALK_A, "main");
    let mut cfg = on();
    cfg.set("accounts", "off").unwrap();
    let idle = a.worker("s-back", &cfg);
    assert_eq!(idle.account(AccountPoint::LoginEnded), None);
    assert_eq!(a.state().account("main").auth, accounts::Auth::SignedOut);
    let due = || {
        let roster = a.roster();
        let logins = a.store().load_logins(a.clock()).expect("reads").0;
        accounts::renew_due(
            &roster,
            &logins,
            &a.state(),
            &accounts::enrolled(&roster),
            a.clock(),
        )
    };
    assert_eq!(due(), ["main"]);
    let profile = a.tmp.path().join("home").join(".claude.json");
    let own = r#"{"oauthAccount":{"emailAddress":"Owner@Example.com"}}"#;
    a.now.store(ACCT_NOW + 60, Ordering::SeqCst);
    std::fs::write(&profile, own).unwrap();
    let _ = idle.account(AccountPoint::TurnEnd);
    assert_eq!(
        a.state().account("main").auth,
        accounts::Auth::SignedOut,
        "a turn end is no sign-in"
    );
    assert_eq!(due(), ["main"]);
    for text in [
        r#"{"oauthAccount":{"emailAddress":"someone-else@example.com"}}"#,
        r#"{"oauthAccount":{"accountUuid":"u-1"}}"#,
    ] {
        std::fs::write(&profile, text).unwrap();
        idle.login_back();
        assert_eq!(
            a.state().account("main").auth,
            accounts::Auth::SignedOut,
            "{text}"
        );
        assert_eq!(due(), ["main"], "{text}");
    }
    std::fs::write(&profile, own).unwrap();
    idle.login_back();
    assert_eq!(a.state().account("main").auth, accounts::Auth::Ok);
    assert!(due().is_empty(), "{:?}", due());
}

#[test]
fn a_login_a_tab_signs_in_is_off_the_digests_due_line() {
    let a = Accts::new();
    std::fs::write(
        a.roster_path(),
        "[[account]]\nlabel = \"main\"\nclass = \"dedicated\"\nemail = \"owner@example.com\"\n",
    )
    .unwrap();
    a.spawn("s-carry", ACCT_TALK_A, "main");
    let mut cfg = on();
    cfg.set("accounts", "off").unwrap();
    let idle = a.worker("s-carry", &cfg);
    assert_eq!(idle.account(AccountPoint::LoginEnded), None);
    let due = || {
        let logins = a.store().load_logins(a.clock()).expect("reads").0;
        match AccountsSaid::listed(
            &a.roster(),
            &a.state(),
            &logins,
            a.clock(),
            &idle.login_latches.carried_rows(),
        ) {
            AccountsSaid::Listed { due, .. } => due,
            other => panic!("{other:?}"),
        }
    };
    let looked = || {
        accounts_said(
            false,
            true,
            false,
            &(a.hooks().acts.account_seat)().expect("a seat"),
            &idle.login_latches.carried_rows(),
        )
    };
    assert_eq!(due(), ["main"]);
    assert!(
        matches!(looked(), Some(AccountsSaid::Listed { due, .. }) if due == ["main"]),
        "{:?}",
        looked()
    );
    assert_eq!(idle.login_carry(), Ok(()));
    assert!(due().is_empty(), "{:?}", due());
    assert!(
        matches!(looked(), Some(AccountsSaid::Listed { due, .. }) if due.is_empty()),
        "{:?}",
        looked()
    );
    idle.login_latches.gone(&latch_tab("s-carry"));
    assert_eq!(due(), ["main"]);
}

#[test]
fn a_tabs_sign_in_ends_when_a_move_relaunches_it_onto_another_login() {
    let signed_out = |said: &AccountsSaid| match said {
        AccountsSaid::Listed { signed_out, .. } => signed_out.clone(),
        other => panic!("{other:?}"),
    };
    for (answer, took) in [("adopted", true), ("failed:no-resume", false)] {
        let a = Accts::new();
        a.spawn("s-left", ACCT_TALK_A, "main");
        a.wall(ACCT_TALK_A, ACCT_NOW - 10);
        a.answers.lock().unwrap().push_back(answer);
        let (hooks, notes) = noting(a.hooks());
        let idle = idle_host("s-left", Program::Claude, switched(&on()), hooks);
        idle.kept.lock().unwrap().snapshot = a.tabs.lock().unwrap().get("s-left").cloned();
        assert_eq!(
            moves(&idle.account(usage_wall())),
            Some("work-2"),
            "{answer}"
        );
        assert_eq!(idle.login_carry(), Ok(()), "{answer}");
        let main = BTreeSet::from(["main".to_string()]);
        assert_eq!(idle.login_latches.carried_rows(), main, "{answer}");
        struck_out(&a, "main", "s-other", ACCT_NOW - 5);
        let told = accounts_told(&notes).len();
        let step = idle.restart(&move_to("work-2", AccountAt::Wall));
        assert_eq!(
            step.as_deref().is_some_and(relaunch_took),
            took,
            "{answer}: {step:?}"
        );
        let logins = a.store().load_logins(a.clock()).expect("reads").0;
        let now = AccountsSaid::listed(
            &a.roster(),
            &a.state(),
            &logins,
            a.clock(),
            &idle.login_latches.carried_rows(),
        );
        let after = accounts_told(&notes);
        if took {
            assert!(idle.login_latches.carried_rows().is_empty());
            assert_eq!(signed_out(&now), ["main"]);
            assert!(
                after[told..]
                    .iter()
                    .any(|said| signed_out(said) == ["main"]),
                "told at once: {after:?}"
            );
        } else {
            assert_eq!(idle.login_latches.carried_rows(), main);
            assert!(signed_out(&now).is_empty(), "{now:?}");
            assert!(
                !after[told..]
                    .iter()
                    .any(|said| signed_out(said) == ["main"]),
                "{after:?}"
            );
        }
    }
}

#[test]
fn a_struck_login_signed_back_in_at_the_tab_is_ok_again() {
    let (a, idle) = moved_at_wall("s-acct-back");
    idle.account_answered(AccountBad::SignedOut);
    assert_eq!(a.state().account("work-2").auth, accounts::Auth::SignedOut);
    let signed_out = || {
        let roster = a.roster();
        accounts::signed_out(&roster, &a.state(), &accounts::enrolled(&roster), a.clock())
    };
    assert_eq!(signed_out(), ["work-2"]);
    a.now.store(ACCT_NOW + 60, Ordering::SeqCst);
    idle.account_served();
    assert_eq!(a.state().account("work-2").auth, accounts::Auth::Ok);
    assert!(signed_out().is_empty());
    let (a, idle) = moved_at_wall("s-acct-served");
    let before = a.ledger();
    idle.account_served();
    let after = a.ledger();
    assert_eq!(
        after[before.len()..]
            .iter()
            .filter(|k| **k == "auth")
            .count(),
        0,
        "{after:?}"
    );
}

#[test]
fn a_renewable_login_s_end_is_recorded_and_its_renewal_followed() {
    let a = Accts::new();
    std::fs::write(
        a.roster_path(),
        "[[account]]\nlabel = \"main\"\nclass = \"dedicated\"\nemail = \"owner@example.com\"\n",
    )
    .unwrap();
    a.spawn("s-login", ACCT_TALK_A, "main");
    let mut cfg = on();
    cfg.set("accounts", "off").unwrap();
    let idle = a.worker("s-login", &cfg);
    assert_eq!(idle.login_label().as_deref(), Some("main"));
    assert!(!idle.login_superseded(), "its row's own login");
    let ended = AccountPoint::LoginEnded;
    assert_eq!(
        idle.account(ended),
        None,
        "nothing to move to before a renewal"
    );
    assert_eq!(a.state().account("main").auth, accounts::Auth::SignedOut);
    assert_eq!(a.ledger(), ["auth", "login-ended"]);
    assert_eq!(idle.account(ended), None);
    assert_eq!(a.ledger(), ["auth", "login-ended"], "the same end, once");
    idle.login_notice(2);
    let logins = || a.store().load_logins(a.clock()).expect("reads").0;
    assert_eq!(
        logins().get("main").and_then(|b| b.notice_end),
        Some(a.clock() + 2 * 86_400)
    );
    let staging = a.tmp.path().join("logins").join("main+1");
    std::fs::create_dir_all(&staging).unwrap();
    std::fs::write(staging.join(".claude.json"), "{}").unwrap();
    let staging = staging.to_string_lossy().into_owned();
    let mut note = None;
    a.store()
        .transact_logins(a.clock(), &mut note, |state, logins| {
            Ok(accounts::note_renewed(
                state,
                logins,
                "main",
                None,
                &staging,
                None,
                a.clock(),
            ))
        })
        .expect("renewed");
    idle.login_notice(1);
    assert_eq!(logins().get("main").and_then(|b| b.notice_end), None);
    assert_eq!(
        idle.login_label().as_deref(),
        Some("main"),
        "still the account's"
    );
    assert!(idle.login_superseded(), "on the login the renewal replaced");
    assert_eq!(
        idle.account(ended),
        Some(AccountAdvice::Move {
            to: "main".to_string()
        }),
        "the move onto the renewed login"
    );
    let step = idle.restart(&move_to("main", AccountAt::Wall));
    assert_eq!(step.as_deref(), Some("adopted"));
    let tab = a
        .tabs
        .lock()
        .unwrap()
        .get("s-login")
        .cloned()
        .expect("relaunched");
    assert_eq!(
        tab.login.as_deref(),
        Some(staging.as_str()),
        "the RENEWED login"
    );
    assert!(!idle.login_superseded(), "its row's own login again");
    assert_eq!(idle.account(AccountPoint::TurnEnd), None);
    assert!(logins().get("main").and_then(|b| b.served_at).is_some());
    let file = accounts::Roster::load(&a.roster_path()).unwrap();
    assert_eq!(
        accounts::login_state(&file.rows[0], &logins(), &a.state(), a.clock()),
        accounts::LoginState::Ok
    );

    let b = Accts::new();
    b.spawn("s-plain", ACCT_TALK_A, "main");
    let plain = b.worker("s-plain", &on());
    assert_eq!(plain.login_label(), None);
    assert!(!plain.login_superseded());
    let mut off = cfg.clone();
    off.set("logins", "off").unwrap();
    let quiet = a.worker("s-login", &off);
    let before = a.said().len();
    assert_eq!(quiet.login_label(), None);
    assert!(!quiet.login_superseded());
    quiet.login_notice(3);
    assert_eq!(quiet.account(ended), None);
    assert_eq!(a.said().len(), before, "nothing of the agent is read");
}

#[test]
fn a_superseded_logins_end_strikes_nothing_and_follows_under_a_wall() {
    let a = Accts::new();
    a.spawn("s-left", ACCT_TALK_A, "main");
    let mut cfg = on();
    cfg.set("accounts", "off").unwrap();
    let idle = a.worker("s-left", &cfg);
    let staging = renew_own(&a);
    assert!(idle.login_superseded());
    let mut note = None;
    let ledger = a.ledger();
    idle.account_answered(AccountBad::SignedOut);
    assert_eq!(
        a.state().account("main").auth,
        accounts::Auth::Ok,
        "the renewed login is not struck"
    );
    assert_eq!(a.ledger(), ledger, "nothing recorded");
    let lost = AccountPoint::Wall {
        kind: aterm_phase::WallKind::Auth,
    };
    assert_eq!(
        idle.account(lost),
        Some(AccountAdvice::Move {
            to: "main".to_string()
        }),
        "the move onto the renewed login"
    );
    let until = a.clock() + 5 * 24 * 3600;
    a.store()
        .transact(a.clock(), &mut note, |state| {
            Ok(accounts::note_wall(
                state,
                "main",
                "seven_day_opus",
                Some(until),
                a.clock() - 60,
                a.clock(),
            ))
        })
        .expect("walled");
    for point in [lost, AccountPoint::LoginEnded] {
        assert_eq!(
            idle.account(point),
            Some(AccountAdvice::Move {
                to: "main".to_string()
            }),
            "{point:?}: followed under the wall"
        );
    }
    a.exec("s-left", ACCT_TALK_A, Some(&staging), a.clock());
    assert!(refresh_snapshot("s-left", &idle.kept, &idle.hooks));
    assert!(!idle.login_superseded(), "its row's own login");
    idle.account_answered(AccountBad::SignedOut);
    assert_eq!(a.state().account("main").auth, accounts::Auth::SignedOut);
}

const OWN_ROW: &str =
    "[[account]]\nlabel = \"main\"\nclass = \"dedicated\"\nemail = \"owner@example.com\"\n";

fn renew_own(a: &Accts) -> String {
    std::fs::write(a.roster_path(), OWN_ROW).unwrap();
    let staging = a.tmp.path().join("logins").join("main+1");
    std::fs::create_dir_all(&staging).unwrap();
    std::fs::write(staging.join(".claude.json"), "{}").unwrap();
    let staging = staging.to_string_lossy().into_owned();
    let mut note = None;
    a.store()
        .transact_logins(a.clock(), &mut note, |state, logins| {
            Ok(accounts::note_renewed(
                state,
                logins,
                "main",
                None,
                &staging,
                None,
                a.clock(),
            ))
        })
        .expect("renewed");
    staging
}

#[test]
fn logins_off_does_not_advise_following_a_superseded_login() {
    for mode in ["early", "wall"] {
        let a = Accts::new();
        a.spawn("s-renew-off", ACCT_TALK_A, "main");
        renew_own(&a);
        let mut cfg = on();
        cfg.set("accounts", mode).unwrap();
        let idle = a.worker("s-renew-off", &cfg);
        assert_eq!(moves(&idle.account(AccountPoint::TurnEnd)), Some("main"));
        cfg.set("logins", "off").unwrap();
        idle.switches.set(&cfg, false);
        assert_eq!(idle.login_label(), None);
        assert!(!idle.login_superseded());
        assert_eq!(
            moves(&idle.account(AccountPoint::TurnEnd)),
            None,
            "{mode}: ordinary account advice must respect the renewal opt-out"
        );
        assert_eq!(a.asked("restart:"), 0);
    }
}

#[test]
fn logins_off_between_advice_and_commit_prevents_a_renewal_relaunch() {
    for mode in ["early", "wall"] {
        let a = Accts::new();
        a.spawn("s-renew-off", ACCT_TALK_A, "main");
        renew_own(&a);
        let mut cfg = on();
        cfg.set("accounts", mode).unwrap();
        let idle = a.worker("s-renew-off", &cfg);
        assert_eq!(moves(&idle.account(AccountPoint::TurnEnd)), Some("main"));
        cfg.set("logins", "off").unwrap();
        idle.switches.set(&cfg, false);
        assert_eq!(
            idle.restart(&move_to("main", AccountAt::Ahead)).as_deref(),
            Some("wait:account-changed"),
            "{mode}: a renewal advised while on is not committed while off"
        );
        assert_eq!(a.asked("restart:"), 0, "no process was relaunched");
        let tab = a.tabs.lock().unwrap().get("s-renew-off").cloned().unwrap();
        assert_eq!(tab.login, None, "the process retains its existing login");
    }
}

#[test]
fn logins_off_while_the_commit_is_opening_is_read_by_its_re_advice() {
    let a = Accts::new();
    a.spawn("s-renew-off", ACCT_TALK_A, "main");
    renew_own(&a);
    let mut cfg = on();
    let idle = a.worker("s-renew-off", &cfg);
    assert_eq!(moves(&idle.account(AccountPoint::TurnEnd)), Some("main"));
    cfg.set("logins", "off").unwrap();
    let switches = idle.switches.clone();
    a.at_seat_read(2, move |_| switches.set(&cfg, false));
    assert_eq!(
        idle.restart(&move_to("main", AccountAt::Ahead)).as_deref(),
        Some("wait:account-changed")
    );
    assert_eq!(
        a.asked("restart:"),
        0,
        "the late switch fences the relaunch"
    );
}

#[test]
fn logins_off_keeps_a_superseded_process_attributed_for_account_rotation() {
    for mode in ["early", "wall"] {
        let a = Accts::new();
        a.spawn("s-renew-off", ACCT_TALK_A, "main");
        renew_own(&a);
        std::fs::write(
            a.roster_path(),
            format!(
                "{OWN_ROW}\n[[account]]\nlabel = \"work-2\"\nclass = \"dedicated\"\ndir = '{}'\n",
                a.login_dir("work-2")
            ),
        )
        .unwrap();
        let roster = a.roster();
        a.store()
            .transact(a.clock(), &mut None, |state| {
                accounts::pin(
                    state,
                    &roster,
                    &accounts::enrolled(&roster),
                    "work-2",
                    a.clock(),
                )
                .map(|event| vec![event])
            })
            .expect("the owner's pinned account");
        let mut cfg = on();
        cfg.set("accounts", mode).unwrap();
        cfg.set("logins", "off").unwrap();
        let idle = a.worker("s-renew-off", &cfg);
        assert_eq!(moves(&idle.account(usage_wall())), Some("work-2"));
        assert_eq!(
            idle.restart(&move_to("work-2", AccountAt::Wall)).as_deref(),
            Some("adopted")
        );
        assert_eq!(a.asked("restart:s-renew-off:work-2:"), 1);
        let tab = a.tabs.lock().unwrap().get("s-renew-off").cloned().unwrap();
        assert_eq!(tab.login.as_deref(), Some(a.login_dir("work-2").as_str()));
    }
}

#[test]
fn uncertain_login_bindings_do_not_make_an_old_login_strike_its_renewal() {
    for damage in ["torn", "unreadable"] {
        let a = Accts::new();
        a.spawn("s-binding-unknown", ACCT_TALK_A, "main");
        renew_own(&a);
        let idle = a.worker("s-binding-unknown", &on());
        assert!(
            idle.login_superseded(),
            "known bindings identify the old login"
        );
        assert_eq!(a.state().account("main").auth, accounts::Auth::Ok);
        let file = a.store().logins_file();
        let saved = std::fs::read(&file).unwrap();
        let ledger = a.ledger_len();
        if damage == "torn" {
            std::fs::write(&file, "{").unwrap();
        } else {
            std::fs::remove_file(&file).unwrap();
            std::fs::create_dir(&file).unwrap();
        }
        idle.account_answered(AccountBad::SignedOut);
        assert_eq!(
            a.state().account("main").auth,
            accounts::Auth::Ok,
            "{damage}: an uncertain old-login identity is no strike against the renewed login"
        );
        assert_eq!(a.ledger_len(), ledger, "{damage}: no account was judged");
        assert_eq!(idle.account(AccountPoint::TurnEnd), None, "{damage}");
        assert_eq!(a.asked("restart:"), 0);
        if damage == "unreadable" {
            std::fs::remove_dir(&file).unwrap();
        }
        std::fs::write(&file, saved).unwrap();
        assert!(
            idle.login_superseded(),
            "the same session recovers after repair"
        );
        assert_eq!(moves(&idle.account(AccountPoint::TurnEnd)), Some("main"));
    }
}

#[test]
fn uncertain_login_bindings_do_not_cold_restore_an_original_login() {
    let a = Accts::new();
    let original = a.login_dir("work-2");
    let renewed = a.login_dir("work-2+1");
    std::fs::create_dir_all(&renewed).unwrap();
    std::fs::write(Path::new(&renewed).join(".claude.json"), "{}").unwrap();
    let roster = a.roster();
    a.store()
        .transact_logins(a.clock(), &mut None, |state, logins| {
            let mut events = accounts::note_renewed(
                state,
                logins,
                "work-2",
                Some(&original),
                &renewed,
                None,
                a.clock(),
            );
            events.push(accounts::pin(
                state,
                &roster,
                &accounts::enrolled(&roster),
                "work-2",
                a.clock(),
            )?);
            Ok(events)
        })
        .unwrap();
    std::fs::write(
        a.tmp
            .path()
            .join("home/.claude/projects/proj")
            .join(format!("{ACCT_TALK_A}.jsonl")),
        "{}\n",
    )
    .unwrap();
    let seat = AccountSeat {
        roster: Some(a.roster_path()),
        state: a.state_root(),
        home: a.tmp.path().join("home"),
        now: a.clock(),
        ladder: a.ladder(),
    };
    let cold = Snapshot {
        session: Some(ACCT_TALK_A.to_string()),
        ..snap("s-binding-cold")
    };
    assert_eq!(
        account_cold_at(&seat, &cold, || None).as_deref(),
        Some(renewed.as_str())
    );
    let file = a.store().logins_file();
    let saved = std::fs::read(&file).unwrap();
    std::fs::write(&file, "{").unwrap();
    assert_eq!(
        account_cold_at(&seat, &cold, || panic!(
            "unknown bindings must stop before reading the shell"
        )),
        None,
        "no old-directory fallback is a substitute for the unknown renewed login"
    );
    std::fs::write(&file, saved).unwrap();
    assert_eq!(
        account_cold_at(&seat, &cold, || None).as_deref(),
        Some(renewed.as_str())
    );
}

#[test]
fn a_superseded_session_at_a_usage_limit_is_not_followed() {
    let a = Accts::new();
    a.spawn("s-left", ACCT_TALK_A, "main");
    let idle = a.worker("s-left", &on());
    renew_own(&a);
    assert!(idle.login_superseded());
    let mut note = None;
    a.store()
        .transact(a.clock(), &mut note, |state| {
            Ok(accounts::note_wall(
                state,
                "main",
                "five_hour",
                Some(ACCT_NOW + 3600),
                a.clock() - 60,
                a.clock(),
            ))
        })
        .expect("walled");
    let again = |advice: Option<AccountAdvice>| {
        matches!(advice, Some(AccountAdvice::Wait { until })
            if until <= Instant::now() + WALL_AGAIN_AFTER)
    };
    let unwritten = idle.account(usage_wall());
    assert!(again(unwritten.clone()), "no row yet: {unwritten:?}");
    a.wall(ACCT_TALK_A, ACCT_NOW - 200);
    assert_eq!(idle.account(usage_wall()), None, "an earlier process's row");
    a.wall(ACCT_TALK_A, ACCT_NOW - 50);
    let own = idle.account(usage_wall());
    assert!(
        matches!(own, Some(AccountAdvice::Wait { .. })) && !again(own.clone()),
        "its own wall waits for the reset: {own:?}"
    );
    assert_eq!(a.asked("restart:"), 0, "nobody relaunched");
    assert_eq!(
        idle.account(AccountPoint::TurnEnd),
        Some(AccountAdvice::Move {
            to: "main".to_string()
        })
    );
}

#[test]
fn a_superseded_session_at_a_usage_limit_follows_the_owners_account() {
    let a = Accts::new();
    a.spawn("s-left", ACCT_TALK_A, "main");
    let idle = a.worker("s-left", &on());
    renew_own(&a);
    std::fs::write(
        a.roster_path(),
        format!(
            "{OWN_ROW}\n[[account]]\nlabel = \"work-2\"\nclass = \"dedicated\"\ndir = '{}'\n",
            a.login_dir("work-2")
        ),
    )
    .unwrap();
    assert!(idle.login_superseded());
    let roster = a.roster();
    let mut note = None;
    a.store()
        .transact(ACCT_NOW, &mut note, |state| {
            accounts::pin(
                state,
                &roster,
                &accounts::enrolled(&roster),
                "work-2",
                ACCT_NOW,
            )
            .map(|event| vec![event])
        })
        .expect("the pin");
    assert_eq!(moves(&idle.account(AccountPoint::TurnEnd)), Some("main"));
    assert_eq!(
        moves(&idle.account(usage_wall())),
        Some("work-2"),
        "unwritten"
    );
    a.wall(ACCT_TALK_A, ACCT_NOW - 200);
    assert_eq!(
        moves(&idle.account(usage_wall())),
        Some("work-2"),
        "not own"
    );
    assert_eq!(
        idle.restart(&move_to("work-2", AccountAt::Wall)).as_deref(),
        Some("adopted")
    );
    assert_eq!(a.asked("restart:s-left:work-2:"), 1, "{:?}", a.said());
    let state = a.state();
    assert!(
        state.account("main").walls.is_empty(),
        "recorded for nobody"
    );
    assert!(state.rotations.is_empty(), "a follow rotates nothing");
    assert_eq!(
        state.sessions.get("s-left").map(|s| s.account.as_str()),
        Some("work-2")
    );
}

/// A world for the usage tap's host half.
#[cfg(unix)]
struct TapWorld {
    tmp: aterm_tempfile::TempDir,
    now: std::sync::atomic::AtomicI64,
    born: i64,
    env: Mutex<Vec<String>>,
    listed: AtomicBool,
    world: Arc<World>,
    /// The seat's bounded wait for the store's lock ([`AccountSeat::ladder`]):
    /// the product's, until the test's own hand holds the lock
    /// ([`Self::hold_lock`]).
    ladder: Mutex<&'static [Duration]>,
}

#[cfg(unix)]
const TAP_SID: &str = "s-7a9";
#[cfg(unix)]
const TAP_PID: u32 = 4242;

#[cfg(unix)]
impl TapWorld {
    fn new() -> Arc<Self> {
        let now = aterm_time::unix_secs()
            .and_then(|s| i64::try_from(s).ok())
            .expect("a clock");
        Arc::new(TapWorld {
            tmp: aterm_tempfile::Builder::new()
                .prefix("aterm-host-tap-")
                .tempdir()
                .expect("temp dir"),
            now: std::sync::atomic::AtomicI64::new(now),
            born: now - 120,
            env: Mutex::new(vec!["HOME=/Users//example".to_string()]),
            listed: AtomicBool::new(false),
            world: Arc::new(World::default()),
            ladder: Mutex::new(&accounts::LOCK_LADDER),
        })
    }

    fn hold_lock(&self) -> accounts::Lock {
        *self.ladder.lock().unwrap() = &[];
        accounts::Store::at(&self.state())
            .acquire()
            .expect("the store's lock")
    }

    fn state(&self) -> PathBuf {
        self.tmp.path().join("state")
    }

    fn roster_path(&self) -> PathBuf {
        self.tmp.path().join("accounts.toml")
    }

    fn rl(&self) -> PathBuf {
        tap::rl_dir_in(&self.state())
    }

    fn clock(&self) -> i64 {
        self.now.load(Ordering::SeqCst)
    }

    fn later(&self, s: i64) {
        self.now.fetch_add(s, Ordering::SeqCst);
    }

    fn tap(&self, api_ms: u64, pct: u32, login: Option<&str>) {
        let vars = tap::TapVars {
            sid: Some(TAP_SID.to_string()),
            pid: Some(TAP_PID.to_string()),
            login: login.map(str::to_owned),
            home: None,
        };
        let reset = self.born + 4 * 3600;
        let stdin = format!(
            r#"{{"cost":{{"total_api_duration_ms":{api_ms}}},"rate_limits":{{"five_hour":{{"used_percentage":{pct},"resets_at":{reset}}},"seven_day":{{"used_percentage":30,"resets_at":{}}}}}}}"#,
            reset + 86_400
        );
        let mut out = Vec::new();
        let _ = tap::run(
            &mut stdin.as_bytes(),
            false,
            &vars,
            Some(&self.rl()),
            self.clock(),
            &mut out,
        );
        let file = self
            .rl()
            .join(tap::file_name(TAP_SID, TAP_PID).expect("a name"));
        let at = std::time::UNIX_EPOCH
            + Duration::from_secs(u64::try_from(self.clock()).expect("a clock"));
        std::fs::File::options()
            .write(true)
            .open(&file)
            .and_then(|f| f.set_modified(at))
            .expect("the reading's time");
    }

    fn worker(
        self: &Arc<Self>,
        cfg: &SupervisorConfig,
        argv: Vec<String>,
        stored: bool,
    ) -> WorkerIdle {
        let mut hooks = hooks(&self.world, parking_body(&self.world));
        let (a1, a2, a3) = (Arc::clone(self), Arc::clone(self), Arc::clone(self));
        hooks.acts = Acts {
            account_seat: Arc::new(move || {
                Some(AccountSeat {
                    roster: Some(a1.roster_path()),
                    state: a1.state(),
                    home: a1.tmp.path().join("home"),
                    now: a1.clock(),
                    ladder: *a1.ladder.lock().unwrap(),
                })
            }),
            account_env: Arc::new(move |pid| {
                (pid == TAP_PID).then(|| a2.env.lock().unwrap().clone())
            }),
            route: Arc::new(|_, _, _| Route::Default),
            account_settings: Arc::new(|_, _, _| true),
            tap_born: Arc::new(move |pid| [TAP_PID, TAP_PID + 1].contains(&pid).then_some(a3.born)),
            ..Acts::inert()
        };
        if self.listed.load(Ordering::SeqCst) {
            std::fs::write(
                self.roster_path(),
                "[[account]]\nlabel = \"main\"\nclass = \"dedicated\"\n\n[[account]]\nlabel = \"work-2\"\nclass = \"dedicated\"\ndir = \"/logins/work-2\"\n",
            )
            .expect("roster");
        }
        let idle = idle_host(TAP_SID, Program::Claude, switched(cfg), hooks);
        idle.kept.lock().unwrap().snapshot = Some(Snapshot {
            stored_login: stored,
            profile: None,
            pid: TAP_PID,
            argv,
            ..snap(TAP_SID)
        });
        idle
    }

    fn sample(&self) -> Option<accounts::Sample> {
        self.sample_of("main")
    }

    fn sample_of(&self, label: &str) -> Option<accounts::Sample> {
        let (state, _) = accounts::Store::at(&self.state()).load(self.clock()).ok()?;
        state.accounts.get(label)?.sample.clone()
    }

    fn rows(&self, kind: accounts::Kind) -> usize {
        accounts::Store::at(&self.state())
            .tail(100)
            .unwrap_or_default()
            .iter()
            .filter(|e| e.kind == kind)
            .count()
    }

    fn notes(&self) -> Vec<HostNote> {
        self.world.notes.lock().unwrap().clone()
    }
}

/// A Claude Code argv carrying aterm's tap.
#[cfg(unix)]
fn tapped_argv() -> Vec<String> {
    let value = tap::settings_value(std::path::Path::new(
        "/Applications/aterm.app/Contents/MacOS/aterm",
    ))
    .expect("an admissible path");
    vec!["claude".to_string(), "--settings".to_string(), value]
}

#[cfg(unix)]
fn tap_on() -> SupervisorConfig {
    let mut c = on();
    c.set("usage_tap", "true").expect("a switch");
    c
}

/// [`on`] with the tap turned off (`[harness] usage_tap = false`; it ships on).
#[cfg(unix)]
fn tap_off() -> SupervisorConfig {
    let mut c = on();
    c.set("usage_tap", "false").expect("a switch");
    c
}

/// The usage tap's session log mark.
#[cfg(unix)]
#[test]
fn a_taken_usage_reading_is_one_session_log_mark_while_the_tap_is_on() {
    let w = TapWorld::new();
    let idle = w.worker(&tap_on(), tapped_argv(), true);
    w.tap(10, 42, None);
    idle.usage_tap();
    assert_eq!(
        *w.world.usage.lock().unwrap(),
        [(TAP_SID.to_string(), Some(42), Some(30))]
    );
    w.later(10);
    w.tap(10, 42, None);
    idle.usage_tap();
    assert_eq!(w.world.usage.lock().unwrap().len(), 1, "an idle repeat");
    idle.switches.usage_tap.store(false, Ordering::SeqCst);
    w.later(10);
    w.tap(30, 47, None);
    idle.usage_tap();
    assert_eq!(w.sample().and_then(|s| s.session_pct), Some(47), "taken");
    assert_eq!(w.world.usage.lock().unwrap().len(), 1, "the tap is off");
    let store = crate::session_store::new_store();
    let h = crate::session_store::test_handle(5);
    store.write().unwrap().register(h.clone());
    let sub = crate::session_watch::Subscription::single(&h.ctx.watchers);
    let _ = sub.wait(Duration::ZERO);
    log_usage(&store, h.ctx.self_id.as_str(), Some(42), Some(30));
    assert!(
        sub.wait(aterm_spec::wait::MUST_HAPPEN),
        "the tab's watchers"
    );
    let marks = || -> Vec<String> {
        let g = h.ctx.timeline.lock().unwrap();
        g.slog()
            .log()
            .window()
            .filter_map(|r| aterm_slog::encode(r, aterm_slog::Tier::Host).ok())
            .filter(|l| l.contains(" mark - usage "))
            .collect()
    };
    let got = marks();
    assert_eq!(got.len(), 1, "{got:?}");
    assert!(
        got[0].contains(" mark - usage h5=42 d7=30 by=vendor src=aterm conf=strong "),
        "{got:?}"
    );
    log_usage(&store, "s-gone", Some(1), None);
    assert_eq!(marks().len(), 1, "a tab gone");
}

#[test]
fn a_hosted_relaunch_row_that_moved_the_session_is_one_act_mark() {
    let store = crate::session_store::new_store();
    let h = crate::session_store::test_handle(5);
    store.write().unwrap().register(h.clone());
    let sub = crate::session_watch::Subscription::single(&h.ctx.watchers);
    let _ = sub.wait(Duration::ZERO);
    let sid = h.ctx.self_id.as_str().to_string();
    let row = live_row(store.clone());
    let report = |step: &str| upgrade_drive::Report {
        pid: 4242,
        tab: sid.clone(),
        session: "c0ffee".to_string(),
        from: "2.1.0".to_string(),
        to: "2.2.0(npm)".to_string(),
        step: step.to_string(),
    };
    row(&sid, "relaunch", &report("relaunched"));
    assert!(
        sub.wait(aterm_spec::wait::MUST_HAPPEN),
        "the tab's watchers"
    );
    row(&sid, "upgrade", &report("wait:held"));
    row(&sid, "relaunch", &report("failed:no-resume"));
    row(&sid, "restart:account", &report("terminated"));
    row("s-gone", "relaunch", &report("relaunched"));
    let got: Vec<String> = {
        let g = h.ctx.timeline.lock().unwrap();
        g.slog()
            .log()
            .window()
            .filter_map(|r| aterm_slog::encode(r, aterm_slog::Tier::Host).ok())
            .filter(|l| l.contains(" mark - act "))
            .map(|l| {
                let body = l.split_once(' ').map_or("", |(_, b)| b);
                body.split(" t=").next().unwrap_or_default().to_string()
            })
            .collect()
    };
    assert_eq!(
        got,
        [
            "mark - act word=relaunch rule=relaunch by=harness src=aterm conf=strong",
            "mark - act word=relaunch rule=restart:account by=harness src=aterm conf=strong",
        ]
    );
}

struct HostedLog {
    store: Store,
    h: crate::session_store::SessionHandle,
    ms: Arc<AtomicU64>,
    base: aterm_slog::Stamp,
}

impl HostedLog {
    fn new() -> Self {
        let store = crate::session_store::new_store();
        let h = crate::session_store::test_handle(6);
        store.write().unwrap().register(h.clone());
        let ms = Arc::new(AtomicU64::new(0));
        let base = {
            let mut g = h.ctx.timeline.lock().unwrap();
            let base = g.slog().now();
            let read = Arc::clone(&ms);
            g.slog_mut()
                .set_clock(crate::session_log::Clock::reading(move || {
                    let ms = read.load(Ordering::SeqCst);
                    aterm_slog::Stamp::new(base.wall_ms + ms, base.mono_ms + ms)
                }));
            g.note_root_group(100);
            base
        };
        HostedLog { store, h, ms, base }
    }

    fn sid(&self) -> String {
        self.h.ctx.self_id.as_str().to_string()
    }

    fn block(&self, ms: u64, (blk, start, detail): (u64, u64, &str), end: Option<(u64, i32)>) {
        use crate::session_log::{BlockEnd, BlockFact, BlockRead};
        self.ms.store(ms, Ordering::SeqCst);
        let wall = |t: u64| self.base.wall_ms + t;
        let end = end.map_or(BlockEnd::Running, |(t, code)| {
            BlockEnd::Done(crate::session_status::CompletedBlock {
                id: blk,
                exit_code: Some(code),
                started_ms: Some(wall(start)),
                ended_ms: Some(wall(t)),
            })
        });
        let read = BlockRead {
            facts: vec![BlockFact {
                id: blk,
                started_ms: Some(wall(start)),
                end,
                detail: Some(detail.to_string()),
            }],
            ..BlockRead::default()
        };
        let mut g = self.h.ctx.timeline.lock().unwrap();
        let now = g.slog().now();
        g.slog_mut().shell_blocks(&read, None, now);
    }

    fn claude_in_front(&self, ms: u64, (blk, start): (u64, u64), pgid: i32) {
        use crate::session_log::{BlockEnd, BlockFact, BlockRead};
        self.ms.store(ms, Ordering::SeqCst);
        let read = BlockRead {
            facts: vec![BlockFact {
                id: blk,
                started_ms: Some(self.base.wall_ms + start),
                end: BlockEnd::Running,
                detail: Some("claude".to_string()),
            }],
            ..BlockRead::default()
        };
        let mut g = self.h.ctx.timeline.lock().unwrap();
        assert!(g.note_foreground_group(pgid));
        assert!(g.set_program(pgid, Some("claude".into())));
        let _ = g.sweep_slog(&read, false, 100, pgid);
    }

    fn relaunched_claude() -> Self {
        let tab = HostedLog::new();
        tab.block(150, (0, 100, "claude"), None);
        tab.claude_in_front(160, (0, 100), 300);
        tab.block(400, (0, 100, "claude"), Some((300, 143)));
        tab.block(600, (1, 500, "claude"), None);
        tab.claude_in_front(650, (1, 500), 301);
        tab
    }

    fn row(&self, ms: u64, kind: &str, step: &str) {
        self.ms.store(ms, Ordering::SeqCst);
        let sid = self.sid();
        let r = upgrade_drive::Report {
            pid: 4242,
            tab: sid.clone(),
            session: "c0ffee".to_string(),
            from: "2.1.0".to_string(),
            to: "2.2.0(npm)".to_string(),
            step: step.to_string(),
        };
        live_row(self.store.clone())(&sid, kind, &r);
    }

    fn acts_and_seen(&self) -> Vec<String> {
        let g = self.h.ctx.timeline.lock().unwrap();
        g.slog()
            .log()
            .window()
            .filter_map(|r| aterm_slog::encode(r, aterm_slog::Tier::Host).ok())
            .filter(|l| l.contains(" mark - act ") || l.contains(" mark - seen "))
            .map(|l| {
                let body = l.split_once(' ').map_or("", |(_, b)| b);
                body.split(" t=").next().unwrap_or_default().to_string()
            })
            .collect()
    }

    fn labels(&self) -> Vec<String> {
        let g = self.h.ctx.timeline.lock().unwrap();
        g.slog()
            .log()
            .window()
            .filter_map(|r| aterm_slog::encode(r, aterm_slog::Tier::Host).ok())
            .filter(|l| l.contains(" mark - label "))
            .map(|l| {
                let body = l.split_once(' ').map_or("", |(_, b)| b);
                body.split(" t=").next().unwrap_or_default().to_string()
            })
            .collect()
    }

    fn need(&self) -> Option<&'static str> {
        let g = self.h.ctx.timeline.lock().unwrap();
        g.slog().log().state().top_need().map(|n| n.word)
    }

    fn brief(&self) -> String {
        let g = self.h.ctx.timeline.lock().unwrap();
        crate::session_log::BriefCopy::copied_from(g.slog().log(), aterm_slog::Node::SESSION, None)
            .brief(&self.sid(), 4000, g.slog().now().wall_ms)
            .text
    }
}

fn relaunch_act_line(rule: &str) -> String {
    format!("mark - act word=relaunch rule={rule} by=harness src=aterm conf=strong")
}

const HARNESS_SEEN: &str = "mark - seen by=harness src=aterm conf=strong";

fn harness_label_line(text: &str) -> String {
    format!("mark - label text={text} ttl=30 by=harness src=aterm conf=strong")
}

#[test]
fn a_hosted_relaunch_lifts_the_failure_it_caused() {
    for (kind, step, words) in [
        ("relaunch", "relaunched", "restarting"),
        ("relaunch", "adopted", "restarting"),
        ("carry-on-after-update", "done:fresh", "restarting"),
        ("upgrade", "done:unconfirmed", "upgrading%20to%202.2.0"),
    ] {
        let tab = HostedLog::relaunched_claude();
        assert_eq!(
            tab.need(),
            Some("failure"),
            "PRECONDITION: the old run failed"
        );
        assert!(tab.brief().contains("need=failure"), "{}", tab.brief());
        tab.row(700, "relaunch", "wait:held");
        assert!(
            tab.acts_and_seen().is_empty(),
            "NEGATIVE CONTROL: a row that moved nothing: {:?}",
            tab.acts_and_seen()
        );
        assert_eq!(tab.need(), Some("failure"), "NEGATIVE CONTROL: it stands");
        assert!(tab.labels().is_empty(), "NEGATIVE CONTROL: no label");
        tab.row(800, kind, step);
        assert_eq!(
            tab.acts_and_seen(),
            [relaunch_act_line(kind), HARNESS_SEEN.to_string()],
            "{step}"
        );
        assert_eq!(tab.need(), None, "{step}: the relaunch lifted it");
        assert_eq!(
            tab.labels(),
            [harness_label_line(words)],
            "{kind} {step}: after the seen, the harness's own words"
        );
        let text = tab.brief();
        assert!(!text.contains("need=failure"), "{step}: {text}");
        assert!(text.contains("acts 1 "), "{step}: {text}");
    }
}

#[test]
fn a_hosted_turn_typed_or_stop_lifts_no_failure() {
    let tab = HostedLog::relaunched_claude();
    assert_eq!(tab.need(), Some("failure"), "PRECONDITION");
    let rows = [
        ("carry-on", "continued"),
        ("upgrade-at-break", "announced:1"),
        ("upgrade-at-break", "released:void"),
        ("carry-on", "continued:restore"),
        ("carry-restart", "terminated"),
        ("restart:account", "exited"),
    ];
    let mut want = Vec::new();
    for (i, (kind, step)) in (0u64..).zip(rows) {
        tab.row(700 + i, kind, step);
        want.push(relaunch_act_line(kind));
        assert_eq!(tab.acts_and_seen(), want, "{kind} {step}: its act, no seen");
        assert_eq!(tab.need(), Some("failure"), "{kind} {step}: it stands");
        assert!(
            tab.labels().is_empty(),
            "{kind} {step}: no restart, no label"
        );
    }
    tab.row(800, "relaunch", "adopted");
    want.push(relaunch_act_line("relaunch"));
    want.push(HARNESS_SEEN.to_string());
    assert_eq!(tab.acts_and_seen(), want, "the restart lifts it");
    assert_eq!(tab.need(), None);
    assert_eq!(tab.labels(), [harness_label_line("restarting")]);
}

#[test]
fn a_hosted_restart_beside_a_command_that_ran_no_agent_lifts_nothing() {
    let tab = HostedLog::new();
    tab.block(150, (0, 100, "make"), None);
    tab.block(400, (0, 100, "make"), Some((300, 2)));
    tab.block(600, (1, 500, "claude"), None);
    tab.claude_in_front(650, (1, 500), 300);
    assert_eq!(tab.need(), Some("failure"), "PRECONDITION: make failed");
    let rows = [
        ("carry-on", "continued"),
        ("upgrade-at-break", "announced:1"),
        ("relaunch", "adopted"),
        ("carry-on-after-update", "done:fresh"),
    ];
    let mut want = Vec::new();
    for (i, (kind, step)) in (0u64..).zip(rows) {
        tab.row(700 + i, kind, step);
        want.push(relaunch_act_line(kind));
        assert_eq!(tab.acts_and_seen(), want, "{kind} {step}: its act, no seen");
        assert_eq!(tab.need(), Some("failure"), "{kind} {step}: make's stands");
        assert!(
            tab.labels().is_empty(),
            "{kind} {step}: under make's failure the harness labels nothing"
        );
    }
    assert!(tab.brief().contains("need=failure"), "{}", tab.brief());
}

#[test]
fn the_harness_labels_a_typed_disk_resume_only_while_no_need_is_open() {
    let tab = HostedLog::new();
    tab.block(150, (0, 100, "claude"), None);
    tab.claude_in_front(160, (0, 100), 300);
    assert_eq!(tab.need(), None, "PRECONDITION: nothing open");
    let sid = tab.sid();
    assert_eq!(
        disk_resumed(&tab.store, &sid, "wait:held".to_string()),
        "wait:held"
    );
    assert!(
        tab.labels().is_empty(),
        "NEGATIVE CONTROL: a resume that typed nothing labels nothing"
    );
    tab.ms.store(200, Ordering::SeqCst);
    assert_eq!(disk_resumed(&tab.store, &sid, "typed".to_string()), "typed");
    assert_eq!(
        tab.labels(),
        [harness_label_line("resuming%20after%20disk")]
    );
    let failed = HostedLog::relaunched_claude();
    assert_eq!(failed.need(), Some("failure"), "PRECONDITION");
    assert_eq!(
        disk_resumed(&failed.store, &failed.sid(), "typed".to_string()),
        "typed"
    );
    assert!(
        failed.labels().is_empty(),
        "under an open need the harness labels nothing: {:?}",
        failed.labels()
    );
}

/// A tapped session's fresh reading is recorded for the machine's own login (`main`, with no
/// roster), and only news is written.
#[cfg(unix)]
#[test]
fn a_tapped_sessions_fresh_reading_is_recorded_for_the_machines_own_login() {
    let w = TapWorld::new();
    let idle = w.worker(&tap_on(), tapped_argv(), true);
    w.tap(10, 42, None);
    idle.usage_tap();
    let held = w.sample().expect("a sample");
    assert_eq!((held.session_pct, held.week_pct), (Some(42), Some(30)));
    assert_eq!(w.rows(accounts::Kind::Sample), 1);
    w.later(10);
    w.tap(10, 42, None);
    idle.usage_tap();
    w.later(10);
    w.tap(20, 42, None);
    assert_eq!(
        idle.tap_step(),
        None,
        "the same windows: not taken to the store"
    );
    assert_eq!(w.rows(accounts::Kind::Sample), 1, "nothing new written");
    w.later(10);
    w.tap(30, 47, None);
    idle.usage_tap();
    assert_eq!(w.sample().and_then(|s| s.session_pct), Some(47));
    assert_eq!(w.rows(accounts::Kind::Sample), 2);
    assert!(w.notes().is_empty(), "a reading tells the window nothing");

    let cases = [
        (
            "no tap on its argv",
            vec!["claude".to_string()],
            true,
            None,
            None,
            false,
        ),
        (
            "not on its stored login",
            tapped_argv(),
            false,
            None,
            None,
            false,
        ),
        (
            "another login's reading",
            tapped_argv(),
            true,
            None,
            Some("/logins/b"),
            false,
        ),
        (
            "a login no row of the roster names",
            tapped_argv(),
            true,
            Some("/logins/unlisted"),
            Some("/logins/unlisted"),
            true,
        ),
    ];
    for (why, argv, stored, snap_login, tap_login, listed) in cases {
        let w = TapWorld::new();
        w.listed.store(listed, Ordering::SeqCst);
        if let Some(login) = snap_login {
            w.env
                .lock()
                .unwrap()
                .push(format!("{}={login}", accounts::LOGIN_ENV));
        }
        let idle = w.worker(&tap_on(), argv, stored);
        if let Some(snap) = idle.kept.lock().unwrap().snapshot.as_mut() {
            snap.login = snap_login.map(str::to_owned);
        }
        w.tap(10, 42, tap_login);
        idle.usage_tap();
        assert_eq!(w.sample(), None, "{why}");
        assert_eq!(w.rows(accounts::Kind::Sample), 0, "{why}");
    }
}

/// Under listed accounts the tap records for the judged account (`home-a`, `work-2`).
#[cfg(unix)]
#[test]
fn a_roster_of_one_account_takes_its_taps_readings() {
    let one =
        "[[account]]\nlabel = \"home-a\"\nclass = \"dedicated\"\nemail = \"owner@example.com\"\n";
    let two = format!(
        "{one}\n[[account]]\nlabel = \"work-2\"\nclass = \"dedicated\"\ndir = \"/logins/work-2\"\n"
    );
    for (roster, login, label) in [
        (one.to_string(), None, "home-a"),
        (two.clone(), None, "home-a"),
        (two, Some("/logins/work-2"), "work-2"),
    ] {
        let w = TapWorld::new();
        std::fs::write(w.roster_path(), &roster).expect("roster");
        if let Some(login) = login {
            w.env
                .lock()
                .unwrap()
                .push(format!("{}={login}", accounts::LOGIN_ENV));
        }
        let idle = w.worker(&tap_on(), tapped_argv(), true);
        if let Some(snap) = idle.kept.lock().unwrap().snapshot.as_mut() {
            snap.login = login.map(str::to_owned);
        }
        w.tap(10, 42, login);
        idle.usage_tap();
        assert_eq!(
            w.sample_of(label).and_then(|s| s.session_pct),
            Some(42),
            "{roster}"
        );
        assert_eq!(w.rows(accounts::Kind::Sample), 1);
        idle.turn_ran();
        w.later(31);
        idle.usage_tap();
        w.later(31);
        idle.usage_tap();
        assert_eq!(w.rows(accounts::Kind::NoTap), 1, "{roster}");
    }
}

/// The tap follows the one account through its renewal.
#[cfg(unix)]
#[test]
fn a_renewed_one_account_login_keeps_its_taps_readings() {
    for (why, on, recorded) in [
        ("the renewed login", Some(true), true),
        ("the superseded default login", None, true),
        ("a login no row names", Some(false), false),
    ] {
        let w = TapWorld::new();
        std::fs::write(
            w.roster_path(),
            "[[account]]\nlabel = \"home-a\"\nclass = \"dedicated\"\nemail = \"owner@example.com\"\n",
        )
        .expect("roster");
        let renewed = w.tmp.path().join("logins").join("home-a.1");
        std::fs::create_dir_all(&renewed).expect("staging");
        std::fs::write(renewed.join(".claude.json"), "{}").expect("staging");
        let renewed = renewed.to_string_lossy().into_owned();
        let mut note = None;
        accounts::Store::at(&w.state())
            .transact_logins(w.clock(), &mut note, |state, logins| {
                Ok(accounts::note_renewed(
                    state,
                    logins,
                    "home-a",
                    None,
                    &renewed,
                    None,
                    w.clock(),
                ))
            })
            .expect("renewed");
        let login = on.map(|ours| {
            if ours {
                renewed.clone()
            } else {
                "/logins/elsewhere".to_string()
            }
        });
        if let Some(login) = &login {
            w.env
                .lock()
                .unwrap()
                .push(format!("{}={login}", accounts::LOGIN_ENV));
        }
        let idle = w.worker(&tap_on(), tapped_argv(), true);
        if let Some(snap) = idle.kept.lock().unwrap().snapshot.as_mut() {
            snap.login.clone_from(&login);
        }
        w.tap(10, 42, login.as_deref());
        idle.usage_tap();
        assert_eq!(
            w.sample_of("home-a").and_then(|s| s.session_pct),
            recorded.then_some(42),
            "{why}"
        );
    }
}

/// A silent tap is said once.
#[cfg(unix)]
#[test]
fn a_silent_tap_is_said_once_and_its_end_with_it() {
    let silent = |w: &TapWorld| {
        w.notes()
            .iter()
            .filter(|n| matches!(n, HostNote::UsageTap { silent: true, .. }))
            .count()
    };
    let w = TapWorld::new();
    let idle = w.worker(&tap_on(), tapped_argv(), true);
    idle.usage_tap();
    w.later(31);
    idle.usage_tap();
    assert_eq!(silent(&w), 0, "no turn served");
    idle.turn_ran();
    idle.usage_tap();
    w.later(31);
    idle.usage_tap();
    assert_eq!(silent(&w), 1);
    assert_eq!(w.rows(accounts::Kind::NoTap), 1);
    w.later(31);
    idle.usage_tap();
    assert_eq!((silent(&w), w.rows(accounts::Kind::NoTap)), (1, 1), "once");
    w.tap(10, 42, None);
    idle.usage_tap();
    assert!(
        w.notes().contains(&HostNote::UsageTap {
            sid: TAP_SID.to_string(),
            silent: false
        }),
        "heard again: {:?}",
        w.notes()
    );
    let w = TapWorld::new();
    let idle = w.worker(&tap_off(), tapped_argv(), true);
    idle.turn_ran();
    idle.usage_tap();
    w.later(31);
    idle.usage_tap();
    assert_eq!(w.rows(accounts::Kind::NoTap), 1);
    assert!(w.notes().is_empty(), "{:?}", w.notes());
}

/// A silent tap's line ends with its process: the mark said for a process the same worker then
/// relaunches in place.
#[cfg(unix)]
#[test]
fn a_silent_taps_line_ends_with_its_process() {
    let ended = |w: &TapWorld| {
        w.notes()
            .iter()
            .filter(|n| matches!(n, HostNote::UsageTap { silent: false, .. }))
            .count()
    };
    for argv in [tapped_argv(), vec!["claude".to_string()]] {
        let w = TapWorld::new();
        let idle = w.worker(&tap_on(), tapped_argv(), true);
        idle.turn_ran();
        idle.usage_tap();
        w.later(31);
        idle.usage_tap();
        assert_eq!(
            w.notes(),
            vec![HostNote::UsageTap {
                sid: TAP_SID.to_string(),
                silent: true
            }]
        );
        w.later(31);
        idle.usage_tap();
        assert_eq!(ended(&w), 0, "the same process, still stale");
        {
            let mut kept = idle.kept.lock().unwrap();
            let snap = kept.snapshot.as_mut().expect("a snapshot");
            snap.pid = TAP_PID + 1;
            snap.argv.clone_from(&argv);
        }
        w.later(5);
        idle.usage_tap();
        assert_eq!(ended(&w), 1, "{argv:?}");
        w.later(31);
        idle.usage_tap();
        drop(idle);
        assert_eq!(ended(&w), 1, "once: {argv:?}");
    }
}

/// A fresh reading the window could not take is tried again.
#[cfg(unix)]
#[test]
fn a_fresh_reading_not_taken_is_tried_again() {
    let w = TapWorld::new();
    let idle = w.worker(&tap_on(), tapped_argv(), true);
    let env = std::mem::take(&mut *w.env.lock().unwrap());
    w.tap(10, 42, None);
    idle.usage_tap();
    assert_eq!(w.sample(), None, "its environment unread");
    *w.env.lock().unwrap() = env;
    w.later(10);
    w.tap(10, 42, None);
    idle.usage_tap();
    assert_eq!(w.sample().and_then(|s| s.session_pct), Some(42));
    assert_eq!(w.rows(accounts::Kind::Sample), 1);
    w.later(10);
    w.tap(20, 47, None);
    let held = w.hold_lock();
    assert_eq!(idle.tap_step(), Some("reading dropped: lock-held"));
    drop(held);
    w.later(10);
    w.tap(20, 47, None);
    idle.usage_tap();
    assert_eq!(w.sample().and_then(|s| s.session_pct), Some(47));
    assert_eq!(w.rows(accounts::Kind::Sample), 2);
    w.later(10);
    w.tap(20, 47, None);
    assert_eq!(idle.tap_step(), None, "an idle repeat of one taken");
    assert_eq!(w.rows(accounts::Kind::Sample), 2);
}

/// The reading that times a wall is the tab's own process's newest, stamped when the tap wrote it,
/// and recorded nowhere. Negative controls answer nothing: the switch off, no tap on the argv, a
/// Codex, a file older than the process.
#[cfg(unix)]
#[test]
fn a_tapped_processs_own_reading_times_its_wall_under_the_switch() {
    use aterm_agent::supervise::tap_clock::{TapWindow, UsageWindow};
    let w = TapWorld::new();
    let idle = w.worker(&tap_on(), tapped_argv(), false);
    assert_eq!(idle.tap_window(UsageWindow::FiveHour), None, "no file yet");
    w.tap(10, 100, None);
    let reset = w.born + 4 * 3600;
    assert_eq!(
        idle.tap_window(UsageWindow::FiveHour),
        Some(TapWindow {
            figure: Some(tap::Window {
                pct: 100,
                resets_at: reset,
                pct_x10: Some(1000),
            }),
            read_at: w.clock(),
        })
    );
    assert_eq!(
        idle.tap_window(UsageWindow::SevenDay)
            .and_then(|t| t.figure)
            .map(|f| f.pct),
        Some(30)
    );
    let first = w.clock();
    w.later(10);
    w.tap(10, 100, None);
    assert_eq!(
        idle.tap_window(UsageWindow::FiveHour).map(|t| t.read_at),
        Some(w.clock())
    );
    assert_eq!(
        tap::Reading::read(&w.rl(), TAP_SID, TAP_PID, 0).map(|(r, _)| r.at),
        Some(first),
        "a re-report keeps its first report's time"
    );
    assert_eq!(w.sample(), None, "nothing recorded");
    assert_eq!(w.rows(accounts::Kind::Sample), 0);
    let off = w.worker(&tap_off(), tapped_argv(), true);
    assert_eq!(
        off.tap_window(UsageWindow::FiveHour),
        None,
        "the switch off"
    );
    let bare = w.worker(&tap_on(), vec!["claude".to_string()], true);
    assert_eq!(
        bare.tap_window(UsageWindow::FiveHour),
        None,
        "no tap on its argv"
    );
    let mut codex = w.worker(&tap_on(), tapped_argv(), true);
    codex.agent = Program::Codex;
    assert_eq!(codex.tap_window(UsageWindow::FiveHour), None, "a Codex");
    let old = TapWorld::new();
    old.later(-200);
    old.tap(10, 100, None);
    old.later(200);
    let idle = old.worker(&tap_on(), tapped_argv(), true);
    assert_eq!(
        idle.tap_window(UsageWindow::FiveHour),
        None,
        "a file older than the process"
    );
}

/// A reading the new login's adoption held back is taken when served again after it: the default
/// home's profile.
#[cfg(unix)]
#[test]
fn a_reading_held_back_for_a_new_login_is_taken_when_served_after_it() {
    let w = TapWorld::new();
    let home = w.tmp.path().join("home");
    std::fs::create_dir_all(&home).expect("home");
    *w.env.lock().unwrap() = vec![format!("HOME={}", home.display())];
    let (a, b) = (
        "11111111-1111-4111-8111-111111111111",
        "22222222-2222-4222-8222-222222222222",
    );
    let sign_in = |uuid: &str| {
        let text = format!(r#"{{"oauthAccount":{{"accountUuid":"{uuid}"}}}}"#);
        std::fs::write(home.join(".claude.json"), text).expect("profile");
    };
    let key = || {
        let (state, _) = accounts::Store::at(&w.state()).load(w.clock()).ok()?;
        state.accounts.get("main")?.key
    };
    sign_in(a);
    let idle = w.worker(&tap_on(), tapped_argv(), true);
    w.tap(10, 42, None);
    idle.usage_tap();
    assert_eq!(w.sample().and_then(|s| s.session_pct), Some(42));
    assert_eq!(key(), profile::AccountKey::claude(a));
    w.later(10);
    w.tap(20, 42, None);
    assert_eq!(idle.tap_step(), None, "a repeat of figures taken");
    sign_in(b);
    w.later(10);
    w.tap(30, 50, None);
    assert_eq!(idle.tap_step(), Some("reading recorded"), "the epoch");
    assert_eq!(key(), profile::AccountKey::claude(b));
    assert_eq!(w.sample(), None, "held back");
    w.later(accounts::KEY_ADOPT_S);
    w.tap(40, 50, None);
    assert_eq!(idle.tap_step(), Some("reading recorded"), "served again");
    assert_eq!(w.sample().and_then(|s| s.session_pct), Some(50));
    assert_eq!(key(), profile::AccountKey::claude(b));
}

/// Under a roster of several accounts a tap reading carries no key.
#[cfg(unix)]
#[test]
fn under_several_accounts_a_tap_reading_carries_no_key() {
    let one =
        "[[account]]\nlabel = \"home-a\"\nclass = \"dedicated\"\nemail = \"owner@example.com\"\n";
    let two = format!(
        "{one}\n[[account]]\nlabel = \"work-2\"\nclass = \"dedicated\"\ndir = \"/logins/work-2\"\n"
    );
    let (a, b) = (
        "11111111-1111-4111-8111-111111111111",
        "22222222-2222-4222-8222-222222222222",
    );
    for (roster, keyed) in [(two, false), (one.to_string(), true)] {
        let w = TapWorld::new();
        std::fs::write(w.roster_path(), &roster).expect("roster");
        let home = w.tmp.path().join("home");
        std::fs::create_dir_all(&home).expect("home");
        *w.env.lock().unwrap() = vec![format!("HOME={}", home.display())];
        let sign_in = |uuid: &str| {
            let text = format!(r#"{{"oauthAccount":{{"accountUuid":"{uuid}"}}}}"#);
            std::fs::write(home.join(".claude.json"), text).expect("profile");
        };
        let key = || {
            let (state, _) = accounts::Store::at(&w.state()).load(w.clock()).ok()?;
            state.accounts.get("home-a")?.key
        };
        sign_in(a);
        let idle = w.worker(&tap_on(), tapped_argv(), true);
        w.tap(10, 42, None);
        idle.usage_tap();
        assert_eq!(
            w.sample_of("home-a").and_then(|s| s.session_pct),
            Some(42),
            "{roster}"
        );
        assert_eq!(key(), profile::AccountKey::claude(a).filter(|_| keyed));
        sign_in(b);
        w.later(10);
        w.tap(20, 47, None);
        idle.usage_tap();
        if keyed {
            assert_eq!(w.rows(accounts::Kind::Epoch), 1, "{roster}");
            assert_eq!(w.sample_of("home-a"), None, "held back");
        } else {
            assert_eq!(w.rows(accounts::Kind::Epoch), 0, "{roster}");
            assert_eq!(key(), None);
            assert_eq!(
                w.sample_of("home-a").and_then(|s| s.session_pct),
                Some(47),
                "taken at once"
            );
        }
    }
}

/// A first reading under an epoch is not noted as taken.
#[cfg(unix)]
#[test]
fn a_first_reading_under_an_epoch_is_tried_again_when_served_again() {
    let w = TapWorld::new();
    let idle = w.worker(&tap_on(), tapped_argv(), true);
    w.tap(10, 100, None);
    idle.usage_tap();
    w.later(10);
    w.tap(20, 5, None);
    idle.usage_tap();
    assert_eq!(
        w.sample().and_then(|s| s.session_pct),
        Some(5),
        "the refill"
    );
    assert_eq!(w.rows(accounts::Kind::Reset), 1);
    let after = w.worker(&tap_on(), tapped_argv(), true);
    w.later(10);
    w.tap(30, 7, None);
    after.usage_tap();
    assert_eq!(
        w.sample().and_then(|s| s.session_pct),
        Some(5),
        "a first reading under the epoch says nothing"
    );
    w.later(10);
    w.tap(40, 7, None);
    assert_eq!(after.tap_step(), Some("reading recorded"), "served again");
    assert_eq!(w.sample().and_then(|s| s.session_pct), Some(7));
    w.later(10);
    w.tap(50, 7, None);
    assert_eq!(after.tap_step(), None, "a repeat of figures taken");
}

/// One [`Acts::startup_mark`] as the deadlines' fakes keep it.
#[derive(Clone, Debug, PartialEq, Eq)]
enum Marked {
    /// `stalled why=startup`, for what held the screen.
    Stalled(StartupHold),
    /// `working` again.
    Working,
    /// `stalled why=held`, at this verdict word.
    Held(String),
    /// `working` again: the held worker moved.
    Moved,
    /// No mark; the stall's attention taken down.
    Over,
    /// No mark; the startup stall's attention names this hold now.
    Restated(StartupHold),
}

/// The startup deadline's fakes.
#[derive(Default)]
struct StartupWorld {
    reads: Mutex<Vec<Startup>>,
    judged: Mutex<Vec<Vec<String>>>,
    marks: Mutex<Vec<(String, Marked)>>,
}

impl StartupWorld {
    fn hooks(self: &Arc<Self>) -> Hooks {
        let world = Arc::new(World::default());
        let (r, m) = (Arc::clone(self), Arc::clone(self));
        let mut hooks = hooks(&world, parking_body(&world));
        hooks.acts = Acts {
            startups: Arc::new(move |judged| {
                let mut judged: Vec<String> = judged.iter().cloned().collect();
                judged.sort();
                r.judged.lock().unwrap().push(judged);
                r.reads.lock().unwrap().clone()
            }),
            startup_mark: Arc::new(move |sid, mark| {
                let marked = match mark {
                    StartupMark::Stalled { hold } => Marked::Stalled((*hold).clone()),
                    StartupMark::Started => Marked::Working,
                    StartupMark::Held { read, .. } => Marked::Held(read.word.clone()),
                    StartupMark::Moved => Marked::Moved,
                    StartupMark::Over => Marked::Over,
                    StartupMark::Restated { hold } => Marked::Restated((*hold).clone()),
                };
                m.marks.lock().unwrap().push((sid.to_string(), marked));
            }),
            ..Acts::inert()
        };
        hooks
    }

    fn set(&self, workers: Vec<Startup>) {
        *self.reads.lock().unwrap() = workers;
    }

    fn marks(&self) -> Vec<(String, Marked)> {
        std::mem::take(&mut *self.marks.lock().unwrap())
    }

    fn reads(&self) -> usize {
        self.judged.lock().unwrap().len()
    }
}

fn startup(sid: &str, state: StartupState, since: Instant, seen: StartupSeen) -> Startup {
    let held = matches!(
        state,
        StartupState::Working | StartupState::Reopened | StartupState::StalledHeld
    )
    .then(|| held_at("idle", Progress::default()));
    Startup {
        sid: sid.to_string(),
        state,
        since,
        seen,
        held,
        standing: None,
    }
}

fn held_at(word: &str, progress: Progress) -> HeldRead {
    HeldRead {
        word: word.to_string(),
        detail: None,
        program: Some("claude".to_string()),
        progress,
        escalated: false,
        last_row: Some("Enter to continue · Esc to cancel".to_string()),
        panel: false,
        unread: false,
        person: None,
        driver: false,
        carried: false,
    }
}

fn held_worker(sid: &str, state: StartupState, read: HeldRead) -> Startup {
    Startup {
        sid: sid.to_string(),
        state,
        since: Instant::now(),
        seen: StartupSeen::Unread,
        held: Some(read),
        standing: None,
    }
}

fn no_agent() -> StartupHold {
    StartupHold::NoAgent {
        agent: Program::Claude,
        program: Some("zsh".to_string()),
    }
}

fn stalled(sid: &str, hold: StartupHold) -> (String, Marked) {
    (sid.to_string(), Marked::Stalled(hold))
}

#[test]
fn the_startup_deadline_stalls_a_worker_that_never_shows_its_composer() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let t0 = Instant::now();
    let mut books = Startups::default();
    w.set(vec![startup(
        "s-a",
        StartupState::Working,
        t0,
        StartupSeen::Holds(no_agent()),
    )]);
    assert_eq!(
        look_at_startups(&mut books, t0, true, &OffSessions::default(), &hooks),
        Some(t0 + STARTUP_DEADLINE)
    );
    let before = t0 + STARTUP_DEADLINE - Duration::from_millis(1);
    assert_eq!(
        look_at_startups(&mut books, before, true, &OffSessions::default(), &hooks),
        Some(t0 + STARTUP_DEADLINE)
    );
    assert!(w.marks().is_empty(), "not before its deadline");
    assert_eq!(
        look_at_startups(
            &mut books,
            t0 + STARTUP_DEADLINE,
            true,
            &OffSessions::default(),
            &hooks
        ),
        None
    );
    assert_eq!(w.marks(), [stalled("s-a", no_agent())]);
    let later = t0 + 2 * STARTUP_DEADLINE;
    w.set(vec![startup(
        "s-a",
        StartupState::StalledAtStartup,
        t0 + STARTUP_DEADLINE,
        StartupSeen::Holds(no_agent()),
    )]);
    assert_eq!(
        look_at_startups(&mut books, later, true, &OffSessions::default(), &hooks),
        None
    );
    assert!(w.marks().is_empty());
    w.set(vec![startup(
        "s-a",
        StartupState::StalledAtStartup,
        t0 + STARTUP_DEADLINE,
        StartupSeen::Started,
    )]);
    look_at_startups(&mut books, later, true, &OffSessions::default(), &hooks);
    assert_eq!(w.marks(), [("s-a".to_string(), Marked::Working)]);
    w.set(vec![startup(
        "s-a",
        StartupState::Working,
        later,
        StartupSeen::Unread,
    )]);
    look_at_startups(
        &mut books,
        later + STARTUP_DEADLINE,
        true,
        &OffSessions::default(),
        &hooks,
    );
    assert!(w.marks().is_empty(), "started: never judged again");
    assert_eq!(
        w.judged.lock().unwrap().last().cloned(),
        Some(vec!["s-a".to_string()]),
        "its screen no longer read"
    );

    let mut books = Startups::default();
    w.set(vec![startup(
        "s-b",
        StartupState::Working,
        t0,
        StartupSeen::Started,
    )]);
    assert_eq!(
        look_at_startups(&mut books, t0, true, &OffSessions::default(), &hooks),
        None
    );
    w.set(vec![startup(
        "s-b",
        StartupState::Working,
        t0,
        StartupSeen::Holds(StartupHold::Box {
            agent: Program::Claude,
            title: "Bash command".to_string(),
        }),
    )]);
    look_at_startups(
        &mut books,
        t0 + 10 * STARTUP_DEADLINE,
        true,
        &OffSessions::default(),
        &hooks,
    );
    assert!(w.marks().is_empty());
    let mut books = Startups::default();
    w.set(vec![
        startup("s-c", StartupState::Other, t0, StartupSeen::Unread),
        startup("s-d", StartupState::Other, t0, StartupSeen::Unread),
    ]);
    assert_eq!(
        look_at_startups(
            &mut books,
            t0 + 10 * STARTUP_DEADLINE,
            true,
            &OffSessions::default(),
            &hooks
        ),
        None
    );
    assert!(w.marks().is_empty());
    w.set(vec![startup(
        "s-e",
        StartupState::StallOver,
        t0,
        StartupSeen::Unread,
    )]);
    look_at_startups(&mut books, t0, true, &OffSessions::default(), &hooks);
    assert_eq!(w.marks(), [("s-e".to_string(), Marked::Over)]);
    let asked = w.reads();
    w.set(vec![startup(
        "s-a",
        StartupState::Working,
        t0,
        StartupSeen::Holds(no_agent()),
    )]);
    let mut books = Startups::default();
    assert_eq!(
        look_at_startups(
            &mut books,
            t0 + 10 * STARTUP_DEADLINE,
            false,
            &OffSessions::default(),
            &hooks
        ),
        None
    );
    assert_eq!(w.reads(), asked, "nothing read");
    assert!(w.marks().is_empty());
}

#[test]
fn the_startup_deadline_counts_from_the_successors_first_look() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let t0 = Instant::now() + Duration::from_secs(3 * 3600);
    let carried = t0 - Duration::from_secs(3600);
    let mut books = Startups::default();
    w.set(vec![startup(
        "s-a",
        StartupState::Working,
        carried,
        StartupSeen::Holds(no_agent()),
    )]);
    assert_eq!(
        look_at_startups(&mut books, t0, true, &OffSessions::default(), &hooks),
        Some(t0 + STARTUP_DEADLINE)
    );
    assert!(w.marks().is_empty(), "not at the first look");
    w.set(vec![startup(
        "s-a",
        StartupState::Working,
        carried,
        StartupSeen::Unread,
    )]);
    let at = t0 + STARTUP_DEADLINE;
    assert_eq!(
        look_at_startups(&mut books, at, true, &OffSessions::default(), &hooks),
        Some(at + STARTUP_UNREAD_LOOK)
    );
    assert!(w.marks().is_empty());
    w.set(vec![startup(
        "s-a",
        StartupState::Working,
        carried,
        StartupSeen::Holds(no_agent()),
    )]);
    look_at_startups(&mut books, at, true, &OffSessions::default(), &hooks);
    assert_eq!(w.marks(), [stalled("s-a", no_agent())]);
}

#[test]
fn supervision_back_on_gives_a_worker_a_whole_deadline() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let t0 = Instant::now() + Duration::from_secs(3 * 3600);
    let trust = StartupSeen::Holds(StartupHold::Trust {
        agent: Program::Claude,
    });
    let mut books = Startups::default();
    w.set(vec![startup(
        "s-a",
        StartupState::Working,
        t0,
        trust.clone(),
    )]);
    assert_eq!(
        look_at_startups(&mut books, t0, true, &OffSessions::default(), &hooks),
        Some(t0 + STARTUP_DEADLINE)
    );
    let back = t0 + 10 * STARTUP_DEADLINE;
    assert_eq!(
        look_at_startups(&mut books, back, false, &OffSessions::default(), &hooks),
        None
    );
    assert_eq!(
        look_at_startups(&mut books, back, true, &OffSessions::default(), &hooks),
        Some(back + STARTUP_DEADLINE)
    );
    assert!(w.marks().is_empty(), "a whole deadline from the look after");
    look_at_startups(
        &mut books,
        back + STARTUP_DEADLINE,
        true,
        &OffSessions::default(),
        &hooks,
    );
    assert_eq!(
        w.marks(),
        [stalled(
            "s-a",
            StartupHold::Trust {
                agent: Program::Claude
            }
        )]
    );
    let mut books = Startups::default();
    look_at_startups(&mut books, t0, true, &OffSessions::default(), &hooks);
    look_at_startups(&mut books, back, true, &OffSessions::default(), &hooks);
    assert_eq!(
        w.marks(),
        [stalled(
            "s-a",
            StartupHold::Trust {
                agent: Program::Claude
            }
        )]
    );
}

#[test]
fn the_startup_deadline_marks_no_off_worker() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let t0 = Instant::now() + Duration::from_secs(3 * 3600);
    let trust = StartupSeen::Holds(StartupHold::Trust {
        agent: Program::Claude,
    });
    let word = |word: Autopilot| OffSessions {
        words: [("s-a".to_string(), word)].into(),
        default: Autopilot::Cruise,
    };
    let by_default = OffSessions {
        words: HashMap::new(),
        default: Autopilot::Off,
    };
    let none = OffSessions::default();
    let late = t0 + 10 * STARTUP_DEADLINE;
    w.set(vec![startup(
        "s-a",
        StartupState::Working,
        t0,
        trust.clone(),
    )]);
    let mut books = Startups::default();
    let off = word(Autopilot::Off);
    assert_eq!(look_at_startups(&mut books, t0, true, &off, &hooks), None);
    assert_eq!(look_at_startups(&mut books, late, true, &off, &hooks), None);
    assert_eq!(
        look_at_startups(&mut books, late, true, &by_default, &hooks),
        None
    );
    assert!(
        w.marks().is_empty(),
        "an Off worker is neither marked nor badged"
    );
    let cruise = word(Autopilot::Cruise);
    assert_eq!(
        look_at_startups(&mut books, late, true, &cruise, &hooks),
        Some(late + STARTUP_DEADLINE)
    );
    assert!(w.marks().is_empty(), "not on the clock it had before Off");
    look_at_startups(&mut books, late + STARTUP_DEADLINE, true, &cruise, &hooks);
    assert_eq!(
        w.marks(),
        [stalled(
            "s-a",
            StartupHold::Trust {
                agent: Program::Claude
            }
        )]
    );
    w.set(vec![startup(
        "s-a",
        StartupState::StalledAtStartup,
        late + STARTUP_DEADLINE,
        StartupSeen::Started,
    )]);
    let again = late + 2 * STARTUP_DEADLINE;
    look_at_startups(&mut books, again, true, &off, &hooks);
    assert!(w.marks().is_empty(), "no `working` mark while Off");
    look_at_startups(&mut books, again, true, &cruise, &hooks);
    assert_eq!(w.marks(), [("s-a".to_string(), Marked::Working)]);

    w.set(vec![startup("s-a", StartupState::Working, t0, trust)]);
    let mut books = Startups::default();
    look_at_startups(&mut books, t0, true, &none, &hooks);
    look_at_startups(&mut books, t0 + STARTUP_DEADLINE, true, &none, &hooks);
    assert_eq!(
        w.marks(),
        [stalled(
            "s-a",
            StartupHold::Trust {
                agent: Program::Claude
            }
        )]
    );
}

#[test]
fn the_startup_deadline_skips_the_harnesss_own_waits() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let none = OffSessions::default();
    let t0 = Instant::now() + Duration::from_secs(3 * 3600);
    let carried = t0 - Duration::from_secs(3600);
    let grace = Duration::from_secs(30);
    let books = |relaunching: &[&str]| Startups {
        waits: HarnessWaits {
            grace,
            relaunching: relaunching.iter().map(|s| (*s).to_string()).collect(),
        },
        ..Startups::default()
    };
    w.set(vec![startup(
        "s-a",
        StartupState::Working,
        carried,
        StartupSeen::Holds(no_agent()),
    )]);
    let mut relaunch = books(&["s-a"]);
    let late = t0 + 5 * STARTUP_DEADLINE;
    for at in [t0, late] {
        assert_eq!(
            look_at_startups(&mut relaunch, at, true, &none, &hooks),
            Some(at + HELD_RELOOK)
        );
    }
    assert!(w.marks().is_empty(), "a relaunch in hand is no stall");
    relaunch.waits.relaunching.clear();
    let back = late + HELD_RELOOK;
    assert_eq!(
        look_at_startups(&mut relaunch, back, true, &none, &hooks),
        Some(late + STARTUP_DEADLINE)
    );
    assert!(w.marks().is_empty(), "a whole deadline after the relaunch");
    look_at_startups(&mut relaunch, late + STARTUP_DEADLINE, true, &none, &hooks);
    assert_eq!(w.marks(), [stalled("s-a", no_agent())]);
    let mut plain = books(&[]);
    look_at_startups(&mut plain, t0, true, &none, &hooks);
    look_at_startups(&mut plain, t0 + STARTUP_DEADLINE, true, &none, &hooks);
    assert_eq!(w.marks(), [stalled("s-a", no_agent())]);

    let typed = t0 + STARTUP_DEADLINE - Duration::from_secs(1);
    let boxed = |person: Option<Instant>| Startup {
        held: Some(HeldRead {
            person,
            ..held_at("prompt", Progress::default())
        }),
        ..startup(
            "s-b",
            StartupState::Working,
            t0,
            StartupSeen::Holds(StartupHold::Box {
                agent: Program::Claude,
                title: "Allow this tool?".to_string(),
            }),
        )
    };
    w.set(vec![boxed(Some(typed))]);
    let mut held = books(&[]);
    look_at_startups(&mut held, t0, true, &none, &hooks);
    assert_eq!(
        look_at_startups(&mut held, t0 + STARTUP_DEADLINE, true, &none, &hooks),
        Some(typed + grace + STARTUP_DEADLINE)
    );
    assert!(
        w.marks().is_empty(),
        "the harness's hold for the hand first"
    );
    look_at_startups(
        &mut held,
        typed + grace + STARTUP_DEADLINE,
        true,
        &none,
        &hooks,
    );
    assert_eq!(w.marks().len(), 1);
    w.set(vec![boxed(None)]);
    let mut plain = books(&[]);
    look_at_startups(&mut plain, t0, true, &none, &hooks);
    look_at_startups(&mut plain, t0 + STARTUP_DEADLINE, true, &none, &hooks);
    assert_eq!(w.marks().len(), 1);

    let driven = |driver: bool| {
        let mut b = boxed(None);
        if let Some(read) = b.held.as_mut() {
            read.driver = driver;
        }
        b
    };
    w.set(vec![driven(true)]);
    let mut held = books(&[]);
    assert_eq!(
        look_at_startups(&mut held, t0, true, &none, &hooks),
        Some(t0 + HELD_RELOOK)
    );
    let stood = t0 + STARTUP_DEADLINE;
    assert_eq!(
        look_at_startups(&mut held, stood, true, &none, &hooks),
        Some(stood + HELD_RELOOK),
        "looked at again within a relook while the hand stands"
    );
    w.set(vec![driven(false)]);
    let lifted = stood + HELD_RELOOK;
    assert_eq!(
        look_at_startups(&mut held, lifted, true, &none, &hooks),
        Some(stood + grace + STARTUP_DEADLINE)
    );
    assert!(
        w.marks().is_empty(),
        "the harness's hold for the driver's hand first"
    );
    look_at_startups(
        &mut held,
        stood + grace + STARTUP_DEADLINE,
        true,
        &none,
        &hooks,
    );
    assert_eq!(w.marks().len(), 1);
    let mut plain = books(&[]);
    look_at_startups(&mut plain, t0, true, &none, &hooks);
    look_at_startups(&mut plain, lifted, true, &none, &hooks);
    assert_eq!(w.marks().len(), 1);
}

#[test]
fn the_held_deadline_stalls_a_started_worker_where_nothing_moves() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let none = OffSessions::default();
    let t0 = Instant::now() + Duration::from_secs(3 * 3600);
    let still = Progress {
        screen: 4,
        verdict: 9,
        input: 3,
        transcript: Some(1000),
    };
    let mut books = Startups::default();
    let look = |books: &mut Startups, at: Instant| look_at_startups(books, at, true, &none, &hooks);
    w.set(vec![held_worker(
        "s-a",
        StartupState::Reopened,
        held_at("unknown", still),
    )]);
    assert_eq!(look(&mut books, t0), Some(t0 + HELD_RELOOK));
    let before = t0 + HELD_DEADLINE - Duration::from_millis(1);
    assert_eq!(look(&mut books, before), Some(t0 + HELD_DEADLINE));
    assert!(w.marks().is_empty(), "not before its deadline");
    let due = t0 + HELD_DEADLINE;
    assert_eq!(look(&mut books, due), Some(due + HELD_RELOOK));
    assert_eq!(
        w.marks(),
        [("s-a".to_string(), Marked::Held("unknown".to_string()))]
    );
    w.set(vec![held_worker(
        "s-a",
        StartupState::StalledHeld,
        held_at("unknown", still),
    )]);
    let later = due + HELD_DEADLINE;
    assert_eq!(look(&mut books, later), Some(later + HELD_RELOOK));
    assert!(w.marks().is_empty());
    let pressed = Progress {
        input: still.input + 1,
        ..still
    };
    w.set(vec![held_worker(
        "s-a",
        StartupState::StalledHeld,
        held_at("unknown", pressed),
    )]);
    assert_eq!(look(&mut books, later), None);
    assert_eq!(w.marks(), [("s-a".to_string(), Marked::Moved)]);
    w.set(vec![held_worker(
        "s-a",
        StartupState::Working,
        held_at("unknown", pressed),
    )]);
    assert_eq!(look(&mut books, later), Some(later + HELD_RELOOK));
    let before = later + HELD_DEADLINE - Duration::from_millis(1);
    assert_eq!(look(&mut books, before), Some(later + HELD_DEADLINE));
    assert!(
        w.marks().is_empty(),
        "seen started: held, never its start judged"
    );

    for word in ["busy", "idle", "wall:limit", "wall:unresponsive"] {
        let mut books = Startups::default();
        w.set(vec![held_worker(
            "s-b",
            StartupState::Reopened,
            held_at(word, still),
        )]);
        assert_eq!(look(&mut books, t0), None, "{word}");
        assert_eq!(look(&mut books, t0 + 10 * HELD_DEADLINE), None, "{word}");
        assert!(w.marks().is_empty(), "{word} is never held");
    }
    let mut books = Startups::default();
    let growing = |len: u64| {
        vec![held_worker(
            "s-c",
            StartupState::Reopened,
            held_at(
                "unknown",
                Progress {
                    transcript: Some(len),
                    ..still
                },
            ),
        )]
    };
    w.set(growing(1000));
    look(&mut books, t0);
    let moved_at = t0 + HELD_DEADLINE - Duration::from_secs(1);
    w.set(growing(1400));
    assert_eq!(look(&mut books, moved_at), Some(moved_at + HELD_RELOOK));
    look(&mut books, t0 + HELD_DEADLINE);
    assert!(w.marks().is_empty(), "its transcript moved");
    look(&mut books, moved_at + HELD_DEADLINE);
    assert_eq!(
        w.marks(),
        [("s-c".to_string(), Marked::Held("unknown".to_string()))],
        "and once it stops, it is held"
    );
    let mut books = Startups::default();
    let mut escalated = held_at("question", still);
    escalated.escalated = true;
    w.set(vec![held_worker("s-d", StartupState::Reopened, escalated)]);
    assert_eq!(look(&mut books, t0), None);
    look(&mut books, t0 + 10 * HELD_DEADLINE);
    assert!(w.marks().is_empty(), "the harness handed it to a person");
    let asked = w.reads();
    w.set(vec![held_worker(
        "s-a",
        StartupState::Reopened,
        held_at("unknown", still),
    )]);
    let mut books = Startups::default();
    assert_eq!(
        look_at_startups(&mut books, t0 + 10 * HELD_DEADLINE, false, &none, &hooks),
        None
    );
    assert_eq!(w.reads(), asked, "nothing read");
}

#[test]
fn a_held_stall_ends_when_anything_moves() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let none = OffSessions::default();
    let t0 = Instant::now();
    let still = Progress {
        screen: 4,
        verdict: 9,
        input: 3,
        transcript: Some(1000),
    };
    let moves: [(&str, HeldRead); 5] = [
        ("text", held_at("unknown", Progress { screen: 5, ..still })),
        (
            "verdict",
            held_at(
                "prompt",
                Progress {
                    verdict: 10,
                    ..still
                },
            ),
        ),
        ("busy", held_at("busy", still)),
        (
            "transcript",
            held_at(
                "unknown",
                Progress {
                    transcript: Some(1001),
                    ..still
                },
            ),
        ),
        (
            "escalated",
            HeldRead {
                escalated: true,
                ..held_at("unknown", still)
            },
        ),
    ];
    for (what, moved) in moves {
        let mut books = Startups::default();
        w.set(vec![held_worker(
            "s-a",
            StartupState::StalledHeld,
            held_at("unknown", still),
        )]);
        assert_eq!(
            look_at_startups(&mut books, t0, true, &none, &hooks),
            Some(t0 + HELD_RELOOK),
            "{what}"
        );
        assert!(w.marks().is_empty(), "{what}: nothing moved yet");
        w.set(vec![held_worker("s-a", StartupState::StalledHeld, moved)]);
        look_at_startups(&mut books, t0, true, &none, &hooks);
        assert_eq!(w.marks(), [("s-a".to_string(), Marked::Moved)], "{what}");
    }
}

#[test]
fn the_held_deadline_judges_started_workers_and_no_off_one() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let none = OffSessions::default();
    let t0 = Instant::now() + Duration::from_secs(3 * 3600);
    let short = Duration::from_secs(10);
    let still = Progress::default();
    let mut books = Startups::held_after(short);
    w.set(vec![Startup {
        seen: StartupSeen::Holds(StartupHold::NoComposer {
            agent: Program::Claude,
        }),
        ..held_worker("s-a", StartupState::Working, held_at("unknown", still))
    }]);
    let since = w.reads.lock().unwrap()[0].since;
    look_at_startups(&mut books, t0, true, &none, &hooks);
    look_at_startups(&mut books, t0 + short, true, &none, &hooks);
    assert!(w.marks().is_empty(), "not held before it is started");
    let mut books = Startups::held_after(short);
    w.set(vec![Startup {
        seen: StartupSeen::Started,
        since,
        ..held_worker("s-b", StartupState::Working, held_at("prompt", still))
    }]);
    assert_eq!(
        look_at_startups(&mut books, t0, true, &none, &hooks),
        Some(t0 + short)
    );
    look_at_startups(&mut books, t0 + short, true, &none, &hooks);
    assert_eq!(
        w.marks(),
        [("s-b".to_string(), Marked::Held("prompt".to_string()))]
    );
    let off = OffSessions {
        words: [("s-c".to_string(), Autopilot::Off)].into(),
        default: Autopilot::Cruise,
    };
    let mut books = Startups::held_after(short);
    w.set(vec![held_worker(
        "s-c",
        StartupState::Reopened,
        held_at("unknown", still),
    )]);
    assert_eq!(look_at_startups(&mut books, t0, true, &off, &hooks), None);
    let late = t0 + 100 * short;
    assert_eq!(look_at_startups(&mut books, late, true, &off, &hooks), None);
    assert!(
        w.marks().is_empty(),
        "an Off worker is neither marked nor badged"
    );
    assert_eq!(
        look_at_startups(&mut books, late, true, &none, &hooks),
        Some(late + short),
        "back from Off: not on the clock it had before"
    );
    look_at_startups(&mut books, late + short, true, &none, &hooks);
    assert_eq!(
        w.marks(),
        [("s-c".to_string(), Marked::Held("unknown".to_string()))]
    );
    w.set(vec![held_worker(
        "s-c",
        StartupState::StalledHeld,
        held_at("busy", still),
    )]);
    look_at_startups(&mut books, late + short, true, &off, &hooks);
    assert!(w.marks().is_empty(), "no `working` mark while Off");
    let mut books = Startups::held_after(short);
    w.set(vec![held_worker(
        "s-c",
        StartupState::Reopened,
        held_at("unknown", still),
    )]);
    look_at_startups(&mut books, t0, true, &none, &hooks);
    look_at_startups(&mut books, t0 + short, true, &none, &hooks);
    assert_eq!(
        w.marks(),
        [("s-c".to_string(), Marked::Held("unknown".to_string()))]
    );
}

#[test]
fn the_held_deadline_counts_none_of_the_harnesss_own_waits() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let none = OffSessions::default();
    let t0 = Instant::now() + Duration::from_secs(3 * 3600);
    let grace = Duration::from_secs(300);
    let still = Progress::default();
    let books_with = |relaunching: &[&str]| Startups {
        waits: HarnessWaits {
            grace,
            relaunching: relaunching.iter().map(|sid| (*sid).to_string()).collect(),
        },
        ..Startups::default()
    };
    let look = |books: &mut Startups, at: Instant| look_at_startups(books, at, true, &none, &hooks);
    let at_box = |person: Option<Instant>| {
        vec![held_worker(
            "s-a",
            StartupState::Reopened,
            HeldRead {
                person,
                ..held_at("prompt", still)
            },
        )]
    };
    let typed = t0 - Duration::from_secs(1);
    let due = typed + grace + HELD_DEADLINE;
    let mut books = books_with(&[]);
    w.set(at_box(Some(typed)));
    for at in [
        t0,
        t0 + HELD_DEADLINE,
        typed + grace,
        due - Duration::from_millis(1),
    ] {
        assert_eq!(look(&mut books, at), Some(due.min(at + HELD_RELOOK)));
    }
    assert!(
        w.marks().is_empty(),
        "the harness's hold for a person is no worker held"
    );
    assert_eq!(look(&mut books, due), Some(due + HELD_RELOOK));
    assert_eq!(
        w.marks(),
        [("s-a".to_string(), Marked::Held("prompt".to_string()))],
        "a whole deadline past the grace, nothing pressed: held"
    );
    let mut books = books_with(&[]);
    w.set(at_box(Some(t0 - grace - Duration::from_secs(1))));
    look(&mut books, t0);
    look(&mut books, t0 + HELD_DEADLINE);
    assert_eq!(
        w.marks(),
        [("s-a".to_string(), Marked::Held("prompt".to_string()))]
    );

    let at_shell = |state| {
        vec![held_worker(
            "s-r",
            state,
            HeldRead {
                program: Some("zsh".to_string()),
                ..held_at("-", still)
            },
        )]
    };
    let mut books = books_with(&["s-r"]);
    w.set(at_shell(StartupState::Reopened));
    assert_eq!(look(&mut books, t0), None);
    assert_eq!(look(&mut books, t0 + 10 * HELD_DEADLINE), None);
    assert!(
        w.marks().is_empty(),
        "a relaunch's back-off is no worker held"
    );
    w.set(at_shell(StartupState::StalledHeld));
    look(&mut books, t0 + 10 * HELD_DEADLINE);
    assert_eq!(w.marks(), [("s-r".to_string(), Marked::Moved)]);
    let mut books = books_with(&[]);
    w.set(at_shell(StartupState::Reopened));
    assert_eq!(look(&mut books, t0), Some(t0 + HELD_RELOOK));
    look(&mut books, t0 + HELD_DEADLINE);
    assert_eq!(
        w.marks(),
        [("s-r".to_string(), Marked::Held("-".to_string()))]
    );
}

fn held_when(
    w: &StartupWorld,
    hooks: &Hooks,
    books: &mut Startups,
    (t0, end): (Instant, Instant),
    read_at: impl Fn(Instant) -> HeldRead,
) -> Option<Instant> {
    let mut at = t0;
    while at <= end {
        w.set(vec![held_worker(
            "s-a",
            StartupState::Reopened,
            read_at(at),
        )]);
        let next = look_at_startups(books, at, true, &OffSessions::default(), hooks);
        if w.marks().iter().any(|(_, m)| matches!(m, Marked::Held(_))) {
            return Some(at);
        }
        at = next?;
    }
    None
}

#[test]
fn a_held_clock_restarts_within_a_relook_of_what_moved() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let t0 = Instant::now() + Duration::from_secs(3 * 3600);
    let span = (t0, t0 + 3 * HELD_DEADLINE);
    let keyed = t0 + Duration::from_secs(1);
    let read_at = |at: Instant| {
        held_at(
            "unknown",
            Progress {
                input: u64::from(at >= keyed),
                ..Progress::default()
            },
        )
    };
    let held = held_when(&w, &hooks, &mut Startups::default(), span, read_at).expect("held");
    assert!(
        held >= keyed + HELD_DEADLINE && held <= keyed + HELD_RELOOK + HELD_DEADLINE,
        "held {:?} after the key",
        held - keyed
    );
    let still = |_| held_at("unknown", Progress::default());
    assert_eq!(
        held_when(&w, &hooks, &mut Startups::default(), span, still),
        Some(t0 + HELD_DEADLINE)
    );
}

#[test]
fn the_held_deadline_holds_off_through_a_drivers_hand() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let t0 = Instant::now() + Duration::from_secs(3 * 3600);
    let grace = Duration::from_secs(300);
    let span = (t0, t0 + 10 * HELD_DEADLINE);
    let lifted = t0 + Duration::from_secs(100);
    let books = || Startups {
        waits: HarnessWaits {
            grace,
            relaunching: HashSet::new(),
        },
        ..Startups::default()
    };
    let at_box = |driver: bool| HeldRead {
        driver,
        ..held_at("prompt", Progress::default())
    };
    let held = held_when(&w, &hooks, &mut books(), span, |at| at_box(at < lifted)).expect("held");
    assert!(
        held >= lifted - HELD_RELOOK + grace + HELD_DEADLINE
            && held <= lifted + grace + HELD_DEADLINE,
        "held {:?} after the hand lifted",
        held - lifted
    );
    assert_eq!(
        held_when(&w, &hooks, &mut books(), span, |_| at_box(false)),
        Some(t0 + HELD_DEADLINE)
    );
}

#[test]
fn a_hand_defers_no_stall_where_the_harness_has_no_act() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let t0 = Instant::now() + Duration::from_secs(3 * 3600);
    let grace = Duration::from_secs(3600);
    let span = (t0, t0 + grace + 3 * HELD_DEADLINE);
    let typed = t0 - Duration::from_secs(1);
    let first_look_only = t0 + Duration::from_millis(1);
    let books = || Startups {
        waits: HarnessWaits {
            grace,
            relaunching: HashSet::new(),
        },
        ..Startups::default()
    };
    let keyed = |word: &'static str, panel: bool| {
        move |_: Instant| HeldRead {
            person: Some(typed),
            panel,
            ..held_at(word, Progress::default())
        }
    };
    let driven = |word: &'static str, panel: bool| {
        move |at: Instant| HeldRead {
            driver: at < first_look_only,
            panel,
            ..held_at(word, Progress::default())
        }
    };
    for word in ["unknown", "-"] {
        assert_eq!(
            held_when(&w, &hooks, &mut books(), span, keyed(word, false)),
            Some(t0 + HELD_DEADLINE),
            "{word}: a person's keystroke"
        );
        assert_eq!(
            held_when(&w, &hooks, &mut books(), span, driven(word, false)),
            Some(t0 + HELD_DEADLINE),
            "{word}: a driver's hand"
        );
    }
    for (word, panel) in [("prompt", false), ("unknown", true)] {
        let held = held_when(&w, &hooks, &mut books(), span, keyed(word, panel)).expect("held");
        assert!(
            held >= typed + grace + HELD_DEADLINE,
            "{word} panel={panel}: held {:?} after the keystroke",
            held - typed
        );
        let held = held_when(&w, &hooks, &mut books(), span, driven(word, panel)).expect("held");
        assert!(
            held >= t0 + grace + HELD_DEADLINE,
            "{word} panel={panel}: held {:?} after the hand",
            held - t0
        );
    }
}

#[test]
fn a_look_that_could_not_read_the_screen_marks_nothing() {
    let w = Arc::new(StartupWorld::default());
    let hooks = w.hooks();
    let t0 = Instant::now() + Duration::from_secs(3 * 3600);
    let grace = Duration::from_secs(3600);
    let span = (t0, t0 + grace + 3 * HELD_DEADLINE);
    let typed = t0 - Duration::from_secs(1);
    let busy = (t0 + Duration::from_secs(1), t0 + 2 * HELD_DEADLINE);
    let books = || Startups {
        waits: HarnessWaits {
            grace,
            relaunching: HashSet::new(),
        },
        ..Startups::default()
    };
    let at_panel = |flagged: bool| {
        move |at: Instant| {
            let lost = (busy.0..busy.1).contains(&at);
            HeldRead {
                person: Some(typed),
                panel: !lost,
                unread: lost && flagged,
                last_row: (!lost).then(|| "Esc to cancel".to_string()),
                ..held_at("unknown", Progress::default())
            }
        }
    };
    let held = held_when(&w, &hooks, &mut books(), span, at_panel(true)).expect("held");
    assert!(
        held >= typed + grace + HELD_DEADLINE,
        "held {:?} after the keystroke",
        held - typed
    );
    assert_eq!(
        held_when(&w, &hooks, &mut books(), span, at_panel(false)),
        Some(t0 + HELD_DEADLINE)
    );
}

#[test]
fn a_drivers_hand_is_another_holders_lease_or_a_named_drivers_turn() {
    let now = 5_000_000;
    let ours = holder();
    let drive = |holder: &str, expires_us: u64| crate::Lease::Drive {
        holder: holder.to_string(),
        expires_us,
        conn: None,
        hard: false,
        here: false,
        holder_pid: None,
    };
    let turn = |driver: Option<&str>| crate::Lease::Turn {
        id: 4,
        driver: driver.map(aterm_session::SessionId::new),
        typing: false,
    };
    assert!(driver_holds(Some(&drive("manager", now + 1)), now, &ours));
    assert!(driver_holds(Some(&turn(Some("s-mgr"))), now, &ours));
    assert!(!driver_holds(Some(&drive(&ours, now + 1)), now, &ours));
    assert!(!driver_holds(Some(&drive("manager", now)), now, &ours));
    assert!(!driver_holds(Some(&turn(None)), now, &ours));
    assert!(!driver_holds(None, now, &ours));
}

#[test]
fn the_relaunches_in_hand_are_the_exits_handed_and_the_restored_queue() {
    let mut workers = Workers::default();
    let handed = idle_worker();
    assert!(handed.left.hand());
    workers.0.insert("s-left".to_string(), handed);
    workers.0.insert("s-watching".to_string(), idle_worker());
    let back = idle_worker();
    assert!(back.left.hand() && back.left.back());
    workers.0.insert("s-back".to_string(), back);
    let stopped = idle_worker();
    stopped.stop();
    workers.0.insert("s-stopped".to_string(), stopped);
    let pending = relaunches_pending(&workers, ["s-restored"]);
    let want: std::collections::HashSet<String> =
        ["s-left".to_string(), "s-restored".to_string()].into();
    assert_eq!(pending, want);
}

#[test]
fn the_held_attention_says_where_and_what_the_screen_shows() {
    let read = held_at("unknown", Progress::default());
    let said = held_attention(&read, Duration::from_secs(125));
    assert!(said.starts_with(HELD_HEAD), "{said}");
    assert!(
        said.contains("2m05s") && said.contains("agent=unknown"),
        "{said}"
    );
    assert!(said.contains("Enter to continue · Esc to cancel"), "{said}");
    assert!(said.ends_with("why=held)"), "{said}");
    assert!(deadline_attention_stands(Some(&said)));
    let shell = HeldRead {
        word: "-".to_string(),
        program: Some("zsh".to_string()),
        last_row: Some("%".to_string()),
        ..read.clone()
    };
    assert!(held_attention(&shell, Duration::from_secs(9)).contains("`zsh`"));
    let long = HeldRead {
        last_row: Some(format!("é{}\u{202e}\u{7}", "→".repeat(200))),
        ..read.clone()
    };
    let said = held_attention(&long, Duration::from_secs(4000));
    assert!(said.len() <= 200, "{} bytes: {said}", said.len());
    assert!(
        said.ends_with("why=held)") && said.contains("1h06m"),
        "{said}"
    );
    assert!(
        !said.contains('\u{202e}') && !said.contains('\u{7}'),
        "{said:?}"
    );
    let blank = HeldRead {
        last_row: None,
        ..read
    };
    assert!(!held_attention(&blank, Duration::from_secs(1)).contains("screen ending"));
}

#[test]
fn the_host_pass_runs_the_startup_deadline() {
    let w = Arc::new(StartupWorld::default());
    let handle = HostHandle::start(on(), false, true, w.hooks());
    handle.shared.lock().suspended = false;
    let mut host = HostState::from_shared(&handle.shared);
    let pass = |host: &mut HostState| match host_pass(&handle.shared, host, true, &handle.hooks) {
        ControlFlow::Continue(until) => until,
        ControlFlow::Break(()) => panic!("shut down"),
    };
    let long_ago = Instant::now()
        .checked_sub(3 * STARTUP_DEADLINE)
        .expect("the clock");
    w.set(vec![startup(
        "s-a",
        StartupState::Working,
        long_ago,
        StartupSeen::Holds(no_agent()),
    )]);
    host.startups.from = Some(long_ago);
    pass(&mut host);
    assert_eq!(w.marks(), [stalled("s-a", no_agent())]);
    handle.shared.lock().suspended = true;
    let asked = w.reads();
    pass(&mut host);
    assert_eq!(w.reads(), asked, "nothing read while suspended");
    assert_eq!(host.startups.from, None);
    handle.shared.lock().suspended = false;
    let before = Instant::now();
    pass(&mut host);
    assert!(host.startups.from.is_some_and(|from| from >= before));
    assert!(w.marks().is_empty(), "a whole deadline from the look after");
    handle.shared.lock().shutting_down = true;
    assert_eq!(
        host_pass(&handle.shared, &mut host, true, &handle.hooks),
        ControlFlow::Break(())
    );
    handle.shutdown_and_join();
}

#[test]
fn a_workers_start_is_read_off_its_screen() {
    use aterm_phase::prompt::fixtures as f;
    let mut composed = f::rows(&[
        "⏺ Reading the parser.",
        "",
        "✻ Worked for 3s · done 4:24 PM",
        "",
    ]);
    composed.extend(f::composer("  ? for shortcuts"));
    assert_eq!(
        startup_seen(&composed, Some("claude"), Some(Program::Claude), None),
        StartupSeen::Started
    );
    assert_eq!(
        startup_seen(
            &f::bash_one_row(),
            Some("claude"),
            Some(Program::Claude),
            None
        ),
        StartupSeen::Started
    );
    assert_eq!(
        startup_seen(
            &f::screen(f::TRUST),
            Some("claude"),
            Some(Program::Claude),
            None
        ),
        StartupSeen::Holds(StartupHold::Trust {
            agent: Program::Claude
        })
    );
    let blank = vec![String::new(); 24];
    assert_eq!(
        startup_seen(&blank, Some("claude"), Some(Program::Claude), None),
        StartupSeen::Holds(StartupHold::NoComposer {
            agent: Program::Claude
        })
    );
    let prompt = f::rows(&["Last login: Thu Oct 15 09:00:00 on ttys001", "% "]);
    assert_eq!(
        startup_seen(&prompt, Some("zsh"), None, None),
        StartupSeen::Holds(no_agent())
    );
    assert_eq!(
        startup_seen(&prompt, None, None, None),
        StartupSeen::Holds(StartupHold::NoAgent {
            agent: Program::Claude,
            program: None
        })
    );
    for hold in [
        StartupHold::Trust {
            agent: Program::Claude,
        },
        StartupHold::Box {
            agent: Program::Claude,
            title: "Bash command".to_string(),
        },
        StartupHold::NoComposer {
            agent: Program::Claude,
        },
        no_agent(),
        StartupHold::NoAgent {
            agent: Program::Claude,
            program: None,
        },
    ] {
        assert!(
            deadline_attention_stands(Some(&hold.attention())),
            "{hold:?}"
        );
    }
}

#[test]
fn another_harnesss_agent_at_its_composer_has_started() {
    let rows = |text: &str| -> Vec<String> { text.lines().skip(1).map(str::to_owned).collect() };
    for (agent, text, claude_finds_it) in [
        (
            Program::Agy,
            include_str!("../../aterm-phase/src/fixtures/agy-1.4.0-lab-idle.txt"),
            false,
        ),
        (
            Program::Gemini,
            include_str!("../../aterm-phase/src/fixtures/gemini-0.46.0-idle.txt"),
            false,
        ),
        (
            Program::Muse,
            include_str!(
                "../../aterm-phase/src/fixtures/muse-1.4.10-R6427.1-end-of-turn-finished.txt"
            ),
            true,
        ),
    ] {
        let screen = rows(text);
        assert_eq!(
            startup_seen(&screen, Some(agent.name()), Some(agent), None),
            StartupSeen::Started,
            "{agent:?}"
        );
        let by_claude = if claude_finds_it {
            StartupSeen::Started
        } else {
            StartupSeen::Holds(StartupHold::NoAgent {
                agent: Program::Claude,
                program: Some(agent.name().to_string()),
            })
        };
        assert_eq!(
            startup_seen(&screen, Some(agent.name()), None, None),
            by_claude,
            "{agent:?}: Claude Code's reader"
        );
    }
    let prompt = aterm_phase::prompt::fixtures::rows(&["% "]);
    assert_eq!(
        startup_seen(&prompt, Some("zsh"), Some(Program::Agy), None),
        StartupSeen::Holds(StartupHold::NoAgent {
            agent: Program::Agy,
            program: Some("zsh".to_string()),
        })
    );
}

#[test]
fn a_spawned_workers_start_is_read_by_its_own_agent() {
    use aterm_phase::prompt::fixtures::screen;
    let prompt = aterm_phase::prompt::fixtures::rows(&["% "]);
    for (agent, trust, idle) in [
        (
            Program::Gemini,
            aterm_phase::gemini::fixtures::TRUST,
            aterm_phase::gemini::fixtures::IDLE,
        ),
        (
            Program::Agy,
            aterm_phase::agy::fixtures::lab::FIRST_RUN_TRUST,
            aterm_phase::agy::fixtures::lab::IDLE,
        ),
        (
            Program::Muse,
            aterm_phase::muse::fixtures::TRUST_1_4_10,
            aterm_phase::muse::fixtures::IDLE_1_4_10,
        ),
    ] {
        let held = startup_seen(&screen(trust), Some("node"), None, Some(agent));
        assert_eq!(
            held,
            StartupSeen::Holds(StartupHold::Trust { agent }),
            "{agent:?}: its trust box"
        );
        let StartupSeen::Holds(hold) = held else {
            unreachable!()
        };
        assert!(
            hold.attention()
                .contains(&format!("{}'s folder-trust dialog", agent.product())),
            "{}",
            hold.attention()
        );
        assert!(deadline_attention_stands(Some(&hold.attention())));
        assert_eq!(
            startup_seen(&screen(idle), Some(agent.name()), None, Some(agent)),
            StartupSeen::Started,
            "{agent:?}: its composer"
        );
        let shell = startup_seen(&prompt, Some("zsh"), None, Some(agent));
        assert_eq!(
            shell,
            StartupSeen::Holds(StartupHold::NoAgent {
                agent,
                program: Some("zsh".to_string()),
            }),
            "{agent:?}: the line never typed"
        );
        let StartupSeen::Holds(hold) = shell else {
            unreachable!()
        };
        assert!(
            hold.attention().contains(&format!(
                "no {} started; `zsh` holds the tab",
                agent.product()
            )),
            "{}",
            hold.attention()
        );
        let blank = vec![String::new(); 24];
        assert_eq!(
            startup_seen(&blank, Some(agent.name()), Some(agent), Some(agent)),
            StartupSeen::Holds(StartupHold::NoComposer { agent }),
            "{agent:?}: its own screen with no composer"
        );
        assert_ne!(
            startup_seen(&screen(trust), Some("node"), None, None),
            StartupSeen::Holds(StartupHold::Trust { agent }),
            "CONTROL {agent:?}: Claude Code's reader"
        );
        assert_eq!(
            startup_seen(
                &screen(idle),
                Some(agent.name()),
                Some(agent),
                Some(Program::Claude)
            ),
            StartupSeen::Started,
            "CONTROL {agent:?}: the published agent's reader wins"
        );
    }
}

