#[test]
fn a_restored_queue_that_panicked_drops_nothing_unsaid() {
    for closed in [false, true] {
        let world = Arc::new(World::default());
        let cleared: Arc<Mutex<Vec<String>>> = Arc::default();
        let mut h = hooks(&world, parking_body(&world));
        let c = Arc::clone(&cleared);
        h.badge = Arc::new(move |sid, text| {
            if text.is_none() {
                c.lock().unwrap().push(sid.to_string());
            }
        });
        let host = HostHandle::start(on(), false, false, h);
        let restored = |sid: &str, tab: u32| RestoredAgent {
            sid: sid.to_string(),
            snap: snap(sid),
            place: format!("in tab {tab}"),
            cold: true,
            asked: None,
            was: None,
        };
        {
            let mut queue = host.shared.restored.lock().unwrap();
            queue.running = true;
            queue.attempts.extend([
                queued_attempt(restored("s-qa", 3), 0),
                queued_attempt(restored("s-qb", 4), 1),
            ]);
        }
        let gathered = RestoredMiss {
            order: 99,
            sid: "s-qz".to_string(),
            place: "in tab 2".to_string(),
            agent: upgrade::Agent::Claude,
            outcome: Outcome::Cannot("test".to_string()),
            said: 0,
        };
        {
            let mut queue = host.shared.restored.lock().unwrap();
            queue.missed.push(gathered.clone());
            queue.closed = closed;
        }
        let mut missed = restored_queue_panicked(&host.shared, host.hooks.badge.as_ref());
        missed.sort_by_key(|m| m.order);
        let (left, running) = {
            let queue = host.shared.restored.lock().unwrap();
            (queue.attempts.len(), queue.running)
        };
        assert!(
            !running,
            "closed={closed}: the next restore starts a worker"
        );
        if closed {
            assert_eq!(left, 2, "CONTROL: what it owes is kept");
            assert!(missed.is_empty(), "CONTROL: nothing said");
            assert!(
                cleared.lock().unwrap().is_empty(),
                "CONTROL: no word cleared"
            );
        } else {
            assert_eq!(left, 0, "over");
            let places: Vec<&str> = missed.iter().map(|m| m.place.as_str()).collect();
            assert_eq!(places, ["in tab 3", "in tab 4", "in tab 2"], "{missed:?}");
            assert!(
                missed[..2]
                    .iter()
                    .all(|m| m.outcome == Outcome::Cannot(RESTORED_PANIC.to_string())),
                "{missed:?}"
            );
            let mut words = cleared.lock().unwrap().clone();
            words.sort();
            assert_eq!(words, ["s-qa", "s-qb"], "every tab's word cleared");
        }
        host.shutdown_and_join();
    }
}

#[test]
fn a_view_that_panicked_is_asked_again_in_a_while() {
    for (panics, back_off) in [
        (true, Duration::ZERO),
        (true, Duration::from_secs(3600)),
        (false, Duration::ZERO),
    ] {
        let case = format!("panics={panics} back-off={back_off:?}");
        let world = Arc::new(World::default());
        let (looks, downs) = (Arc::new(AtomicUsize::new(0)), Arc::new(AtomicUsize::new(0)));
        let (l, d) = (Arc::clone(&looks), Arc::clone(&downs));
        let hooks = Hooks {
            upgrade_view: Arc::new(move |look, _, _, _| {
                if !look {
                    d.fetch_add(1, Ordering::SeqCst);
                    assert!(!panics, "the stand-down fails (a test's)");
                    return ViewNext::default();
                }
                let n = l.fetch_add(1, Ordering::SeqCst) + 1;
                assert!(!(panics && n >= 2), "the view fails (a test's)");
                ViewNext {
                    at: Some(crate::upgrade_host::now_s()),
                    watch: vec!["s-old".to_string()],
                    ..ViewNext::default()
                }
            }),
            pause: Arc::new(move |_| back_off),
            ..hooks(&world, parking_body(&world))
        };
        let mut view = ViewLook::default();
        let stamps: HashMap<String, FollowStamp> = HashMap::new();
        let tabs: HashMap<String, Program> = [("s-a".to_string(), Program::Claude)].into();
        let mut named = Vec::new();
        for _ in 0..4 {
            named.push(look_at_upgrades(&mut view, &tabs, &stamps, true, (0, 0), &hooks).is_some());
        }
        let asked = looks.load(Ordering::SeqCst);
        assert_eq!(named, [true; 4], "{case}: an instant named at every pass");
        match (panics, back_off.is_zero()) {
            (true, true) => assert_eq!(asked, 4, "{case}: asked again at every retry"),
            (true, false) => assert_eq!(asked, 2, "{case}: one look per back-off, never a loop"),
            (false, _) => assert_eq!(asked, 4, "CONTROL: asked at every instant it named"),
        }
        assert_eq!(view.watch, ["s-old"], "{case}: the last good look's watch");
        let mut stood = Vec::new();
        for _ in 0..3 {
            stood
                .push(look_at_upgrades(&mut view, &tabs, &stamps, false, (0, 0), &hooks).is_some());
        }
        let downs = downs.load(Ordering::SeqCst);
        match (panics, back_off.is_zero()) {
            (true, true) => assert_eq!((downs, stood), (3, vec![true; 3]), "{case}"),
            (true, false) => assert_eq!((downs, stood), (1, vec![true; 3]), "{case}"),
            (false, _) => assert_eq!((downs, stood), (1, vec![false; 3]), "CONTROL"),
        }
        assert!(view.watch.is_empty(), "{case}: stood down, nothing watched");
    }
}

#[test]
fn a_panicked_body_leaves_the_face_unknown_before_the_next_runs_start_face() {
    use aterm_agent::harness::acts::TaskFace;
    type Told = Arc<Mutex<Vec<crate::HarnessFact>>>;
    let run = |panics: bool| {
        let world = Arc::new(World::default());
        world.set(&[("s-face", Program::Claude)]);
        let told: Told = Arc::default();
        let w = Arc::clone(&world);
        let body: Arc<BodyFn> = Arc::new(move |job: &WorkerJob| {
            let n = w.runs.fetch_add(1, Ordering::SeqCst);
            let idle = job.opts.idle_host.as_ref().expect("the worker's idle host");
            idle.task_face(if n == 0 {
                TaskFace::Landed
            } else {
                TaskFace::Open
            });
            if panics && n == 0 {
                panic!("boom in the loop");
            }
            while !job.stop.load(Ordering::SeqCst) {
                std::thread::sleep(Duration::from_millis(2));
            }
            BodyEnd::Stopped
        });
        let mut h = hooks(&world, body);
        let into = Arc::clone(&told);
        h.fact = Arc::new(move |sid, fact| {
            assert_eq!(sid, "s-face");
            if matches!(fact, crate::HarnessFact::Task(_)) {
                into.lock().unwrap().push(fact);
            }
        });
        let host = HostHandle::start(on(), false, false, h);
        let want = if panics { 3 } else { 1 };
        until("the faces told", || told.lock().unwrap().len() >= want);
        let running = told.lock().unwrap().clone();
        host.shutdown_and_join();
        let all = told.lock().unwrap().clone();
        (running, all)
    };
    use crate::HarnessFact::Task;
    let (running, all) = run(true);
    assert_eq!(
        running,
        [
            Task(Some(TaskFace::Landed)),
            Task(None),
            Task(Some(TaskFace::Open))
        ],
        "unknown between the panicked run and the next run's start"
    );
    assert_eq!(
        all[running.len()..],
        [Task(None), Task(None)],
        "after the last run, and at the worker's end"
    );
    let (running, all) = run(false);
    assert_eq!(running, [Task(Some(TaskFace::Landed))]);
    assert_eq!(all[1..], [Task(None), Task(None)]);
}

#[test]
fn a_stuck_program_check_holds_the_worker_and_keeps_what_it_owes() {
    use crate::program_check_watch::{Board, step};
    use aterm_uds::program_check::Look;
    use aterm_vitals::program_check::{Daemon, Reading, STUCK_AFTER_MS};
    static STUCK: Mutex<Board> = Mutex::new(Board::new());
    static CLEAR: Mutex<Board> = Mutex::new(Board::new());
    let read = |workers, at_limit| {
        Look::Read(Reading {
            daemon: Daemon {
                pid: 690,
                start_s: 1_791_000_000,
                start_us: 1,
            },
            workers,
            at_limit,
            limit: Some(90),
        })
    };
    let look = |at, l| {
        let _ = step(&mut STUCK.lock().unwrap(), at, l);
    };
    look(0, read(95, true));
    look(STUCK_AFTER_MS, read(95, true));
    let worker = |sid: &str, board: &'static Mutex<Board>| {
        let mut hooks = hooks(
            &Arc::new(World::default()),
            Arc::new(|_: &WorkerJob| BodyEnd::Stopped),
        );
        hooks.acts = Acts {
            program_check: board,
            due: Arc::new(|_| Due::Yes),
            notice: Arc::new(|_, _| "announced:1".to_string()),
            ..Acts::inert()
        };
        let w = idle_host(sid, Program::Claude, switched(&resetting()), hooks);
        w.park.store(true, Ordering::SeqCst);
        *w.look_at.lock().unwrap() = Some(Instant::now());
        w
    };

    let held = worker("s-check-stuck", &STUCK);
    assert!(
        held.withholds_turn_end(),
        "no keep going while no program can start"
    );
    assert!(!held.owns_turn_end(), "no upgrade's ownership");
    assert!(!held.wants(), "no point asked");
    assert!(held.wants_at().is_none(), "no wake set");
    assert!(held.at_idle().is_none(), "nothing typed, no step taken");
    assert!(held.at_background().is_none(), "no step at a break either");
    assert!(
        !held.relaunches_after_stall(),
        "no frozen agent ended for a start that would not start"
    );
    assert_eq!(
        held.reset_claimed(&reset_ask(None), &mut None),
        Err(NoReset::ProgramCheck),
        "no limit reset spent on an agent nothing it starts would start"
    );
    assert!(
        held.park.load(Ordering::SeqCst) && held.look_at.lock().unwrap().is_some(),
        "the park and the look are kept"
    );

    let asks = worker("s-check-clear", &CLEAR);
    assert!(
        !asks.withholds_turn_end(),
        "CONTROL: a board that never read stuck holds nothing"
    );
    assert!(asks.wants(), "CONTROL: the park asks at once");
    assert!(asks.wants_at().is_some(), "CONTROL: the look's wake stands");
    assert_eq!(
        asks.at_background().map(|(line, _)| line).as_deref(),
        Some("upgrade step=announced:1"),
        "CONTROL: a break takes the due upgrade's notice"
    );
    assert!(
        asks.relaunches_after_stall(),
        "CONTROL: a stall relaunches the agent"
    );
    assert_eq!(
        asks.reset_claimed(&reset_ask(None), &mut None),
        Err(NoReset::Unread),
        "CONTROL: the reset goes on to read the account, which this world has none of"
    );

    look(STUCK_AFTER_MS + 60_000, read(4, false));
    assert!(
        !held.withholds_turn_end(),
        "the turn ends are the loop's again"
    );
    assert!(
        held.wants(),
        "the kept park asks for its point once the check clears"
    );
}

#[test]
fn a_full_disk_withholds_continuations_and_space_back_types_the_resume_once() {
    use aterm_agent::harness::disk::Level;
    use aterm_phase::disk_full::{Code, DiskFull, Source};
    static BOARD: Shelf = Shelf::new();
    let tmp = aterm_tempfile::Builder::new()
        .prefix("aterm-host-disk-episode-")
        .tempdir()
        .expect("temp dir");
    let state = tmp.path().join("state");
    let seen = |sid: &str| {
        (
            sid.to_string(),
            DiskFull {
                code: Code::Enospc,
                source: Source::Notification,
                row: 3,
                message: "the notice".to_string(),
            },
        )
    };
    let world = Arc::new(World::default());
    let typed: Arc<Mutex<Vec<(String, String)>>> = Arc::default();
    let answer = Arc::new(Mutex::new("typed".to_string()));
    let (t, a) = (Arc::clone(&typed), Arc::clone(&answer));
    let mut hooks = hooks(&world, parking_body(&world));
    hooks.acts = Acts {
        due: Arc::new(|_| Due::No),
        disk_resume: Arc::new(move |sid, text| {
            t.lock().unwrap().push((sid.to_string(), text.to_string()));
            a.lock().unwrap().clone()
        }),
        disk_board: &BOARD,
        ..Acts::inert()
    };
    let switches = Arc::new(Switches::default());
    switches.set(&on(), false);
    let idle = |sid: &str| WorkerIdle {
        stop: Arc::default(),
        tap: Mutex::default(),
        login_latches: Arc::default(),
        lifted_off: false,
        beside: Arc::default(),
        sid: sid.to_string(),
        agent: Program::Claude,
        grace: 0,
        park: Arc::default(),
        look_at: Arc::default(),
        acting: Arc::default(),
        stepped: Arc::default(),
        switches: Arc::clone(&switches),
        kept: Arc::default(),
        hooks: hooks.clone(),
        run: Mutex::default(),
        owns: AtomicBool::new(false),
        background_at: Mutex::default(),
        tasked: Mutex::default(),
        finished: Mutex::default(),
        note: Arc::default(),
        clock_hold: Mutex::default(),
        net: NetProbe::new(),
        route: Mutex::default(),
        memory: Mutex::default(),
        points: Arc::default(),
        settle_later: AtomicBool::default(),
        told: AtomicU8::new(0),
        activations: Arc::default(),
    };
    let full = idle("s-disk-full");
    let plenty = idle("s-disk-plenty");
    let quiet = idle("s-disk-quiet");

    disk_sightings(
        &BOARD,
        &[seen("s-disk-plenty")],
        Level::Ok,
        Some(200 << 30),
        &state,
        1,
    );
    disk_episode_after(&BOARD, Level::Ok, 0, &[]);
    assert!(!plenty.withholds_turn_end() && !plenty.wants());

    let tool = (
        "s-disk-tool".to_string(),
        DiskFull {
            source: Source::ToolOutput,
            ..seen("s-disk-tool").1
        },
    );
    disk_sightings(&BOARD, &[tool], Level::Emergency, Some(0), &state, 2);
    assert!(!idle("s-disk-tool").withholds_turn_end());

    disk_sightings(
        &BOARD,
        &[seen("s-disk-full")],
        Level::Emergency,
        Some(0),
        &state,
        2,
    );
    disk_episode_after(&BOARD, Level::Emergency, 0, &[]);
    assert!(full.withholds_turn_end(), "no keep going into a full disk");
    assert!(!full.owns_turn_end(), "no upgrade's ownership");
    assert!(!full.wants());
    assert!(!quiet.withholds_turn_end(), "no sighting, nothing withheld");

    disk_episode_after(
        &BOARD,
        Level::Short,
        30 << 30,
        &["30.0 GiB a gone cache".to_string()],
    );
    assert!(
        !full.withholds_turn_end(),
        "the turn ends are the loop's again"
    );
    assert!(full.wants(), "the resume asks for a point");
    let step = full.at_idle().expect("the resume's step");
    assert_eq!(step.line, "disk-resume@v1 step=typed");
    assert!(step.moved && step.typed.is_some());
    {
        let typed = typed.lock().unwrap();
        assert_eq!(typed.len(), 1);
        assert_eq!(typed[0].0, "s-disk-full");
        assert!(
            typed[0]
                .1
                .starts_with(aterm_agent::harness::upgrade::HARNESS_MARK)
                && typed[0].1.contains("ENOSPC"),
            "{}",
            typed[0].1
        );
    }
    assert!(!full.wants(), "typed once");
    assert!(!plenty.wants() && !quiet.wants());

    disk_sightings(
        &BOARD,
        &[seen("s-disk-full")],
        Level::Emergency,
        Some(0),
        &state,
        3,
    );
    disk_episode_after(&BOARD, Level::Emergency, 0, &[]);
    disk_episode_after(&BOARD, Level::Low, 0, &[]);
    *answer.lock().unwrap() = "wait:held".to_string();
    for _ in 0..DISK_RESUME_TRIES {
        assert!(full.wants());
        assert_eq!(full.at_idle().map(|s| s.line), None);
    }
    assert!(!full.wants(), "given up after its tries");
    assert_eq!(
        typed.lock().unwrap().len(),
        1 + usize::from(DISK_RESUME_TRIES)
    );
    let ledger = std::fs::read_to_string(state.join(aterm_agent::harness::cli::DISK_LEDGER))
        .unwrap_or_default();
    assert_eq!(
        ledger
            .lines()
            .filter(|l| l.contains("\"kind\":\"poke\""))
            .count(),
        3,
        "one row per sighting, not per look: {ledger}"
    );

    let notes: Arc<Mutex<Vec<HostNote>>> = Arc::default();
    let n = Arc::clone(&notes);
    let note = move |h: HostNote| {
        assert!(
            BOARD.is_free(),
            "the host callback can inspect the episode without reentering its lock"
        );
        n.lock().unwrap().push(h);
    };
    let lines = aterm_agent::harness::disk::Config::default().thresholds(None);
    let alert = |level, free| {
        disk_alert(
            &BOARD,
            level,
            &lines,
            free,
            0,
            &[],
            DiskFullCause::Spent,
            &note,
        );
    };
    alert(Level::Low, Some(9 << 30));
    alert(Level::Emergency, Some(1 << 20));
    alert(Level::Emergency, Some(1 << 20));
    alert(Level::Short, Some(9 << 30));
    alert(Level::Short, Some(9 << 30));
    let kinds: Vec<&str> = notes
        .lock()
        .unwrap()
        .iter()
        .map(|h| match h {
            HostNote::DiskFull { .. } => "full",
            HostNote::DiskFullOver => "over",
            _ => "other",
        })
        .collect();
    assert_eq!(kinds, ["full", "full", "over"]);
    let _ = std::fs::remove_dir_all(&state);
}

#[test]
fn the_disk_resume_keeps_a_continuations_gates() {
    use aterm_agent::harness::disk::Level;
    use aterm_phase::disk_full::{Code, DiskFull, Source};
    static BOARD: Shelf = Shelf::new();
    let state = aterm_tempfile::TempDir::new().expect("owned disk journal");
    let world = Arc::new(World::default());
    let typed: Arc<Mutex<Vec<String>>> = Arc::default();
    let t = Arc::clone(&typed);
    let mut hooks = hooks(&world, parking_body(&world));
    hooks.acts = Acts {
        due: Arc::new(|_| Due::No),
        disk_resume: Arc::new(move |sid, _| {
            t.lock().unwrap().push(sid.to_string());
            "typed".to_string()
        }),
        finished: Arc::new(|sid, _, _| Some(sid == "s-dr-finished")),
        tasked: Arc::new(|sid, _, _| Some(sid != "s-dr-taskless")),
        disk_board: &BOARD,
        ..Acts::inert()
    };
    hooks.autopilot =
        Arc::new(|| std::collections::HashMap::from([("s-dr-land".to_string(), Autopilot::Land)]));
    let tabs = ["s-dr-land", "s-dr-finished", "s-dr-taskless", "s-dr-open"];
    let idles: Vec<WorkerIdle> = tabs
        .iter()
        .map(|sid| {
            let mut idle = idle_of(
                hooks.clone(),
                Program::Claude,
                Some("0badf00d-1111-2222-3333-444455556666".to_string()),
            );
            idle.sid = (*sid).to_string();
            idle
        })
        .collect();
    assert_eq!(idles[0].autopilot(), Autopilot::Land);
    assert_eq!(idles[3].autopilot(), Autopilot::Cruise);
    let seen: Vec<(String, DiskFull)> = tabs
        .iter()
        .map(|sid| {
            (
                (*sid).to_string(),
                DiskFull {
                    code: Code::Enospc,
                    source: Source::Notification,
                    row: 3,
                    message: "the notice".to_string(),
                },
            )
        })
        .collect();
    disk_sightings(&BOARD, &seen, Level::Emergency, Some(0), state.path(), 1);
    disk_episode_after(&BOARD, Level::Emergency, 0, &[]);
    disk_episode_after(&BOARD, Level::Short, 30 << 30, &[]);
    assert!(
        tabs.iter().all(|sid| disk_owed(&BOARD, sid).is_some()),
        "owed"
    );
    let steps: Vec<Option<String>> = idles
        .iter()
        .map(|idle| idle.at_idle().map(|step| step.line))
        .collect();
    assert_eq!(*typed.lock().unwrap(), ["s-dr-open"], "{steps:?}");
    assert_eq!(steps[3].as_deref(), Some("disk-resume@v1 step=typed"));
    assert!(
        tabs.iter().all(|sid| disk_owed(&BOARD, sid).is_none()),
        "spent, typed or not"
    );
}

#[test]
fn the_disk_free_line_goes_only_to_the_tab_it_is_owed_at_its_turn_break_and_keeps_its_gates() {
    static BOARD: Shelf = Shelf::new();
    let world = Arc::new(World::default());
    /// Each act's tab and why it was unfit.
    type Calls = Vec<(String, Option<&'static str>)>;
    let calls: Arc<Mutex<Calls>> = Arc::default();
    let answer = Arc::new(Mutex::new("wait:busy".to_string()));
    let (c, a) = (Arc::clone(&calls), Arc::clone(&answer));
    let mut hooks = hooks(&world, parking_body(&world));
    hooks.acts = Acts {
        due: Arc::new(|_| Due::No),
        disk_free: Arc::new(move |sid, owed, unfit| {
            assert!(owed.text.ends_with("(rule disk-free@v1)"), "{}", owed.text);
            c.lock().unwrap().push((sid.to_string(), unfit));
            unfit.map_or_else(
                || a.lock().unwrap().clone(),
                |why| format!("released:{why}"),
            )
        }),
        finished: Arc::new(|sid, _, _| Some(sid == "s-df-finished")),
        tasked: Arc::new(|sid, _, _| Some(sid != "s-df-taskless")),
        disk_board: &BOARD,
        ..Acts::inert()
    };
    hooks.autopilot =
        Arc::new(|| std::collections::HashMap::from([("s-df-land".to_string(), Autopilot::Land)]));
    let tabs = [
        "s-df-open",
        "s-df-land",
        "s-df-finished",
        "s-df-taskless",
        "s-df-other",
    ];
    let idles: Vec<WorkerIdle> = tabs
        .iter()
        .map(|sid| {
            let mut idle = idle_of(
                hooks.clone(),
                Program::Claude,
                Some("0badf00d-1111-2222-3333-444455556666".to_string()),
            );
            idle.sid = (*sid).to_string();
            idle
        })
        .collect();
    BOARD.publish(|b| {
        for sid in &tabs[..4] {
            b.asks.insert(
                (*sid).to_string(),
                crate::disk_board::AskOwed {
                    key: "dev:1".to_string(),
                    text: "[aterm harness] aterm: the volume is full. (rule disk-free@v1)"
                        .to_string(),
                },
            );
        }
    });
    assert!(
        idles[0].wants(),
        "an owed line asks for the next turn break"
    );
    assert_eq!(
        idles[0].at_idle().map(|s| s.line),
        None,
        "the fence refused"
    );
    assert!(
        disk_ask_owed(&BOARD, "s-df-open").is_some(),
        "a wait keeps the line for the next turn break"
    );
    *answer.lock().unwrap() = "typed".to_string();
    let step = idles[0].at_idle().expect("typed");
    assert_eq!(step.line, "disk-free@v1 step=typed");
    assert_eq!(
        step.typed,
        Some(aterm_agent::supervise::policy::turn_end::HostTurn::Fact),
        "its answer is no done report"
    );
    assert_eq!(idles[0].at_idle().map(|s| s.line), None, "typed once");
    let steps: Vec<Option<String>> = idles[1..]
        .iter()
        .map(|idle| idle.at_idle().map(|step| step.line))
        .collect();
    assert_eq!(
        steps[0].as_deref(),
        Some("disk-free@v1 step=typed"),
        "{steps:?}"
    );
    assert_eq!(steps[1..], [None, None, None], "{steps:?}");
    assert_eq!(
        *calls.lock().unwrap(),
        [
            ("s-df-open".to_string(), None),
            ("s-df-open".to_string(), None),
            ("s-df-land".to_string(), None),
            ("s-df-finished".to_string(), Some("finished")),
            ("s-df-taskless".to_string(), Some("taskless")),
        ],
        "landing is no bar; a finished or taskless tab is released, and a tab owed nothing is \
         never stepped"
    );
    assert!(
        tabs.iter().all(|sid| disk_ask_owed(&BOARD, sid).is_none()),
        "typed or released, nothing stays owed"
    );
    assert_eq!(
        BOARD.board_lock().unfit,
        BTreeMap::from([
            ("s-df-finished".to_string(), "finished"),
            ("s-df-taskless".to_string(), "taskless"),
        ]),
        "every turn break tells the look's seats which tabs may not be asked, owed or not"
    );
}

#[test]
fn an_unmeasured_disk_preserves_the_emergency() {
    use aterm_agent::harness::disk::{Config, Level};
    use aterm_phase::disk_full::{Code, DiskFull, Source};
    static BOARD: Shelf = Shelf::new();

    fn empty() -> DiskEpisode {
        DiskEpisode {
            level: None,
            stuck: BTreeMap::new(),
            owed: BTreeMap::new(),
            freed: 0,
            went: Vec::new(),
            said: BTreeSet::new(),
            alerted: false,
        }
    }
    let state = aterm_tempfile::TempDir::new().expect("owned disk journal");
    let thresholds = Config::default().thresholds(Some(1u64 << 40));
    let sid = "unmeasured-emergency";
    let seen = [(
        sid.to_string(),
        DiskFull {
            code: Code::Enospc,
            source: Source::Notification,
            row: 3,
            message: "ENOSPC".to_string(),
        },
    )];
    let notes: Arc<Mutex<Vec<HostNote>>> = Arc::default();
    let captured = Arc::clone(&notes);
    let note = move |h| captured.lock().unwrap().push(h);
    let begin = || {
        *disk_episode(&BOARD) = empty();
        notes.lock().unwrap().clear();
        let emergency = thresholds.level(Some(0), None);
        assert_eq!(emergency, Level::Emergency);
        disk_sightings(&BOARD, &seen, emergency, Some(0), state.path(), 1);
        disk_episode_after(&BOARD, emergency, 0, &[]);
        disk_alert(
            &BOARD,
            emergency,
            &thresholds,
            Some(0),
            0,
            &[],
            DiskFullCause::Spent,
            &note,
        );
        assert!(disk_withholds(&BOARD, sid));
        assert!(disk_owed(&BOARD, sid).is_none());
        assert!(disk_episode(&BOARD).alerted);
    };

    begin();
    let measured = thresholds.level(Some(thresholds.emergency), None);
    assert_ne!(measured, Level::Emergency);
    disk_episode_after(&BOARD, measured, 0, &[]);
    disk_alert(
        &BOARD,
        measured,
        &thresholds,
        Some(thresholds.emergency),
        0,
        &[],
        DiskFullCause::Spent,
        &note,
    );
    assert!(!disk_withholds(&BOARD, sid));
    assert!(disk_owed(&BOARD, sid).is_some());
    assert!(!disk_episode(&BOARD).alerted);
    assert!(matches!(
        notes.lock().unwrap().last(),
        Some(HostNote::DiskFullOver)
    ));
    assert_eq!(
        thresholds.level(None, Some(0)),
        Level::Emergency,
        "a known inode emergency needs no byte figure"
    );

    let mut observations = Vec::new();
    for files_free in [None, Some(thresholds.files_emergency)] {
        begin();
        let unmeasured = thresholds.level(None, files_free);
        disk_episode_after(&BOARD, unmeasured, 0, &[]);
        disk_alert(
            &BOARD,
            unmeasured,
            &thresholds,
            None,
            0,
            &[],
            DiskFullCause::Spent,
            &note,
        );
        observations.push((
            disk_withholds(&BOARD, sid),
            disk_owed(&BOARD, sid).is_none(),
            disk_episode(&BOARD).alerted,
            notes.lock().unwrap().len(),
        ));
    }
    assert_eq!(
        observations,
        [(true, true, true, 1); 2],
        "an unreadable byte count must preserve the emergency, hold, and alert without owing a resume"
    );
}

#[test]
fn the_owners_disk_watch_removes_only_on_a_device_it_can_name() {
    let tmp = aterm_tempfile::Builder::new()
        .prefix("aterm-hh-disk-private-")
        .tempdir()
        .expect("temp dir");
    let account = tmp.path().join("account");
    let scratch = tmp.path().join("scratch");
    let elsewhere = tmp.path().join("elsewhere");
    for dir in [&account, &scratch, &elsewhere] {
        std::fs::create_dir(dir).expect("home");
    }
    let named = |p: &Path| -> Option<u64> { Some(if p.ends_with("elsewhere") { 2 } else { 1 }) };
    let unnamed = |_: &Path| -> Option<u64> { None };
    let owner_unnamed = |p: &Path| -> Option<u64> { (!p.ends_with("account")).then_some(1) };
    assert_eq!(
        disk_private_with(false, Some(&account), &account, &named),
        None
    );
    assert_eq!(
        disk_private_with(false, Some(&account), &scratch, &named),
        Some(DiskPrivate::ScratchHome)
    );
    assert_eq!(
        disk_private_with(false, Some(&account), &scratch, &owner_unnamed),
        Some(DiskPrivate::ScratchHome)
    );
    assert_eq!(
        disk_private_with(false, Some(&account), &elsewhere, &named),
        None
    );
    assert_eq!(
        disk_private_with(false, Some(&account), &account, &unnamed),
        Some(DiskPrivate::DeviceUnnamed),
        "no device named, no removal: `None` would mean any device"
    );
    assert_eq!(
        disk_private_with(false, Some(&account), &elsewhere, &unnamed),
        Some(DiskPrivate::DeviceUnnamed)
    );
    assert_eq!(
        disk_private_with(true, Some(&account), &account, &named),
        Some(DiskPrivate::StateRoot)
    );
    assert_eq!(
        disk_private_with(false, None, &account, &named),
        Some(DiskPrivate::NoAccountHome)
    );
    let product = &aterm_agent::harness::disk::target::dev_of;
    assert!(product(&account).is_some(), "{account:?} has a device");
    assert_eq!(
        disk_private_with(false, Some(&account), &account, product),
        None
    );
}

/// Windows, on the owner's own facts.
#[cfg(windows)]
#[test]
fn on_windows_the_owners_home_removes_and_a_scratch_home_does_not() {
    let account = atpkg::platform::account_home().expect("the account's home");
    let dev = |p: &Path| aterm_sysprobe::volumes::file_id(p, true).map(|id| id.dev);
    assert!(dev(&account).is_some(), "{account:?} has a device");
    assert_eq!(
        disk_private_with(false, Some(&account), &account, &dev),
        None
    );
    let scratch = aterm_tempfile::Builder::new()
        .prefix("aterm-hh-disk-scratch-home-")
        .tempdir()
        .expect("temp dir");
    assert_eq!(dev(scratch.path()), dev(&account), "one volume");
    assert_eq!(
        disk_private_with(false, Some(&account), scratch.path(), &dev),
        Some(DiskPrivate::ScratchHome)
    );
    assert_eq!(
        disk_private_with(true, Some(&account), &account, &dev),
        Some(DiskPrivate::StateRoot)
    );
}

/// Windows: a live tab whose working directory cannot be placed is unknown, never silently absent.
#[cfg(windows)]
#[test]
fn a_windows_tab_with_no_placeable_cwd_is_unknown_and_named() {
    use aterm_agent::harness::disk::idle::SessionCwd;
    let tmp = aterm_tempfile::Builder::new()
        .prefix("aterm-hh-disk-cwd-")
        .tempdir()
        .expect("temp dir");
    let repo = tmp.path().join("repo");
    std::fs::create_dir_all(repo.join("src")).expect("checkout");
    std::fs::create_dir_all(tmp.path().join("other")).expect("beside it");
    let canonical = std::fs::canonicalize(&repo).expect("canonical");
    let plain = aterm_sysprobe::paths::plain(&canonical)
        .to_string_lossy()
        .into_owned();
    let (drive, rest) = plain.split_once(":\\").expect("a drive path");
    let msys = format!(
        "/{}/{}/src",
        drive.to_ascii_lowercase(),
        rest.replace('\\', "/")
    );
    let store = crate::session_store::new_store();
    let tab = |n: u64, report: Option<String>| {
        let handle = crate::session_store::test_handle(n);
        if let Some(report) = report {
            crate::term_lock(&handle.term).process(report.as_bytes());
        }
        store.write().unwrap().register(handle);
    };
    tab(1, Some(format!("\x1b]7;file://localhost{msys}\x07")));
    tab(2, None);
    tab(
        3,
        Some("\x1b]7;file://build-box/c/elsewhere\x07".to_owned()),
    );
    tab(
        4,
        Some("\x1b]7;file://build-box/C:/elsewhere\x07".to_owned()),
    );
    let (known, mut unknown, _) = all_session_dirs(&store, Some(&[]));
    unknown.sort_unstable();
    assert_eq!(unknown, [2, 3, 4], "{known:?}");
    let [(1, cwd)] = known.as_slice() else {
        panic!("tab 1 alone is placed: {known:?}");
    };
    assert_eq!(cwd, &PathBuf::from(format!("{plain}\\src")));
    let table = aterm_sysprobe::volumes::table();
    assert!(SessionCwd::of(cwd).may_work_in(&canonical, Some(&table)));
    let beside = SessionCwd::of(&tmp.path().join("other"));
    assert!(!beside.may_work_in(&canonical, Some(&table)));
    let why = disk_cwd_unknown(&unknown).expect("a reason");
    assert!(why.contains("3 tabs (tab 2 among them)"), "{why}");
    assert_eq!(
        disk_cwd_unknown(&[7]).as_deref(),
        Some(
            "tab 7 reported no working directory this window can place, so any checkout may be \
             one's"
        )
    );
    assert_eq!(disk_cwd_unknown(&[]), None);
}

#[test]
fn the_removal_reads_the_tabs_as_they_stand_now() {
    let tmp = aterm_tempfile::Builder::new()
        .prefix("aterm-hh-disk-now-")
        .tempdir()
        .expect("temp dir");
    let (first, then) = (tmp.path().join("first"), tmp.path().join("then"));
    let report = |dir: &Path| {
        let plain = aterm_sysprobe::paths::plain(dir)
            .to_string_lossy()
            .replace('\\', "/");
        let path = if plain.starts_with('/') {
            plain
        } else {
            format!("/{plain}")
        };
        format!("\x1b]7;file://{path}\x07")
    };
    let store = crate::session_store::new_store();
    let handle = crate::session_store::test_handle(1);
    let term = Arc::clone(&handle.term);
    crate::term_lock(&term).process(report(&first).as_bytes());
    store.write().unwrap().register(handle);
    let now = disk_sessions_now(&store);
    assert_eq!(now.cwds, std::slice::from_ref(&first), "{now:?}");
    assert_eq!(now.unknown, None);

    crate::term_lock(&term).process(report(&then).as_bytes());
    let now = disk_sessions_now(&store);
    assert_eq!(
        now.cwds,
        std::slice::from_ref(&then),
        "moved since: {now:?}"
    );

    store
        .write()
        .unwrap()
        .register(crate::session_store::test_handle(2));
    let now = disk_sessions_now(&store);
    assert_eq!(now.cwds, [then], "{now:?}");
    if cfg!(windows) {
        assert!(
            now.unknown.as_deref().is_some_and(|w| w.contains("tab 2")),
            "{now:?}"
        );
    } else {
        assert_eq!(now.unknown, None, "unix keeps its reading");
    }
}

#[test]
fn a_tab_busy_at_the_removal_is_unknown_on_windows() {
    let tmp = aterm_tempfile::Builder::new()
        .prefix("aterm-hh-disk-busy-")
        .tempdir()
        .expect("temp dir");
    let (first, then) = (tmp.path().join("first"), tmp.path().join("then"));
    let plain = aterm_sysprobe::paths::plain(&then)
        .to_string_lossy()
        .replace('\\', "/");
    let report = if plain.starts_with('/') {
        format!("\x1b]7;file://{plain}\x07")
    } else {
        format!("\x1b]7;file:///{plain}\x07")
    };
    let store = crate::session_store::new_store();
    let handle = crate::session_store::test_handle(1);
    let term = Arc::clone(&handle.term);
    crate::term_lock(&term).process(report.as_bytes());
    store.write().unwrap().register(handle);
    let before = [(1, first.clone())];

    let printing = crate::term_lock(&term);
    let now = disk_sessions_with(&store, &before);
    drop(printing);
    if cfg!(windows) {
        assert!(now.cwds.is_empty(), "never the look's copy: {now:?}");
        assert!(
            now.unknown
                .as_deref()
                .is_some_and(|w| w.starts_with("tab 1 was busy when the removal read the tabs")),
            "{now:?}"
        );
    } else {
        assert_eq!(now.cwds, [first], "unix keeps the look's copy");
        assert_eq!(now.unknown, None);
    }

    let now = disk_sessions_with(&store, &before);
    assert_eq!(now.cwds, [then], "free, read where it is: {now:?}");
    assert_eq!(now.unknown, None);
    assert_eq!(
        disk_tabs_busy(&[4, 9]).as_deref(),
        Some(
            "2 tabs (tab 4 among them) were busy when the removal read the tabs again, so where \
             they work now is not known"
        )
    );
    assert_eq!(disk_tabs_busy(&[]), None);
}

#[test]
fn a_private_instance_says_why_it_removes_nothing_once_a_change() {
    use aterm_agent::harness::disk::Level;
    let root = Some(DiskPrivate::StateRoot);
    assert_eq!(
        disk_private_line(root, true, false, Level::Short).as_deref(),
        Some(
            "harness disk watch: short, and this instance runs under a private state root \
             (ATERM_STATE_HOME): it measures and removes nothing"
        )
    );
    for (rule, says) in [
        (DiskPrivate::ScratchHome, "home is not the account's"),
        (DiskPrivate::DeviceUnnamed, "cannot name its home's device"),
        (DiskPrivate::NoAccountHome, "cannot read the account's home"),
    ] {
        let line = disk_private_line(Some(rule), true, false, Level::Short).expect("a line");
        assert!(
            line.contains(says) && !line.contains("private state root"),
            "{rule:?}: {line}"
        );
    }
    assert_eq!(disk_private_line(None, true, true, Level::Short), None);
    assert_eq!(disk_private_line(root, false, false, Level::Ok), None);
    let demand = disk_private_line(root, false, true, Level::Ok);
    assert!(
        demand
            .as_deref()
            .is_some_and(|l| l.starts_with("harness disk watch: ok with an agent's demand")),
        "{demand:?}"
    );

    let said = Mutex::new(None);
    let short = disk_private_line(root, true, false, Level::Short);
    assert_eq!(disk_private_said(&said, short.clone()), short, "first");
    assert_eq!(disk_private_said(&said, short.clone()), None, "it stands");
    assert_eq!(disk_private_said(&said, short.clone()), None, "it stands");
    let emergency = disk_private_line(root, true, false, Level::Emergency);
    assert_eq!(
        disk_private_said(&said, emergency.clone()),
        emergency,
        "a change"
    );
    assert_eq!(disk_private_said(&said, demand.clone()), demand, "a demand");
    assert_eq!(disk_private_said(&said, None), None, "nothing held back");
    assert_eq!(disk_private_said(&said, demand.clone()), demand, "again");
}

#[test]
fn the_looks_remover_judges_tier_3_against_the_tabs_at_the_removal() {
    let tmp = aterm_tempfile::Builder::new()
        .prefix("aterm-hh-disk-remover-")
        .tempdir()
        .expect("temp dir");
    let made = |p: PathBuf| {
        std::fs::create_dir_all(&p).expect("mkdir");
        std::fs::canonicalize(&p).expect("canonical")
    };
    let checkout = made(tmp.path().join("repo"));
    std::fs::create_dir_all(checkout.join(".git")).expect("git");
    std::fs::write(checkout.join(".git").join("index"), b"DIRC").expect("index");
    let target = made(tmp.path().join("repo").join("target"));
    let beside = made(tmp.path().join("beside"));
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |d| i64::try_from(d.as_secs()).unwrap_or(i64::MAX));
    let report = |dir: &Path| {
        let plain = aterm_sysprobe::paths::plain(dir)
            .to_string_lossy()
            .replace('\\', "/");
        let path = if plain.starts_with('/') {
            plain
        } else {
            format!("/{plain}")
        };
        format!("\x1b]7;file://{path}\x07")
    };
    let store = crate::session_store::new_store();
    let handle = crate::session_store::test_handle(1);
    let term = Arc::clone(&handle.term);
    crate::term_lock(&term).process(report(&beside).as_bytes());
    store.write().unwrap().register(handle);
    let row = aterm_agent::harness::disk::Row {
        class: aterm_agent::harness::disk::Class::CargoTargets,
        path: target,
        bytes: 0,
        bytes_partial: false,
        witness: aterm_agent::harness::disk::Witness::IdleWhole {
            marker: "CACHEDIR.TAG".to_owned(),
            checkout: checkout.clone(),
            profiles: 1,
            last_used: now - 8 * 86_400,
            age_s: 8 * 86_400,
            window_days: 7,
            device: 0,
        },
        removable: true,
        blocked: None,
    };
    let judge = aterm_agent::harness::disk::Judge {
        now,
        threshold_days: 7,
        device: None,
        volume: None,
    };
    let mut remove = disk_remover(judge, &store);

    let first = remove(&row).expect_err("its git index was written just now");
    assert!(
        first.to_string().contains("its git index was written"),
        "the tab is beside it: {first}"
    );
    crate::term_lock(&term).process(report(&checkout).as_bytes());
    let then = remove(&row).expect_err("a session works in it");
    assert!(
        then.to_string().contains("a session works in"),
        "the tab moved in: {then}"
    );
}

#[test]
fn an_emergency_the_bytes_do_not_explain_is_out_of_inodes() {
    use aterm_agent::harness::disk::{Config, Level};
    let t = Config::default().thresholds(Some(1u64 << 40));
    let off = DiskFullCause::CleanupOff { fault: false };
    assert_eq!(t.level(Some(t.emergency), Some(0)), Level::Emergency);
    assert_eq!(
        disk_full_cause(&t, Some(t.emergency), off),
        DiskFullCause::Inodes
    );
    assert_eq!(t.level(None, Some(0)), Level::Emergency);
    assert_eq!(disk_full_cause(&t, None, off), DiskFullCause::Inodes);
    assert_eq!(disk_full_cause(&t, Some(t.emergency - 1), off), off);
    assert_eq!(
        disk_full_cause(&t, Some(0), DiskFullCause::Private(DiskPrivate::StateRoot)),
        DiskFullCause::Private(DiskPrivate::StateRoot)
    );
}

#[test]
fn an_emergency_pass_that_freed_nothing_backs_off_until_the_disk_changes() {
    use aterm_agent::harness::disk::Level;
    let t0 = Instant::now();
    let minute = Duration::from_secs(60);
    let free = Some(2u64 << 30);
    let mut last = None;
    assert!(
        disk_pass_due(&mut last, t0, Level::Short, free, false, 0),
        "first"
    );

    last = Some(DiskPass {
        at: t0,
        free,
        fruitless: false,
        level: Level::Short,
        low_every: DISK_LOW_EVERY,
    });
    assert!(!disk_pass_due(
        &mut last,
        t0 + minute,
        Level::Short,
        free,
        false,
        0
    ));
    assert!(
        disk_pass_due(&mut last, t0 + minute, Level::Short, free, true, 0),
        "poked"
    );
    assert!(disk_pass_due(
        &mut last,
        t0 + minute,
        Level::Emergency,
        free,
        false,
        0
    ));

    last = Some(DiskPass {
        at: t0,
        free,
        fruitless: true,
        level: Level::Emergency,
        low_every: DISK_LOW_EVERY,
    });
    assert!(!disk_pass_due(
        &mut last,
        t0 + minute,
        Level::Emergency,
        free,
        false,
        0
    ));
    assert!(
        !disk_pass_due(&mut last, t0 + minute, Level::Emergency, free, true, 0),
        "a poke"
    );
    let slightly = free.map(|f| f - (DISK_EMERGENCY_DROP / 2));
    assert!(!disk_pass_due(
        &mut last,
        t0 + minute,
        Level::Emergency,
        slightly,
        false,
        0
    ));
    let fell = free.map(|f| f - 2 * DISK_EMERGENCY_DROP);
    assert!(
        disk_pass_due(&mut last, t0 + minute, Level::Emergency, fell, false, 0),
        "fell"
    );
    assert!(
        disk_pass_due(
            &mut last,
            t0 + DISK_PASS_EVERY,
            Level::Emergency,
            free,
            false,
            0
        ),
        "the interval"
    );
    assert!(!disk_pass_due(
        &mut last,
        t0 + minute,
        Level::Short,
        free,
        false,
        0
    ));
    assert!(disk_pass_due(
        &mut last,
        t0 + minute,
        Level::Emergency,
        free,
        false,
        0
    ));
}

#[test]
fn at_low_a_pass_runs_hourly_and_backs_off_while_fruitless() {
    use aterm_agent::harness::disk::Level;
    let t0 = Instant::now();
    let minute = Duration::from_secs(60);
    let room = 40u64 << 30;
    let free = Some(50u64 << 30);
    let at_low = |at, low_every| {
        Some(DiskPass {
            at,
            free,
            fruitless: false,
            level: Level::Low,
            low_every,
        })
    };
    assert!(!disk_pass_due(&mut None, t0, Level::Ok, free, true, room));
    assert!(!disk_pass_due(
        &mut None,
        t0,
        Level::Unknown,
        free,
        true,
        room
    ));
    assert!(
        disk_pass_due(&mut None, t0, Level::Low, free, false, room),
        "first"
    );
    let mut last = at_low(t0, DISK_LOW_EVERY);
    assert!(!disk_pass_due(
        &mut last,
        t0 + 10 * minute,
        Level::Low,
        free,
        false,
        room
    ));
    assert!(disk_pass_due(
        &mut last,
        t0 + 10 * minute,
        Level::Short,
        free,
        false,
        room
    ));
    assert!(disk_pass_due(
        &mut last,
        t0 + DISK_LOW_EVERY,
        Level::Low,
        free,
        false,
        room
    ));
    assert!(
        disk_pass_due(&mut last, t0 + minute, Level::Low, free, true, room),
        "a poke"
    );
    let fell = free.map(|f| f - room / 4 - 1);
    assert!(
        disk_pass_due(&mut last, t0 + minute, Level::Low, fell, false, room),
        "fell"
    );
    let mut from_short = Some(DiskPass {
        level: Level::Short,
        ..at_low(t0, DISK_LOW_EVERY).expect("pass")
    });
    assert!(disk_pass_due(
        &mut from_short,
        t0 + minute,
        Level::Low,
        free,
        false,
        room
    ));

    let mut every = DISK_LOW_EVERY;
    for _ in 0..6 {
        every = disk_low_every(Level::Low, false, at_low(t0, every).as_ref());
    }
    assert_eq!(every, DISK_LOW_EVERY_MAX);
    assert_eq!(
        disk_low_every(Level::Low, false, at_low(t0, DISK_LOW_EVERY).as_ref()),
        DISK_LOW_EVERY * 2
    );
    assert_eq!(
        disk_low_every(Level::Low, true, at_low(t0, DISK_LOW_EVERY_MAX).as_ref()),
        DISK_LOW_EVERY
    );
    let mut backed = at_low(t0, DISK_LOW_EVERY * 4);
    assert!(!disk_pass_due(
        &mut backed,
        t0 + DISK_LOW_EVERY * 2,
        Level::Low,
        free,
        false,
        room
    ));
    assert!(disk_pass_due(
        &mut backed,
        t0 + DISK_LOW_EVERY * 4,
        Level::Low,
        free,
        false,
        room
    ));
}

#[test]
fn the_sweep_counts_the_bytes_of_what_it_swept() {
    use atpkg::build_cache::Unused;
    let (a, b, kept) = (
        PathBuf::from("/c/a/.cargo-build"),
        PathBuf::from("/c/b/.cargo-build"),
        PathBuf::from("/c/k/.cargo-build"),
    );

    let gone = Unused::Gone {
        idle: Duration::from_secs(15 * 60),
        after: atpkg::build_cache::RECLAIM_GONE_UNDER_PRESSURE,
    };
    let idle = Unused::Idle {
        idle: Duration::from_secs(31 * 86_400),
    };
    let sized = [
        (a.clone(), gone, 3 << 30),
        (b.clone(), idle, 1 << 30),
        (kept, Unused::Unfinished, 7 << 30),
    ];
    let (freed, went) = disk_swept(&[(a, gone), (b, idle)], &sized);
    assert_eq!(freed, 4 << 30);
    assert_eq!(went.len(), 2);
    assert!(
        went[0].contains("/c/a/.cargo-build") && went[0].ends_with("(its workspace is gone)"),
        "{went:?}"
    );
    assert!(
        went[1].contains("/c/b/.cargo-build") && went[1].ends_with("(unwritten 31d)"),
        "{went:?}"
    );
    assert_eq!(disk_swept(&[], &sized).0, 0);

    let stage = PathBuf::from("/c/a/.cargo-build.removing");
    let stale = Unused::Stale {
        incremental: 1,
        units: 1,
        after: atpkg::build_cache::RECLAIM_STALE,
    };
    let sized = [
        (stage.clone(), Unused::Unfinished, 2 << 30),
        (stage.clone(), stale, 5 << 30),
    ];
    let swept = [(stage.clone(), Unused::Unfinished), (stage, stale)];
    assert_eq!(disk_swept(&swept, &sized).0, 7 << 30);
    assert_eq!(
        disk_sweep_removals(&swept, &sized),
        [
            (2 << 30, crate::disk_board::BUILD_CACHES),
            (5 << 30, crate::disk_board::BUILD_CACHES)
        ]
    );
}

#[test]
fn each_removal_row_gives_the_freed_tally_one_entry() {
    use aterm_agent::harness::cli::DiskTick;
    use aterm_agent::harness::disk::{Applied, Class, Removed, Row, Witness};
    use atpkg::build_cache::Unused;
    let (a, b, never_sized, kept) = (
        PathBuf::from("/c/a/.cargo-build"),
        PathBuf::from("/c/b/.cargo-build"),
        PathBuf::from("/c/u/.cargo-build"),
        PathBuf::from("/c/k/.cargo-build"),
    );
    let sized = [
        (a.clone(), Unused::Unfinished, 3 << 30),
        (b.clone(), Unused::Unfinished, 1 << 30),
        (kept, Unused::Unfinished, 7 << 30),
    ];
    let swept = [
        (a, Unused::Unfinished),
        (never_sized, Unused::Unfinished),
        (b, Unused::Unfinished),
    ];
    assert_eq!(
        disk_sweep_removals(&swept, &sized),
        [
            (3 << 30, crate::disk_board::BUILD_CACHES),
            (0, crate::disk_board::BUILD_CACHES),
            (1 << 30, crate::disk_board::BUILD_CACHES),
        ]
    );
    assert!(disk_sweep_removals(&[], &sized).is_empty());

    let row = |path: &str| Row {
        class: Class::CargoTargets,
        path: PathBuf::from(path),
        bytes: 9 << 30,
        bytes_partial: false,
        witness: Witness::StaleBuildDir {
            marker: "CACHEDIR.TAG".to_string(),
            profiles: 1,
            idle_days: 9,
            threshold_days: 7,
            leaves: Vec::new(),
        },
        removable: true,
        blocked: None,
    };
    let released = |bytes: u64| Removed {
        bytes,
        ..Removed::default()
    };
    let tick = DiskTick::Reclaimed(
        Applied {
            removed: vec![
                (row("/w/one/target"), released(5 << 30)),
                (row("/w/two/target"), released(0)),
            ],
            freed_bytes: 5 << 30,
            ..Applied::default()
        },
        Vec::new(),
    );
    assert_eq!(
        disk_pass_removals(&tick),
        [
            (5 << 30, crate::disk_board::BUILD_CACHES),
            (0, crate::disk_board::BUILD_CACHES),
        ]
    );
    assert!(disk_pass_removals(&DiskTick::Plenty).is_empty());
}

#[test]
fn a_pass_whose_removals_went_unrecorded_is_not_spent() {
    use aterm_agent::harness::cli::DiskTick;
    use aterm_agent::harness::disk::{Applied, Refusal};
    let tick = |denials: Vec<Refusal>| {
        DiskTick::Reclaimed(
            Applied {
                denials,
                ..Applied::default()
            },
            Vec::new(),
        )
    };
    let cache = PathBuf::from("/Users//x/src/w/target");
    assert_eq!(
        pass_cause(&tick(vec![
            Refusal::RemoveFailed(cache.clone(), "busy".to_string()),
            Refusal::Unjournalled(cache.clone()),
        ])),
        DiskFullCause::Unrecorded
    );
    assert_eq!(
        pass_cause(&tick(vec![Refusal::RemoveFailed(
            cache,
            "busy".to_string()
        )])),
        DiskFullCause::Spent
    );
    assert_eq!(pass_cause(&tick(Vec::new())), DiskFullCause::Spent);
    assert_eq!(pass_cause(&DiskTick::Plenty), DiskFullCause::Spent);
}

/// Every intent of the no-session sweep has its outcome on record.
#[cfg(unix)]
#[test]
fn the_sweep_journals_a_finished_stage_and_counts_it() {
    use atpkg::build_cache::Unused;
    let tmp = aterm_tempfile::Builder::new()
        .prefix("aterm-sweep-stage-")
        .tempdir()
        .expect("temp dir");
    let root = tmp.path().join("cache");
    let stage = root.join("Users/x/gone/.cargo-build.removing");
    std::fs::create_dir_all(stage.join("debug")).unwrap();
    std::fs::write(stage.join("debug/x"), vec![7u8; 4096]).unwrap();
    let board = Shelf::new();
    let sweep = |state: &Path| {
        disk_sweep_journalled(state, 1_790_000_000, &board, |record| {
            atpkg::build_cache::reclaim_watched(
                &root,
                None,
                std::time::SystemTime::now(),
                atpkg::build_cache::RECLAIM_GONE_UNDER_PRESSURE,
                None,
                record,
            )
        })
    };

    let blocked = tmp.path().join("blocked");
    std::fs::write(&blocked, b"").unwrap();
    let kept = sweep(&blocked);
    assert!(kept.swept.is_empty() && kept.sized.is_empty() && kept.unrecorded);
    assert!(stage.join("debug/x").is_file(), "kept whole");
    assert_eq!(board.board_lock().freed.aterm_bytes, 0);

    let state = tmp.path().join("state");
    let done = sweep(&state);
    assert_eq!(done.swept, vec![(stage.clone(), Unused::Unfinished)]);
    assert!(!done.unrecorded);
    assert!(!stage.exists());
    let (freed, went) = disk_swept(&done.swept, &done.sized);
    assert!(freed >= 4096, "{freed}");
    assert!(
        went[0].ends_with("(left half-removed by an earlier sweep)"),
        "{went:?}"
    );
    {
        let b = board.board_lock();
        assert_eq!(
            (b.freed.aterm_bytes, b.freed.last_what.as_str()),
            (freed, "build caches")
        );
    }
    let ledger = std::fs::read_to_string(state.join(aterm_agent::harness::cli::DISK_LEDGER))
        .expect("the ledger");
    let actions: Vec<(String, String)> = ledger
        .lines()
        .map(|l| {
            let v: aterm_json::Value = aterm_json::from_str(l).expect("a row");
            (
                v["action"].as_str().unwrap_or_default().to_string(),
                v["path"].as_str().unwrap_or_default().to_string(),
            )
        })
        .collect();
    let path = stage.display().to_string();
    assert_eq!(
        actions,
        vec![
            ("removing".to_string(), path.clone()),
            ("removed".to_string(), path)
        ]
    );
}

/// The hosted loop presents the harness's in-memory token, so what it types and marks reads
/// `by=harness`.
#[cfg(unix)]
#[test]
fn the_hosted_loop_presents_the_in_memory_token_and_falls_back_beside() {
    use std::io::{BufRead, BufReader};
    let harness = crate::control_auth::harness_token().expect("entropy");
    let dir_guard = crate::test_scratch::short_dir("the token server's socket");
    let dir = dir_guard.path().to_path_buf();
    let sock = dir.join("a.sock");
    let names = aterm_types::control_socket::token_names_for_sock("a.sock");
    std::fs::write(dir.join(&names[0]), "beside\n").unwrap();
    let listener = std::os::unix::net::UnixListener::bind(&sock).unwrap();
    let path = sock.to_string_lossy().into_owned();
    let h = std::thread::spawn(move || {
        let mut seen: Vec<(String, String)> = Vec::new();
        for refuse in [false, true, false] {
            let Ok((stream, _)) = listener.accept() else {
                break;
            };
            let mut w = stream.try_clone().unwrap();
            let mut r = BufReader::new(stream);
            let mut auth = String::new();
            let _ = r.read_line(&mut auth);
            let token = auth.trim_end().trim_start_matches("AUTH ").to_string();
            loop {
                let mut line = String::new();
                if r.read_line(&mut line).unwrap_or(0) == 0 {
                    break;
                }
                seen.push((token.clone(), line.trim_end().to_string()));
                if refuse {
                    let _ = w.write_all(b"ERR auth\n");
                    break;
                }
                let _ = w.write_all(b"OK\n");
            }
        }
        seen
    });
    let mut ctl = HostCtl::as_harness(Endpoint::Socket(path.clone()));
    assert!(ctl.call(&["@s-h", "status"]).unwrap().ok());
    drop(ctl);
    let mut ctl = HostCtl::as_harness(Endpoint::Socket(path));
    let landed = ctl.call(&["@s-h", "send", "x"]).unwrap();
    assert!(landed.ok(), "{landed:?}");
    drop(ctl);
    let seen = h.join().unwrap();
    assert_eq!(
        seen,
        vec![
            (harness.to_string(), "@s-h status".to_string()),
            (harness.to_string(), "@s-h send x".to_string()),
            ("beside".to_string(), "@s-h send x".to_string()),
        ]
    );
}

/// The window's disk resume types through the harness's in-memory token, probed with `version`,
/// so its carry-on reads `by=harness` ([`live_acts`]' `disk_resume`).
#[cfg(unix)]
#[test]
fn the_windows_disk_resume_presents_the_in_memory_token() {
    use std::io::{BufRead, BufReader};
    let harness = crate::control_auth::harness_token().expect("entropy");
    let dir_guard = crate::test_scratch::short_dir("the disk resume's socket");
    let dir = dir_guard.path().to_path_buf();
    let sock = dir.join("a.sock");
    let names = aterm_types::control_socket::token_names_for_sock("a.sock");
    std::fs::write(dir.join(&names[0]), "beside\n").unwrap();
    let listener = std::os::unix::net::UnixListener::bind(&sock).unwrap();
    let path = sock.to_string_lossy().into_owned();
    let (tx, rx) = std::sync::mpsc::channel();
    std::thread::spawn(move || {
        let mut seen: Vec<(String, String)> = Vec::new();
        let Ok((stream, _)) = listener.accept() else {
            return;
        };
        let mut w = stream.try_clone().unwrap();
        let mut r = BufReader::new(stream);
        let mut auth = String::new();
        let _ = r.read_line(&mut auth);
        let token = auth.trim_end().trim_start_matches("AUTH ").to_string();
        loop {
            let mut line = String::new();
            if r.read_line(&mut line).unwrap_or(0) == 0 {
                break;
            }
            let line = line.trim_end().to_string();
            let reply: &[u8] = if line.contains(" lease acquire ") {
                b"ERR busy\n"
            } else {
                b"OK\n"
            };
            seen.push((token.clone(), line));
            let _ = w.write_all(reply);
        }
        let _ = tx.send(seen);
    });
    let acts = live_acts(crate::session_store::new_store(), path);
    assert_eq!((acts.disk_resume)("s-d", "carry on"), "wait:held");
    drop(acts);
    let seen = rx
        .recv_timeout(aterm_spec::wait::MUST_HAPPEN)
        .expect("the resume's one connection ended");
    assert_eq!(
        seen,
        vec![
            (harness.to_string(), "version".to_string()),
            (
                harness.to_string(),
                format!("@s-d {}", upgrade_drive::hand_take_request())
            ),
        ]
    );
}

/// The window's sweeps (the lanes' acts, [`live_acts`], and the owner's view,
/// [`window_drive_opts`]) present the harness's in-memory token on its own socket, never the token
/// beside it; the word writer ([`crate::upgrade_host::word_writer_at`]) dials no socket.
#[cfg(unix)]
#[test]
fn the_windows_sweeps_present_the_in_memory_token_on_its_own_socket() {
    use std::io::{BufRead, BufReader};
    let harness = crate::control_auth::harness_token().expect("entropy");
    let dir_guard = crate::test_scratch::short_dir("the sweeps' socket");
    let dir = dir_guard.path().to_path_buf();
    let sock = dir.join("a.sock");
    let names = aterm_types::control_socket::token_names_for_sock("a.sock");
    std::fs::write(dir.join(&names[0]), "beside\n").unwrap();
    let listener = std::os::unix::net::UnixListener::bind(&sock).unwrap();
    let path = sock.to_string_lossy().into_owned();
    let (tx, rx) = std::sync::mpsc::channel();
    std::thread::spawn(move || {
        let mut seen: Vec<(String, String)> = Vec::new();
        while let Ok((stream, _)) = listener.accept() {
            let mut w = stream.try_clone().unwrap();
            let mut r = BufReader::new(stream);
            let mut auth = String::new();
            let _ = r.read_line(&mut auth);
            let token = auth.trim_end().trim_start_matches("AUTH ").to_string();
            if token == "stop" {
                break;
            }
            loop {
                let mut line = String::new();
                if r.read_line(&mut line).unwrap_or(0) == 0 {
                    break;
                }
                let line = line.trim_end().to_string();
                let reply: &[u8] = if line == "version" {
                    b"OK\n"
                } else {
                    b"ERR busy\n"
                };
                seen.push((token.clone(), line));
                let _ = w.write_all(reply);
            }
        }
        let _ = tx.send(seen);
    });
    let (home, state) = (dir.join("home"), dir.join("state"));
    std::fs::create_dir_all(&home).unwrap();
    std::fs::create_dir_all(&state).unwrap();
    let acts = with_harness_state(&state, || {
        live_acts(crate::session_store::new_store(), path.clone())
    });
    assert!((acts.snapshot)("s-a").is_none(), "no roster, no snapshot");
    drop(acts);
    let mut view = upgrade_drive::View::default();
    let _ = view.refresh(
        &window_drive_opts(home, state, Some(path.clone())),
        &mut |_: &[upgrade_drive::Row]| {},
    );
    let mut stop = std::os::unix::net::UnixStream::connect(&path).expect("the server");
    stop.write_all(b"AUTH stop\n").expect("stop");
    drop(stop);
    let seen = rx
        .recv_timeout(aterm_spec::wait::MUST_HAPPEN)
        .expect("the server read every connection");
    let pair = |l: &str| (harness.to_string(), l.to_string());
    assert_eq!(
        seen,
        vec![pair("version"), pair("who"), pair("version"), pair("who")],
        "the acts' look, then the view's, each on the harness's token"
    );
}

#[test]
fn a_vendor_codex_is_shown_and_admitted_to_no_worker() {
    use crate::session_timeline::claim_supervisor_as;
    let store = crate::session_store::new_store();
    let me = std::process::id();
    let group = i32::try_from(me).unwrap();
    let register = |n: u64, name: &str| {
        let handle = crate::session_store::test_handle(9100 + n);
        let sid = handle.sid.as_str().to_string();
        let ctx = Arc::clone(&handle.ctx);
        {
            let mut tl = ctx.timeline.lock().unwrap();
            tl.note_foreground_group(group);
            tl.set_program(group, Some(name.to_string()));
        }
        store.write().unwrap().register(handle);
        (sid, ctx)
    };
    let (vendor, vendor_ctx) = register(1, "codex");
    let (proven, proven_ctx) = register(2, "codex");
    let (copied, copied_ctx) = register(3, "codex");
    let (alab, alab_ctx) = register(4, "codex");
    let (claude, claude_ctx) = register(5, "claude");
    let (unproven, unproven_ctx) = register(6, "codex");
    let (other_copy, other_copy_ctx) = register(7, "codex");
    let (other_group, other_group_ctx) = register(8, "codex");
    let now = crate::metrics::now_us();
    claim_supervisor_as(
        &proven_ctx,
        &format!("codex-alab@{me}"),
        Some(1),
        None,
        Some(crate::self_claim::Proven {
            pid: me,
            start: "a test identity".to_string(),
        }),
        now,
        aterm_slog::Actor::Ctl,
    )
    .expect("the proven claim");
    claim_supervisor_as(
        &unproven_ctx,
        &format!("codex-alab@{me}"),
        Some(2),
        None,
        None,
        now,
        aterm_slog::Actor::Ctl,
    )
    .expect("an ordinary claim");
    let copy = |pid: u32| aterm_agent::harness::self_claimed::Copy {
        pid,
        start: "a test identity".to_string(),
        home: PathBuf::from("/"),
        seen: aterm_agent::harness::self_claimed::Seen::Removed,
        resume: Err("no-record"),
    };
    crate::self_claim::set_copy_for_test(&copied, Some(copy(me)));
    crate::self_claim::set_copy_for_test(&other_copy, Some(copy(me + 1)));
    let here = aterm_uds::sudo::exe_path(group);
    ALAB_IMAGES.lock().unwrap().insert(
        alab.clone(),
        AlabImage {
            group,
            exe: here.clone(),
            alab: true,
        },
    );
    ALAB_IMAGES.lock().unwrap().insert(
        other_group.clone(),
        AlabImage {
            group: group + 1,
            exe: here,
            alab: true,
        },
    );
    assert_eq!(admitted(&vendor_ctx), None, "nothing read yet");
    let roster: HashMap<String, (Program, FollowStamp)> = roster_of(&store)
        .into_iter()
        .map(|(sid, agent, stamp)| (sid, (agent, stamp)))
        .collect();
    let stamped = |sid: &str| roster.get(sid).map(|(agent, stamp)| (*agent, stamp.vendor));
    for (sid, ctx, want) in [
        (&vendor, &vendor_ctx, None),
        (&proven, &proven_ctx, Some(Program::Codex)),
        (&copied, &copied_ctx, Some(Program::Codex)),
        (&alab, &alab_ctx, Some(Program::Codex)),
        (&claude, &claude_ctx, Some(Program::Claude)),
        (&unproven, &unproven_ctx, None),
        (&other_copy, &other_copy_ctx, None),
    ] {
        let identity = agent_of(ctx.timeline.lock().unwrap().agent());
        assert!(identity.is_some(), "{sid}: an agent by its name");
        assert_eq!(admitted(ctx), want, "{sid}: admitted");
        assert_eq!(
            stamped(sid),
            Some((identity.unwrap(), want.is_none())),
            "{sid}: the roster's stamp"
        );
        let (agent, stamp) = roster[sid.as_str()];
        assert_eq!(
            admits(agent, stamp),
            want.is_some(),
            "{sid}: the host's gate"
        );
    }
    assert_eq!(stamped(&other_group), Some((Program::Codex, true)));
    assert_eq!(admitted(&other_group_ctx), None);
    for sid in [&copied, &other_copy] {
        crate::self_claim::set_copy_for_test(sid, None);
    }
    let mut images = ALAB_IMAGES.lock().unwrap();
    for sid in [
        &vendor,
        &proven,
        &copied,
        &alab,
        &unproven,
        &other_copy,
        &other_group,
    ] {
        images.remove(sid.as_str());
    }
}

#[test]
fn a_groups_image_is_read_again_when_its_leader_execs() {
    let sid = "s-alab-exec";
    let group = i32::try_from(std::process::id()).expect("a pid");
    let script = PathBuf::from("/Users//me/.aterm/agents/codex");
    let binary = PathBuf::from("/Users//me/.aterm/store/codex/0.163.0-alab.1/bin/codex");
    let led_by = |exe: &PathBuf| {
        let exe = exe.clone();
        move |_pid: u32| Some(exe.clone())
    };
    assert!(!alab_image_by(
        sid,
        group,
        super::Probe::Read,
        &led_by(&script)
    ));
    ALAB_IMAGES.lock().unwrap().insert(
        sid.to_string(),
        AlabImage {
            group,
            exe: Some(binary.clone()),
            alab: true,
        },
    );
    assert!(
        alab_image_by(sid, group, super::Probe::Read, &led_by(&binary)),
        "the same image keeps its read"
    );
    let other = PathBuf::from("/nowhere/codex");
    assert!(!alab_image_by(
        sid,
        group,
        super::Probe::Read,
        &led_by(&other)
    ));
    assert_eq!(
        ALAB_IMAGES.lock().unwrap().get(sid).map(|r| r.exe.clone()),
        Some(Some(other)),
        "the new image's read is kept"
    );
    assert!(!alab_image_by(sid, group, super::Probe::Cached, &|_| {
        panic!("a frame reads no image")
    }));
    ALAB_IMAGES.lock().unwrap().remove(sid);
}

#[test]
fn a_codex_worker_is_parked_for_no_upgrade_and_relaunched_by_no_lane() {
    let a = Arc::new(Acting::default());
    a.due.store(true, Ordering::SeqCst);
    let hooks = a.hooks();
    let job = |agent: Program| WorkerJob {
        revoked: Arc::default(),
        sid: "s-k".to_string(),
        agent,
        opts: SuperviseOpts::hosted(),
        stop: Arc::new(AtomicBool::new(true)),
        interrupt: Arc::default(),
        handover: Arc::default(),
        clear_badge: false,
        unset_mark: false,
        faults: Arc::default(),
        park: Arc::default(),
        look_at: Arc::default(),
        left: Arc::new(ExitWord::handed()),
        acting: Arc::default(),
        switches: {
            let s = Arc::new(Switches::default());
            s.set(&on(), false);
            s
        },
        kept: Arc::default(),
        note: Arc::default(),
        group: Arc::default(),
        host: std::sync::Weak::new(),
        watch_until: None,
        beside: Arc::default(),
        left_at_commit: Arc::default(),
    };
    a.set(&[("s-k", Program::Codex)]);
    let codex = job(Program::Codex);
    attach(&codex, &hooks);
    assert!(
        !codex.park.load(Ordering::SeqCst),
        "due: never parked for a step"
    );
    assert!(with_kept(&codex, |k| k.snapshot.is_some()), "its run read");
    assert_eq!(
        codex.watch_beside().as_deref(),
        Some(UNCLAIMED_CODEX_ALAB),
        "its loop watches beside the agent itself"
    );
    let other = job(Program::Generic);
    attach(&other, &hooks);
    assert!(!other.park.load(Ordering::SeqCst), "not written for it");
    assert!(with_kept(&other, |k| k.snapshot.is_none()), "nothing read");
    a.set(&[]);
    on_agent_left(&codex, &hooks);
    assert!(
        a.relaunched.lock().unwrap().is_empty(),
        "no lane's relaunch"
    );
    assert_eq!(
        a.notes
            .lock()
            .unwrap()
            .iter()
            .filter(|n| matches!(n, HostNote::Inform { .. }))
            .count(),
        1,
        "said once"
    );
    assert!(
        a.badges.lock().unwrap().iter().all(Option::is_none),
        "nothing marked: {:?}",
        a.badges.lock().unwrap()
    );
    a.set(&[("s-k", Program::Claude)]);
    let claude = job(Program::Claude);
    attach(&claude, &hooks);
    assert!(claude.park.load(Ordering::SeqCst), "due: parked for");
    assert_eq!(claude.watch_beside(), None, "it is supervised");
    a.set(&[]);
    on_agent_left(&claude, &hooks);
    assert_eq!(*a.relaunched.lock().unwrap(), ["s-k"]);
}

#[test]
fn a_self_supervised_crash_no_snapshot_read_reached_is_relaunched_at_the_tabs_shell() {
    let line = vec![
        "/u/.aterm/agents/codex".to_string(),
        "resume".to_string(),
        "0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string(),
    ];
    let dead = gone_pid();
    let run = |sid: &str, shell: Option<u32>| {
        let a = Arc::new(Acting::default());
        a.unreadable.store(true, Ordering::SeqCst);
        a.open.lock().unwrap().insert(sid.to_string());
        if let Some(shell) = shell {
            a.self_shells.lock().unwrap().insert(sid.to_string(), shell);
        }
        a.set(&[(sid, Program::Codex)]);
        let copy = self_copy(&a, sid, self_claimed::Seen::Never, Ok(line.clone()));
        a.self_copies.lock().unwrap().insert(sid.to_string(), copy);
        let host = HostHandle::start(on(), false, false, a.hooks());
        until("attached", || host.live() == [sid]);
        a.claims
            .lock()
            .unwrap()
            .insert(sid.to_string(), format!("codex-alab@{dead}"));
        a.proven.lock().unwrap().insert(sid.to_string());
        a.set(&[]);
        until("the exit decided", || {
            !a.self_relaunched.lock().unwrap().is_empty()
                || a.notes
                    .lock()
                    .unwrap()
                    .iter()
                    .any(|n| matches!(n, HostNote::Inform { .. }))
        });
        host.shutdown_and_join();
        a
    };
    let a = run("s-selfclaim-unread", Some(4141));
    assert_eq!(
        a.self_relaunched.lock().unwrap().as_slice(),
        [("s-selfclaim-unread".to_string(), line.clone(), None)],
        "relaunched on its copy's line at the shell holding its tab"
    );
    let a = run("s-selfclaim-unread-noshell", None);
    assert!(a.self_relaunched.lock().unwrap().is_empty());
    let said: Vec<String> = a
        .notes
        .lock()
        .unwrap()
        .iter()
        .filter_map(|n| match n {
            HostNote::Inform { text, .. } => Some(text.clone()),
            _ => None,
        })
        .collect();
    assert!(
        said.len() == 1 && said[0].contains("no shell to start it again at"),
        "said once: {said:?}"
    );
}

#[test]
fn an_unread_initial_record_relaunches_only_with_its_validated_line_and_shell() {
    // The copy validates an absolute launch path: Windows' names a drive.
    let launch = if cfg!(windows) {
        "C:\\u\\.aterm\\agents\\codex"
    } else {
        "/u/.aterm/agents/codex"
    };
    let line = vec![
        launch.to_string(),
        "resume".to_string(),
        "0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string(),
    ];
    let dead = gone_pid();
    let run = |sid: &str, shell: Option<u32>, typed: bool| {
        let a = Arc::new(Acting::default());
        a.unreadable.store(true, Ordering::SeqCst);
        a.open.lock().unwrap().insert(sid.to_string());
        if let Some(shell) = shell {
            a.self_shells.lock().unwrap().insert(sid.to_string(), shell);
        }
        a.set(&[(sid, Program::Codex)]);
        let base = self_copy(&a, sid, self_claimed::Seen::Never, Ok(line.clone()));
        let live = self_claimed::Live {
            exec_path: line[0].clone(),
            image: Some(line[0].clone().into()),
            argv: line.clone(),
            codex_home: None,
            cwd: None,
            twin: None,
            managed_launch: None,
        };
        let initial = format!(
            r#"{{"v":1,"pid":{},"sessionId":null,"resumeArgv":null,"cwd":null,"state":null,"status":"busy","exit":null,"draftEmpty":true}}"#,
            base.pid
        );
        let copy = self_claimed::copy_of(
            base.pid,
            &base.start,
            base.home.clone(),
            Some(&initial),
            &live,
            typed.then(|| base.resume.as_ref().unwrap()),
        );
        a.self_copies.lock().unwrap().insert(sid.to_string(), copy);
        let host = HostHandle::start(on(), false, false, a.hooks());
        until("attached", || host.live() == [sid]);
        a.claims
            .lock()
            .unwrap()
            .insert(sid.to_string(), format!("codex-alab@{dead}"));
        a.proven.lock().unwrap().insert(sid.to_string());
        a.set(&[]);
        until("the exit decided", || {
            !a.self_relaunched.lock().unwrap().is_empty()
                || a.notes
                    .lock()
                    .unwrap()
                    .iter()
                    .any(|n| matches!(n, HostNote::Inform { .. }))
        });
        host.shutdown_and_join();
        a
    };
    let a = run("s-initial-lined-shell", Some(4141), true);
    assert_eq!(
        *a.self_relaunched.lock().unwrap(),
        [("s-initial-lined-shell".to_string(), line.clone(), None)]
    );
    for (sid, shell, typed, reason) in [
        ("s-initial-lined-noshell", None, true, "no shell"),
        ("s-initial-unlined-shell", Some(4141), false, "resume line"),
    ] {
        let a = run(sid, shell, typed);
        assert!(a.self_relaunched.lock().unwrap().is_empty());
        let notes = a.notes.lock().unwrap();
        let said: Vec<&str> = notes
            .iter()
            .filter_map(|n| match n {
                HostNote::Inform { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect();
        assert!(said.len() == 1 && said[0].contains(reason), "{said:?}");
        if !typed {
            assert!(
                !said[0].contains("no shell"),
                "the line failed before shell lookup"
            );
        }
    }
}

#[test]
fn a_self_claimed_crash_is_relaunched_only_from_its_own_processs_snapshot() {
    let a = Acting::default();
    let sid = "s-own-snapshot";
    let line = vec![
        "/u/.aterm/agents/codex".to_string(),
        "resume".to_string(),
        "0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string(),
    ];
    let stale = Snapshot {
        pid: 84851,
        start: "1792274666.100000".to_string(),
        shell: 4141,
        ..snap(sid)
    };
    let copy = self_claimed::Copy {
        pid: 85878,
        start: "1792274879.300000".to_string(),
        ..self_copy(&a, sid, standing_record(), Ok(line))
    };
    let fresh = Snapshot {
        pid: copy.pid,
        start: copy.start.clone(),
        ..stale.clone()
    };
    let before_the_fix = |snap: Option<Snapshot>| snap.filter(|snap| snap.shell != 0);
    assert_eq!(
        before_the_fix(Some(stale.clone())),
        Some(stale.clone()),
        "NEGATIVE CONTROL: the old filter relaunched the crashed process's snapshot"
    );
    assert_eq!(
        crash_snapshot(Some(stale), &copy),
        None,
        "another process's snapshot is refused"
    );
    assert_eq!(
        crash_snapshot(Some(fresh.clone()), &copy),
        Some(fresh.clone()),
        "the crashed process's own is relaunched from"
    );
    let reused = Snapshot {
        start: "1792274999.000000".to_string(),
        ..fresh.clone()
    };
    assert_eq!(crash_snapshot(Some(reused), &copy), None);
    assert_eq!(
        crash_snapshot(Some(Snapshot { shell: 0, ..fresh }), &copy),
        None
    );
    assert_eq!(crash_snapshot(None, &copy), None);
}

#[test]
fn a_relaunched_codex_alab_that_crashes_before_any_read_is_relaunched_on_its_own_copy() {
    let first = vec![
        "/u/.aterm/agents/codex".to_string(),
        "resume".to_string(),
        "0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string(),
    ];
    let second = vec![
        "/u/.aterm/agents/codex".to_string(),
        "--search".to_string(),
        "resume".to_string(),
        "0199f2a4-6c1e-7a52-9d3b-2f6c8e1a4b77".to_string(),
    ];
    let dead = gone_pid();
    let run = |sid: &str, landed: Option<self_claimed::Copy>| {
        let a = Arc::new(Acting::default());
        a.open.lock().unwrap().insert(sid.to_string());
        a.self_shells.lock().unwrap().insert(sid.to_string(), 4141);
        a.set(&[(sid, Program::Codex)]);
        let copy = self_copy(&a, sid, standing_record(), Ok(first.clone()));
        a.self_copies.lock().unwrap().insert(sid.to_string(), copy);
        a.self_landed_unread.lock().unwrap().push_back(landed);
        let host = HostHandle::start(on(), false, false, a.hooks());
        a.attached(&host, sid);
        until("its snapshot published", || {
            crate::harness_host::published_snapshot(sid).is_some()
        });
        a.claims
            .lock()
            .unwrap()
            .insert(sid.to_string(), format!("codex-alab@{dead}"));
        a.proven.lock().unwrap().insert(sid.to_string());
        a.set(&[]);
        until("both exits decided", || {
            a.self_relaunched.lock().unwrap().len() >= 2
                || a.notes
                    .lock()
                    .unwrap()
                    .iter()
                    .any(|n| matches!(n, HostNote::Inform { .. }))
        });
        a.passes();
        host.shutdown_and_join();
        a
    };
    let relaunched = self_claimed::Copy {
        pid: dead,
        start: "1792274879.300000".to_string(),
        ..self_copy(
            &Acting::default(),
            "-",
            standing_record(),
            Ok(second.clone()),
        )
    };
    let sid = "s-selfclaim-second-crash";
    let a = run(sid, Some(relaunched));
    assert_eq!(
        a.self_relaunched.lock().unwrap().as_slice(),
        [
            (sid.to_string(), first.clone(), None),
            (sid.to_string(), second.clone(), None),
        ],
        "each crash relaunched once, on its own process's copy: never the first's line again"
    );
    assert!(
        !a.notes
            .lock()
            .unwrap()
            .iter()
            .any(|n| matches!(n, HostNote::Inform { .. })),
        "nothing refused"
    );
    let sid = "s-selfclaim-second-unclaimed";
    let a = run(sid, None);
    assert_eq!(
        a.self_relaunched.lock().unwrap().as_slice(),
        [(sid.to_string(), first.clone(), None)],
        "the first crash's line once, and nothing on it again"
    );
    let said: Vec<String> = a
        .notes
        .lock()
        .unwrap()
        .iter()
        .filter_map(|n| match n {
            HostNote::Inform { text, .. } => Some(text.clone()),
            _ => None,
        })
        .collect();
    assert!(
        said.len() == 1 && said[0].contains("is not relaunched"),
        "said once: {said:?}"
    );
}

#[test]
fn a_codex_alab_end_with_no_copy_is_nobodys() {
    let run = |sid: &str, given_back: bool| {
        let a = Arc::new(Acting::default());
        a.open.lock().unwrap().insert(sid.to_string());
        a.set(&[(sid, Program::Codex)]);
        let host = HostHandle::start(on(), false, false, a.hooks());
        a.attached(&host, sid);
        until("its loop runs beside the agent itself", || {
            a.beside_ran
                .lock()
                .unwrap()
                .iter()
                .any(|(s, beside)| s == sid && beside.as_deref() == Some(UNCLAIMED_CODEX_ALAB))
        });
        if given_back {
            let me = std::process::id();
            a.claims
                .lock()
                .unwrap()
                .insert(sid.to_string(), format!("codex-alab@{me}"));
            a.proven.lock().unwrap().insert(sid.to_string());
            self_claimed(sid, None);
            until("watching beside its proof", || {
                a.beside_ran.lock().unwrap().iter().any(|(s, beside)| {
                    s == sid
                        && beside
                            .as_deref()
                            .is_some_and(|b| b.starts_with("codex-alab@"))
                })
            });
            a.claims.lock().unwrap().remove(sid);
            a.proven.lock().unwrap().remove(sid);
            self_claim_released(sid, true);
            until("its loop runs beside the agent itself again", || {
                a.beside_ran.lock().unwrap().last()
                    == Some(&(sid.to_string(), Some(UNCLAIMED_CODEX_ALAB.to_string())))
            });
        }
        a.set(&[]);
        until("the exit decided, or the lane took it", || {
            a.notes
                .lock()
                .unwrap()
                .iter()
                .any(|n| matches!(n, HostNote::Inform { .. }))
                || !a.relaunched.lock().unwrap().is_empty()
                || a.exit_looks.load(Ordering::SeqCst) > 0
        });
        host.shutdown_and_join();
        a
    };
    for (sid, given_back) in [("s-alab-unclaimed", false), ("s-alab-given-back", true)] {
        let a = run(sid, given_back);
        #[cfg(target_os = "macos")]
        {
            let model = aterm_models_harness::harness_restart_stamp_model();
            let mut before = model.init_state();
            let steps: &[&str] = if given_back {
                &[
                    "IsAlab",
                    "SelfClaimOn",
                    "Copied",
                    "SelfClaimOff",
                    "EndsOtherwise",
                ]
            } else {
                &["IsAlab", "EndsOtherwise"]
            };
            for step in steps {
                assert!(model.fire(step, &mut before), "{step} at {before:?}");
            }
            assert!(!model.action_enabled("Read", &before), "never the lane's");
            let seen = RestartSeen {
                ended: 2,
                read: 2,
                alab: true,
                lane: !a.relaunched.lock().unwrap().is_empty()
                    || a.exit_looks.load(Ordering::SeqCst) > 0,
                ..RestartSeen::default()
            };
            assert!(
                reaches(&model, &before, &project_restart_stamp(&seen), 1),
                "{sid}: {seen:?} from {before:?}"
            );
            let laned = project_restart_stamp(&RestartSeen { lane: true, ..seen });
            assert!(!reaches(&model, &before, &laned, 2), "{laned:?}");
            assert!(!model.check_invariant("NoCodexEndIsTheLanes", &laned));
            let buggy = aterm_spec::interp::with_buggy(&model, 1);
            let mut mutant = before.clone();
            assert!(buggy.fire("ReleaseHandsToLane", &mut mutant));
            assert_eq!(mutant, laned, "the mutant's state is that reader's");
        }
        assert!(
            a.relaunched.lock().unwrap().is_empty(),
            "{sid}: never the lane's relaunch"
        );
        assert!(
            a.self_relaunched.lock().unwrap().is_empty(),
            "{sid}: nor the crash rule's"
        );
        assert_eq!(
            a.exit_looks.load(Ordering::SeqCst),
            0,
            "{sid}: nor the lane's look"
        );
        let said: Vec<String> = a
            .notes
            .lock()
            .unwrap()
            .iter()
            .filter_map(|n| match n {
                HostNote::Inform { text, .. } => Some(text.clone()),
                _ => None,
            })
            .collect();
        assert_eq!(said.len(), 1, "{sid}: said once: {said:?}");
        assert!(said[0].contains("not relaunched"), "{said:?}");
    }
}

#[test]
fn a_codex_sessions_worker_takes_no_step_of_the_upgrade() {
    let a = Arc::new(Acting::default());
    a.due.store(true, Ordering::SeqCst);
    a.set(&[("s-cx", Program::Codex), ("s-cl", Program::Claude)]);
    let host = HostHandle::start(on(), false, false, a.hooks());
    until("both attached", || a.runs.load(Ordering::SeqCst) == 2);
    host.note_activation();
    until("the Claude Code stepped", || {
        a.stepped.load(Ordering::SeqCst) >= 1
    });
    assert!(
        a.beside_ran
            .lock()
            .unwrap()
            .iter()
            .any(|(s, beside)| s == "s-cx" && beside.as_deref() == Some(UNCLAIMED_CODEX_ALAB)),
        "the Codex's loop watches beside the agent itself"
    );
    host.shutdown_and_join();
    let stepped = a.stepped_for.lock().unwrap().clone();
    assert!(
        !stepped.is_empty() && stepped.iter().all(|sid| sid == "s-cl"),
        "the Claude Code's steps alone: {stepped:?}"
    );
}

#[test]
fn a_kept_codex_thread_name_rides_a_read_that_names_none() {
    let read = |session: Option<&str>| Snapshot {
        session: session.map(str::to_string),
        run: aterm_agent::harness::relaunch::AgentRun::Codex(
            aterm_agent::harness::relaunch::CodexRun {
                home: "/u/.codex".into(),
                home_env: None,
                self_claimed: None,
            },
        ),
        ..snap("s-c")
    };
    let before = read(Some("T-other"));
    let mut now = read(None);
    keep_session(Some(&before), &mut now);
    assert_eq!(now.session.as_deref(), Some("T-other"), "kept");
    let mut other = Snapshot {
        pid: before.pid + 1,
        ..read(None)
    };
    keep_session(Some(&before), &mut other);
    assert_eq!(other.session, None, "another process's name");
    let mut named = read(Some("T-mine"));
    keep_session(Some(&before), &mut named);
    assert_eq!(named.session.as_deref(), Some("T-mine"));
}

