#[test]
fn the_real_host_admits_no_worker_for_a_vendor_codex() {
    let model = aterm_models_harness::harness_worker_lifecycle_model();
    let run = |told: bool| {
        let probe = Arc::new(Probe::default());
        probe.vendor.store(true, Ordering::SeqCst);
        probe.told_vendor.store(told, Ordering::SeqCst);
        let host = HostHandle::start(on(), false, false, probe.hooks());
        *probe.roster.lock().unwrap() = vec![("s-t1".to_string(), Program::Codex)];
        ring();
        probe.passes();
        if !told {
            until("the identity-only admission's worker runs", || {
                host.live() == ["s-t1"] && probe.running.lock().unwrap().len() == 1
            });
        }
        probe.passes();
        let seen = probe.project(
            host.faults_of("s-t1"),
            host.live() == ["s-t1"],
            host.shared.switches.on_for(Program::Codex),
            host.off_sessions().contains("s-t1"),
        );
        host.shutdown_and_join();
        seen
    };
    let shipped = run(true);
    let mut expect = model.init_state();
    assert!(model.fire("ArriveVendor", &mut expect));
    assert!(!model.action_enabled("Start", &expect));
    assert_eq!(
        shipped, expect,
        "the vendor codex's session as the model has it"
    );
    for inv in &model.invariants {
        assert!(
            model.check_invariant(inv.name, &shipped),
            "{} broken by {shipped:?}",
            inv.name
        );
    }
    let withheld = run(false);
    assert_eq!(
        (withheld["vendor"], withheld["cur"]),
        (1, 1),
        "{withheld:?}"
    );
    assert!(
        !model.check_invariant("NoWorkerForAVendorCodex", &withheld),
        "an identity-only admission passed the projection: {withheld:?}"
    );
}

#[test]
fn a_run_a_commit_stopped_is_suspended_and_one_stopped_for_good_is_not() {
    let read_at_stop = |commit: bool| {
        let world = Arc::new(World::default());
        world.set(&[("s-t", Program::Claude)]);
        let seen: Arc<Mutex<Vec<bool>>> = Arc::default();
        let mut hooks = hooks(&world, parking_body(&world));
        let (w, s) = (Arc::clone(&world), Arc::clone(&seen));
        hooks.body = Arc::new(move |job: &WorkerJob| {
            let me = std::thread::current();
            *job.interrupt.lock().unwrap() = Some(Box::new(move || me.unpark()));
            w.runs.fetch_add(1, Ordering::SeqCst);
            while !job.stop.load(Ordering::SeqCst) {
                std::thread::park();
            }
            s.lock().unwrap().push(stopped_by_commit(job));
            BodyEnd::Stopped
        });
        let host = HostHandle::start(on(), false, false, hooks);
        until("a worker for s-t, its interrupter published", || {
            host.live() == ["s-t"] && world.runs.load(Ordering::SeqCst) >= 1
        });
        if commit {
            host.suspend();
            until("the run returned from the Commit's stop", || {
                !seen.lock().unwrap().is_empty()
            });
        }
        host.shutdown_and_join();
        until("the run returned from its stop", || {
            !seen.lock().unwrap().is_empty()
        });
        seen.lock().unwrap()[0]
    };
    assert!(
        read_at_stop(true),
        "a Commit's stop: the tape ends suspended"
    );
    assert!(
        !read_at_stop(false),
        "a stop for good: the tape ends as the stop"
    );
}

#[test]
fn a_restored_landing_whose_only_evidence_is_its_record_in_flight_is_said() {
    let started = Outcome::NotYet("wait:resume".to_string());
    let cannot = Outcome::Cannot(RESTORED_PANIC.to_string());
    for (in_flight, landed, only, holds, said) in [
        (true, false, false, false, Some(&started)),
        (true, false, false, true, None),
        (false, true, true, false, Some(&started)),
        (false, true, true, true, None),
        (false, false, false, false, Some(&cannot)),
        (false, true, false, false, None),
    ] {
        let case = format!("in_flight={in_flight} landed={landed} only={only} holds={holds}");
        let world = Arc::new(World::default());
        let mut h = hooks(&world, parking_body(&world));
        h.still_wanted = Arc::new(move |_, _| holds);
        h.acts.adopted_gone = Arc::new(|_, _| None);
        h.acts.in_flight_here = Arc::new(move |sid, _| sid == "s-pz" && in_flight);
        let host = HostHandle::start(on(), false, false, h);
        let agent = restored_in("s-pz", 7);
        let mut attempt = queued_attempt(agent.clone(), 4);
        attempt.acting = true;
        attempt.faults = RESTORED_TRIES - 1;
        attempt.landed = landed;
        attempt.in_flight_only = only;
        host.shared
            .restored
            .lock()
            .unwrap()
            .attempts
            .push_back(attempt);
        let taken = RestoredTaken {
            order: 4,
            agent,
            revoked: Arc::default(),
            typed: false,
            seen: false,
            carried: false,
            landed,
        };
        restored_step_panicked(&host.shared, &host.hooks, &taken, landed);
        let (left, missed) = {
            let queue = host.shared.restored.lock().unwrap();
            (queue.attempts.len(), queue.missed.clone())
        };
        assert_eq!(left, 0, "{case}: over at the budget");
        assert_eq!(
            missed.iter().map(|m| m.outcome.clone()).collect::<Vec<_>>(),
            said.into_iter().cloned().collect::<Vec<_>>(),
            "{case}"
        );
        host.shutdown_and_join();
    }
    let world = Arc::new(World::default());
    let mut h = hooks(&world, parking_body(&world));
    h.still_wanted = Arc::new(|_, _| false);
    h.acts.adopted_gone = Arc::new(|_, _| None);
    h.acts.in_flight_here = Arc::new(|sid, _| sid == "s-pz");
    let host = HostHandle::start(on(), false, false, h);
    let agent = restored_in("s-pz", 7);
    let mut attempt = queued_attempt(agent.clone(), 4);
    attempt.acting = true;
    host.shared
        .restored
        .lock()
        .unwrap()
        .attempts
        .push_back(attempt);
    let taken = RestoredTaken {
        order: 4,
        agent,
        revoked: Arc::default(),
        typed: false,
        seen: false,
        carried: false,
        landed: false,
    };
    restored_step_panicked(&host.shared, &host.hooks, &taken, false);
    let kept = host.shared.restored.lock().unwrap().attempts.pop_front();
    let kept = kept.expect("kept as a landing");
    assert!(kept.landed && kept.in_flight_only, "the record's alone");
    match restored_landing_ends(
        kept,
        LandingLook::Unread,
        quick_pause(LANDED_LOOK),
        quick_pause(RESTORED_FIRST_PAUSE),
    ) {
        LandingEnd::Keep(attempt) => {
            assert!(
                attempt.landed && !attempt.in_flight_only,
                "a look found its agent"
            );
        }
        LandingEnd::Over(..) => panic!("an agent holding its tab is kept"),
    }
    host.shutdown_and_join();
}

#[test]
fn a_restored_landing_whose_pause_panicked_is_kept() {
    for (landed, panics) in [(true, true), (false, true), (true, false), (false, false)] {
        let case = format!("landed={landed} panics={panics}");
        let world = Arc::new(World::default());
        let mut h = hooks(&world, parking_body(&world));
        h.still_wanted = Arc::new(|_, _| false);
        h.acts.adopted_gone = Arc::new(|_, _| Some(false));
        h.acts.relaunch_restored = Arc::new(|_, _, _, _| "adopted".to_string());
        let asked = Arc::new(AtomicUsize::new(0));
        let a = Arc::clone(&asked);
        h.pause = Arc::new(move |pause| {
            if pause == LANDED_LOOK {
                assert!(
                    !(panics && a.fetch_add(1, Ordering::SeqCst) == 0),
                    "the landing's pause panics once (a test's)"
                );
            }
            quick_pause(pause)
        });
        let host = HostHandle::start(on(), false, false, h);
        let agent = restored_in("s-pl", 8);
        let mut attempt = queued_attempt(agent.clone(), 2);
        attempt.acting = true;
        attempt.landed = landed;
        host.shared
            .restored
            .lock()
            .unwrap()
            .attempts
            .push_back(attempt);
        let taken = RestoredTaken {
            order: 2,
            agent,
            revoked: Arc::default(),
            typed: landed,
            seen: false,
            carried: false,
            landed,
        };
        let relaunched = AtomicBool::new(taken.landed);
        if caught("a test's step", "said", || {
            restored_step(&host.shared, &host.hooks, &taken, &relaunched)
        })
        .is_none()
        {
            restored_step_panicked(
                &host.shared,
                &host.hooks,
                &taken,
                relaunched.load(Ordering::SeqCst),
            );
        }
        let (left, missed) = {
            let queue = host
                .shared
                .restored
                .lock()
                .unwrap_or_else(PoisonError::into_inner);
            let left: Vec<_> = queue
                .attempts
                .iter()
                .map(|a| (a.landed, a.faults, a.acting))
                .collect();
            (left, queue.missed.clone())
        };
        assert_eq!(
            left,
            [(true, u32::from(panics), false)],
            "{case}: kept as a landing"
        );
        assert!(missed.is_empty(), "{case}: nothing said: {missed:?}");
        host.shutdown_and_join();
    }
}

#[test]
fn every_wait_of_the_restored_queue_is_the_pause_seams() {
    #[derive(Clone, Copy, Debug)]
    enum Step {
        /// The relaunch says this.
        Says(&'static str),
        /// A landing's look: the record says its agent died.
        Died,
        /// The step, or the landing's look, panics.
        Panics,
    }
    const HOUR: Duration = Duration::from_secs(3600);
    let back_off = RESTORED_FIRST_PAUSE * 4;
    for (landed, typed, step, wait, then) in [
        (
            false,
            false,
            Step::Says("wait:shell-prompt"),
            back_off,
            (false, 1, 0, back_off * 2),
        ),
        (
            true,
            true,
            Step::Died,
            back_off,
            (false, 0, 0, back_off * 2),
        ),
        (
            false,
            true,
            Step::Panics,
            back_off,
            (false, 1, 1, back_off * 2),
        ),
        (
            true,
            true,
            Step::Panics,
            LANDED_LOOK,
            (true, 0, 1, back_off),
        ),
    ] {
        let case = format!("landed={landed} typed={typed} {step:?}");
        let world = Arc::new(World::default());
        let mut h = hooks(&world, parking_body(&world));
        h.still_wanted = Arc::new(|_, _| false);
        h.acts.relaunch_restored = Arc::new(move |_, _, _, _| match step {
            Step::Says(word) => word.to_string(),
            Step::Died | Step::Panics => panic!("the step fails (a test's)"),
        });
        h.acts.adopted_gone = Arc::new(move |_, _| match step {
            Step::Panics => panic!("the look fails (a test's)"),
            Step::Says(_) | Step::Died => Some(true),
        });
        h.pause = Arc::new(|pause| pause + HOUR);
        let host = HostHandle::start(on(), false, false, h);
        let agent = restored_in("s-pw", 9);
        let mut attempt = queued_attempt(agent.clone(), 6);
        attempt.acting = true;
        attempt.pause = back_off;
        attempt.landed = landed;
        attempt.resume_wait_since = (typed && !landed).then(Instant::now);
        let taken = RestoredTaken {
            order: 6,
            agent,
            revoked: Arc::default(),
            typed: attempt.typed(),
            seen: false,
            carried: false,
            landed,
        };
        host.shared
            .restored
            .lock()
            .unwrap()
            .attempts
            .push_back(attempt);
        let before = Instant::now();
        let relaunched = AtomicBool::new(taken.landed);
        if caught("a test's step", "said", || {
            restored_step(&host.shared, &host.hooks, &taken, &relaunched)
        })
        .is_none()
        {
            restored_step_panicked(
                &host.shared,
                &host.hooks,
                &taken,
                relaunched.load(Ordering::SeqCst),
            );
        }
        let after = Instant::now();
        let left: Vec<_> = host
            .shared
            .restored
            .lock()
            .unwrap()
            .attempts
            .iter()
            .map(|a| ((a.landed, a.tried, a.faults, a.pause), a.due))
            .collect();
        let [(kept, due)] = left[..] else {
            panic!("{case}: kept: {left:?}");
        };
        assert_eq!(kept, then, "{case}");
        let (from, to) = (before + wait + HOUR, after + wait + HOUR);
        assert!(
            from <= due && due <= to,
            "{case}: due its {wait:?} through the seam (an hour more), not {:?} on",
            due.saturating_duration_since(before)
        );
        host.shutdown_and_join();
    }
}

#[test]
fn the_first_disk_reading_runs_beside_the_host_start() {
    static GATE: Mutex<()> = Mutex::new(());
    static SEEN: Mutex<Option<(std::thread::ThreadId, Option<PathBuf>)>> = Mutex::new(None);
    fn read(state: Option<&Path>) {
        let _held = GATE.lock().unwrap_or_else(PoisonError::into_inner);
        *SEEN.lock().unwrap_or_else(PoisonError::into_inner) =
            Some((std::thread::current().id(), state.map(Path::to_path_buf)));
    }
    let dir = aterm_tempfile::TempDir::new().expect("harness state");
    let state = dir.path().to_path_buf();
    let held = GATE.lock().unwrap_or_else(PoisonError::into_inner);
    let (tx, rx) = std::sync::mpsc::channel();
    let handed = state.clone();
    std::thread::spawn(move || {
        let threaded = first_reading_off_thread(Some(handed), read);
        let _ = tx.send((std::thread::current().id(), threaded));
    });
    let (caller, threaded) = rx
        .recv_timeout(aterm_spec::wait::MUST_HAPPEN)
        .expect("the host's start returns while its first reading is held");
    assert!(threaded, "the reading went to a thread of its own");
    drop(held);
    let deadline = Instant::now() + aterm_spec::wait::MUST_HAPPEN;
    let (reader, got) = loop {
        if let Some(seen) = SEEN.lock().unwrap_or_else(PoisonError::into_inner).clone() {
            break seen;
        }
        assert!(Instant::now() < deadline, "the first reading never ran");
        std::thread::sleep(Duration::from_millis(1));
    };
    assert_ne!(
        reader, caller,
        "the reading ran beside the start, not on it"
    );
    assert_eq!(
        got.as_deref(),
        Some(state.as_path()),
        "the caller's state directory"
    );
}

#[test]
fn agents_auto_prime_off_leaves_the_claude_settings_byte_identical() {
    let home = aterm_tempfile::TempDir::new().expect("scratch home");
    let settings = home.path().join(".claude/settings.json");
    std::fs::create_dir_all(settings.parent().unwrap()).unwrap();
    let mine = b"{\n    \"model\":   \"opus\",\n  \"theme\": \"dark\"\n}\n";
    std::fs::write(&settings, mine).unwrap();

    sweep_claude_settings_in(home.path(), false);
    assert_eq!(std::fs::read(&settings).unwrap(), mine, "nothing written");
    let backups: Vec<_> = std::fs::read_dir(settings.parent().unwrap())
        .unwrap()
        .map(|entry| entry.unwrap().file_name())
        .collect();
    assert_eq!(backups.len(), 1, "no backup either: {backups:?}");

    sweep_claude_settings_in(home.path(), true);
    let primed = std::fs::read_to_string(&settings).unwrap();
    assert!(
        primed.contains("\"effortLevel\"") && primed.contains("\"model\""),
        "on, the defaults join the person's own: {primed}"
    );
}

#[test]
fn an_agents_launch_is_the_command_start_its_process_began_at_or_after() {
    const START: &str = "Thu Sep 24 01:02:03 2026";
    let began = i64::try_from(
        aterm_agent::harness::upgrade_models::parse_lstart(START).expect("the start"),
    )
    .expect("unix seconds");
    let ms = began * 1000;
    let launch = |mark: Option<i64>, kept: bool| {
        let world = Arc::new(World::default());
        let mut h = hooks(&world, parking_body(&world));
        h.acts.launch = Arc::new(move |sid| {
            assert_eq!(sid, "s-idle");
            mark
        });
        let idle = idle_of(h, Program::Gemini, None);
        {
            let mut k = idle.kept.lock().unwrap();
            match k.snapshot.as_mut() {
                Some(snap) if kept => snap.start = START.to_string(),
                _ => k.snapshot = None,
            }
        }
        IdleHost::launch(&idle)
    };
    assert_eq!(launch(Some(ms - 1300), true), Some(ms - 1300), "after it");
    assert_eq!(launch(Some(ms + 400), true), Some(ms + 400), "its second");
    assert_eq!(launch(Some(ms + 5_000), true), None, "an earlier process");
    assert_eq!(launch(None, true), None, "no command start");
    assert_eq!(launch(Some(ms - 1300), false), None, "no process read");
}

#[test]
fn the_live_launch_is_the_witnesss_last_start_with_no_gesture_since() {
    use crate::launch_witness::{Launch, Why};
    let store = crate::session_store::new_store();
    let handle = crate::session_store::test_handle(7301);
    let sid = handle.sid.as_str().to_string();
    let ctx = Arc::clone(&handle.ctx);
    store.write().unwrap().register(handle);
    assert_eq!(launch_of(&store, &sid), None, "no command start");
    ctx.launch.mark_at_for_test(
        Launch {
            id: 1,
            seq: ctx.human_input.seq(),
            word: None,
            why: Why::Other,
        },
        1_792_520_389_950,
    );
    assert_eq!(launch_of(&store, &sid), Some(1_792_520_389_950));
    ctx.human_input.note(0, crate::human_input::Gesture::Other);
    assert_eq!(launch_of(&store, &sid), None, "a person keyed since");
    assert_eq!(launch_of(&store, "s-none"), None, "no such tab");
}
